// Content for Navigating Addictions (node g68, Parent Layer, Chapter 8): NEW v2 build to GDD 68
// (mechanic-embodying), a HIGH-CARE Parent-Layer pillar. The core insight: shame and punishment drive addiction
// UNDERGROUND, while calm, connection and the right help bring it into the light. 84 researched, India-grounded
// scenarios across spot-the-signs → respond-dont-rupture → its-a-health-issue → get-the-right-help →
// screens-and-modelling → tools-and-safety, each encoded as one of the shared v2 play actions (strike-rewrite /
// branch / role-play / sort / match / reflect / spot): no binary "tap the right card". Lead: strike-rewrite (bust
// the myth), branch (your move), role-play (say it). Six modes: spot the signs (warning signs of substance &
// screen/gaming dependence, typical vs concerning, calm noticing not panic or snooping; gaming disorder is a
// recognised condition), respond don't rupture (busts 'crack down / it's just willpower / good kids don't / shame
// will scare them straight'; connection over control & surveillance; firm about the behaviour and unconditionally
// there for the child), it's a health issue (dependence is a treatable health condition involving brain, genes &
// environment: not weak willpower or a moral failing; treatment works and recovery is real), get the right help
// (counselling & de-addiction services EARLY; family involvement strongly improves outcomes; routes to Tele-MANAS
// 14416 and Childline 1098), screens and modelling (calm agreed screen limits the WHOLE family keeps, healthy
// outlets, honestly tending your OWN substance & screen habits), tools and safety (a signs-and-help-finder &
// calm-response plan; any acute risk such as a possible overdose or danger is an EMERGENCY: route immediately to
// 112 or a hospital). HIGH-CARE and firmly non-shaming of both child AND parent; frames dependence as health, not
// moral failure; NEVER provides any how-to for obtaining or using substances; treats acute risk as an emergency;
// NOT medical advice: points to professionals. Builds on Bounce (g39) and connects to the screen-literacy thread
// (Reality Check g28, Decoded g36). India: youth substance use and screen/gaming dependence are both rising while
// stigma and harsh punitive responses are common (exactly what drives the problem deeper) so the node
// de-stigmatises and signposts real help. gameId "navigating-addictions".
import type { V2GameConfig, Scenario } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  {"id":"na-001","cat":"spot-the-signs","type":"strike-rewrite","hook":"\"A good kid would never get into substances or get hooked on screens.\"","myth":{"un":"A good kid would never get into substances or get hooked on screens.","re":"Dependence can affect any child from any family; it's about a developing brain and pressures, not about being a 'bad' kid.","why":"It isn't a verdict on your child or your parenting."},"relearn":"Dependence can affect any child; it's not a sign of a 'bad' kid or bad parenting, and it can be addressed.","persona":"Vikram","source":"any kid"},
  {"id":"na-002","cat":"spot-the-signs","type":"sort","hook":"Sort: a possible warning sign worth gently checking, or ordinary teen behaviour?","items":[{"id":"a","text":"Secrecy, withdrawal and lost interest in everything else"},{"id":"b","text":"Wanting some more privacy in their room"},{"id":"c","text":"Skipping sleep, school and meals for a habit"},{"id":"d","text":"Enjoying time with friends"},{"id":"e","text":"Money or things going missing to feed a habit"},{"id":"f","text":"Trying a new look or new music taste"}],"bins":[{"id":"sign","label":"Worth checking","valence":"uhoh"},{"id":"ordinary","label":"Ordinary","valence":"pos"}],"key":{"a":"sign","b":"ordinary","c":"sign","d":"ordinary","e":"sign","f":"ordinary"},"relearn":"Withdrawal, skipping life and missing money are worth checking; privacy, friends and a new look are ordinary.","persona":"any","source":"sign vs ordinary"},
  {"id":"na-003","cat":"spot-the-signs","type":"strike-rewrite","hook":"\"Screen and gaming overuse isn't a real problem, only drugs count.\"","myth":{"un":"Screen and gaming overuse isn't a real problem, only drugs count.","re":"Gaming disorder is a recognised condition, and screen or phone dependence can genuinely disrupt a child's sleep, mood and life.","why":"Behavioural dependence is real too."},"relearn":"Screen and gaming dependence is real and recognised; it can disrupt a child's sleep, mood and life, not just substances.","persona":"Priya","source":"screens count too"},
  {"id":"na-004","cat":"spot-the-signs","type":"match","hook":"Match each area to a sign that it may have tipped into dependence.","pairs":[{"left":"Substances","right":"Hiding use and needing more to feel the same"},{"left":"Gaming or screens","right":"Gaming over sleep, school and everything else"},{"left":"Taking it away","right":"Distress or conflict the moment it stops"},{"left":"School and grades","right":"A steady slide and lost interest in class"},{"left":"Friends","right":"Dropping old friends for only one crowd"}],"relearn":"Across substances and screens, the signs are loss of control, escalation and disruption of sleep, school and relationships.","persona":"any","source":"signs by area"},
  {"id":"na-005","cat":"spot-the-signs","type":"reflect","hook":"Lensy: noticing early, with calm not panic, gives you the best chance to help. Sit right?","prompt":"What do you think?","options":["Sits right","Calm not panic","Notice early"],"affirm":"Noticing signs early and calmly, rather than panicking or ignoring them, gives you the best chance to help.","relearn":"Noticing early, with calm rather than panic, gives you the best chance to help.","persona":"any","source":"notice early"},
  {"id":"na-006","cat":"spot-the-signs","type":"spot","hook":"Spot the two ways of reading a worry that shut a child down.","scene":[{"id":"a","text":"Staying curious and gently checking in","trick":false},{"id":"b","text":"Jumping straight to accusations","trick":true},{"id":"c","text":"Looking at the whole picture over time","trick":false},{"id":"d","text":"Panicking and assuming the worst","trick":true},{"id":"e","text":"Leaving the door open to talk","trick":false}],"why":"Accusations and panic are the two that shut a child down; curiosity, the whole picture and an open door keep them reachable.","relearn":"Read warning signs with curiosity and the whole picture, not accusations and panic.","persona":"Divya","source":"calm reading"},
  {"id":"na-007","cat":"spot-the-signs","type":"branch","persona":"Vikram","source":"open the door","hook":"Your son Kunal, 15, has been skipping meals, sleeping late and dropping cricket practice.","steps":[{"prompt":"The changes have built up over a few weeks. What do you do first?","options":[{"text":"Confront him tonight and accuse him of taking drugs","then":"Kunal denies everything and locks his door."},{"text":"Read his messages while he sleeps","then":"You find nothing clear, and you feel uneasy about looking."},{"text":"Put it down to his age and let it go","then":"The weeks pass, and the changes deepen."},{"text":"Keep noticing, and look for a calm moment to check in","then":"Over the next days you notice he has also stopped meeting old friends.","best":true}],"why":"Calm noticing over time shows you the real picture without pushing him away."},{"prompt":"On a drive to your mother's, it's just you and Kunal. What do you say?","options":[{"text":"Ask him straight out whether he's taking something","then":"Kunal stiffens. \"No. Why would you even think that?\""},{"text":"Say nothing, and enjoy the quiet drive","then":"The drive passes in silence, and the moment slips by."},{"text":"Say he seems low lately, and ask how he's doing","then":"Kunal shrugs, then says school has been rough.","best":true},{"text":"List every change you've noticed, one by one","then":"Kunal stares out of the window, feeling watched."}],"why":"Opening gently with care, not accusation, makes it easier for him to talk."},{"prompt":"In the weeks after, Kunal insists he's fine but still looks tired and flat. What do you do?","options":[{"text":"Take his phone until he tells you what's going on","then":"Kunal says even less, and spends more time out."},{"text":"Keep the door open, and say you're there when he's ready","then":"A few nights later, he knocks on your door and sits down.","best":true},{"text":"Accept that he's fine and stop asking","then":"Things look calm, but he keeps missing practice."},{"text":"Ask his friends what's going on behind his back","then":"Word gets back to Kunal, and he feels betrayed."}],"why":"Staying open and patient lets him come to you when he's ready."},{"prompt":"One night Kunal admits he vapes a lot and can't sleep without it. What do you do?","options":[{"text":"Thank him, stay calm, and plan to find help together","then":"Kunal breathes out. \"I thought you'd lose it,\" he says, half smiling.","best":true},{"text":"Tell him you knew it all along","then":"Kunal's face closes. \"Then why didn't you say anything?\""},{"text":"Ground him for a month","then":"Kunal nods silently and doesn't bring it up again."},{"text":"Tell him to cut down on his own and see how it goes","then":"Kunal tries for a few days, then goes quiet about it."}],"why":"A calm response to his honesty opens the way to real help."}],"debrief":"Meet worrying changes by staying observant and opening the door gently, not with immediate accusations.","relearn":"Open the door gently when worried; accusations make a teen hide what you most need to understand."},
  {"id":"na-008","cat":"spot-the-signs","type":"strike-rewrite","hook":"\"If I just search their things, I'll know everything and fix it.\"","myth":{"un":"If I just search their things, I'll know everything and fix it.","re":"Surveillance alone breaks trust and drives a child further underground; connection reveals more than searching ever will.","why":"Trust opens doors that snooping slams shut."},"relearn":"Surveillance alone breaks trust and drives a child underground; connection reveals more than searching does.","persona":"any","source":"connection over snooping"},
  {"id":"na-009","cat":"spot-the-signs","type":"reflect","hook":"Lensy: the goal isn't to catch your child, it's to reach them. Feel the difference?","prompt":"What's your take?","options":["Feel it","Reach not catch","Yes"],"affirm":"The aim with a struggling child isn't to catch them out but to reach them, which keeps the door open to help.","relearn":"The goal isn't to catch your child, it's to reach them.","persona":"any","source":"reach not catch"},
  {"id":"na-010","cat":"spot-the-signs","type":"sort","hook":"Sort: helps you spot dependence early, or misses or worsens it?","items":[{"id":"a","text":"Knowing the real warning signs"},{"id":"b","text":"Assuming it could never be your kid"},{"id":"c","text":"Calm, ongoing connection"},{"id":"d","text":"Only reacting once it's a crisis"},{"id":"e","text":"Watching the whole picture over weeks"},{"id":"f","text":"Shaming them the moment you worry"}],"bins":[{"id":"helps","label":"Helps you spot it","valence":"pos"},{"id":"misses","label":"Misses or worsens","valence":"neg"}],"key":{"a":"helps","b":"misses","c":"helps","d":"misses","e":"helps","f":"misses"},"relearn":"Knowing the signs, calm connection and the whole picture help you spot it early; denial, waiting for a crisis and shame miss or worsen it.","persona":"any","source":"spot or miss"},
  {"id":"na-011","cat":"respond-dont-rupture","type":"strike-rewrite","hook":"\"The way to stop it is to crack down hard, punish and threaten.\"","myth":{"un":"The way to stop it is to crack down hard, punish and threaten.","re":"Harsh crackdowns and threats usually drive it underground; calm, connected responses keep a child reachable and willing to get help.","why":"Connection works where fear fails."},"relearn":"Cracking down with punishment and threats drives it underground; calm, connected responses keep a child reachable.","persona":"Vikram","source":"connection over crackdown"},
  {"id":"na-012","cat":"respond-dont-rupture","type":"strike-rewrite","hook":"\"Shaming my child about it will scare them into stopping.\"","myth":{"un":"Shaming my child about it will scare them into stopping.","re":"Shame drives dependence underground and deepens it; a child who feels safe to be honest is far easier to help.","why":"Shame closes the door you need open."},"relearn":"Shaming a child about dependence drives it underground; safety to be honest is what makes help possible.","persona":"Vikram","source":"shame drives it under"},
  {"id":"na-013","cat":"respond-dont-rupture","type":"branch","persona":"Vikram","source":"calm not explosion","hook":"You've just found drugs in your son Arnav's school bag. You're furious, and scared.","steps":[{"prompt":"He walks in from tuition and sees the bag open on his bed. What do you do?","options":[{"text":"Take a breath, and say you're worried and want to talk","then":"Arnav freezes, then sits down slowly. \"It's not what you think.\"","best":true},{"text":"Shout and demand to know who gave it to him","then":"Arnav shouts back, grabs the bag and locks himself in the bathroom."},{"text":"Say nothing, and wait to see if he brings it up","then":"Arnav zips the bag shut. He says nothing, and neither do you."},{"text":"Stay calm, but tell him he's grounded until further notice","then":"Arnav goes silent. \"Fine,\" he says, and won't say more."}],"why":"Calm concern keeps him willing to talk, where an explosion makes him hide."},{"prompt":"Later that night, Arnav comes to you and says a friend asked him to hold it. What do you do?","options":[{"text":"Say you're not here to punish, just to understand","then":"Arnav hesitates, then admits he's tried it a few times.","best":true},{"text":"Call him a liar to his face","then":"Arnav's face closes. \"Believe what you want.\""},{"text":"Accept the story with relief and drop it","then":"Arnav looks relieved too. The subject is closed."},{"text":"Say you'll believe him if he gives you the friend's name","then":"Arnav refuses. \"I'm not getting him in trouble.\""}],"why":"Leaving room for honesty, instead of a fight over the story, helps the truth come out."},{"prompt":"Your wife comes home and wants to call his friends' parents tonight. What do you do?","options":[{"text":"Suggest you both calm down first, then plan together","then":"She takes a breath. \"Okay. But tomorrow we do something.\"","best":true},{"text":"Agree, and start making calls right away","then":"Word spreads fast, and Arnav feels humiliated in front of everyone."},{"text":"Tell her to keep out of it and let you handle it","then":"She's hurt, and now you're handling it alone."},{"text":"Agree to call just one parent tonight, quietly","then":"That parent has told two others by morning."}],"why":"Planning together, once you're both calm, keeps the moment from becoming a rupture."},{"prompt":"The next morning, you wonder what the next step should be. What do you do?","options":[{"text":"Call Tele-MANAS 14416 to talk it through and find help","then":"The counsellor helps you plan a calm family talk and a local service.","best":true},{"text":"Ground him for three months and check his bag daily","then":"Arnav goes sullen, and gets better at hiding things."},{"text":"Decide it was a one-time thing and move on","then":"A few weeks later, you find another packet."},{"text":"Go and speak to his school principal first","then":"The principal promises to keep an eye on him, and nothing more."}],"why":"Getting help early, before a crisis, gives him the best chance."},{"prompt":"A few days later, Arnav asks if you'll ever trust him again. What do you say?","options":[{"text":"Say you love him, and you'll rebuild trust together","then":"Arnav nods slowly. \"Okay. I'll try.\"","best":true},{"text":"Say that trust is gone for good","then":"Arnav's shoulders drop, and he stops trying to talk."},{"text":"Say of course, and it's all forgotten already","then":"Arnav looks relieved, but nothing has really been sorted out."},{"text":"Say he can earn it back only if he never touches it again","then":"Arnav nods fast, too scared to say it may not be that easy."}],"why":"Holding both the worry and the love keeps him reachable as you work through it."}],"debrief":"Meet a discovery with calm concern, not an explosion, so your teen stays reachable.","relearn":"Calm concern keeps a teen reachable; rupture sends a struggling teen underground."},
  {"id":"na-014","type":"match","persona":"Vikram","source":"connecting responses","relearn":"Each punitive instinct has a connecting response that keeps a child reachable and willing to accept help.","hook":"Match each punitive instinct to the connecting response that works better.","pairs":[{"left":"'You're grounded forever'","right":"'I'm worried about you, let's talk'"},{"left":"'How could you do this to us'","right":"'You can be honest with me'"},{"left":"'You're a disappointment'","right":"'We'll face this together'"},{"left":"'Get out of my sight'","right":"'I'm staying right here with you'"},{"left":"'I can never trust you'","right":"'Let's rebuild this step by step'"}],"cat":"respond-dont-rupture"},
  {"id":"na-015","cat":"respond-dont-rupture","type":"role-play","persona":"Vikram","source":"first words","hook":"Your son Rehan, 14, has been gaming through the night for months.","setup":"Tonight he sits on your bed, not meeting your eyes.","steps":[{"prompt":"Rehan says: \"I can't stop playing. I've tried. Something's wrong with me.\"","options":[{"text":"\"I knew it. You've wasted your whole life on that game.\"","then":"Rehan's face shuts. \"Forget I said anything.\""},{"text":"\"Nothing's wrong with you. Just delete the game tonight.\"","then":"Rehan hesitates. \"I've deleted it before. I always reinstall it.\""},{"text":"\"I'm glad you told me. I'm not angry. We'll face this together.\"","then":"Rehan looks up. \"Really? I thought you'd take my phone forever.\"","best":true},{"text":"\"Everyone your age games. You're just worrying far too much.\"","then":"Rehan frowns. \"But I missed my exam revision again.\""}],"why":"Thanking him and staying calm keeps him safe to talk and ready for help."},{"prompt":"Rehan asks: \"Are you going to tell Mummy? She'll be so upset.\"","options":[{"text":"\"No. This stays between us two.\"","then":"Rehan breathes out. \"Thanks, Papa. Let's not make it a big thing.\""},{"text":"\"Yes, and we'll tell her together. She'll want to help too.\"","then":"Rehan nods slowly. \"Okay. If you're there with me.\"","best":true},{"text":"\"She'll be furious, so you'd better tell her yourself.\"","then":"Rehan pales. \"Then I'm not telling her anything.\""},{"text":"\"Let's wait and see if you can fix it on your own first.\"","then":"\"Okay,\" Rehan says, unsure. \"But what if I can't?\""}],"why":"The whole family pulling together, not secrecy, gives him the best chance."},{"prompt":"Rehan asks: \"So what happens now? Do I have to see a doctor or something?\"","options":[{"text":"\"We'll see a counsellor who knows this. I'll come with you.\"","then":"Rehan chews his lip. \"Okay. As long as you're there.\"","best":true},{"text":"\"No doctors. We'll sort this out ourselves, here at home.\"","then":"Rehan shrugs. \"Fine. Same as last time, then.\""},{"text":"\"Only if you still can't stop by yourself after this month.\"","then":"\"Okay,\" Rehan says, shoulders sagging. \"One more month of trying alone.\""},{"text":"\"A doctor will only say what I'm saying. Just stop playing.\"","then":"Rehan looks away. \"You don't get it,\" he mutters."}],"why":"Getting help early, together, works far better than waiting for a crisis."}],"relearn":"A calm 'thank you for telling me' and 'we'll face this together' keep a struggling child safe and reachable."},
  {"id":"na-016","cat":"respond-dont-rupture","type":"reflect","hook":"Lensy: a child who fears your reaction hides; a child who trusts it comes to you. Which keeps them safer?","prompt":"What do you think?","options":["Trust keeps them safe","Come to me","Calm wins"],"affirm":"A child who trusts your calm reaction will come to you, which keeps them far safer than one who hides in fear.","relearn":"A child who fears your reaction hides; one who trusts it comes to you, and that keeps them safer.","persona":"any","source":"trust keeps safe"},
  {"id":"na-017","type":"spot","persona":"any","source":"stay reachable","relearn":"Calm concern and 'we'll face this together' keep a child reachable; rage and humiliation drive them away.","hook":"Spot the two responses that drive a struggling child away.","scene":[{"id":"a","text":"Calm concern and an open door","trick":false},{"id":"b","text":"Rage, threats and humiliation","trick":true},{"id":"c","text":"'We'll face this together'","trick":false},{"id":"d","text":"The silent treatment for days","trick":true},{"id":"e","text":"A steady, lowered voice","trick":false}],"why":"Rage with humiliation and the silent treatment drive a struggling child away; calm concern and togetherness keep them reachable.","cat":"respond-dont-rupture"},
  {"id":"na-018","cat":"respond-dont-rupture","type":"strike-rewrite","hook":"\"Cutting off all connection until they 'sort themselves out' will teach them.\"","myth":{"un":"Cutting off all connection until they 'sort themselves out' will teach them.","re":"Connection is the most protective thing you have; withdrawing it removes the lifeline a struggling child most needs.","why":"Stay connected, especially when it's hard."},"relearn":"Cutting off connection removes a struggling child's lifeline; staying connected is the most protective thing you can do.","persona":"Vikram","source":"stay the lifeline"},
  {"id":"na-019","cat":"respond-dont-rupture","type":"branch","persona":"Divya","source":"limit and door","hook":"Your daughter Sana, 16, swore she'd stopped vaping. Today you found out she lied.","steps":[{"prompt":"She walks in, sees your face, and knows that you know. What do you do?","options":[{"text":"Say you're upset about the lie, and still want to talk","then":"Sana's eyes fill. \"I didn't want to let you down again.\"","best":true},{"text":"Declare that you can never trust her again","then":"Sana goes white, then storms off to her room."},{"text":"Pretend you don't know, to avoid a fight","then":"Sana relaxes. The lie stays between you, unspoken."},{"text":"Tell her you're too hurt to even talk to her right now","then":"Sana waits by your door all evening. You don't open it."}],"why":"Naming the lie while keeping the door open holds the limit without losing her."},{"prompt":"The next morning, Sana admits she lied because she was scared of how you'd react. What do you do?","options":[{"text":"Say you'd always rather hear the truth, even a hard one","then":"Sana nods. \"Okay. I'm still vaping. Most days.\"","best":true},{"text":"Say that's no excuse for lying to you","then":"Sana shuts down. \"See? This is why.\""},{"text":"Apologise, and say it's your fault for being strict","then":"Sana looks confused. The lie is dropped, and so is the vaping talk."},{"text":"Say you understand, then list the new rules straight away","then":"Sana's face falls, and she stops talking."}],"why":"Showing her the truth is safe with you makes honesty easier next time."},{"prompt":"A day later, you want to set a limit that sticks. What do you do?","options":[{"text":"Agree one clear limit with her, plus a plan to get help","then":"Sana argues, then agrees to no vaping at home and a counsellor visit.","best":true},{"text":"Take her phone and ban her friends for a month","then":"Sana goes along with it, but starts hiding everything."},{"text":"Skip the limit for now, since she's already upset","then":"The vaping carries on, and nothing changes."},{"text":"Decide the limit yourself, and tell her about it afterwards","then":"Sana hears it as a punishment and pushes back hard."}],"why":"A limit made with her, plus real help, holds firm and keeps her on side."},{"prompt":"A week later, the school calls: Sana was caught vaping in the washroom. What do you do?","options":[{"text":"Stay firm and warm, and bring in a counsellor's help","then":"Sana is quiet, but comes to your room that night to talk.","best":true},{"text":"Tell her this proves she's a liar","then":"Sana turns away. \"Why do I even try?\""},{"text":"Drop all the rules, since nothing works","then":"Sana is relieved, but she's vaping more than ever."},{"text":"Stay calm, but keep this between you two for now","then":"Things settle, but no one who could help hears about it."}],"why":"Holding the limit and the relationship together is what keeps her reachable."}],"debrief":"Address lying about use while keeping the relationship and door open; don't sever the connection a child needs.","relearn":"Hold the limit and the relationship both; 'I can never trust you' cuts a child's lifeline."},
  {"id":"na-020","cat":"respond-dont-rupture","type":"reflect","hook":"Lensy: you can be firm about the behaviour and unconditionally there for the child, at the same time. Sit right?","prompt":"What's your take?","options":["Sits right","Firm and there","Both at once"],"affirm":"You can hold firm limits about the behaviour while being unconditionally there for the child; both at once is the goal.","relearn":"You can be firm about the behaviour and unconditionally there for the child at the same time.","persona":"any","source":"firm and there"},
  {"id":"na-021","cat":"its-a-health-issue","type":"strike-rewrite","hook":"\"Addiction is just weak willpower or a moral failing.\"","myth":{"un":"Addiction is just weak willpower or a moral failing.","re":"Addiction is a treatable health condition involving the brain, genes and environment, not simply weakness or bad character.","why":"It's a health issue, and health issues have treatments."},"relearn":"Addiction is a treatable health condition, not weak willpower or a moral failing.","persona":"Vikram","source":"health not weakness"},
  {"id":"na-022","cat":"its-a-health-issue","type":"strike-rewrite","hook":"\"If my child were strong enough, they'd just stop on their own.\"","myth":{"un":"If my child were strong enough, they'd just stop on their own.","re":"Dependence changes the brain's reward system, making 'just stop' very hard; that's why support and treatment matter.","why":"It's not about strength; it's about help."},"relearn":"Dependence changes the brain, so 'just stop' is very hard; it isn't about strength, it's about getting support.","persona":"Vikram","source":"not about strength"},
  {"id":"na-023","cat":"its-a-health-issue","type":"sort","hook":"Sort: a fact that helps, or a stigma that harms, a child with dependence?","items":[{"id":"a","text":"It's a treatable health condition"},{"id":"b","text":"'They're just bad or weak'"},{"id":"c","text":"Recovery is possible with support"},{"id":"d","text":"'It's a hopeless disgrace'"},{"id":"e","text":"The brain's reward system is involved"},{"id":"f","text":"'Once an addict, always an addict'"}],"bins":[{"id":"helps","label":"Helpful fact","valence":"pos"},{"id":"stigma","label":"Harmful stigma","valence":"neg"}],"key":{"a":"helps","b":"stigma","c":"helps","d":"stigma","e":"helps","f":"stigma"},"relearn":"'Treatable', 'recovery is possible' and 'the brain is involved' help; 'bad or weak', 'hopeless disgrace' and 'always an addict' are harmful stigma.","persona":"any","source":"fact vs stigma"},
  {"id":"na-024","cat":"its-a-health-issue","type":"reflect","hook":"Lensy: seeing dependence as a health issue, not a disgrace, changes everything about how you respond. Resonate?","prompt":"What do you think?","options":["Resonates","Health not disgrace","Changes everything"],"affirm":"Viewing dependence as a treatable health issue rather than a disgrace shifts a parent from punishment toward effective help.","relearn":"Seeing dependence as a health issue, not a disgrace, changes how you respond, toward help.","persona":"any","source":"health not disgrace"},
  {"id":"na-025","cat":"its-a-health-issue","type":"strike-rewrite","hook":"\"Treatment doesn't work; once an addict, always an addict.\"","myth":{"un":"Treatment doesn't work; once an addict, always an addict.","re":"Addiction can be managed successfully; people who get and stay in treatment can recover and rebuild good lives.","why":"Recovery is real and common."},"relearn":"Treatment works; addiction can be managed and people recover and rebuild good lives with support.","persona":"Vikram","source":"recovery is real"},
  {"id":"na-026","cat":"its-a-health-issue","type":"match","hook":"Match each health-issue truth to what it means for your child.","pairs":[{"left":"It's treatable","right":"There's real hope and a path"},{"left":"It's not a moral failing","right":"Less shame, more honesty"},{"left":"Support improves outcomes","right":"Getting help is the strong move"},{"left":"The brain's reward system changed","right":"'Just stop' is hard, so seek treatment"},{"left":"Any child can be affected","right":"No blame to pin on you or them"}],"relearn":"Treatable means hope; not-a-failing means honesty; support means help is strong; the brain change means treatment; any-child means no blame.","persona":"any","source":"health truths"},
  {"id":"na-027","cat":"its-a-health-issue","type":"reflect","hook":"Lensy: you'd get your child help for any other illness without shame; this deserves the same. Sit right?","prompt":"What's your take?","options":["Sits right","Same as any illness","No shame"],"affirm":"Dependence deserves the same shame-free, get-help response you'd give any other illness your child faced.","relearn":"You'd get your child help for any other illness without shame; this deserves the same.","persona":"any","source":"same as any illness"},
  {"id":"na-028","cat":"its-a-health-issue","type":"spot","hook":"Spot the two lines that deepen a child's shame instead of helping them recover.","scene":[{"id":"a","text":"'This is treatable, let's get help'","trick":false},{"id":"b","text":"'You're a hopeless addict'","trick":true},{"id":"c","text":"'Recovery is possible, I believe in you'","trick":false},{"id":"d","text":"'You've brought shame on us all'","trick":true},{"id":"e","text":"'You're unwell, not bad, and I'm here'","trick":false}],"why":"'Hopeless addict' and 'shame on us all' deepen shame and despair; the rest frame it as treatable, with hope.","relearn":"Catch the shame-deepening lines; frame dependence as treatable, with hope, not a hopeless identity.","persona":"any","source":"framing for recovery"},
  {"id":"na-029","cat":"its-a-health-issue","type":"branch","persona":"Kamla","source":"face it openly","hook":"Your son Chotu's drinking has become a real problem, and it feels like a family shame to hide.","steps":[{"prompt":"Your sister asks why Chotu has missed school all week. What do you do?","options":[{"text":"Tell her he's struggling with drinking and you're getting help","then":"Your sister goes quiet, then offers to help you find a counsellor.","best":true},{"text":"Say he has a fever and change the subject","then":"Your sister believes you. You go home with the secret still heavy."},{"text":"Snap that it's none of her business","then":"Your sister leaves hurt, and you're left with no one to talk to."},{"text":"Tell her the truth, but beg her never to mention it again","then":"She promises. The subject closes, and nobody talks about help."}],"why":"Facing it openly lets family support you and opens the door to help."},{"prompt":"That night, your husband says outside help will shame the family. What do you do?","options":[{"text":"Say it's a health problem, and help is how he gets better","then":"He's quiet for a while, then asks what a counsellor would even do.","best":true},{"text":"Agree to keep it hidden a while longer","then":"Weeks pass, and Chotu's drinking stays the family secret."},{"text":"Tell him his pride matters more to him than his son","then":"He storms off, and nothing is decided."},{"text":"Ask the family elders to lecture Chotu instead","then":"The elders scold Chotu at length, and he stays out later than ever."}],"why":"Calling it a health problem, not a shame, makes getting help possible."},{"prompt":"You finally call Tele-MANAS 14416. The counsellor asks if Chotu knows you're calling. What do you say?","options":[{"text":"Say not yet, and ask how to tell him calmly","then":"The counsellor helps you plan the words and suggests a family session.","best":true},{"text":"Say he must never find out that you called","then":"The counsellor explains that help works better when he's part of it."},{"text":"Say you'll just make him come, whether he likes it or not","then":"The counsellor gently warns that force often pushes children away."},{"text":"Say you'll leave it to his father to tell him","then":"The counsellor asks whether his father is on board yet."}],"why":"Planning an honest, calm talk with him brings him into the help."},{"prompt":"At a family gathering, your uncle jokes about Chotu's 'bad habits' while Chotu can hear. What do you do?","options":[{"text":"Say calmly that Chotu is unwell and getting help","then":"The room goes quiet. Chotu looks at you, surprised and grateful.","best":true},{"text":"Laugh along to keep things light","then":"Chotu leaves the room and won't talk to you that night."},{"text":"Shout at your uncle in front of everyone","then":"The gathering turns tense, and Chotu is now at the centre of it."},{"text":"Quietly take Chotu out of the room without a word","then":"Chotu is relieved to leave, but the joke stays unanswered."}],"why":"Naming it calmly as a health issue shields him from shame and shows you're not hiding him."}],"debrief":"Treat dependence as a health challenge to face and get help for, not a family shame to hide.","relearn":"Face dependence openly as a health issue; hiding it in shame blocks help."},
  {"id":"na-030","cat":"get-the-right-help","type":"strike-rewrite","hook":"\"We should handle this entirely within the family and tell no professional.\"","myth":{"un":"We should handle this entirely within the family and tell no professional.","re":"Dependence usually needs professional help; counsellors and de-addiction services know what works, and family plus help is strongest.","why":"Asking for help is wise, not weak."},"relearn":"Dependence usually needs professional help; counsellors and de-addiction services work best alongside family support.","persona":"Vikram","source":"get professional help"},
  {"id":"na-031","cat":"get-the-right-help","type":"branch","persona":"Vikram","source":"reach out early","hook":"Your son Kabir, 16, keeps coming home smelling of alcohol. Your talks and new rules haven't changed a thing.","steps":[{"prompt":"Another weekend, the same thing happens. What do you do now?","options":[{"text":"Call a de-addiction counsellor this week for help","then":"The counsellor listens and offers an assessment slot for next Tuesday.","best":true},{"text":"Wait a few more months to see if it's just a phase","then":"Weekends blur together, and Kabir starts missing Monday classes too."},{"text":"Take away his pocket money and phone until he stops","then":"Kabir goes quiet and starts coming home later, with new excuses."},{"text":"Read up online and try one more plan at home first","then":"You find ten conflicting tips. A month passes and nothing has changed."}],"why":"Reaching out early gives him the best chance, because dependence usually needs professional help."},{"prompt":"Your wife Anjali says: \"Let's not make this bigger than it is. People will talk.\" What do you do?","options":[{"text":"Say it's a health issue, and ask her to get help with you","then":"Anjali hesitates, then says she'll come if it stays within the family for now.","best":true},{"text":"Agree to keep it quiet and handle it yourselves","then":"Anjali relaxes. The worry stays between you two, and nothing new is tried."},{"text":"Tell her she's in denial and you'll go without her","then":"Anjali walks out of the room. You end up planning alone."},{"text":"Offer to handle getting help alone so she doesn't have to","then":"Anjali nods, relieved. You'll be carrying every step on your own."}],"why":"Bringing your partner in helps, because family involvement strongly improves how children do."},{"prompt":"Later that week, Kabir asks why everyone at home seems so tense around him. What do you do?","options":[{"text":"Admit you're worried and want to find help together","then":"Kabir rolls his eyes but doesn't leave. \"I'm not an addict,\" he mutters.","best":true},{"text":"Say it's nothing and change the subject","then":"Kabir shrugs and goes to his room. The chance to talk passes."},{"text":"Tell him he's bringing shame on the family","then":"Kabir slams the door. That night he doesn't come home till two."},{"text":"Say you're worried, then list everything he's done wrong","then":"Kabir argues back point by point, and the talk turns into a fight."}],"why":"Honest, calm worry with help as the plan keeps him in the conversation."},{"prompt":"You book a family session for Saturday. Kabir says he has cricket practice and can't come. What do you do?","options":[{"text":"Ask for a time that suits him, and say you'll all go together","then":"The counsellor moves it to Sunday. Kabir grumbles, but gets in the car.","best":true},{"text":"Tell him cricket is cancelled until he goes","then":"Kabir comes, arms folded, and answers every question in one word."},{"text":"Let him skip this one and try again sometime next month","then":"He has another reason next month too. The first session happens six weeks late."},{"text":"Go without him this time, and tell him about it afterwards","then":"The counsellor helps you plan, and asks you to bring Kabir next week."}],"why":"Fitting help around his life, while keeping him included, makes it doable without turning it into a punishment."},{"prompt":"A few sessions in, Kabir says counselling is pointless and he wants to stop. What do you do?","options":[{"text":"Hear him out, then ask the counsellor how to adjust the plan","then":"The counsellor tries a new approach, and Kabir agrees to two more weeks.","best":true},{"text":"Let him stop, since forcing it won't work","then":"Kabir stops going. A month later, the weekends look the same again."},{"text":"Tell him he's not allowed to quit, end of discussion","then":"Kabir keeps going but says as little as he can in every session."},{"text":"Agree he can stop if he promises to quit drinking by himself","then":"Kabir promises quickly. Within a fortnight he's slipped and is hiding it."}],"why":"Recovery takes time; adjusting the plan with the counsellor keeps him in help instead of dropping it."}],"debrief":"When dependence is beyond what you can manage alone, reach out early to a counsellor or de-addiction service.","relearn":"Get professional help early rather than waiting; effective treatment exists."},
  {"id":"na-032","cat":"get-the-right-help","type":"match","hook":"Match each India support to what it offers.","pairs":[{"left":"Tele-MANAS 14416","right":"Mental-health and addiction support, any time"},{"left":"A de-addiction centre / counsellor","right":"Assessment and structured treatment"},{"left":"Childline 1098","right":"Help for a child in distress or danger"},{"left":"112 or a hospital","right":"For acute danger like a possible overdose"},{"left":"Family-inclusive counselling","right":"Brings the whole family into recovery"}],"relearn":"Tele-MANAS, de-addiction services, Childline, 112 and family-inclusive care are real routes for a child's dependence.","persona":"any","source":"the help routes"},
  {"id":"na-033","cat":"get-the-right-help","type":"strike-rewrite","hook":"\"Family involvement doesn't matter once a child is in treatment.\"","myth":{"un":"Family involvement doesn't matter once a child is in treatment.","re":"Family-based support strongly improves outcomes; a calm, connected, involved parent is part of what makes treatment work.","why":"You're part of the treatment, not outside it."},"relearn":"Family involvement strongly improves outcomes; a calm, connected parent is part of what makes treatment work.","persona":"Divya","source":"family helps treatment"},
  {"id":"na-034","cat":"get-the-right-help","type":"sort","hook":"Sort: a step toward effective help, or a barrier to it?","items":[{"id":"a","text":"Seeking a professional assessment"},{"id":"b","text":"Shame that stops you asking"},{"id":"c","text":"Staying involved in treatment"},{"id":"d","text":"Believing nothing can help"},{"id":"e","text":"Calling early, before a crisis"},{"id":"f","text":"Keeping it a total secret"}],"bins":[{"id":"step","label":"Step toward help","valence":"pos"},{"id":"barrier","label":"A barrier","valence":"neg"}],"key":{"a":"step","b":"barrier","c":"step","d":"barrier","e":"step","f":"barrier"},"relearn":"Assessment, staying involved and calling early are steps toward help; shame, hopelessness and secrecy are barriers.","persona":"any","source":"step or barrier"},
  {"id":"na-035","cat":"get-the-right-help","type":"reflect","hook":"Lensy: getting help early, before crisis, gives your child the best chance, just like any health issue. Worth it?","prompt":"What do you think?","options":["Worth it","Early is best","Best chance"],"affirm":"Getting help early, before a crisis, gives a child the best chance of recovery, as with any health condition.","relearn":"Getting help early, before crisis, gives your child the best chance.","persona":"any","source":"early help best"},
  {"id":"na-036","cat":"get-the-right-help","type":"role-play","persona":"Kamla","source":"partner on board","hook":"Your son Bablu, 15, is drinking with older boys most nights. You want to get outside help.","setup":"You raise it with your husband Ramesh after dinner.","steps":[{"prompt":"Ramesh says: \"A counsellor? What will people say about our family?\"","options":[{"text":"\"It's a health problem. Getting help protects Bablu.\"","then":"Ramesh hesitates. \"But if anyone finds out...\"","best":true},{"text":"\"Fine. We'll keep pretending everything is okay.\"","then":"Ramesh nods, relieved. \"Good. It will pass.\""},{"text":"\"You care more about gossip than your own son.\"","then":"Ramesh's face hardens. \"Don't tell me what I care about.\""},{"text":"\"No one needs to know. I'll go on my own, secretly.\"","then":"Ramesh shrugs. \"Do what you want. Just don't tell anyone.\""}],"why":"Framing help as protecting your child, not a shameful secret, gives him a reason to agree."},{"prompt":"Ramesh says: \"In my family, we always sorted things out ourselves.\"","options":[{"text":"\"This needs more than us. A counsellor knows what works.\"","then":"Ramesh is quiet, then asks what they would even do.","best":true},{"text":"\"Your family sorted nothing. Look at your brother.\"","then":"Ramesh stands up. \"Leave my brother out of this.\""},{"text":"\"Maybe we should ask your mother what we ought to do.\"","then":"Ramesh brightens. \"She'll know. She raised five of us.\""},{"text":"\"Then let's try one more month at home first.\"","then":"\"One month,\" Ramesh agrees. \"Then we'll see.\""}],"why":"Dependence usually needs professional help, and saying so plainly moves him past 'we'll manage'."},{"prompt":"Ramesh asks, lowering his voice: \"What if the neighbours find out about Bablu?\"","options":[{"text":"\"Then they'll see parents getting help for their son.\"","then":"Ramesh almost smiles. \"You make it sound normal.\"","best":true},{"text":"\"Then we'll tell them it's something else.\"","then":"\"Good,\" says Ramesh. \"Nobody needs the truth.\""},{"text":"\"Who cares about the neighbours right now?\"","then":"\"I care,\" Ramesh snaps. \"We have to live here.\""},{"text":"\"I'll take him for help alone, so you're never seen.\"","then":"Ramesh nods. \"Better that way.\""}],"why":"Treating help-seeking as ordinary takes the power out of the shame."},{"prompt":"Later, Ramesh asks: \"If we did go, what would we even tell Bablu?\"","options":[{"text":"\"That we love him and we're worried, so we'll go together.\"","then":"Ramesh nods slowly. \"Together. Okay. I'll come.\"","best":true},{"text":"\"Nothing. We'll just take him there one day.\"","then":"\"He'll feel tricked,\" Ramesh says. \"He'll refuse.\""},{"text":"\"That he's shamed us, and this is his last chance.\"","then":"Ramesh nods. \"Maybe fear will work where talking didn't.\""},{"text":"\"That he'll see a counsellor next week, and that's that.\"","then":"Ramesh shrugs. \"And we just drop him off?\""}],"why":"Telling him with love, and going together, keeps him reachable and brings both parents in."}],"relearn":"Framing help as protecting your child, not a shameful admission, helps a reluctant partner accept it."},
  {"id":"na-037","cat":"get-the-right-help","type":"spot","hook":"Lensy: spot the two moves that fail to get a child real, lasting help.","scene":[{"id":"a","text":"Early professional support plus family involvement","trick":false},{"id":"b","text":"A one-off threat and hoping for the best","trick":true},{"id":"c","text":"Treating it as a health issue with a plan","trick":false},{"id":"d","text":"Keeping it all secret until it explodes","trick":true},{"id":"e","text":"Choosing a recognised de-addiction service","trick":false}],"why":"The two caught moves, threats-and-hoping and hiding it, don't get lasting help; early support and a plan do.","relearn":"Lasting help comes from early support, family involvement and a plan, not threats or hiding.","persona":"any","source":"real help"},
  {"id":"na-038","cat":"screens-and-modelling","type":"strike-rewrite","hook":"\"My own drinking, smoking or phone habits have nothing to do with my child.\"","myth":{"un":"My own drinking, smoking or phone habits have nothing to do with my child.","re":"Children learn habits by watching; honestly looking at what you model is part of helping your child with theirs.","why":"Kids copy what they see at home."},"relearn":"Your own substance and screen habits are part of the picture; children learn by watching what you model.","persona":"Kamla","source":"model honestly"},
  {"id":"na-039","cat":"screens-and-modelling","type":"sort","persona":"any","source":"boundary or backfire","hook":"Sort: a healthy screen boundary, or one that backfires?","items":[{"id":"a","text":"Agreed screen-free times, for everyone"},{"id":"b","text":"A sudden, total, angry ban"},{"id":"c","text":"Devices out of bedrooms at night"},{"id":"d","text":"Rules for the child but not the parent"},{"id":"e","text":"A short wind-down hour before bed"},{"id":"f","text":"Grabbing the phone in anger mid-row"}],"bins":[{"id":"healthy","label":"Healthy boundary","valence":"pos"},{"id":"backfire","label":"Backfires","valence":"neg"}],"key":{"a":"healthy","b":"backfire","c":"healthy","d":"backfire","e":"healthy","f":"backfire"},"relearn":"Agreed screen-free times and no devices at night are healthy; angry total bans and one-rule-for-the-child backfire."},
  {"id":"na-040","cat":"screens-and-modelling","type":"strike-rewrite","hook":"\"The best way to handle screens is a sudden, total ban with no discussion.\"","myth":{"un":"The best way to handle screens is a sudden, total ban with no discussion.","re":"Calm, consistent, agreed limits and replacing screen time with other good things work better than a sudden, total ban.","why":"Steady limits beat shock bans."},"relearn":"Calm, agreed, consistent screen limits work better than a sudden total ban with no discussion.","persona":"Priya","source":"steady limits"},
  {"id":"na-041","cat":"screens-and-modelling","type":"branch","persona":"Kamla","source":"model the limits","hook":"You want to limit your children's phone time, but you're on your own phone most evenings.","steps":[{"prompt":"Your daughter Munni is watching reels at dinner again. What do you do?","options":[{"text":"Tell her to put it away while you keep checking yours","then":"Munni points at your phone. \"You're on yours,\" she says, and keeps scrolling."},{"text":"Snatch her phone and put it up on the shelf","then":"Munni sulks through dinner and grabs it back the moment you leave."},{"text":"Put your own phone away first, then ask her to join you","then":"Munni looks at your empty hands, sighs, and puts her phone face down.","best":true},{"text":"Say nothing tonight, since you're on yours too","then":"Both of you scroll through dinner, and nobody talks."}],"why":"Modelling the limit yourself gives it weight before you ask anything of her."},{"prompt":"You want a proper screen rule for the family. How do you set it?","options":[{"text":"Make a rule for the children and leave yourself out of it","then":"The children follow it for a day, then point out that you never do."},{"text":"Agree phone-free dinners and bedtimes that you keep too","then":"Munni and her brother Sonu add a rule for you: no phone during homework help.","best":true},{"text":"Copy a strict timetable from a parenting video","then":"The timetable goes up on the fridge and is ignored by the weekend."},{"text":"Cut down on your own first and set a rule later","then":"Weeks pass with no rule, and the evenings look the same."}],"why":"Shared limits that include you feel fair, so everyone is more likely to keep them."},{"prompt":"One evening at dinner, you catch yourself reaching for your phone. What do you do?","options":[{"text":"Put it back, and say out loud you're trying too","then":"Munni grins. \"Caught you, Amma.\" Everyone laughs, and the phones stay down.","best":true},{"text":"Check it quickly under the table where no one can see","then":"Munni notices and quietly pulls hers out too."},{"text":"Decide phone limits are for children, not for you","then":"By the weekend, everyone is back on their phones at dinner."},{"text":"Feel guilty and quietly give up on cutting down","then":"The evenings drift back, and you feel worse about your phone than before."}],"why":"Owning a slip out loud keeps you honest and shows them how to recover."},{"prompt":"Your sister visits and says screen limits are for kids, not grown-ups. What do you say?","options":[{"text":"Agree, and pick your phone back up at dinner that night","then":"Munni watches you and reaches for her own phone."},{"text":"Tell her she sets a poor example for her own kids","then":"Your sister goes stiff, and the visit turns awkward."},{"text":"Laugh it off and quickly change the subject to something else","then":"The talk moves on. Later Munni asks if phone limits are only for children."},{"text":"Say grown-ups need limits too, so children believe in them","then":"Your sister shrugs, then asks how that works in your house.","best":true}],"why":"Children learn from what you do, so your limits need to include you."}],"debrief":"Set screen limits the whole family keeps, modelling them yourself, not one rule for the child only.","relearn":"Model the screen limits you set; 'unplug while I scroll' tells a child the rule isn't real."},
  {"id":"na-042","cat":"screens-and-modelling","type":"match","persona":"any","source":"habit practices","hook":"Match each healthy-habit area to a simple family practice.","pairs":[{"left":"Screens","right":"Agreed limits and screen-free meals"},{"left":"Stress and boredom","right":"Healthy outlets, not numbing"},{"left":"Modelling","right":"Parents keep the rules too"},{"left":"Sleep","right":"Devices out of bedrooms at night"},{"left":"Cutting screen time","right":"Crowd it out with better things"}],"relearn":"Agreed limits, healthy outlets, parents keeping the rules, device-free nights and crowding the habit out are simple practices that protect a child."},
  {"id":"na-043","cat":"screens-and-modelling","type":"reflect","hook":"Lensy: kids learn how to handle stress, screens and substances largely from watching us. Worth a look at our own habits?","prompt":"What do you think?","options":["Worth it","Look at my own","They watch us"],"affirm":"Children learn how to handle stress, screens and substances largely by watching their parents, so our own habits matter.","relearn":"Kids learn how to handle stress, screens and substances by watching us; our own habits are worth a look.","persona":"Kamla","source":"look at our habits"},
  {"id":"na-044","cat":"screens-and-modelling","type":"spot","persona":"any","source":"build healthy habits","hook":"Spot the two moves that undermine a child's healthy habits.","scene":[{"id":"a","text":"Parents modelling balance","trick":false},{"id":"b","text":"Do-as-I-say-not-as-I-do rules","trick":true},{"id":"c","text":"Shared limits and good alternatives","trick":false},{"id":"d","text":"A sudden, angry, total ban","trick":true},{"id":"e","text":"Offering appealing offline things","trick":false}],"why":"Do-as-I-say rules and a sudden angry ban undermine a child's habits; modelling balance, shared limits and outlets build them.","relearn":"Help a child build healthy habits by modelling balance, shared limits and outlets, not do-as-I-say rules or shock bans."},
  {"id":"na-045","cat":"screens-and-modelling","type":"branch","persona":"Kamla","source":"own habit too","hook":"While worrying about your son Sonu's smoking, you realise your own gutka habit may be a problem too.","steps":[{"prompt":"Sonu points at your gutka packet when you raise his smoking. What do you do?","options":[{"text":"Tell him grown-ups can decide for themselves","then":"Sonu shrugs. \"Then so can I,\" he says, and walks out."},{"text":"Hide your packets and chew only when he's out","then":"A week later Sonu finds a packet in your bag and laughs."},{"text":"Promise to quit today, then turn the talk back to him","then":"Sonu raises an eyebrow. The next day he sees you chewing again."},{"text":"Admit he has a point and say you'll work on yours too","then":"Sonu is quiet for a moment. \"Seriously?\" he asks, less defensive.","best":true}],"why":"Owning your own habit honestly makes your worry about his believable."},{"prompt":"That night you feel ashamed about your own habit. What do you do?","options":[{"text":"Call yourself a hypocrite and a failure as a parent","then":"The shame sits heavy, and you chew more to cope."},{"text":"Tell yourself your habit is nothing like his smoking","then":"You feel better for a moment, but Sonu's words keep coming back."},{"text":"Treat yourself with the same compassion you'd give Sonu","then":"The shame eases, and you start thinking about what would help you.","best":true},{"text":"Decide to deal with yours once Sonu has stopped","then":"Your packet stays in your bag, and his stays in his pocket."}],"why":"Compassion, not shame, is what makes change possible, for you and for him."},{"prompt":"You decide you want support for your habit. What do you do?","options":[{"text":"Try to quit alone and in secret, so that no one knows","then":"You manage two days, then slip, and no one knows to help."},{"text":"Call Tele-MANAS 14416 for support, and tell Sonu you did","then":"Sonu listens. \"Maybe I could talk to them too,\" he says slowly.","best":true},{"text":"Ask Sonu to keep watch on you and report every slip","then":"Sonu feels awkward policing you, and your talks get tense."},{"text":"Wait for a less busy month before you make a start","then":"The busy months keep coming, and nothing changes."}],"why":"Seeking help openly models the very help-seeking you want him to learn."}],"debrief":"Address your own habit with the same compassion you offer your child; modelling recovery is powerful.","relearn":"Tend your own habit too, with compassion; ignoring it while policing your child's undercuts it."},
  {"id":"na-046","cat":"tools-and-safety","type":"branch","persona":"Vikram","source":"be ready","hook":"A neighbour's son was found using last month, and she says she was caught completely unprepared.","steps":[{"prompt":"Walking home, you wonder what you'd do in her place. What do you do?","options":[{"text":"Learn the signs, plan a calm response, save the numbers","then":"That weekend you save Tele-MANAS 14416 and jot down how you'd want to respond.","best":true},{"text":"Assume you'll figure it out if it ever happens","then":"The thought fades. Nothing is saved and nothing is planned."},{"text":"Decide your own kids would never do that","then":"You feel reassured, and put the thought away."},{"text":"Start checking your son's phone every night, just in case","then":"You find nothing, and your son notices his apps have been opened."}],"why":"Mid-crisis is the hardest time to plan, so preparing now lets you respond calmly."},{"prompt":"Over dinner, your spouse hears the neighbour's story and says it could never happen here. What do you do?","options":[{"text":"Say any child can be affected, and plan together","then":"Your spouse is quiet, then agrees to save the numbers too.","best":true},{"text":"Agree, since your kids are doing fine","then":"The subject closes. Only you know the story kept you awake."},{"text":"Lecture the kids at dinner about staying away from drugs","then":"The kids exchange looks and eat faster. Nobody asks you anything."},{"text":"Drop it to avoid an argument at the table","then":"Your spouse moves on. Any plan stays only in your head."}],"why":"Dependence can affect any family, and a plan both parents share is one either can use."},{"prompt":"You sit down to plan how you'd respond if you ever found something. What comes first?","options":[{"text":"Stay calm, listen first, then get help together","then":"You write it on a note: breathe, listen, no shouting, call for help.","best":true},{"text":"Find out who got them into it and confront that person","then":"You picture storming a stranger's house, and the plan goes no further."},{"text":"Search their room and phone to learn everything first","then":"The plan starts with a search, and leaves no room for your child to tell you."},{"text":"Punish hard, so it never happens again","then":"Your plan now begins with anger, the very thing you wanted to avoid."}],"why":"A calm-response plan keeps you steady, so a discovery doesn't become a rupture."},{"prompt":"A few days later, the school sends home a card with Tele-MANAS 14416, Childline 1098 and 112. Where do you keep it?","options":[{"text":"In your phone, and on the fridge for everyone","then":"Your daughter reads the card on the fridge and asks what Tele-MANAS is. You explain.","best":true},{"text":"In your wallet, where only you will see it","then":"It's safe, but no one else at home knows the numbers exist."},{"text":"In a drawer, so the children don't get worried","then":"The card slides under old bills and is soon forgotten."},{"text":"Nowhere. You'll search online if you ever need them","then":"In a panic, you'd be scrolling search results instead of calling."}],"why":"Numbers saved where everyone can see them are there the instant anyone needs them."}],"debrief":"Be ready: know the signs, plan a calm response, and save the help numbers before you need them.","relearn":"Prepare a calm response and save help numbers now; mid-crisis is the hardest time to plan."},
  {"id":"na-047","type":"match","persona":"any","hook":"Match each tool to what it does.","pairs":[{"left":"A signs-and-help-finder","right":"Knowing what to watch for and where to turn"},{"left":"A calm-response plan","right":"Responding without rupture"},{"left":"Saved help lines","right":"Support and emergencies covered"},{"left":"A shared family plan","right":"Anyone home can act"},{"left":"A counsellor's contact","right":"Treatment when you need it"}],"relearn":"A signs-and-help-finder, a calm-response plan, saved lines, a shared plan and a counsellor are the core tools.","source":"the toolkit","cat":"tools-and-safety"},
  {"id":"na-048","cat":"tools-and-safety","type":"strike-rewrite","hook":"\"An app or game can treat my child's addiction.\"","myth":{"un":"An app or game can treat my child's addiction.","re":"This helps you understand and respond, but it isn't treatment; counsellors and de-addiction services provide that.","why":"Support tools point to care; they don't replace it."},"relearn":"This supports understanding and response but isn't treatment; professionals provide that.","persona":"any","source":"not treatment"},
  {"id":"na-049","cat":"tools-and-safety","type":"branch","persona":"Vikram","source":"emergency now","hook":"Your son Arnav, 16, comes home from a party confused and very drowsy. You fear he's taken something.","steps":[{"prompt":"He's slumped on the sofa and barely answers you. What do you do?","options":[{"text":"Call 112 now and get him medical help","then":"The operator answers at once and tells you help is on the way.","best":true},{"text":"Let him sleep it off and check on him later","then":"An hour later he's harder to wake. Frightened, you finally call 112."},{"text":"Shake him and shout at him to say what he took","then":"Arnav mumbles something you can't make out. Minutes pass before you call 112."},{"text":"Phone his friends first to find out what happened","then":"The first friend doesn't pick up. Precious minutes pass before you call 112."}],"why":"A possible overdose is an emergency. Calling 112 at once gets him the fastest help."},{"prompt":"The ambulance arrives, and the medic asks what Arnav may have taken. What do you do?","options":[{"text":"Tell them everything you know or suspect","then":"The medic nods and uses what you've said straight away.","best":true},{"text":"Say he's just tired, to protect his reputation","then":"The medic looks doubtful and has to work it out without your help."},{"text":"Wait for Arnav to answer for himself","then":"Arnav can't answer. The medic turns back to you, and time slips by."},{"text":"Say the family doctor can deal with it quietly","then":"The medic explains he needs hospital care now. Minutes are lost arguing."}],"why":"Telling the medical team everything you know helps them treat him quickly and safely."},{"prompt":"Arnav is home from hospital and recovering. What do you do next?","options":[{"text":"Talk with him calmly, then call Tele-MANAS 14416","then":"Arnav says he was scared too. The counsellor helps you plan follow-up support.","best":true},{"text":"Tell him he's brought shame on the whole family","then":"Arnav stops speaking to you and stays in his room for days."},{"text":"Treat it as a one-off and move on quickly","then":"Nobody talks about it. The next party invitation arrives a week later."},{"text":"Ban parties and friends until he turns eighteen","then":"Arnav agrees, too tired to argue. You both know it won't hold."}],"why":"After an emergency, calm follow-up help treats it as the health issue it is."}],"debrief":"Treat a possible overdose or any acute danger as an emergency and get medical help immediately (112, a hospital).","relearn":"In an acute emergency like a possible overdose, get medical help now; don't wait it out."},
  {"id":"na-050","type":"sort","persona":"any","hook":"Sort: a wise move in a serious situation, or one to avoid?","items":[{"id":"a","text":"Calling emergency help for acute danger"},{"id":"b","text":"Hiding it to avoid embarrassment"},{"id":"c","text":"Reaching a helpline when unsure"},{"id":"d","text":"Punishing instead of getting help"},{"id":"e","text":"Staying calm and keeping your child close"},{"id":"f","text":"Waiting out a possible overdose"}],"bins":[{"id":"wise","label":"Wise move","valence":"pos"},{"id":"avoid","label":"To avoid","valence":"neg"}],"key":{"a":"wise","c":"wise","e":"wise","b":"avoid","d":"avoid","f":"avoid"},"relearn":"Calling for acute danger, reaching a helpline and staying calm are wise; hiding, punishing and waiting it out aren't.","source":"wise vs avoid","cat":"tools-and-safety"},
  {"id":"na-051","cat":"tools-and-safety","type":"reflect","hook":"Lensy: in any acute danger, getting help fast always comes before worrying about shame or trouble. Clear?","prompt":"What do you think?","options":["Clear","Help first","Safety over shame"],"affirm":"In any acute danger, a child's safety and getting help fast always come before any worry about shame or trouble.","relearn":"In acute danger, get help fast; safety always comes before shame or trouble.","persona":"any","source":"safety over shame"},
  {"id":"na-052","type":"match","persona":"any","hook":"Match a situation to the right India support.","pairs":[{"left":"Needing to talk or find help","right":"Tele-MANAS 14416"},{"left":"A child in distress or danger","right":"Childline 1098"},{"left":"An acute medical emergency","right":"Emergency 112 or a hospital"},{"left":"Structured treatment over time","right":"A de-addiction counsellor"},{"left":"A worried question at midnight","right":"Tele-MANAS, open any time"}],"relearn":"Tele-MANAS, Childline, emergency 112 and a counsellor cover support, child-distress, emergencies and treatment.","source":"right support","cat":"tools-and-safety"},
  {"id":"na-053","type":"spot","persona":"any","hook":"Spot the two moves that won't help a child through dependence.","scene":[{"id":"a","text":"Calm connection and early help","trick":false},{"id":"b","text":"Shame and secrecy","trick":true},{"id":"c","text":"Staying involved through recovery","trick":false},{"id":"d","text":"One big crackdown to scare them","trick":true},{"id":"e","text":"A plan and saved help numbers","trick":false}],"why":"Shame, secrecy and a single crackdown push dependence into hiding; calm connection, early help and staying involved sustain recovery.","relearn":"Help a child through dependence with calm connection, early help and staying involved, not shame and crackdowns.","source":"sustainable help","cat":"tools-and-safety"},
  {"id":"na-054","cat":"tools-and-safety","type":"reflect","hook":"Lensy: spot it early, respond with calm connection, treat it as health, get help, and check your own habits. Equipped?","prompt":"What's your take?","options":["Equipped","I've got this","Ready"],"affirm":"Spotting early, responding with calm connection, treating it as health, getting help and checking your own habits equip you fully.","relearn":"You hold the kit: spot early, connect calmly, treat it as health, get help, and check your own habits.","persona":"any","source":"equipped"},
  {"id":"na-055","cat":"tools-and-safety","type":"role-play","persona":"Divya","source":"steer to help","hook":"Your partner Manish has just learned that your son Om, 15, has been smoking weed with friends.","setup":"Manish is pacing the living room.","steps":[{"prompt":"Manish says: \"I'm taking his phone, his bike, everything. He's grounded for a year.\"","options":[{"text":"\"I'm upset too. But that will push him away.\"","then":"Manish stops pacing. \"So we just do nothing?\"","best":true},{"text":"\"Yes. Come down on him as hard as you can.\"","then":"Manish nods grimly. \"Finally, we agree on something.\""},{"text":"\"You always overreact. Let me handle Om myself.\"","then":"Manish's face hardens. \"So I'm the problem now?\""},{"text":"\"Maybe just take his phone for a week and see how he does.\"","then":"Manish frowns. \"A week? That's nothing.\""}],"why":"Naming your own feelings while steering away from punishment keeps you both on Om's side."},{"prompt":"Manish sighs and says: \"Part of me wants to scare him. Part of me is scared for him.\"","options":[{"text":"\"Me too. We can be firm and still keep him close.\"","then":"Manish sits down heavily. \"Firm how, then?\"","best":true},{"text":"\"Then scare him. Fear is the only thing that works.\"","then":"Manish nods. \"Exactly. He needs to be scared.\""},{"text":"\"It's just weed. Lots of kids try it at his age.\"","then":"Manish stares at you. \"You can't be serious.\""},{"text":"\"Fine, do it your way. I'm staying out of it.\"","then":"Manish shrugs. \"Then I'll handle it.\" He heads for Om's room, then stops."}],"why":"Being firm about the behaviour and staying close to the child are not opposites."},{"prompt":"Manish asks: \"So what do we actually do, then?\"","options":[{"text":"\"Talk to him together, calmly, then call a counsellor.\"","then":"Manish rubs his face. \"Okay. Together. I'll try to stay calm.\"","best":true},{"text":"\"Search his room tonight and see what else he's hiding.\"","then":"Manish nods. \"Good. I'll start with the cupboard.\""},{"text":"\"Ask his friends' parents to keep their boys away from him.\"","then":"Manish brightens. \"Yes. Cut him off from that lot.\""},{"text":"\"Let's wait and see if he stops on his own.\"","then":"Manish shakes his head. \"And do nothing? No.\""}],"why":"A calm talk together, then the right help, keeps Om reachable and safe."},{"prompt":"Outside Om's door, Manish whispers: \"What if he lies to us?\"","options":[{"text":"\"Then we stay calm. He may need time to trust us.\"","then":"Manish nods slowly. \"Okay. No shouting.\"","best":true},{"text":"\"Then we take everything away until he tells the truth.\"","then":"Manish's jaw sets. \"Right. That's plan B.\""},{"text":"\"Then we check his phone and find out for ourselves.\"","then":"Manish nods. \"I know his password.\""},{"text":"\"Then you do the talking. I can't handle this.\"","then":"Manish looks at you. \"You're leaving it all to me?\""}],"why":"Honesty grows when a child feels safe, so patience now keeps the next talk possible."}],"relearn":"Steering a co-parent from punishment toward calm connection and help keeps a struggling child reachable and safe."},
  {"id":"na-056","cat":"spot-the-signs","type":"role-play","persona":"Vikram","source":"gentle check-in","hook":"Dev, 16, has been quiet and moody for weeks. You want to check in, not interrogate.","setup":"He's alone in the kitchen, making Maggi.","steps":[{"prompt":"Dev glances up and asks: \"What? Why are you staring?\"","options":[{"text":"\"You've seemed a bit different lately. I'm here if anything's up.\"","then":"Dev shrugs. \"I'm fine. Just tired.\" But he stays in the kitchen.","best":true},{"text":"\"What are you hiding from me? I want the truth right now.\"","then":"Dev drops the spoon. \"Nothing! Why do you always think the worst?\""},{"text":"\"Nothing, beta. Just making sure you eat properly for once.\"","then":"\"Okay,\" Dev says, and eats without looking up."},{"text":"\"Your mother and I have been talking about you, and we're worried.\"","then":"Dev stiffens. \"Great. So now I'm a problem you two discuss.\""}],"why":"A gentle, no-judgement opener tells him it's safe to talk, where an interrogation makes him clam up."},{"prompt":"After a pause, Dev mutters: \"Everyone keeps getting on my case about marks.\"","options":[{"text":"\"That sounds heavy. What part is weighing on you most?\"","then":"Dev pokes at his noodles. \"Maths. And I can't sleep because of it.\"","best":true},{"text":"\"If you studied instead of scrolling, nobody would be on your case.\"","then":"Dev rolls his eyes. \"Here we go again.\""},{"text":"\"Marks aren't everything. Don't worry about it.\"","then":"\"Easy for you to say,\" Dev mutters, and goes quiet."},{"text":"\"Okay. Then I'll stay off your case too.\"","then":"Dev nods, relieved, and goes back to his noodles."}],"why":"Taking his worry seriously and asking more shows him you're really listening."},{"prompt":"Picking up his bowl, Dev asks: \"Can I go now?\"","options":[{"text":"\"Sure. If it ever feels too big, come to me.\"","then":"Dev pauses at the door. \"Okay. Maybe later.\"","best":true},{"text":"\"Go, but I'll be keeping a much closer eye on you.\"","then":"Dev's jaw tightens. \"Great. Thanks.\" He's gone."},{"text":"\"Not until you tell me what's really going on.\"","then":"Dev folds his arms and stares at the floor. The silence stretches."},{"text":"\"Sure. We'll talk properly once your exams are over.\"","then":"\"Fine,\" Dev says. The door closes, and exams are weeks away."}],"why":"Ending with an open door, not a threat, makes it likelier he comes back to you."}],"relearn":"A gentle, no-judgement opener invites a worried teen to talk, where an interrogation makes them clam up."},
  {"id":"na-057","cat":"spot-the-signs","type":"sort","hook":"Sort: a sign of possible dependence, or just normal ups and downs?","items":[{"id":"a","text":"Needing more and more for the same effect"},{"id":"b","text":"An off day or a bad mood"},{"id":"c","text":"Lying and sneaking to keep a habit going"},{"id":"d","text":"A new hobby they enjoy"},{"id":"e","text":"Can't cut down even when they try"},{"id":"f","text":"Sleeping in late on a holiday"}],"bins":[{"id":"sign","label":"Possible sign","valence":"uhoh"},{"id":"normal","label":"Normal","valence":"pos"}],"key":{"a":"sign","b":"normal","c":"sign","d":"normal","e":"sign","f":"normal"},"relearn":"Needing more, sneaking, and not being able to cut down are signs; an off day, a new hobby or a late holiday lie-in aren't.","persona":"any","source":"sign or normal"},
  {"id":"na-058","cat":"spot-the-signs","type":"branch","persona":"Divya","source":"look closer","hook":"Your daughter Nandini came home late smelling of smoke. You tell yourself you're overreacting.","steps":[{"prompt":"It's the second time this month. What do you do?","options":[{"text":"Dismiss it so you don't have to deal with it","then":"The week passes, and a small worry grows quietly in the background."},{"text":"Search her bag that night","then":"You find a lighter and nothing else, and you feel guilty for looking."},{"text":"Ask her younger sister if Nandini smokes","then":"Her sister shrugs, then tells Nandini that you asked."},{"text":"Take it seriously, and keep a calm eye on things","then":"Over the week you notice she's quieter, and her pocket money runs out fast.","best":true}],"why":"Taking a worry seriously, calmly, helps you catch a problem early."},{"prompt":"At the weekend Nandini seems withdrawn and skips her dance class. What do you do?","options":[{"text":"Decide teenagers are moody and let it pass","then":"She skips the next class too, and nothing is said."},{"text":"Tell her she can't go out until she explains","then":"Nandini says she's just tired and goes to her room."},{"text":"Note it, and look for a quiet time to check in","then":"On Sunday evening she's in the kitchen with you, making chai.","best":true},{"text":"Message her dance teacher to ask what's wrong","then":"The teacher doesn't know, and Nandini feels checked up on."}],"why":"One sign is not a verdict, but several together are worth gently checking."},{"prompt":"One evening you're alone together in the kitchen. What do you say?","options":[{"text":"Ask her straight out whether she's been smoking","then":"Nandini flushes. \"It was other people. Not me.\""},{"text":"Say she seems low lately and you're here to listen","then":"Nandini hesitates, then says some friends smoke and she's been joining in.","best":true},{"text":"Say nothing, since you might be overreacting","then":"The chai gets made in silence, and the moment passes."},{"text":"Warn her that smoking will ruin her health and looks","then":"Nandini rolls her eyes and takes her chai to her room."}],"why":"A gentle, open question invites honesty far more than an accusation."},{"prompt":"Soon after, Nandini tells you she has tried smoking a few times. What do you do?","options":[{"text":"Thank her for telling you, and ask what it's been like","then":"She says it began as a joke, but now she wants one after every class.","best":true},{"text":"Ban her from seeing the friends she smokes with","then":"Nandini goes silent and starts meeting them in secret."},{"text":"Say a few times is nothing to worry about","then":"She relaxes, and the topic closes."},{"text":"Tell her how disappointed you are that she's been smoking","then":"Nandini's face falls, and she says she wishes she hadn't told you."}],"why":"Staying calm when she opens up keeps her talking to you."},{"prompt":"A few weeks on, it's clear Nandini now craves a cigarette every day. What do you do?","options":[{"text":"Tell her to just stop right now, since she's only just started","then":"Nandini tries, fails, and starts hiding it from you."},{"text":"Keep it within the family and handle it quietly","then":"Weeks pass, and nobody who could help knows."},{"text":"Wait and see if it passes on its own","then":"A month later, it's a daily habit she can't shake."},{"text":"Offer to call Tele-MANAS 14416 together, like any health issue","then":"Nandini nods. \"Can you stay with me while I talk?\"","best":true}],"why":"Getting help early, before it becomes a crisis, gives the best chance."}],"debrief":"Take a worrying sign seriously enough to look closer gently, rather than dismissing it to avoid worry.","relearn":"Don't talk yourself out of a real worry; look closer gently rather than dismissing it."},
  {"id":"na-059","cat":"spot-the-signs","type":"spot","hook":"Spot the two ways of watching that break trust.","scene":[{"id":"a","text":"Noticing patterns over time, calmly","trick":false},{"id":"b","text":"One panicked search of their room","trick":true},{"id":"c","text":"Keeping the relationship open","trick":false},{"id":"d","text":"Reading their phone in secret","trick":true},{"id":"e","text":"Letting them know you've noticed and care","trick":false}],"why":"A panicked search and secret phone-reading break trust; calm pattern-noticing and an open relationship are the steady way.","relearn":"Watch for dependence with calm pattern-noticing and an open relationship, not snooping.","persona":"any","source":"steady watching"},
  {"id":"na-060","cat":"respond-dont-rupture","type":"role-play","persona":"Vikram","source":"disarm with calm","hook":"Your daughter Anika, 15, knows you found the vape in her drawer this afternoon.","setup":"She stands in the kitchen doorway, arms crossed.","steps":[{"prompt":"Anika snaps: \"Go on then. Shout at me. Get it over with.\"","options":[{"text":"\"You should be ashamed of yourself, sneaking around like this.\"","then":"Anika's eyes flash. \"Fine. I'm ashamed. Can I go now?\""},{"text":"\"Don't take that tone with me, young lady.\"","then":"\"Whatever,\" Anika says, and turns to leave."},{"text":"\"I'm not here to shout. I love you, and I want to understand.\"","then":"Anika blinks. \"Seriously?\" Her arms loosen a little.","best":true},{"text":"\"Relax. I'm not angry at all. It's only a vape.\"","then":"Anika looks confused. \"So you don't even care?\""}],"why":"Leading with calm and love lowers her guard so a real talk can start."},{"prompt":"Anika asks: \"So what happens to me now?\"","options":[{"text":"\"You're grounded, and your phone is mine for a month.\"","then":"Anika shrugs. \"See? Knew it.\""},{"text":"\"We talk, and we work this out together.\"","then":"She hesitates. \"Okay. What do you want to know?\"","best":true},{"text":"\"That depends on whether you tell me everything right now.\"","then":"Anika's mouth sets. \"Then I'm telling you nothing.\""},{"text":"\"I haven't decided yet. Let's see how you behave.\"","then":"Anika watches you warily. \"Okay,\" she says, choosing her words."}],"why":"Offering partnership instead of punishment keeps her talking."},{"prompt":"Later that night, Anika admits: \"Everyone vapes at tuition. I just didn't want to be left out.\"","options":[{"text":"\"That sounds hard. Can we think of ways to handle it together?\"","then":"Anika nods slowly. \"Maybe. I don't even like it that much.\"","best":true},{"text":"\"Then you'll need new friends, starting from tomorrow.\"","then":"Anika rolls her eyes. \"You don't get to choose my friends.\""},{"text":"\"If everyone jumped off a bridge, would you jump too?\"","then":"Anika groans. \"That's not the same thing at all.\""},{"text":"\"Okay. Just promise me you'll never do it again.\"","then":"\"Fine, I promise,\" Anika says quickly, eyes on the floor."}],"why":"Understanding the pressure she faces helps you plan together, not just forbid."}],"relearn":"Leading with calm and love disarms a defensive child and keeps the conversation, and the help, possible."},
  {"id":"na-061","type":"sort","persona":"any","source":"open or slam","relearn":"'I'm on your side', calm curiosity and togetherness keep the door open; 'dead to me', screaming and shame slam it shut.","hook":"Sort each response: keeps the door open, or slams it shut?","items":[{"id":"a","text":"'Let's talk, I'm on your side'"},{"id":"b","text":"'You're dead to me'"},{"id":"c","text":"Staying calm and curious"},{"id":"d","text":"Screaming and threats"},{"id":"e","text":"'We'll get through this together'"},{"id":"f","text":"Shaming them in front of others"}],"bins":[{"id":"open","label":"Keeps it open","valence":"pos"},{"id":"slam","label":"Slams it shut","valence":"neg"}],"key":{"a":"open","b":"slam","c":"open","d":"slam","e":"open","f":"slam"},"cat":"respond-dont-rupture"},
  {"id":"na-062","cat":"respond-dont-rupture","type":"branch","persona":"Divya","source":"limit with warmth","hook":"Your son Kiaan, 14, games until 3 am on school nights, and his marks are slipping.","steps":[{"prompt":"You want to set a real limit without it becoming a war. What do you do first?","options":[{"text":"Sit with him, say you're worried, and ask what would help","then":"Kiaan shrugs, then admits he's tired all the time.","best":true},{"text":"Tell him the Wi-Fi goes off at nine, starting tonight","then":"Kiaan explodes and slams his door."},{"text":"Let it slide a little longer to avoid a fight","then":"Another week of 3 am nights goes by."},{"text":"Write the new rules on the fridge for him to find","then":"Kiaan reads them, rolls his eyes, and ignores them."}],"why":"Starting with worry and a question opens a talk instead of a fight."},{"prompt":"His teacher calls about his marks, and Kiaan says every other kid games late too. What do you do?","options":[{"text":"Stay firm, and agree a cut-off time together","then":"Kiaan grumbles, but agrees to devices off at eleven.","best":true},{"text":"Say other kids don't matter, and set ten o'clock yourself","then":"Kiaan storms off. The limit feels like a war now."},{"text":"Give in and let him set his own hours","then":"Kiaan is thrilled, and games until 3 am again."},{"text":"Agree a limit, but just for him, not the rest of you","then":"Kiaan points at your phone. \"So why do you get to?\""}],"why":"A clear limit set with him, with warmth, holds both the boundary and the bond."},{"prompt":"A few nights later, he's still gaming at midnight. What do you do?","options":[{"text":"Calmly ask for the phone, and talk about bedtime tomorrow","then":"Kiaan sighs and hands it over. \"Fine. Goodnight.\"","best":true},{"text":"Warn coldly that one more time and the console goes for good","then":"Kiaan goes silent, and avoids you all the next day."},{"text":"Let it go this once, to keep the peace","then":"Midnight becomes one, and then two."},{"text":"Take the phone without a word and leave the room","then":"Kiaan fumes. The phone stays out, but he won't speak to you."}],"why":"Calm follow-through with warmth keeps the limit without breaking the bond."}],"debrief":"Pair a clear limit with warmth and connection so a boundary doesn't become a rupture.","relearn":"Hold limits warmly; a cold ultimatum can rupture the connection a struggling child needs."},
  {"id":"na-063","type":"match","persona":"any","source":"connecting moves","relearn":"Defensiveness, lies, relapse, silence and lashing out each meet a connecting move that keeps a child reachable.","hook":"Match each hard moment to a connecting move.","pairs":[{"left":"They're defensive","right":"Lower your voice and your stakes"},{"left":"They lie","right":"Name it calmly, keep the door open"},{"left":"They relapse","right":"Disappointment without rejection"},{"left":"They go silent","right":"Sit nearby, no pressure to talk"},{"left":"They lash out","right":"Stay steady, don't match the heat"}],"cat":"respond-dont-rupture"},
  {"id":"na-064","cat":"its-a-health-issue","type":"role-play","persona":"Vikram","source":"counter the shame","hook":"Your son Rishi, 17, is struggling with his drinking and has started calling himself names.","setup":"He sits slumped on the steps outside.","steps":[{"prompt":"Rishi says: \"I'm just a junkie. I'm hopeless.\"","options":[{"text":"\"You have a health problem we can treat. You're not hopeless.\"","then":"Rishi looks up. \"You don't think I'm a lost cause?\"","best":true},{"text":"\"Well, you've made your bed now.\"","then":"Rishi's face hardens. \"Yeah. Thanks, Papa.\""},{"text":"\"Don't say that. Just stop drinking, and then you won't be.\"","then":"Rishi shakes his head. \"I've tried. I can't.\""},{"text":"\"Don't be so dramatic. You're absolutely fine.\"","then":"Rishi laughs bitterly. \"I'm not fine.\""}],"why":"Replacing a shaming label with the truth restores the hope he needs."},{"prompt":"Rishi asks: \"Why would you even bother with me?\"","options":[{"text":"\"Because you're my son, and I'm not giving up on you.\"","then":"Rishi's eyes fill. \"Even after all this?\"","best":true},{"text":"\"Honestly, I'm starting to wonder that myself.\"","then":"Rishi stands up. \"Figured.\""},{"text":"\"Because your mother would never forgive me otherwise.\"","then":"Rishi looks away. \"So it's for her.\""},{"text":"\"Because you'll make us proud again one day.\"","then":"Rishi winces. \"And if I don't?\""}],"why":"Support with no conditions is what keeps a struggling child reachable."},{"prompt":"Rishi says: \"Even if I wanted help, where would I start?\"","options":[{"text":"\"With a counsellor. I'll find one and come with you.\"","then":"Rishi nods slowly. \"Okay. If you come.\"","best":true},{"text":"\"That's your problem to figure out.\"","then":"Rishi shrugs. \"Then I won't.\""},{"text":"\"Start by pulling yourself together.\"","then":"Rishi sighs. \"That's what I keep failing at.\""},{"text":"\"Look it up online. There's loads of advice out there.\"","then":"Rishi scrolls, then puts the phone down. \"It's all so confusing.\""}],"why":"Offering a concrete first step, and your company, makes help feel reachable."}],"relearn":"Replacing a shaming self-label with 'you have a treatable health problem, and I'm not giving up' restores the hope a child needs to recover."},
  {"id":"na-065","cat":"its-a-health-issue","type":"sort","hook":"Sort: treats dependence as the health issue it is, or as a moral failing?","items":[{"id":"a","text":"Seeking treatment without blame"},{"id":"b","text":"Calling the child a disgrace"},{"id":"c","text":"Believing recovery is possible"},{"id":"d","text":"Treating it as a character flaw"},{"id":"e","text":"Making a plan with a counsellor"},{"id":"f","text":"Punishing it to 'teach a lesson'"}],"bins":[{"id":"health","label":"Health issue","valence":"pos"},{"id":"moral","label":"Moral-failing view","valence":"neg"}],"key":{"a":"health","b":"moral","c":"health","d":"moral","e":"health","f":"moral"},"relearn":"Seeking treatment, believing in recovery and planning with a counsellor treat it as health; 'disgrace', 'character flaw' and punishing-to-teach don't.","persona":"any","source":"health or moral"},
  {"id":"na-066","cat":"its-a-health-issue","type":"branch","persona":"Vikram","source":"child not condition","hook":"Your son Rehan has been using something for months. You catch yourself thinking he's become a bad person.","steps":[{"prompt":"He walks in late again, avoiding your eyes. What do you do?","options":[{"text":"Remind yourself he's unwell, and greet him calmly","then":"Rehan looks surprised. He mumbles sorry and sits down to eat.","best":true},{"text":"Let your judgement show in a long, cold look","then":"Rehan goes straight to his room. The door clicks shut."},{"text":"Tell him he's become a disgrace to this family","then":"Rehan's jaw tightens, and he walks back out of the house."},{"text":"Stay calm on the outside, but stop asking about his day","then":"Rehan notices the distance and stops talking to you too."}],"why":"Seeing him as unwell, not bad, lets you respond with care instead of contempt."},{"prompt":"Your brother calls Rehan 'rotten' and says you should cut him off. What do you do?","options":[{"text":"Say Rehan has a health problem, and he's still your son","then":"Your brother shakes his head, but drops it.","best":true},{"text":"Agree he's gone bad, and start keeping your distance","then":"Rehan notices you pulling away and goes quieter still."},{"text":"Tell your brother his own children aren't perfect","then":"The call ends in an argument, and nothing about Rehan changes."},{"text":"Say nothing, and move the talk on to something else","then":"Your brother takes your silence as agreement."}],"why":"Separating your child from the condition keeps care and hope alive."},{"prompt":"A week later, Rehan asks if you think he's a bad person. What do you say?","options":[{"text":"Say he isn't bad but unwell, and you want to help","then":"Rehan looks at the floor. \"I don't know how to stop.\"","best":true},{"text":"Say you don't know what to think any more","then":"Rehan nods, hurt, and goes back to his room."},{"text":"Say good people don't do what he's doing","then":"Rehan's face shuts. \"Right. Thanks.\""},{"text":"Say no, and that he just needs to try harder","then":"Rehan sighs. \"I have tried.\""}],"why":"Separating him from the condition, and offering help, gives him somewhere to turn."}],"debrief":"Separate your child from the condition: they have a health problem and aren't a bad person.","relearn":"See your child as unwell, not bad; the condition isn't who they are. Care beats contempt."},
  {"id":"na-067","cat":"its-a-health-issue","type":"role-play","persona":"Kamla","source":"reframe to relative","hook":"Your son Pappu, 15, games through the night and has stopped going to school.","setup":"Your sister-in-law drops in for tea.","steps":[{"prompt":"Your sister-in-law says: \"He's not sick. He's just spoilt.\"","options":[{"text":"\"It's a real health condition. What helps is treatment.\"","then":"She sets down her cup. \"Treatment? For games?\"","best":true},{"text":"\"Maybe you're right. We did spoil him.\"","then":"She nods, pleased. \"A firm hand is all he needs.\""},{"text":"\"How dare you judge my son like that.\"","then":"She stiffens. \"I'm only saying what everyone thinks.\""},{"text":"\"He's just going through a phase. It'll pass soon enough.\"","then":"\"A long phase,\" she says, unconvinced."}],"why":"Firmly naming it as a health condition protects him from stigma-driven contempt."},{"prompt":"She scoffs: \"Now people even call gaming an illness. Can you imagine?\"","options":[{"text":"\"Gaming disorder is recognised. It's hard to stop.\"","then":"She frowns. \"I didn't know that was real.\"","best":true},{"text":"\"I don't know. Maybe it isn't one.\"","then":"\"See?\" she says. \"He needs discipline.\""},{"text":"\"You wouldn't understand. You barely use a phone.\"","then":"She looks hurt. \"No need to be rude.\""},{"text":"\"A doctor would know that. I can't really say.\"","then":"She shrugs. \"So even you don't know.\""}],"why":"Knowing gaming disorder is recognised lets you answer doubt calmly."},{"prompt":"She asks: \"So what will you do? Just let him play?\"","options":[{"text":"\"We're getting him help, and we'll stand by him.\"","then":"She pauses. \"Well. Tell me if I can help.\"","best":true},{"text":"\"We'll lock his phone away until he learns to behave.\"","then":"\"Good,\" she says. \"About time.\""},{"text":"\"Nothing. It's none of anyone's business.\"","then":"She raises her eyebrows. \"Suit yourself.\""},{"text":"\"We'll wait and see if he grows out of it.\"","then":"She shrugs. \"Hope you're right.\""}],"why":"Treatment and support, not contempt or waiting, is what helps him recover."}],"relearn":"Firmly reframing dependence as a health condition needing treatment protects your child from stigma-driven contempt."},
  {"id":"na-068","cat":"its-a-health-issue","type":"spot","hook":"Spot the two lines that crush the hope a child needs to recover.","scene":[{"id":"a","text":"'This is treatable and you can recover'","trick":false},{"id":"b","text":"'You're a lost cause'","trick":true},{"id":"c","text":"'I'm in your corner through this'","trick":false},{"id":"d","text":"'You'll never be any different'","trick":true},{"id":"e","text":"'People recover from this; so can you'","trick":false}],"why":"'Lost cause' and 'never be any different' crush the hope recovery needs; the others affirm it's treatable and you're in your child's corner.","relearn":"Catch the hope-crushing lines; support recovery with belief that it's treatable and you're in their corner.","persona":"any","source":"supports recovery"},
  {"id":"na-069","cat":"get-the-right-help","type":"role-play","persona":"Divya","source":"first call","hook":"Your daughter Riya's vaping has become constant. You're calling a de-addiction service for the first time.","setup":"Your hands are cold as someone picks up.","steps":[{"prompt":"The counsellor says: \"Hello, how can I help you today?\"","options":[{"text":"\"I'm worried my daughter is dependent on vaping.\"","then":"\"Thank you for calling. Tell me what you've noticed.\"","best":true},{"text":"\"Sorry, wrong number. Never mind.\"","then":"\"That's alright. We're here any time.\" Ten minutes later, you call back."},{"text":"\"I need you to fix my daughter's vaping habit.\"","then":"\"We'll try to help. First, what's been happening?\""},{"text":"\"It's probably nothing, but my daughter vapes a bit.\"","then":"\"Alright. How often would you say, roughly?\""}],"why":"A simple, honest opening is all a service needs to start helping."},{"prompt":"The counsellor asks: \"How long has this been going on, and what worries you most?\"","options":[{"text":"\"About a year. She can't go a few hours without it.\"","then":"\"That's useful to know. It sounds hard for both of you.\"","best":true},{"text":"\"I don't know. I'm a terrible mother for not noticing.\"","then":"\"This isn't about blame. Let's focus on Riya for now.\""},{"text":"\"Just tell me what to do to stop her.\"","then":"\"Let's understand it first, so the plan actually fits her.\""},{"text":"\"A while. I'd rather not go into the details.\"","then":"\"That's okay. The more you share, the better I can help.\""}],"why":"Honest details, even rough ones, help the service guide you well."},{"prompt":"The counsellor says: \"We can set up a session for you and Riya. Would that work?\"","options":[{"text":"\"Yes. I'll talk to Riya tonight, and we'll come together.\"","then":"\"Good. We'll see you both on Thursday, then.\"","best":true},{"text":"\"Could you see her alone, without me there?\"","then":"\"We can, but it usually helps to have family involved too.\""},{"text":"\"I'll book it and bring her along without telling her why.\"","then":"\"She may feel tricked. It helps if she knows beforehand.\""},{"text":"\"Let me think it over and call you back later.\"","then":"\"Of course. Call whenever you're ready.\""}],"why":"Saying yes, and bringing her in openly, gives help the best start."}],"relearn":"A simple, honest opening is all a service needs; you don't need the perfect words to start getting help."},
  {"id":"na-070","cat":"get-the-right-help","type":"sort","hook":"Sort: gets a child effective help, or delays it?","items":[{"id":"a","text":"Seeing a professional early"},{"id":"b","text":"Waiting for rock bottom"},{"id":"c","text":"A family-inclusive treatment plan"},{"id":"d","text":"Keeping it a total secret"},{"id":"e","text":"Saving the helpline numbers now"},{"id":"f","text":"Chasing a 'guaranteed instant cure'"}],"bins":[{"id":"helps","label":"Gets help","valence":"pos"},{"id":"delays","label":"Delays help","valence":"neg"}],"key":{"a":"helps","b":"delays","c":"helps","d":"delays","e":"helps","f":"delays"},"relearn":"Early professional help, a family-inclusive plan and saved numbers get help; rock-bottom waiting, secrecy and 'cures' delay it.","persona":"any","source":"helps or delays"},
  {"id":"na-071","cat":"get-the-right-help","type":"branch","persona":"Vikram","source":"keep looking","hook":"A month into counselling for her vaping, your daughter Meera, 15, says the sessions feel like a lecture.","steps":[{"prompt":"She asks not to go back. What do you do?","options":[{"text":"Ask the counsellor about another approach or someone else","then":"The counsellor suggests a colleague who works mainly with teenagers.","best":true},{"text":"Decide counselling just doesn't work for her","then":"Meera is relieved. The vaping carries on, and so does your worry."},{"text":"Make her keep going to the same counsellor, no discussion","then":"Meera goes, but sits through each session staring at the floor."},{"text":"Let her take a few months off from help, then see","then":"Meera promises to cut down on her own. The months pass without help."}],"why":"One poor fit doesn't mean nothing works; the right person or approach often changes things."},{"prompt":"Your mother says: \"These counsellors are useless. Just be stricter with her.\" What do you do?","options":[{"text":"Say the first fit was wrong, and a better one is worth finding","then":"Your mother sniffs, but asks what a new counsellor would do differently.","best":true},{"text":"Agree, and set much stricter rules for Meera at home instead","then":"Meera starts vaping away from home and coming back later."},{"text":"Tell her she has no idea what she's talking about","then":"Your mother goes silent. Dinners are tense for days."},{"text":"Say you'll wait a few months before trying someone new","then":"Your mother nods. Meera's vaping carries on while you wait."}],"why":"Explaining calmly keeps family on side, and a poor fit is a reason to keep looking, not to crack down."},{"prompt":"You find a counsellor who works with teens, and Meera agrees to one visit. Afterwards she's quiet. What do you do?","options":[{"text":"Ask how it felt, and whether she'd go back","then":"She shrugs. \"She actually listened. I might go again.\"","best":true},{"text":"Ask what she told the counsellor about the vaping","then":"Meera tenses. \"Why? So you can check up on me?\""},{"text":"Say nothing and hope she brings it up","then":"Meera goes to her room. You don't know what she made of it."},{"text":"Tell her this one had better work, because you're out of options","then":"Meera's face falls. \"So if it doesn't, it's my fault?\""}],"why":"Asking how the fit felt, not what she said, respects her privacy and helps you both judge it."},{"prompt":"Two weeks later, Meera says she likes the new counsellor but still vapes sometimes. What do you do?","options":[{"text":"Say that's normal early on, and keep going with this counsellor","then":"Meera looks relieved. \"Okay. She said it would take time too.\"","best":true},{"text":"Decide this one isn't working either and start searching again","then":"Meera groans. \"I only just started trusting her.\""},{"text":"Check her bag each evening to see if she's stopped","then":"Meera starts hiding the vape better and stops mentioning it."},{"text":"Keep going, but say you expect her to stop fully by next month","then":"Meera nods, but looks worried. \"What if I can't?\""}],"why":"Recovery takes time, so sticking with a good fit matters more than instant results."}],"debrief":"If the first help doesn't fit, keep looking for the right professional or approach instead of giving up.","relearn":"Keep searching for the right-fit help; one poor fit doesn't mean nothing can help your child."},
  {"id":"na-072","cat":"get-the-right-help","type":"match","hook":"Match each worry about getting help to the reassuring truth.","pairs":[{"left":"'It's shameful to ask'","right":"It's wise, like any health issue"},{"left":"'It won't work'","right":"Treatment helps and recovery is real"},{"left":"'We're alone in this'","right":"Services and helplines are there"},{"left":"'It's too late for our child'","right":"Recovery is real with support"},{"left":"'They'll blame us as parents'","right":"Counsellors work with families"}],"relearn":"Each worry has a reassurance: it's wise, treatment works, you're not alone, it's not too late, and counsellors are with you.","persona":"any","source":"worry to truth"},
  {"id":"na-073","cat":"get-the-right-help","type":"role-play","persona":"Vikram","source":"encourage to treatment","hook":"Your son Farhan, 17, keeps refusing to see a counsellor about his drinking.","setup":"Tonight he's calm, and you sit down beside him.","steps":[{"prompt":"Farhan says: \"I'm not going to some rehab place. I'm not crazy.\"","options":[{"text":"\"It's health help, like seeing a doctor. I'll come too.\"","then":"Farhan glances at you. \"You'd actually come?\"","best":true},{"text":"\"Go to rehab or you're out of this house.\"","then":"Farhan stands up. \"Fine. Maybe I'll just leave, then.\""},{"text":"\"Okay, forget it. It's your life.\"","then":"Farhan shrugs. \"Good.\" At the door, he stops. \"It's not that simple, though.\""},{"text":"\"It's not rehab. It's a chat, and you'll be done in an hour.\"","then":"\"One hour? And then you'll leave me alone?\""}],"why":"Offering to go with him, and calling it health help, invites him in without force."},{"prompt":"The next evening, Farhan says: \"Everyone will think I'm a drunk.\"","options":[{"text":"\"It's private health care. I'll be with you each step.\"","then":"Farhan picks at his sleeve. \"Private? Like, no one at college?\"","best":true},{"text":"\"Well, whose fault would that be?\"","then":"Farhan's face closes. \"Knew you'd say that.\""},{"text":"\"No one will know. We'll say you're at tuition.\"","then":"Farhan snorts. \"So even you think it's shameful.\""},{"text":"\"Then stop drinking, and there's nothing to know.\"","then":"\"If it were that easy, I would have,\" he mutters."}],"why":"Reassuring him about privacy, and that you're with him, lowers the shame blocking help."},{"prompt":"Farhan asks: \"What if I go and it doesn't work?\"","options":[{"text":"\"Then we try again, or someone else. I'm not giving up.\"","then":"Farhan nods slowly. \"Okay. One visit.\"","best":true},{"text":"\"It will work. You'll be fine in a week.\"","then":"Farhan brightens. \"A week? That's all?\""},{"text":"\"Then it's on you for not trying hard enough.\"","then":"Farhan pulls back. \"See? It's always my fault.\""},{"text":"\"Let's not worry about that yet. Just try going the once.\"","then":"Farhan shrugs. \"Fine, but I'm not promising anything.\""}],"why":"Promising to keep going with him, not a quick fix, makes trying feel safe."},{"prompt":"A few days later, Farhan says quietly: \"If I go, I'm scared of what they'll ask.\"","options":[{"text":"\"That's normal. Tell them only what you're ready to.\"","then":"Farhan exhales. \"Okay. Will you wait outside?\"","best":true},{"text":"\"Don't be silly. There's nothing to be scared of.\"","then":"Farhan goes quiet. \"Forget I said anything.\""},{"text":"\"If you're scared, maybe you're not ready yet.\"","then":"Farhan looks relieved. \"Yeah. Maybe next month.\""},{"text":"\"Just tell them everything. Hold nothing back.\"","then":"Farhan tenses. \"Everything? That's worse.\""}],"why":"Naming fear as normal, and letting him choose what to share, helps him take the step."}],"relearn":"Encouraging with companionship and 'you're not alone' invites a child toward help better than threats and ultimatums."},
  {"id":"na-074","cat":"get-the-right-help","type":"spot","hook":"Lensy: spot the two moves that close the door to real help.","scene":[{"id":"a","text":"Reaching out early without shame","trick":false},{"id":"b","text":"Hiding it until it explodes","trick":true},{"id":"c","text":"Involving the family in treatment","trick":false},{"id":"d","text":"Punishing and threatening to force a stop","trick":true},{"id":"e","text":"Choosing a recognised counsellor","trick":false}],"why":"The two caught moves, hiding it and punishing, close the door to help; reaching out early and involving family open it.","relearn":"Open the door to help by reaching out early and involving the family, not hiding it or punishing your way through.","persona":"any","source":"open to help"},
  {"id":"na-075","cat":"screens-and-modelling","type":"role-play","persona":"Kamla","source":"own the hypocrisy","hook":"You've just set screen limits for your daughter Munni, 13. She isn't impressed.","setup":"She points at the phone in your hand.","steps":[{"prompt":"Munni says: \"You're on your phone all day, Amma. That's so hypocritical.\"","options":[{"text":"\"You're right. I'll keep the same limits, with you.\"","then":"Munni blinks. \"Wait, really? You too?\"","best":true},{"text":"\"Don't be cheeky. The rules are for you, not me.\"","then":"Munni rolls her eyes. \"Then they're not real rules.\""},{"text":"\"I use my phone for work. That's different.\"","then":"Munni scoffs. \"You watch serials, Amma.\""},{"text":"\"Let's talk about my phone some other time, beta.\"","then":"Munni crosses her arms. \"You always say that, Amma.\""}],"why":"Owning the double standard gives the rules integrity and models honesty."},{"prompt":"Next morning Munni asks: \"Will you keep your phone away at meals, like me?\"","options":[{"text":"\"I'll try to use it less. We'll see how it goes.\"","then":"Munni folds her arms. \"That's not a yes, Amma.\""},{"text":"\"My phone is my business. Just keep to yours.\"","then":"Munni shrugs. \"Okay. Then I'll make my own rules too.\""},{"text":"\"Yes, but I can take it out for work calls.\"","then":"Munni raises an eyebrow. \"Then every call will be work.\""},{"text":"\"Yes. None at meals or after nine. Remind me.\"","then":"Munni smirks. \"Oh, I will,\" she says, and shakes your hand.","best":true}],"why":"Clear limits that you keep too make the plan fair and easy to check."},{"prompt":"A week later Munni says: \"You were on your phone at dinner yesterday.\"","options":[{"text":"\"It was urgent, Munni. Stop keeping score on me.\"","then":"Munni goes quiet. \"Fine. Forget the rules, then,\" she mutters."},{"text":"\"So? You're on yours far more than I am.\"","then":"Munni's face falls. \"That's not the point, Amma.\""},{"text":"\"You're right. My mistake. Thanks for saying so.\"","then":"Munni looks pleased. \"It's okay. I slipped on Tuesday too.\"","best":true},{"text":"\"Sorry. I'll give up my phone completely now.\"","then":"Munni laughs. \"Amma, that's never going to happen.\""}],"why":"Owning it when she calls you out keeps the rule honest and shows her how to recover."}],"relearn":"Owning the hypocrisy and committing to the same limits gives the rules integrity and models honesty."},
  {"id":"na-076","cat":"screens-and-modelling","type":"sort","persona":"any","source":"helps or fuels","hook":"Sort: a habit that helps a child manage screens, or one that fuels dependence?","items":[{"id":"a","text":"Screen-free family meals"},{"id":"b","text":"Endless unstructured screen time"},{"id":"c","text":"Good offline things to do"},{"id":"d","text":"Screens as the only way to cope"},{"id":"e","text":"A clear time to switch off"},{"id":"f","text":"A screen on in every room all day"}],"bins":[{"id":"helps","label":"Helps manage it","valence":"pos"},{"id":"fuels","label":"Fuels dependence","valence":"neg"}],"key":{"a":"helps","b":"fuels","c":"helps","d":"fuels","e":"helps","f":"fuels"},"relearn":"Screen-free meals and good offline options help; endless screen time and screens-as-only-coping fuel dependence."},
  {"id":"na-077","cat":"screens-and-modelling","type":"branch","persona":"Priya","source":"replace not just remove","hook":"You want your son Aryan, 11, to game less, but after school he has nothing else to do.","steps":[{"prompt":"He's been gaming for three hours straight again. What do you do?","options":[{"text":"Ask what else he might enjoy, and try something together","then":"Aryan shrugs, then says he used to like drawing comics.","best":true},{"text":"Take the controller away and leave him to find something","then":"Aryan wanders round bored, then begs for the tablet instead."},{"text":"Let him play on, since there's nothing else for him","then":"Three hours becomes four, and his homework is left undone."},{"text":"Book tuition every evening to fill the time","then":"Aryan dreads the evenings now and games late to make up for it."}],"why":"Filling the gap with things he enjoys crowds out the habit instead of leaving a void."},{"prompt":"At the weekend Aryan says drawing comics, which he used to love, is boring on his own. What do you do?","options":[{"text":"Tell him a bit of boredom is good for him","then":"Aryan sighs, and within ten minutes he's back on the game."},{"text":"Buy him an expensive art kit and leave him to it","then":"The kit sits mostly unopened on his desk."},{"text":"Suggest he invite friends over someday, without a plan","then":"Nothing gets arranged, and gaming fills the gap again."},{"text":"Join him for the first few times","then":"You both draw terrible comics, and Aryan laughs harder than he has in weeks.","best":true}],"why":"Doing it together makes the new activity appealing enough to compete with screens."},{"prompt":"A month on, Aryan asks for more gaming time at weekends. What do you do?","options":[{"text":"Refuse, since any extra gaming would be a step backwards","then":"Aryan feels punished and starts gaming at a friend's instead."},{"text":"Say yes to as much as he likes, to keep the peace","then":"The weekend disappears into the game, and the comics sit unfinished."},{"text":"Agree a weekend limit together that leaves room for hobbies","then":"Aryan settles on an hour, then heads out with his sketchbook.","best":true},{"text":"Let him earn game time for every hour he spends drawing","then":"Drawing turns into a chore he rushes through for points."}],"why":"An agreed limit alongside real outlets keeps gaming in balance with what he enjoys."}],"debrief":"Reduce gaming by replacing it with appealing offline activities, not just removing the device.","relearn":"Fill the gap with better things when cutting screen time; a void just pulls a child back."},
  {"id":"na-078","cat":"screens-and-modelling","type":"match","persona":"Kamla","source":"modelling teaches","hook":"Match each modelling choice to what it teaches a child.","pairs":[{"left":"Parents off phones at dinner","right":"Connection over screens"},{"left":"Healthy ways to de-stress","right":"Coping without numbing"},{"left":"Owning your own slip-ups","right":"Honesty and growth"},{"left":"Keeping the limits you set","right":"Rules are real, not for show"},{"left":"Asking for help yourself","right":"Reaching out is a strength"}],"relearn":"Parents off phones, healthy de-stressing, owning slips, keeping your own limits and asking for help each teach a child something that protects them."},
  {"id":"na-079","cat":"screens-and-modelling","type":"role-play","persona":"Priya","source":"family agreement","hook":"Phones fill every corner of family life. You want to fix it with your children, not at them.","setup":"You gather Aditya, 15, and Tia, 11, in the living room.","steps":[{"prompt":"Aditya asks: \"Is this another lecture about phones?\"","options":[{"text":"\"No lecture. From tonight, I'm collecting phones at nine.\"","then":"Aditya groans. \"So, yes. A lecture, just shorter.\""},{"text":"\"Yes, and it's overdue. You two are always on them.\"","then":"Tia shrinks into the sofa. \"Here we go,\" Aditya mutters."},{"text":"\"Sort of. I've written some rules. Tell me if you like them.\"","then":"Aditya skims the list. \"You've already decided, then.\""},{"text":"\"No. Let's make a family screen plan together. Parents included.\"","then":"Aditya looks up, surprised. \"Parents too? Okay. I'm listening.\"","best":true}],"why":"Inviting everyone to shape the plan, parents included, gets real buy-in."},{"prompt":"Aditya says: \"Fine. But I need my phone for homework and friends.\"","options":[{"text":"\"Homework can be done on paper, the way we used to do it.\"","then":"Aditya laughs. \"Not anymore, Mumma.\""},{"text":"\"Friends can wait till the weekend. School comes first.\"","then":"Aditya folds his arms. \"Then what's the point of a plan?\""},{"text":"\"Fair. Let's write down what you need it for, and when.\"","then":"Aditya thinks. \"Homework, the class group, and calls at the weekend.\"","best":true},{"text":"\"Okay. Keep it whenever it's for homework.\"","then":"Aditya grins. \"Everything's for homework, then.\""}],"why":"Taking real needs seriously makes the plan fair enough to keep."},{"prompt":"Tia asks: \"Papa checks his phone at dinner. Is that allowed?\"","options":[{"text":"\"Papa has important work. That's different.\"","then":"Tia frowns. \"My game is important too.\""},{"text":"\"No. Dinner's phone-free for all of us.\"","then":"Tia beams. \"I'm writing it in big letters,\" she says.","best":true},{"text":"\"Let's leave Papa out of this one.\"","then":"Aditya snorts. \"So it's a kids' plan, then.\""},{"text":"\"We'll ask Papa later what he thinks about it.\"","then":"Tia shrugs. \"He'll just say no.\""}],"why":"A rule that holds for adults too is one children believe in."},{"prompt":"Aditya asks: \"And what happens if someone breaks it?\"","options":[{"text":"\"We remind each other kindly, and fix the plan together.\"","then":"Aditya nods. \"Okay. That's fair.\"","best":true},{"text":"\"Then I confiscate that person's phone for a whole week.\"","then":"Tia looks worried. \"Even Papa's?\" she asks."},{"text":"\"Nothing, really. It's only a guideline, after all.\"","then":"Aditya shrugs. \"So we can ignore it.\""},{"text":"\"We'll deal with that when it happens.\"","then":"Aditya raises an eyebrow. \"So probably nothing, then.\""}],"why":"Kind reminders and regular reviews keep the plan alive without a crackdown."}],"relearn":"Proposing a fair family agreement everyone shapes, parents included, gets far more buy-in than imposed, arbitrary rules."},
  {"id":"na-080","cat":"screens-and-modelling","type":"sort","persona":"Kamla","source":"models which","hook":"Sort: models healthy habits, or models the opposite?","items":[{"id":"a","text":"Coping with stress without substances"},{"id":"b","text":"Drinking to unwind every night"},{"id":"c","text":"Balanced phone use"},{"id":"d","text":"Doom-scrolling for hours daily"},{"id":"e","text":"A walk to clear your head"},{"id":"f","text":"Smoking to take the edge off"}],"bins":[{"id":"healthy","label":"Models healthy","valence":"pos"},{"id":"opposite","label":"Models the opposite","valence":"neg"}],"key":{"a":"healthy","b":"opposite","c":"healthy","d":"opposite","e":"healthy","f":"opposite"},"relearn":"Coping without substances and balanced phone use model healthy habits; nightly drinking and doom-scrolling model the opposite."},
  {"id":"na-081","cat":"tools-and-safety","type":"role-play","persona":"Vikram","source":"emergency plan","hook":"Your son Tushar has struggled with drinking, and you want your partner Rekha ready for an emergency.","setup":"You're sitting together after dinner.","steps":[{"prompt":"Rekha asks: \"Why talk about emergencies? Nothing's happened.\"","options":[{"text":"\"Because in a crisis there's no time to think.\"","then":"Rekha sets down her cup. \"Okay. What would we do?\"","best":true},{"text":"\"You're right. Let's just hope nothing ever happens.\"","then":"Rekha nods, relieved, then pauses. \"Still, I do wonder what we'd do.\""},{"text":"\"Because you'd panic. I'd better handle anything serious.\"","then":"Rekha frowns. \"I wouldn't panic. You don't trust me?\""},{"text":"\"Because I read something awful online, and it scared me.\"","then":"Rekha looks worried. \"Now you're scaring me too.\""}],"why":"Agreeing a plan while things are calm means neither of you hesitates when seconds count."},{"prompt":"Rekha asks: \"If he ever passed out, wouldn't we call the family doctor first?\"","options":[{"text":"\"No. In acute danger, it's 112 or straight to hospital.\"","then":"Rekha nods. \"112 first. Got it.\"","best":true},{"text":"\"Yes. Our family doctor knows Tushar better than anyone.\"","then":"Rekha nods, then frowns. \"Though at 2 a.m., he may not even pick up.\""},{"text":"\"We'd wait a bit first and see if he comes round.\"","then":"Rekha hesitates. \"Is waiting safe, though?\""},{"text":"\"Let's decide that if it ever actually happens.\"","then":"Rekha shrugs. \"Okay.\" The question stays open."}],"why":"Acute danger is an emergency, and 112 or a hospital is the fastest route to help."},{"prompt":"Rekha asks: \"And for everything short of an emergency?\"","options":[{"text":"\"We call Tele-MANAS 14416 and talk it through.\"","then":"Rekha saves 14416 in her phone and writes it out for the fridge. \"Done.\"","best":true},{"text":"\"We keep it in the family. No outsiders.\"","then":"Rekha nods slowly. \"I suppose that's safest.\""},{"text":"\"We come down hard, so it never gets that far.\"","then":"Rekha looks uneasy. \"Would that really help him?\""},{"text":"\"We'll just figure it out case by case, as it comes.\"","then":"Rekha sighs. \"So, no plan, then.\""}],"why":"Knowing which number fits which situation keeps you both calm and quick."}],"relearn":"Agreeing a clear emergency plan in advance means no hesitation when seconds count."},
  {"id":"na-082","type":"sort","persona":"any","hook":"Sort: a wise preparation, or a risky gap?","items":[{"id":"a","text":"Saved helpline and emergency numbers"},{"id":"b","text":"No plan for a crisis"},{"id":"c","text":"Knowing the signs of acute danger"},{"id":"d","text":"Assuming it'll never happen to you"},{"id":"e","text":"A calm-response plan you've rehearsed"},{"id":"f","text":"Leaving the plan only in your head"}],"bins":[{"id":"wise","label":"Wise preparation","valence":"pos"},{"id":"gap","label":"Risky gap","valence":"neg"}],"key":{"a":"wise","c":"wise","e":"wise","b":"gap","d":"gap","f":"gap"},"relearn":"Saved numbers, known danger signs and a rehearsed plan are wise; no plan, 'never us' denial and an unshared plan are gaps.","source":"prep or gap","cat":"tools-and-safety"},
  {"id":"na-083","cat":"tools-and-safety","type":"role-play","persona":"Divya","source":"point a friend","hook":"Your friend Rehana's son Faiz, 17, can't stop using painkillers, and she doesn't know where to turn.","setup":"She calls you late at night, crying.","steps":[{"prompt":"Rehana says: \"I'm so ashamed. What kind of mother lets this happen?\"","options":[{"text":"\"It's not a verdict on you. It's a treatable health issue.\"","then":"Rehana's breathing slows. \"Treatable? Really?\"","best":true},{"text":"\"That's so shameful. I wouldn't tell anyone if I were you.\"","then":"Rehana goes quiet. \"But I can't do this alone either.\""},{"text":"\"Where was Faiz getting them from? Didn't you notice?\"","then":"Rehana sobs harder. \"I didn't know. I should have.\""},{"text":"\"Don't cry. Boys go through phases like this.\"","then":"Rehana sniffs. \"It doesn't feel like a phase.\""}],"why":"Lifting the shame first helps her see dependence as treatable, which makes help possible."},{"prompt":"Rehana asks: \"But who do I even call? I don't know anyone.\"","options":[{"text":"\"Tele-MANAS 14416 is a good start. Then a counsellor.\"","then":"Rehana grabs a pen. \"Say that number again?\"","best":true},{"text":"\"Just search online. There's plenty of advice out there.\"","then":"Rehana sighs. \"There's too much. I don't know what to trust.\""},{"text":"\"Try keeping it in the family first. Outsiders talk.\"","then":"Rehana hesitates. \"Then who helps me?\""},{"text":"\"Take away his phone and money, and he'll have to stop.\"","then":"Rehana sounds unsure. \"Will that really work?\""}],"why":"Concrete, trusted routes are what a frightened parent needs most."},{"prompt":"Rehana sighs: \"Faiz swears he can stop by himself. He says he needs no one.\"","options":[{"text":"\"You can still call and get guidance for yourself.\"","then":"Rehana breathes out. \"So I don't have to wait for him.\"","best":true},{"text":"\"Then force him to get help. He's still a child.\"","then":"Rehana's voice shakes. \"I don't think I can.\""},{"text":"\"Then there's not much anyone can do.\"","then":"Rehana goes silent. \"So I just watch?\""},{"text":"\"Then let me talk to him. He'll listen to me.\"","then":"Rehana hesitates. \"Maybe. But I'd still be lost.\""}],"why":"Family-inclusive help can start with the parent, even before the child is ready."}],"relearn":"Sharing that it's a health issue with concrete help routes serves a struggling friend far better than fuelling shame."},
  {"id":"na-084","cat":"tools-and-safety","type":"role-play","persona":"Vikram","source":"stay involved","hook":"Your daughter Isha, 16, has just had her first session at a de-addiction centre.","setup":"You're driving her home in silence.","steps":[{"prompt":"Isha asks quietly: \"So is that it? Now it's the counsellor's job?\"","options":[{"text":"\"No. I'm with you, on the good days and the hard ones.\"","then":"Isha glances at you. \"Even the hard ones?\"","best":true},{"text":"\"There, I got you help. Now it's your problem to fix.\"","then":"Isha looks out of the window. \"Right. My problem.\""},{"text":"\"Yes. They're the experts, so I'll stay out of it.\"","then":"Isha nods, and looks more alone than before."},{"text":"\"Only if you actually listen to them this time.\"","then":"Isha's jaw tightens. \"Thanks for the vote of confidence.\""}],"why":"Committing to stay involved gives her the steady support that helps recovery last."},{"prompt":"Isha says: \"The counsellor wants you to come to some sessions.\"","options":[{"text":"\"I'll be there. Just tell me when.\"","then":"Isha nods. \"Thursday. Four o'clock.\"","best":true},{"text":"\"Why? You're the one who needs help, not me.\"","then":"Isha stiffens. \"Forget it.\""},{"text":"\"I'll try, but work is really busy right now.\"","then":"Isha shrugs. \"Sure. Whatever.\""},{"text":"\"Only if they won't blame me for all this.\"","then":"Isha rolls her eyes. \"It's not about blaming you.\""}],"why":"Joining family sessions strongly improves outcomes, and shows her you mean it."},{"prompt":"A few weeks later, Isha says: \"I slipped last night. I'm sorry.\"","options":[{"text":"\"Thanks for telling me. Let's raise it at the next session.\"","then":"Isha's shoulders drop. \"I thought you'd be so angry.\"","best":true},{"text":"\"After everything we've done? I can't believe you.\"","then":"Isha's eyes fill. \"I knew I shouldn't tell you.\""},{"text":"\"It's okay. One slip doesn't matter at all.\"","then":"Isha looks unsure. \"Doesn't it?\""},{"text":"\"That's it. No going out at all until the counsellor says so.\"","then":"Isha stares at the floor. \"Fine.\" She says nothing more."}],"why":"Slips happen in recovery. Meeting honesty with calm keeps her telling you."},{"prompt":"Isha asks: \"Do you ever wish I was just normal?\"","options":[{"text":"\"No. I'm proud of how hard you're working.\"","then":"Isha smiles for the first time in days. \"Really?\"","best":true},{"text":"\"Sometimes, yes. Your cousins never gave us trouble.\"","then":"Isha turns away. \"Great. Thanks.\""},{"text":"\"You are normal. Let's not talk about this stuff.\"","then":"Isha shrugs. \"Okay.\" The moment closes."},{"text":"\"You'll be normal once you're done with counselling.\"","then":"Isha frowns. \"So I'm not normal now?\""}],"why":"Recovery is real, and your pride in her effort is part of what keeps her going."}],"relearn":"Committing to stay involved through recovery, good days and hard, gives a child the steady support that helps it last."},
  {"id":"na-900","cat":"get-the-right-help","type":"strike-rewrite","hook":"\"De-addiction help is only for grown men who drink, not for a teen on a phone.\"","myth":{"un":"De-addiction help is only for grown men who drink, not for a teen on a phone.","re":"Counsellors and de-addiction services help with screen and gaming dependence too, and starting young gives the best chance.","why":"The same help reaches every kind of dependence."},"relearn":"Professional help fits screen and gaming dependence as much as substances; early help helps most.","persona":"Vikram","source":"help fits screens too"},
  {"id":"na-901","cat":"get-the-right-help","type":"strike-rewrite","hook":"\"A counsellor will just blame us as parents, so it's safer not to go.\"","myth":{"un":"A counsellor will just blame us as parents, so it's safer not to go.","re":"A good de-addiction counsellor works with the family, not against it; family-inclusive help improves a child's chances.","why":"They want you on the team, not in the dock."},"relearn":"Counsellors partner with families; family-inclusive treatment improves outcomes, so going helps your child.","persona":"Kamla","source":"counsellor won't blame"},
  {"id":"na-902","cat":"get-the-right-help","type":"strike-rewrite","hook":"\"We should wait until it gets really bad before bothering a professional.\"","myth":{"un":"We should wait until it gets really bad before bothering a professional.","re":"Getting help early, before a crisis, gives the best chance, just as catching any health issue early does.","why":"Early is easier than rock bottom."},"relearn":"Reach out early rather than waiting for crisis; early help gives a child the best chance.","persona":"Vikram","source":"don't wait for bad"},
  {"id":"na-903","cat":"get-the-right-help","type":"strike-rewrite","hook":"\"If we ask for help, everyone will know and our family name is ruined.\"","myth":{"un":"If we ask for help, everyone will know and our family name is ruined.","re":"Counselling and Tele-MANAS are confidential; reaching out is a private, wise step, not a public shame.","why":"Help is confidential, not a notice board."},"relearn":"Help routes like Tele-MANAS and counselling are confidential; asking is wise, not shameful exposure.","persona":"Kamla","source":"help is private"},
  {"id":"na-904","cat":"get-the-right-help","type":"strike-rewrite","hook":"\"Love and willpower at home are enough; we don't need any outside help.\"","myth":{"un":"Love and willpower at home are enough; we don't need any outside help.","re":"Love matters hugely, and dependence usually also needs professionals who know what works; the two go together.","why":"Your love plus their skill is strongest."},"relearn":"Family love and professional help work together; dependence usually needs trained support too.","persona":"Divya","source":"love plus help"},
  {"id":"na-905","cat":"get-the-right-help","type":"strike-rewrite","hook":"\"Once we hand our child to a service, our job as parents is finished.\"","myth":{"un":"Once we hand our child to a service, our job as parents is finished.","re":"You stay central in treatment; a calm, involved parent is part of what makes recovery hold.","why":"You're a partner in the plan, not a drop-off."},"relearn":"Parents stay involved through treatment; staying connected is part of what makes recovery last.","persona":"Vikram","source":"stay involved through treatment"},
  {"id":"na-906","cat":"get-the-right-help","type":"strike-rewrite","hook":"\"There's no real treatment for this, so reaching out is pointless.\"","myth":{"un":"There's no real treatment for this, so reaching out is pointless.","re":"Effective, evidence-based treatment exists and recovery is real; reaching out is the step that opens it.","why":"Help works, and it starts with the call."},"relearn":"Real treatment exists and recovery is common with support; reaching out opens the door to it.","persona":"any","source":"treatment exists"},
  {"id":"na-907","cat":"get-the-right-help","type":"strike-rewrite","hook":"\"Asking for help means I've failed as a parent.\"","myth":{"un":"Asking for help means I've failed as a parent.","re":"Reaching out is a strength, and it models the very help-seeking you want your child to learn.","why":"Seeking help teaches your child to seek help."},"relearn":"Asking for help is a strength that models help-seeking for your child, not a parenting failure.","persona":"Divya","source":"asking is strength"},
  {"id":"na-908","cat":"get-the-right-help","type":"branch","persona":"any","source":"small worry is enough","hook":"Your son Rohan, 14, games past midnight and skips family meals. You can't tell if it's serious.","steps":[{"prompt":"You keep thinking about it at work. What do you do?","options":[{"text":"Call Tele-MANAS 14416 to talk it through","then":"The counsellor asks a few questions and suggests two calm first steps.","best":true},{"text":"Tell yourself it's probably nothing and wait","then":"A month later, Rohan's teacher says he's falling asleep in class."},{"text":"Take his console away tonight without warning","then":"Rohan explodes, then games on his phone under the blanket instead."},{"text":"Ask the class parents' WhatsApp group if it's normal","then":"Everyone says their kids game a lot too. You feel reassured and do nothing."}],"why":"You don't need a crisis to call; talking it through early gives you a clearer next step."},{"prompt":"That weekend, Rohan snaps at you when you call him for lunch. What do you do?","options":[{"text":"Once he's calm, say he seems tired lately and ask how he is","then":"Rohan shrugs, then admits he can't stop once he starts playing.","best":true},{"text":"Snap back that he's addicted to that game","then":"Rohan slams his door. \"You don't understand anything.\""},{"text":"Let it go, since all teenagers are moody","then":"Lunch passes in silence. The gaming carries on late into the night."},{"text":"Tell him calmly that a gaming limit starts from tomorrow","then":"Rohan argues it's unfair. The limit begins without him agreeing to it."}],"why":"Calm noticing and asking reaches him, where a label or silence doesn't."},{"prompt":"Your mother-in-law says all kids game, and asking anyone for advice is making a fuss. What do you do?","options":[{"text":"Say asking early is just guidance, and it's worth it","then":"She shrugs, and you plan a next step with Rohan this week.","best":true},{"text":"Agree, and drop the idea of asking for help","then":"The late nights go on, and so does your worry."},{"text":"Tell her she knows nothing about screens","then":"She's offended, and the house feels tense all evening."},{"text":"Agree to wait until his exams are over, then decide","then":"The exams come and go, and the gaming only grows."}],"why":"Small, early worries are worth a call; there's no need to wait until it feels big enough."}],"debrief":"You don't need a crisis to call; Tele-MANAS 14416 can help you think it through early.","relearn":"You can reach out with an early, small worry; you don't have to wait for it to be 'big enough'."},
  {"id":"na-909","cat":"get-the-right-help","type":"branch","persona":"Vikram","source":"faith plus help","hook":"Your son Aarav starts counselling for his drinking next week. Your aunt says a temple ritual will cure him instead.","steps":[{"prompt":"She has already booked the priest for Sunday. What do you do?","options":[{"text":"Thank her, do the ritual, and keep the counsellor too","then":"Your aunt is pleased about the ritual, though she frowns at the counselling.","best":true},{"text":"Cancel the counsellor and trust the ritual","then":"The ritual is done. A fortnight later Aarav is drinking again, and you rebook counselling."},{"text":"Tell her faith has nothing to do with this","then":"Your aunt is hurt and tells the family you've insulted her beliefs."},{"text":"Try the ritual first and see the counsellor only if it fails","then":"You wait on the ritual first, and Aarav's counselling starts a month late."}],"why":"Faith and family can sit alongside treatment, but they don't replace it."},{"prompt":"At a family function, your aunt warns that counselling will make everyone talk. What do you say?","options":[{"text":"Say getting him health care is nothing to hide","then":"A cousin nods quietly. Your aunt changes the subject.","best":true},{"text":"Promise her you'll keep the counselling a secret","then":"Your aunt relaxes. Now you feel you must hide Aarav's appointments."},{"text":"Argue with her in front of everyone","then":"Voices rise, and across the room Aarav looks mortified."},{"text":"Say it's only a few sessions and nothing serious","then":"Your aunt seems reassured, and you've made his help sound smaller than it is."}],"why":"Treating counselling as ordinary health care takes the shame out of it for everyone."},{"prompt":"Later, Aarav asks you privately whether prayer can fix him. What do you say?","options":[{"text":"Say prayer can help, and so can a counsellor","then":"Aarav nods slowly. \"So I'd still need to see someone.\"","best":true},{"text":"Say yes, and that he won't need anything else","then":"Aarav looks relieved. He stops mentioning counselling at all."},{"text":"Say rituals are nonsense and he needs real treatment","then":"Aarav goes quiet. \"Don't say that in front of her.\""},{"text":"Say you hope so, and change the subject to his exams","then":"Aarav looks unsure. The question stays hanging between you."}],"why":"Honouring his faith while being honest about treatment gives him both hope and a plan."},{"prompt":"A month later, your aunt says the ritual worked because Aarav seems calmer. What do you do?","options":[{"text":"Say her care has helped him, and so has the counselling","then":"Your aunt shrugs. \"Whatever helps. Just keep him well.\"","best":true},{"text":"Agree with her and stop the counselling","then":"Within weeks the old pattern returns, and Aarav hides it better."},{"text":"Tell her flatly that it had nothing to do with the ritual","then":"Your aunt stiffens and doesn't call for a week."},{"text":"Agree it worked, and keep counselling going without telling her","then":"The peace holds, but you're still hiding his treatment from family."}],"why":"Recovery needs steady support; thanking her care and naming the counselling keeps both side by side."}],"debrief":"Faith and family can sit alongside treatment; they don't replace the counsellor.","relearn":"You can honour faith and still get professional de-addiction help; both go together."},
  {"id":"na-910","cat":"get-the-right-help","type":"branch","persona":"Kamla","source":"find help together","hook":"Late one night, your son Sonu, 14, finally admits he's been vaping for months.","steps":[{"prompt":"His voice shakes as he asks if you're going to send him away. What do you say?","options":[{"text":"Promise you won't, and that you'll find help together","then":"Sonu's shoulders drop. He tells you he's tried to stop and couldn't.","best":true},{"text":"Warn that a strict hostel is next if it happens again","then":"Sonu goes pale and swears it won't. He won't meet your eyes."},{"text":"Say you're too angry to talk about it tonight","then":"Sonu goes to bed in tears, and you lie awake too."},{"text":"Say no, but now that you know, he simply has to stop","then":"Sonu nods fast. He doesn't tell you he's already tried and failed."}],"why":"Promising to find help together keeps him talking, while fear of being sent away makes children hide."},{"prompt":"Next morning, Sonu begs you not to tell anyone, not even a doctor. What do you do?","options":[{"text":"Say it stays private, but you'll ask someone who can help","then":"Sonu frowns and asks who. \"Someone kind,\" you say, and he nods.","best":true},{"text":"Promise him you'll never tell anyone at all","then":"Sonu relaxes. You now hold a secret with no plan behind it."},{"text":"Tell him he's lost the right to decide that","then":"Sonu shuts down and stops talking about the vaping."},{"text":"Agree to try on your own for a month before asking anyone","then":"Sonu is relieved. The month passes, and he's still vaping every day."}],"why":"Guarding his privacy while still getting help keeps his trust and gets him real support."},{"prompt":"Sonu is still vaping most days. You need help, but money is tight. What do you do?","options":[{"text":"Call Tele-MANAS 14416 with Sonu, since the call is free","then":"Sonu sits beside you. The counsellor speaks to both of you, kindly.","best":true},{"text":"Tell him help costs money, so he'll just have to stop","then":"Sonu nods. The cravings don't care what anything costs."},{"text":"Ask his class teacher what to do first","then":"The teacher is kind but unsure, and suggests asking someone else."},{"text":"Book a private clinic, whatever it costs","then":"You start borrowing from relatives, and the whole family hears why."}],"why":"A free call to Tele-MANAS 14416 is a real first step, and doing it together shows him he's not alone."},{"prompt":"A week later, you smell vape on Sonu again when he comes home. What do you do?","options":[{"text":"Stay calm, say you're in this together, and reach out for help","then":"Sonu looks surprised you're not shouting. \"Today was hard,\" he says.","best":true},{"text":"Tell him he's going to the hostel, and that's final","then":"Sonu storms out and doesn't come back until late."},{"text":"Pretend you didn't notice, to keep the peace","then":"Sonu relaxes, and the vaping quietly picks up again."},{"text":"Tell him calmly that you're disappointed, and leave it at that","then":"Sonu hangs his head. He doesn't mention the craving he had all day."}],"why":"A slip is part of recovery; staying calm and reaching out for help keeps him in it."}],"debrief":"Promising to find help together keeps a child reachable; threats of being sent away drive them to hide.","relearn":"Offer to find help together rather than threatening to send a child away; connection keeps help possible."},
  {"id":"na-911","cat":"get-the-right-help","type":"branch","persona":"Kamla","source":"phone first when far","hook":"Your daughter Pooja, 16, drinks with older friends. The nearest de-addiction centre is hours away.","steps":[{"prompt":"You work long shifts and only have your phone. What do you do?","options":[{"text":"Call Tele-MANAS 14416 on your break to plan a first step","then":"The counsellor listens and helps you plan a calm talk with Pooja.","best":true},{"text":"Decide help is impossible from this far away","then":"Weeks pass, and Pooja's weekends out get longer."},{"text":"Wait until you can take days off to travel to the centre","then":"Months go by before you get the time, and the drinking carries on."},{"text":"Stop her from going out at all for a month","then":"Pooja starts slipping out after you've fallen asleep."}],"why":"When a centre is far, a phone call is a real first step that needs no travel."},{"prompt":"That weekend, Pooja comes home late and you smell alcohol on her. What do you do?","options":[{"text":"Check she's safe tonight, then talk calmly in the morning","then":"Next morning Pooja is quiet, but listens when you say you're worried.","best":true},{"text":"Shout at her the moment she's through the door","then":"The neighbours hear. Pooja pushes past you and locks her door."},{"text":"Say nothing at all, to avoid a scene","then":"Pooja goes to bed. Nothing is said, but the worry keeps you awake."},{"text":"Sit her down and talk it all through right then, at midnight","then":"Pooja is tired and defensive, and the talk goes round in circles."}],"why":"Safety first, then a calm talk when she's sober, reaches her better than a fight at the door."},{"prompt":"A few days later, you raise getting help. Pooja says she can't miss school to travel. What do you do?","options":[{"text":"Suggest a Tele-MANAS 14416 call together one evening","then":"Pooja agrees. The counsellor hears her side too and suggests a next step.","best":true},{"text":"Say school matters more, so help can wait","then":"Pooja is relieved. The drinking stays a secret she shares with friends."},{"text":"Say you'll handle the calls yourself so she needn't be involved","then":"The counsellor is helpful, but asks to hear from Pooja herself."},{"text":"Ask her friends' parents to keep an eye on her","then":"The other parents gossip, and Pooja feels watched everywhere she goes."}],"why":"A phone call fits around school and work, and bringing Pooja in makes the help hers too."}],"debrief":"When a centre is far, a Tele-MANAS 14416 call is a real first step that needs only a phone.","relearn":"Distance isn't a dead end: Tele-MANAS 14416 gives expert guidance by phone."},
  {"id":"na-912","cat":"get-the-right-help","type":"branch","persona":"Divya","source":"both parents in","hook":"Ishaan's counsellor asks both parents to join his sessions about gaming. Your husband Nikhil isn't keen.","steps":[{"prompt":"Nikhil says: \"You go. I'm swamped at work, and it's his problem anyway.\" What do you do?","options":[{"text":"Say you're both needed, since it helps Ishaan most","then":"Nikhil sighs. \"Fine. But I don't see what I'll add.\"","best":true},{"text":"Go on your own and leave him out of it","then":"You go each week. Ishaan notices his father never comes."},{"text":"Tell him he never shows up for anything","then":"Nikhil digs in. \"Now I'm definitely not going.\""},{"text":"Go alone, and fill him in on everything afterwards","then":"Nikhil listens politely, but the plan feels like yours, not his."}],"why":"Family-inclusive help works better than one parent alone, so asking him in is worth it."},{"prompt":"The counsellor suggests screen-free dinners. Nikhil says that rule is for Ishaan, not him. What do you do?","options":[{"text":"Say it works best if all of you keep it, you two included","then":"Nikhil rolls his eyes, but leaves his phone in the other room.","best":true},{"text":"Let it be a rule for Ishaan only","then":"Ishaan sees his father scrolling at dinner and pushes back hard."},{"text":"Mock Nikhil's phone habit in front of Ishaan","then":"Nikhil goes red. Dinner ends early, and in silence."},{"text":"Keep the rule yourself, and hope Nikhil starts copying you","then":"You manage it, but Nikhil's phone stays on the table every night."}],"why":"Children learn habits by watching, so limits the whole family keeps work better than one-sided rules."},{"prompt":"A few weeks in, Ishaan says he feels like the family's 'problem child'. What do you do?","options":[{"text":"Say he isn't the problem, and you're in this as a family","then":"Ishaan looks up. \"So it's not just me who has to change?\"","best":true},{"text":"Tell him that's silly and he shouldn't feel that way","then":"Ishaan shrugs and stops sharing how he feels."},{"text":"Say he'd feel better if he just stopped gaming","then":"Ishaan goes quiet and heads back to his room."},{"text":"Reassure him, and promise the sessions will be over soon","then":"Ishaan brightens, but the counsellor later says there's more to do."}],"why":"Framing it as a family effort eases his shame and keeps him engaged."},{"prompt":"Before the next session, Nikhil asks what the point of him being there is. What do you say?","options":[{"text":"Say Ishaan does better when both parents are in it","then":"Nikhil nods. \"Okay. What should I say in there?\"","best":true},{"text":"Say he's right, and he needn't bother","then":"Nikhil stays home. Ishaan asks why his father never comes."},{"text":"Say he owes it after ignoring the problem for so long","then":"Nikhil stiffens. \"So this is about blaming me now?\""},{"text":"Say he can come along just to keep you company","then":"Nikhil comes, but sits back and leaves everything to you."}],"why":"Your son's chances improve when both parents take part, so his place in the room matters."}],"debrief":"Family-inclusive sessions work better than one parent alone; bring your partner in.","relearn":"Family-inclusive treatment beats going it alone; getting both parents in helps most."},
  {"id":"na-913","cat":"get-the-right-help","type":"branch","persona":"Vikram","source":"recognised over miracle","hook":"Worried about your son Dev's drinking, you find a clinic online promising a 'guaranteed cure' in three days.","steps":[{"prompt":"The clinic wants full payment upfront and says no follow-up is needed. What do you do?","options":[{"text":"Look for a recognised de-addiction service instead","then":"A recognised centre explains that recovery takes time, with regular follow-up.","best":true},{"text":"Pay and book the three-day cure","then":"Dev comes back after three days. Within a week, he's drinking again."},{"text":"Give up on clinics and keep handling it at home","then":"Months pass, and Dev gets better at hiding his drinking."},{"text":"Book the clinic, and plan a counsellor afterwards just in case","then":"You pay a lot for three days, and real help is pushed back."}],"why":"Recovery is real but rarely instant; a recognised service gives real, evidence-based care."},{"prompt":"Your brother-in-law says: \"My friend's son was fixed at that clinic in three days.\" What do you say?","options":[{"text":"Say you're glad for them, but you'll go with recognised care","then":"He shrugs. \"Your choice. Let me know how it goes.\"","best":true},{"text":"Tell him his friend must be exaggerating","then":"He's offended, and the family chat goes cold for a while."},{"text":"Agree that one quick treatment should be enough","then":"He nods, and you start to see follow-up care as optional."},{"text":"Ask to speak to his friend first, just to compare","then":"You spend a week trading calls with his friend, while Dev's care waits."}],"why":"One story isn't evidence; recognised services use treatment that is known to work."},{"prompt":"You meet a recognised de-addiction counsellor. She says recovery may take months, and Dev groans. What do you do?","options":[{"text":"Tell Dev you'll be with him the whole way","then":"Dev groans again, but asks how often he'll have to come.","best":true},{"text":"Tell Dev it's his own fault this will take so long","then":"Dev's jaw tightens, and he stares at the floor for the rest of it."},{"text":"Agree months is too long, and ask for a shorter plan","then":"Dev brightens. The counsellor warns that cutting it short rarely lasts."},{"text":"Say that's fine, as long as he stops completely right away","then":"Dev looks panicked. \"And if I can't?\""}],"why":"Real recovery takes time, and knowing you'll stay alongside makes the long road bearable."}],"debrief":"Recovery is real but rarely instant; a recognised service beats a 'guaranteed cure' promise.","relearn":"Trust recognised de-addiction services over 'instant cure' promises."},
  {"id":"na-914","cat":"get-the-right-help","type":"branch","persona":"Vikram","source":"respect private session","hook":"Your daughter Tara, 16, agrees to see a counsellor about her drinking, but on one condition.","steps":[{"prompt":"She says she'll only talk if you're not in the room. What do you do?","options":[{"text":"Agree, and say you'll wait right outside if she needs you","then":"Tara looks surprised. \"Really? Okay. Thanks.\"","best":true},{"text":"Insist on sitting in, since you're the parent","then":"Tara says almost nothing. The counsellor asks to see her alone next time."},{"text":"Agree, and say she can handle it all on her own from now","then":"Tara goes alone each week. You have no idea how any of it is going."},{"text":"Agree, but plan to ask the counsellor for every detail later","then":"The counsellor explains that sessions stay private unless safety is at risk."}],"why":"A private session helps her be honest, and staying close keeps you involved."},{"prompt":"Tara gets home from her next session looking thoughtful. You're desperate to know how it went. What do you do?","options":[{"text":"Ask how it went, and let her share what she wants","then":"Tara says it was okay, and that the counsellor was easy to talk to.","best":true},{"text":"Press her for everything she told the counsellor","then":"Tara clams up. \"This is why I didn't want you in there.\""},{"text":"Call the counsellor later and ask for a full report","then":"The counsellor gently declines, and Tara finds out that you asked."},{"text":"Say nothing at all, so she doesn't feel checked on","then":"Tara waits for you to ask, then wonders if you even care how it went."}],"why":"Letting her set the pace keeps counselling a safe place to be honest."},{"prompt":"The counsellor invites you to a joint session to plan next steps together. What do you do?","options":[{"text":"Go, and focus on how you can support her plan","then":"Tara talks more than you expected, and the plan includes a part for you.","best":true},{"text":"Go, and use the time to list every worry you have","then":"Tara stops talking, and the counsellor steers you back gently."},{"text":"Decline, since Tara asked for her privacy","then":"Tara's plan is made without you, and she wonders where you were."},{"text":"Go, but question Tara afterwards about what's really true","then":"Tara feels checked on again and goes quiet for the evening."}],"why":"Involvement isn't watching every minute; showing up to back her plan is what helps."}],"debrief":"A child often opens up more in a private session; involvement isn't watching every minute.","relearn":"A private session, while you stay involved, can help a child be honest."},
  {"id":"na-915","cat":"get-the-right-help","type":"branch","persona":"Kamla","source":"low-cost routes exist","hook":"Your son Raju's drinking is getting worse, and you earn just enough for rent and food.","steps":[{"prompt":"You assume de-addiction help would cost far more than you have. What do you do?","options":[{"text":"Ask Tele-MANAS 14416 about low-cost and government options","then":"The counsellor tells you about a government service in your district.","best":true},{"text":"Give up on help, since you can't afford it","then":"Months pass, and Raju starts skipping school to be with his friends."},{"text":"Borrow heavily from relatives to pay for a private clinic","then":"The debt weighs on you daily, and you can't pay for follow-up visits."},{"text":"Ask the neighbours in your lane if they know a cheap clinic","then":"A neighbour names one, and soon the whole lane knows about Raju."}],"why":"Tele-MANAS 14416 is free and can point you to affordable routes you might not know about."},{"prompt":"You hear the nearest government service has long queues on weekdays. You'd lose a day's pay. What do you do?","options":[{"text":"Ask them for a time or day that costs you less pay","then":"They offer you an early Saturday slot.","best":true},{"text":"Decide it isn't worth a day's wages","then":"You stay home, and Raju's drinking carries on unchecked."},{"text":"Send Raju on his own so that you don't lose the pay","then":"Raju goes, but leaves the queue long before his turn comes."},{"text":"Ask your sister to take Raju in your place","then":"Your sister takes him, but the counsellor asks for a parent next time."}],"why":"Asking the service about timings often finds a way that fits around your work."},{"prompt":"When Raju is finally seen, the counsellor asks you to join family sessions too. What do you do?","options":[{"text":"Say yes, and ask which times fit around your shifts","then":"The counsellor finds you an evening slot once a fortnight.","best":true},{"text":"Say you work, so it will have to be Raju alone","then":"Raju attends alone and feels he's the only one trying."},{"text":"Say you'll come only once he's stopped drinking","then":"Raju hears this and stops talking about the sessions at home."},{"text":"Say yes, but you'll only come when there's a problem","then":"You miss the calm sessions where the real plan gets made."}],"why":"Family involvement strongly improves outcomes, and a slot that fits your shifts makes it possible."},{"prompt":"Your husband says: \"Free help is cheap help. It won't work.\" What do you say?","options":[{"text":"Say free services are real treatment, and you'll keep going","then":"Your husband grunts, but doesn't argue any further.","best":true},{"text":"Agree, and stop the sessions","then":"Raju is relieved. A few weeks later, the drinking is back to where it was."},{"text":"Say you'll start saving for a private clinic instead","then":"Months of saving go by, and Raju waits without any help."},{"text":"Say it depends on Raju's willpower more than any service","then":"Raju overhears, and stops talking about his sessions at home."}],"why":"Free government and helpline routes are real care, so cost worry needn't end the search."}],"debrief":"Tele-MANAS 14416 is free and can point to low-cost and government de-addiction services.","relearn":"Cost worry needn't block help: Tele-MANAS 14416 is free and can point to affordable routes."},
  {"id":"na-916","cat":"get-the-right-help","type":"match","hook":"Match each parent's situation to the help route that fits it.","pairs":[{"left":"I just need to talk it through, any time","right":"Tele-MANAS 14416"},{"left":"My child needs assessment and structured treatment","right":"A de-addiction centre or counsellor"},{"left":"My child seems in real distress right now","right":"Childline 1098"},{"left":"There may be an overdose, immediate danger","right":"Call 112 or go to a hospital"},{"left":"Both parents want to be part of recovery","right":"Family-inclusive counselling"}],"relearn":"Each need has a route: Tele-MANAS to talk, a centre to treat, Childline for distress, 112 for danger.","persona":"any","source":"situation to route"},
  {"id":"na-917","cat":"get-the-right-help","type":"match","hook":"Match each first step toward help to why it works.","pairs":[{"left":"Calling early, before crisis","right":"Gives the best chance of recovery"},{"left":"Bringing the family into treatment","right":"Improves a child's outcomes"},{"left":"Choosing a recognised service","right":"Means real, evidence-based care"},{"left":"Naming the worry honestly on the call","right":"Helps the service guide you well"},{"left":"Saving the helpline numbers now","right":"Means you can reach them fast later"}],"relearn":"Calling early, involving family, choosing recognised care and being honest all make help work better.","persona":"any","source":"step to why it works"},
  {"id":"na-918","cat":"get-the-right-help","type":"match","hook":"Match each worry that blocks help to a calmer truth.","pairs":[{"left":"'Asking means we failed'","right":"Reaching out is a strength"},{"left":"'It's too late for our child'","right":"Recovery is real with support"},{"left":"'They'll take my child away'","right":"Counsellors work with families"},{"left":"'We must handle it in secret'","right":"A professional's help is what works"},{"left":"'Nobody understands this'","right":"Services have met it many times"}],"relearn":"Each blocking worry has a truth: asking is strength, recovery is real, and counsellors work with families.","persona":"any","source":"block to truth"},
  {"id":"na-919","cat":"get-the-right-help","type":"match","hook":"Match each thing you can prepare to the moment it helps you.","pairs":[{"left":"Tele-MANAS 14416 saved in your phone","right":"When you need to talk or find help"},{"left":"Childline 1098 saved","right":"When a child is in distress or danger"},{"left":"A nearby de-addiction centre noted","right":"When you're ready for assessment"},{"left":"A calm opening line rehearsed","right":"When you make the first nervous call"},{"left":"Your partner already on board","right":"When sessions ask the whole family"}],"relearn":"Saving numbers, noting a centre, rehearsing a line and including your partner all help before the moment comes.","persona":"any","source":"prepare to moment"},
  {"id":"na-920","cat":"get-the-right-help","type":"sort","hook":"Sort: does this move you toward real help, or away from it?","items":[{"id":"a","text":"Calling Tele-MANAS 14416 to talk it through"},{"id":"b","text":"Telling no one and hoping it passes"},{"id":"c","text":"Booking a de-addiction assessment early"},{"id":"d","text":"Deciding it's too shameful to ask"},{"id":"e","text":"Bringing the family into the plan"},{"id":"f","text":"Waiting for rock bottom first"}],"bins":[{"id":"toward","label":"Toward help","valence":"pos"},{"id":"away","label":"Away from help","valence":"neg"}],"key":{"a":"toward","b":"away","c":"toward","d":"away","e":"toward","f":"away"},"relearn":"Calling early, booking assessment and involving family move toward help; secrecy, shame and waiting move away.","persona":"any","source":"toward or away"},
  {"id":"na-921","cat":"get-the-right-help","type":"sort","hook":"Sort each line by whether it opens the door to help or quietly closes it.","items":[{"id":"a","text":"'Let's find someone who knows how to help'"},{"id":"b","text":"'We'll never speak of this to anyone'"},{"id":"c","text":"'I'll be right beside you through it'"},{"id":"d","text":"'You've brought shame on this family'"},{"id":"e","text":"'It's okay to need help with this'"},{"id":"f","text":"'Sort it out yourself or get out'"}],"bins":[{"id":"opens","label":"Opens the door","valence":"pos"},{"id":"closes","label":"Closes the door","valence":"neg"}],"key":{"a":"opens","b":"closes","c":"opens","d":"closes","e":"opens","f":"closes"},"relearn":"Offering to find help and standing beside a child opens the door; secrecy, shame and ultimatums close it.","persona":"any","source":"opens or closes"},
  {"id":"na-922","cat":"get-the-right-help","type":"sort","hook":"Sort each need by the India route that fits it.","items":[{"id":"a","text":"Talk a worry through any time"},{"id":"b","text":"A child in distress right now"},{"id":"c","text":"Assessment and treatment"},{"id":"d","text":"A possible overdose, immediate danger"},{"id":"e","text":"Keeping the family in the plan"},{"id":"f","text":"Sorting it secretly, no one knows"}],"bins":[{"id":"telemanas","label":"Tele-MANAS 14416","valence":"tell"},{"id":"childline","label":"Childline 1098","valence":"tell"},{"id":"centre","label":"De-addiction centre","valence":"pos"},{"id":"emerg","label":"112 / hospital","valence":"uhoh"},{"id":"family","label":"Family-inclusive","valence":"pos"},{"id":"nope","label":"Not a real route","valence":"neg"}],"key":{"a":"telemanas","b":"childline","c":"centre","d":"emerg","e":"family","f":"nope"},"relearn":"Tele-MANAS to talk, Childline for distress, a centre to treat, 112 for danger; secrecy is no route.","persona":"any","source":"need to route bin"},
  {"id":"na-923","cat":"get-the-right-help","type":"sort","hook":"Sort: a strength that helps you reach out, or a barrier that holds you back?","items":[{"id":"a","text":"Treating it as a health issue, not a disgrace"},{"id":"b","text":"Believing nothing and no one can help"},{"id":"c","text":"Asking early, before a crisis"},{"id":"d","text":"Fear of what neighbours will say"},{"id":"e","text":"Willingness to be in treatment as a family"},{"id":"f","text":"'We must keep this entirely secret'"}],"bins":[{"id":"strength","label":"Helps you reach out","valence":"pos"},{"id":"barrier","label":"Holds you back","valence":"neg"}],"key":{"a":"strength","b":"barrier","c":"strength","d":"barrier","e":"strength","f":"barrier"},"relearn":"A health-issue frame, asking early and family involvement help you reach out; hopelessness, fear and secrecy block it.","persona":"any","source":"strength or barrier"},
  {"id":"na-924","cat":"get-the-right-help","type":"sort","hook":"Sort each step of getting help by whether it's a wise move or a risky shortcut.","items":[{"id":"a","text":"Choosing a recognised de-addiction service"},{"id":"b","text":"Trusting a three-day 'guaranteed cure'"},{"id":"c","text":"Asking a free helpline about low-cost options"},{"id":"d","text":"Stopping at the first poor-fit clinic forever"},{"id":"e","text":"Keeping looking for the right-fit counsellor"},{"id":"f","text":"Picking the loudest advertised miracle"}],"bins":[{"id":"wise","label":"Wise move","valence":"pos"},{"id":"risky","label":"Risky shortcut","valence":"neg"}],"key":{"a":"wise","b":"risky","c":"wise","d":"risky","e":"wise","f":"risky"},"relearn":"Recognised services, free guidance and keeping looking are wise; 'guaranteed cures' and giving up are risky.","persona":"any","source":"wise or risky"},
  {"id":"na-925","cat":"get-the-right-help","type":"sort","hook":"Sort each parent feeling by what to do with it on the way to help.","items":[{"id":"a","text":"Honest worry that something is wrong"},{"id":"b","text":"Shame telling you to hide it"},{"id":"c","text":"Hope that treatment can work"},{"id":"d","text":"A voice saying it's all your fault"},{"id":"e","text":"Resolve to call someone today"},{"id":"f","text":"Pride saying you should manage alone"}],"bins":[{"id":"follow","label":"Lean into it","valence":"pos"},{"id":"setdown","label":"Set it aside","valence":"neg"}],"key":{"a":"follow","b":"setdown","c":"follow","d":"setdown","e":"follow","f":"setdown"},"relearn":"Lean into honest worry, hope and resolve to call; set aside shame, blame and the pride that says manage alone.","persona":"any","source":"feeling to do"},
  {"id":"na-926","cat":"get-the-right-help","type":"reflect","hook":"Lensy: reaching out for help models the very help-seeking you hope your child learns. How does that land?","prompt":"Sit with that for a moment.","options":["That reframes it","I can model that","Help-seeking is brave"],"affirm":"When you ask for help, your child sees that needing help and reaching for it is a normal, brave thing to do.","relearn":"Seeking help yourself models help-seeking for your child; it's a strength, not a failure.","persona":"any","source":"modelling help-seeking"},
  {"id":"na-927","cat":"get-the-right-help","type":"reflect","hook":"Lensy: you don't need the perfect words to make the first call, only the willingness to begin. Reassuring?","prompt":"What comes up for you?","options":["I can just begin","Willingness is enough","Less pressure now"],"affirm":"A simple, honest 'I'm worried about my child' is all a service needs; you don't have to get the words perfect.","relearn":"You don't need perfect words to start; a service can take it from an honest, simple opening.","persona":"any","source":"first call willingness"},
  {"id":"na-928","cat":"get-the-right-help","type":"reflect","hook":"Lensy: getting help early isn't an overreaction, it's how we catch any health issue in time. Agree?","prompt":"How do you see it?","options":["Early is sensible","Not overreacting","I'd rather be early"],"affirm":"Reaching out early, before a crisis, isn't fuss; with dependence as with any health issue, early gives the best chance.","relearn":"Early help isn't an overreaction; with dependence, as with any health issue, early gives the best chance.","persona":"any","source":"early isn't overreacting"},
  {"id":"na-929","cat":"get-the-right-help","type":"reflect","hook":"Lensy: you can be part of your child's treatment, not handed outside it. Where does that put you?","prompt":"Notice how that sits.","options":["I stay in it","Part of the team","That's relieving"],"affirm":"Family involvement strongly helps; you stay a central part of treatment, not someone the process happens around.","relearn":"You stay central to treatment; family-inclusive help is part of what makes recovery work.","persona":"any","source":"part of treatment"},
  {"id":"na-930","cat":"get-the-right-help","type":"reflect","hook":"Lensy: a free, confidential call to Tele-MANAS 14416 can start with just 'I'm not sure where to begin'. Try it?","prompt":"Picture making that call.","options":["I could call","Confidential helps","That's a doable start"],"affirm":"Tele-MANAS 14416 is free and confidential; 'I'm not sure where to begin' is a completely fine way to start.","relearn":"A free, confidential Tele-MANAS 14416 call is a low-pressure first step you can take when unsure.","persona":"any","source":"tele-manas first call"},
  {"id":"na-931","cat":"get-the-right-help","type":"reflect","hook":"Lensy: if the first help doesn't fit, that's information, not a dead end. How does keep-looking feel?","prompt":"What do you make of that?","options":["I'd keep looking","One fit isn't all","Worth persisting"],"affirm":"A poor first fit doesn't mean nothing can help; the right counsellor or approach is worth looking for.","relearn":"One poor-fit service isn't the end; keep looking for the right-fit help for your child.","persona":"any","source":"keep-looking mindset"},
  {"id":"na-932","cat":"get-the-right-help","type":"reflect","hook":"Lensy: asking for help with your child is the same courage you'd want them to have one day. Sit with that.","prompt":"How does that feel?","options":["That's courage","I want to model it","Reframes my worry"],"affirm":"The courage it takes to reach out is exactly the courage you hope your child carries; you're showing them how.","relearn":"Reaching out takes courage and shows your child how help-seeking is done; it's a strength to pass on.","persona":"any","source":"courage to ask"},
  {"id":"na-933","cat":"get-the-right-help","type":"role-play","persona":"Divya","source":"shaking first call","hook":"You think your son Aryan, 17, is using something. You're calling a de-addiction service for the first time.","setup":"Your voice shakes as the line connects.","steps":[{"prompt":"A calm voice says: \"Hello, you're through to the service. Take your time.\"","options":[{"text":"\"I'm worried my son may be dependent on something.\"","then":"\"I'm glad you called. What have you noticed?\"","best":true},{"text":"\"Sorry, it's probably nothing. I shouldn't have called.\"","then":"\"You called for a reason. I'm happy to listen.\""},{"text":"\"My son is ruining our lives. Can you take him?\"","then":"\"Let's slow down. Tell me what's been happening.\""},{"text":"\"I'm calling for a friend whose son might be using.\"","then":"\"Of course. Many parents start that way. What have you noticed?\""}],"why":"A simple, honest opening is enough, and a shaky voice doesn't stop them helping."},{"prompt":"The counsellor asks: \"What changes have been worrying you most?\"","options":[{"text":"\"He's dropped his friends, and money keeps going missing.\"","then":"\"Thank you. That gives me a much clearer picture.\"","best":true},{"text":"\"He's just become a bad boy lately. That's all I know.\"","then":"\"Let's set labels aside. What has he actually been doing?\""},{"text":"\"Honestly, maybe I'm just overreacting.\"","then":"\"Your worry counts. What made you call today?\""},{"text":"\"He's moody, but aren't all teenagers these days?\"","then":"\"Some moodiness is normal. What else has changed?\""}],"why":"Describing specific changes over time helps the service see the whole picture."},{"prompt":"The counsellor says: \"A first talk with him matters. How do you think he'll react?\"","options":[{"text":"\"He may get angry. Can you help me plan what to say?\"","then":"\"Yes. Let's work out a calm way to open it.\"","best":true},{"text":"\"I'll just confront him tonight with what I know.\"","then":"\"That can make him defensive. Shall we plan it first?\""},{"text":"\"I won't tell him. Can you call him directly?\"","then":"\"It works better coming from you first. We can help.\""},{"text":"\"I'll wait for the right moment, however long it takes.\"","then":"\"Waiting a long time can make it harder. Let's pick a time.\""}],"why":"Asking for help to plan a calm talk keeps him reachable and keeps you steady."}],"relearn":"A simple, honest opening is enough; a nervous voice and imperfect words don't stop a service from helping."},
  {"id":"na-934","cat":"get-the-right-help","type":"role-play","persona":"Vikram","source":"not broken","hook":"Your son Kunal, 16, has agreed to counselling for his gaming, but he's anxious about it.","setup":"He finds you in the kitchen after dinner.","steps":[{"prompt":"Kunal asks: \"If I go to counselling, does that mean I'm broken?\"","options":[{"text":"\"No. It means we're getting help for a health thing.\"","then":"Kunal leans on the counter. \"Like going to a doctor?\"","best":true},{"text":"\"Well, something's clearly wrong with you, so yes.\"","then":"Kunal's face drops. \"Great. Thanks.\""},{"text":"\"Let's not make a big deal of it. Just go.\"","then":"Kunal shrugs. \"Whatever.\" But he doesn't leave the kitchen."},{"text":"\"Not at all. You'll be totally fine after a few sessions.\"","then":"Kunal looks doubtful. \"Just a few? You're sure?\""}],"why":"Framing counselling as health help, not proof of being broken, lowers his shame."},{"prompt":"Kunal says: \"My friends will laugh at me if they find out.\"","options":[{"text":"\"You decide who knows. There's nothing shameful in it.\"","then":"Kunal thinks. \"Rahul's cousin went too, actually.\"","best":true},{"text":"\"Then don't tell anyone. Ever.\"","then":"Kunal nods slowly. \"So it is something to hide.\""},{"text":"\"Real friends wouldn't laugh. Stop worrying about it.\"","then":"Kunal rolls his eyes. \"You don't know my friends.\""},{"text":"\"Maybe you should stop seeing those friends.\"","then":"Kunal stiffens. \"They're not the problem.\""}],"why":"Letting him choose who knows, while calling it ordinary, respects him and eases the shame."},{"prompt":"Kunal asks: \"Will you tell the counsellor all the bad stuff I've done?\"","options":[{"text":"\"I'll share what I've noticed. You can tell your side.\"","then":"Kunal relaxes a little. \"Okay. That's fair.\"","best":true},{"text":"\"Yes, so they know exactly what you're like.\"","then":"Kunal's jaw tightens. \"Then I'm not going.\""},{"text":"\"No, I won't say anything at all.\"","then":"\"Good,\" Kunal says, relieved. \"Keep it that way.\""},{"text":"\"Only the worst parts, so they see how serious it is.\"","then":"Kunal flinches. \"So they'll think I'm a mess.\""}],"why":"Being honest while leaving room for his voice keeps the counsellor informed and him willing."}],"relearn":"Framing counselling as health help, not proof of being 'broken', lowers shame and keeps a child willing."},
  {"id":"na-935","cat":"get-the-right-help","type":"role-play","persona":"Kamla","source":"hold against shame","hook":"Your daughter Sunita is in counselling for her drinking. At a wedding, your aunt pulls you aside.","setup":"Her voice is low but sharp.","steps":[{"prompt":"Your aunt asks: \"Why are you airing family problems to some counsellor?\"","options":[{"text":"\"Getting Sunita proper help is what a caring family does.\"","then":"Your aunt purses her lips. \"People will talk, you know.\"","best":true},{"text":"\"You're right. Maybe we shouldn't have told anyone at all.\"","then":"\"Good,\" she says. \"Stop before more people hear.\""},{"text":"\"It's none of your business.\"","then":"Her eyes narrow. \"I'm only trying to protect this family.\""},{"text":"\"It's nothing serious, really. Just a few talks.\"","then":"\"Then why go at all?\" she asks."}],"why":"Naming help-seeking as what a caring family does holds the line against shame."},{"prompt":"Your aunt says: \"In our day, we handled such things inside the house.\"","options":[{"text":"\"Alone rarely works. Help is how she gets better.\"","then":"Your aunt pauses. \"And it's actually helping her?\"","best":true},{"text":"\"And look how well that turned out for our family.\"","then":"Your aunt stiffens. \"How dare you say that.\""},{"text":"\"I know. We'll try to keep it quiet from now on.\"","then":"She nods, satisfied. \"The less said, the better.\""},{"text":"\"Times have changed. Let's not argue at a wedding.\"","then":"She sniffs. \"Changed for the worse, if you ask me.\""}],"why":"Dependence usually needs professional help, and saying so calmly answers the old way."},{"prompt":"Your aunt says: \"The others are already asking me what's wrong with Sunita.\"","options":[{"text":"\"Tell them she's unwell and getting care. That's all they need.\"","then":"Your aunt blinks, then softens. \"Just take care of her.\"","best":true},{"text":"\"Please, I'm begging you. Don't tell them anything.\"","then":"She smiles thinly. \"People will guess anyway.\""},{"text":"\"Tell them to mind their own business, or stay away from us.\"","then":"Her face goes stony. \"I'll tell them no such thing.\""},{"text":"\"Tell them it's only exam stress, nothing more.\"","then":"\"So you are hiding something,\" she says."}],"why":"Standing calmly, without shame, protects Sunita from the stigma that blocks recovery."}],"relearn":"Naming help-seeking as what a caring family does holds the line against shame from relatives."},
  {"id":"na-936","cat":"get-the-right-help","type":"role-play","persona":"Vikram","source":"not secret alone","hook":"Your son Manav, 16, has been vaping heavily for a year, and you want professional help.","setup":"Your wife Shalini closes the bedroom door.","steps":[{"prompt":"Shalini says: \"Let's keep this between us and never tell a professional.\"","options":[{"text":"\"Alone usually isn't enough. A counsellor plus us is best.\"","then":"Shalini twists her dupatta. \"But what if it gets out?\"","best":true},{"text":"\"Okay. We'll keep it secret and manage ourselves.\"","then":"Shalini exhales. \"Thank you. We can handle this.\""},{"text":"\"If you won't help, I'll do it without you.\"","then":"Shalini's eyes fill. \"That's not fair.\""},{"text":"\"Fine, but let's at least quietly ask my cousin, the doctor.\"","then":"\"Only family,\" she says. \"Okay. Ask him quietly.\""}],"why":"Handling it in secret usually isn't enough; professional help alongside family works best."},{"prompt":"Shalini says: \"Everyone will think we failed as parents.\"","options":[{"text":"\"This isn't a verdict on us. Any child can struggle.\"","then":"Shalini looks up. \"You really think that?\"","best":true},{"text":"\"Maybe we did fail. That's why we need help.\"","then":"Shalini starts to cry. \"I knew you blamed us.\""},{"text":"\"Who cares what anyone thinks?\"","then":"\"I care,\" she says quietly. \"I have to face them.\""},{"text":"\"No one needs to know. We'll keep it very quiet.\"","then":"Shalini nods. \"Promise me no one finds out.\""}],"why":"Dependence has many causes, and easing the blame helps you both act instead of hide."},{"prompt":"Shalini asks: \"What if Manav hates us for it?\"","options":[{"text":"\"He may be angry at first. We'll tell him we're with him.\"","then":"Shalini nods slowly. \"Together, then.\"","best":true},{"text":"\"He doesn't get a say in this. He's the one who messed up.\"","then":"Shalini hesitates. \"Maybe you're right.\""},{"text":"\"Then let's not tell him, and just take him.\"","then":"Shalini frowns. \"Trick him? That feels wrong too.\""},{"text":"\"He won't. He'll thank us one day, I promise.\"","then":"Shalini isn't sure. \"You can't promise that.\""}],"why":"Expecting his anger, and meeting it with 'we're with you', keeps him reachable."},{"prompt":"Shalini says: \"Say we did it. Who would we even call first?\"","options":[{"text":"\"Tele-MANAS 14416. They'll guide us to the right help.\"","then":"Shalini picks up her phone. \"Let's call now, before we lose our nerve.\"","best":true},{"text":"\"Some clinic online. Whichever one can see him quickest.\"","then":"Shalini scrolls. \"This one promises results in a week.\""},{"text":"\"Let's see if he improves first, then decide.\"","then":"Shalini nods, relieved. \"Yes. Let's wait a bit.\""},{"text":"\"His school principal. The school will know what to do.\"","then":"Shalini hesitates. \"The school? Then everyone will know.\""}],"why":"Tele-MANAS 14416 is a free first call that can point you to the right help."}],"relearn":"Secrecy alone usually isn't enough; pairing professional help with the family gives a child the best chance."},
  {"id":"na-937","cat":"get-the-right-help","type":"role-play","persona":"Divya","source":"won't go alone","hook":"Your daughter Nisha, 15, has agreed to see a counsellor about her gaming. The first session is tomorrow.","setup":"She knocks on your door late at night.","steps":[{"prompt":"Nisha says: \"I'll try, but I don't want to go alone.\"","options":[{"text":"\"You won't. I'll come with you and stay close.\"","then":"Nisha lets out a breath. \"Okay. Thanks.\"","best":true},{"text":"\"You're old enough to deal with the counsellor yourself.\"","then":"Nisha's face falls. \"Fine. Forget I asked.\""},{"text":"\"If you're this nervous, let's postpone it.\"","then":"Nisha looks relieved, then unsure. \"If I put it off, I might never go.\""},{"text":"\"I'll drop you at the door and pick you up after.\"","then":"Nisha hesitates. \"So I walk in alone?\""}],"why":"Going with her makes the first step feel possible, not lonely."},{"prompt":"The next morning, Nisha asks: \"Can you sit in for the first part, at least?\"","options":[{"text":"\"Yes. And I'll step out whenever you want time alone.\"","then":"Nisha nods. \"Okay. That feels better.\"","best":true},{"text":"\"No. You need to learn to do things on your own.\"","then":"Nisha goes quiet. \"Right. Okay.\""},{"text":"\"I'll sit in for all of it, so I know what's said.\"","then":"Nisha stiffens. \"Then I won't say anything real.\""},{"text":"\"Sure. I'll explain everything to them for you.\"","then":"Nisha frowns. \"I can talk too, you know.\""}],"why":"Being there at the start while giving her private time lets her feel safe and speak freely."},{"prompt":"After the session, Nisha says: \"It was weird. I don't know if I want to go back.\"","options":[{"text":"\"First times are weird. Let's try a couple more.\"","then":"Nisha shrugs. \"Okay. Two more. Then we'll see.\"","best":true},{"text":"\"You're going back whether you like it or not.\"","then":"Nisha folds her arms. \"Great. Can't wait.\""},{"text":"\"Fine. If it's weird, you don't have to go.\"","then":"Nisha looks relieved. \"Cool. I'll just game less, then.\""},{"text":"\"What did the counsellor ask you? Tell me.\"","then":"Nisha turns away. \"It's private, Mumma.\""}],"why":"Staying beside her through the awkward start keeps help going."}],"relearn":"Going with a child and staying beside them through help makes the step feel possible, not lonely."},
  {"id":"na-938","cat":"get-the-right-help","type":"role-play","persona":"Vikram","source":"be honest with service","hook":"You're worried about your son Yash's gaming, and you've finally called a counsellor.","setup":"Her voice is warm on the phone.","steps":[{"prompt":"The counsellor asks: \"Tell me what's been happening at home.\"","options":[{"text":"\"It's taken over his sleep, school and mood for months.\"","then":"\"Thank you. That's a clear picture. When did it start?\"","best":true},{"text":"\"It's all fine. I'm probably just overreacting.\"","then":"\"Your worry brought you here. Tell me a little more.\""},{"text":"\"He's just lazy, and he won't listen to anyone.\"","then":"\"Let's look past labels. What does a normal day look like?\""},{"text":"\"He games a bit too much, but school's going fine.\"","then":"\"Okay. So what made you call today?\""}],"why":"Naming the worry honestly helps the service guide you well."},{"prompt":"The counsellor asks: \"What have you tried so far, and how did he react?\"","options":[{"text":"\"We banned it. He got a spare phone and went silent.\"","then":"\"That helps me a lot. It tells us what might work better.\"","best":true},{"text":"\"Everything. Nothing works. He's hopeless.\"","then":"\"He isn't hopeless. Let's go through what you tried.\""},{"text":"\"I'd rather not say. It all went badly.\"","then":"\"That's okay. Knowing what didn't work helps us plan.\""},{"text":"\"We handled it well, I think. He just won't cooperate.\"","then":"\"I see. What happened when you set limits?\""}],"why":"Being honest about what didn't work helps the counsellor plan what will."},{"prompt":"The counsellor says: \"I'd like to see Yash, and you too. Can you both come in?\"","options":[{"text":"\"Yes. I'll talk to him tonight, and we'll both come.\"","then":"\"Wonderful. I'll send you a time this week.\"","best":true},{"text":"\"Can't you just give me tips to fix it at home?\"","then":"\"Some, yes, but seeing him in person helps far more.\""},{"text":"\"Just see him. I'm far too busy to come in.\"","then":"\"It usually works better with a parent involved.\""},{"text":"\"Yes, but I won't tell him it's about the gaming.\"","then":"\"He'll likely work it out. Honesty helps more.\""}],"why":"Coming in together, openly, gives the counsellor and your son the best start."}],"relearn":"Naming the worry honestly helps a service guide you well; minimising it leaves them guessing."},
  {"id":"na-939","cat":"get-the-right-help","type":"role-play","persona":"Vikram","source":"private session ok","hook":"Your son Sahil, 15, has started counselling for his vaping. Before the second session, he pulls you aside.","setup":"He keeps his voice low in the waiting room.","steps":[{"prompt":"Sahil asks: \"Can I talk to the counsellor without you in the room?\"","options":[{"text":"\"Of course. I'll be right outside if you need me.\"","then":"Sahil looks relieved. \"Thanks. It's easier that way.\"","best":true},{"text":"\"No. I'll sit in so I know what you say.\"","then":"Sahil sinks lower. \"Then I'll just say I'm fine.\" The counsellor asks you to wait outside."},{"text":"\"Why? What are you hiding from me?\"","then":"Sahil flushes. \"Nothing. Forget it.\""},{"text":"\"Sure, as long as you tell me everything afterwards.\"","then":"Sahil frowns. \"So it's not really private, then.\""}],"why":"Allowing private time while staying near lets him be honest."},{"prompt":"After the session, Sahil says: \"She asked stuff I didn't expect. It was a lot.\"","options":[{"text":"\"That sounds tiring. Want some chai, or just quiet?\"","then":"Sahil half-smiles. \"Chai. And maybe quiet.\"","best":true},{"text":"\"What stuff? Tell me exactly what she asked.\"","then":"Sahil shuts down. \"Never mind.\""},{"text":"\"Well, you're the one who wanted to go in alone.\"","then":"Sahil looks away. \"Yeah. My mistake, I guess.\""},{"text":"\"That means it's working. You'll be fine now.\"","then":"Sahil shrugs. \"I don't feel fine.\""}],"why":"Offering comfort, not questions, keeps the session a safe place for him."},{"prompt":"A week later, Sahil says: \"The counsellor wants you to come to the next one.\"","options":[{"text":"\"Happy to. I'll mostly listen.\"","then":"Sahil nods. \"Okay. Just don't make it a lecture.\"","best":true},{"text":"\"Finally. Now I'll find out what's going on.\"","then":"Sahil groans. \"This is why I didn't want you there.\""},{"text":"\"I'd rather not. That's your space.\"","then":"Sahil looks a bit hurt. \"She said it would help, though.\""},{"text":"\"Sure. I'll bring a list of everything that's worried me.\"","then":"Sahil winces. \"A list? Seriously?\""}],"why":"Showing up to listen keeps you involved without taking over his space."}],"relearn":"Allowing a private session while staying near lets a child be honest; insisting on watching can silence them."},
  {"id":"na-940","cat":"get-the-right-help","type":"role-play","persona":"Vikram","source":"choose real care","hook":"Your son Karan has just started seeing a de-addiction counsellor for his drinking.","setup":"Your neighbour stops you at the gate.","steps":[{"prompt":"He says: \"Skip the counsellor. My nephew did a one-week cure. Fixed him.\"","options":[{"text":"\"I'm glad he's well. We'll stick with a recognised service.\"","then":"He shrugs. \"Your choice. But one week, yaar.\"","best":true},{"text":"\"A one-week cure? Send me the details.\"","then":"He beams and forwards a number. \"Call today. They fill up fast.\""},{"text":"\"That's nonsense. You really shouldn't spread such things.\"","then":"He bristles. \"I was only trying to help.\""},{"text":"\"Maybe we'll try it once the counselling is over.\"","then":"\"Why wait?\" he says. \"Do both. What's the harm?\""}],"why":"Choosing recognised care over a 'miracle cure' protects him from harm and delay."},{"prompt":"He adds: \"Counselling takes months. Who has that kind of time?\"","options":[{"text":"\"Real recovery takes time. That's how it lasts.\"","then":"He scratches his head. \"Hm. My nephew did slip again, actually.\"","best":true},{"text":"\"You're right. Months is far too long.\"","then":"\"Exactly,\" he says. \"Try the one-week place.\""},{"text":"\"Please don't tell anyone else about Karan.\"","then":"He looks offended. \"Who would I tell?\""},{"text":"\"We're hoping it'll be quick. Maybe a few weeks.\"","then":"\"And if it isn't?\" he asks."}],"why":"Recovery is real but rarely instant; lasting change takes steady support."},{"prompt":"That evening, Karan says: \"Uncle says there's a one-week cure. Why can't I do that?\"","options":[{"text":"\"Quick fixes rarely last. We'll stick with it together.\"","then":"Karan sighs. \"Okay. But it's so slow.\"","best":true},{"text":"\"If you want to try it, let's try it.\"","then":"Karan grins. \"Really? Then I can stop the sessions?\""},{"text":"\"Because you don't get to choose any more.\"","then":"Karan scowls. \"Great. Nothing I say matters.\""},{"text":"\"Ask your counsellor about it. I don't really know.\"","then":"Karan shrugs. \"She'll just say no.\""}],"why":"Explaining why real care lasts, and staying with him, keeps him in treatment."}],"relearn":"Choosing recognised, evidence-based care over a 'miracle cure' protects a child from harm and delay."},
  {"id":"na-941","cat":"get-the-right-help","type":"role-play","persona":"Kamla","source":"slip not the end","hook":"Your son Munna, 16, has been in treatment for his drinking for two months.","setup":"Tonight he comes home late, avoiding your eyes.","steps":[{"prompt":"Munna says: \"I slipped again. You must be done with me.\"","options":[{"text":"\"A slip isn't the end. I'm still right here with you.\"","then":"Munna's eyes fill. \"I thought you'd throw me out.\"","best":true},{"text":"\"After everything we tried? That's it. I give up.\"","then":"Munna's face crumples. \"I knew it.\""},{"text":"\"It's fine. Let's just forget it happened.\"","then":"Munna looks relieved. \"Really? I thought you'd be so angry.\""},{"text":"\"I'm not done, but promise me this is the last time.\"","then":"Munna nods fast. \"I promise.\" He looks scared."}],"why":"Treating a slip as part of recovery, not a verdict, keeps him reachable."},{"prompt":"Munna asks: \"Do we have to tell the counsellor about this?\"","options":[{"text":"\"Yes. She'll help adjust the plan, not punish you.\"","then":"Munna nods slowly. \"Okay. Will you come with me?\"","best":true},{"text":"\"No. It can be our secret this time.\"","then":"Munna exhales. \"Good. She'd think I'm hopeless.\""},{"text":"\"Yes, and I'll tell her how badly you've let us down.\"","then":"Munna flinches. \"Then I'm not going.\""},{"text":"\"Only if it happens again. This one can pass.\"","then":"Munna nods. \"Okay. It won't happen again.\""}],"why":"Telling the counsellor turns a slip into useful information for the plan."},{"prompt":"Munna says: \"Everyone in the basti saw me come home like that.\"","options":[{"text":"\"Let them talk. What matters is you're getting help.\"","then":"Munna looks up. \"You're not ashamed of me?\"","best":true},{"text":"\"Yes, and they'll never let us forget it.\"","then":"Munna hangs his head. \"I've ruined everything.\""},{"text":"\"We'll just tell them you were feeling unwell.\"","then":"Munna nods. \"Okay. So it's a secret.\""},{"text":"\"Stay indoors for a few weeks until they forget.\"","then":"Munna's shoulders drop. \"So I'm locked away now.\""}],"why":"Refusing the shame keeps his focus on recovery, not on hiding."},{"prompt":"The next day, Munna asks: \"What if I slip again?\"","options":[{"text":"\"Then we deal with it the same way. Together.\"","then":"Munna nods. \"Okay. I'll keep going.\"","best":true},{"text":"\"You won't. I simply won't allow it.\"","then":"Munna looks worried. \"And if I do anyway?\""},{"text":"\"Then I really will give up on you.\"","then":"Munna goes pale. \"Okay,\" he whispers."},{"text":"\"Then maybe this treatment isn't right for you.\"","then":"Munna frowns. \"So I should stop going?\""}],"why":"Knowing a slip won't cost him your support keeps him in treatment."}],"relearn":"Treating a slip as part of recovery, not a verdict, keeps a child in treatment and reachable."},
  {"id":"na-942","cat":"get-the-right-help","type":"role-play","persona":"Kamla","source":"can't afford it","hook":"Your daughter Guddi, 14, can't put down the games on her phone, and her sleep and school are slipping.","setup":"Your husband is counting the month's money at the table.","steps":[{"prompt":"Your husband says: \"Counselling costs too much. We can't afford help.\"","options":[{"text":"\"Tele-MANAS 14416 is free. Let's at least find out.\"","then":"He looks up. \"Free? You're sure?\"","best":true},{"text":"\"You're right. It's hopeless. Let's not even look.\"","then":"He nods. \"Good. No point wasting money.\""},{"text":"\"We'll borrow whatever it takes, even from a moneylender.\"","then":"His face darkens. \"And pay it back how?\""},{"text":"\"Let's wait until we've saved up, then look into it.\"","then":"He shrugs. \"Fine. Maybe next year.\""}],"why":"A free helpline can open low-cost routes, so cost worry needn't end the search."},{"prompt":"Your husband says: \"Besides, who has time for counsellors, with our hours?\"","options":[{"text":"\"I'll ring Tele-MANAS 14416 on my lunch break. It's free.\"","then":"He grunts. \"If you want. Tell me what they say.\"","best":true},{"text":"\"Fine. I'll forget about it, then.\"","then":"He nods. \"Good. We have enough to deal with.\""},{"text":"\"You never have time for anything to do with her.\"","then":"He stands up. \"I work all day for her.\""},{"text":"\"I'll ask the lady at the chemist's shop what to do.\"","then":"\"She'll know something,\" he says. \"Ask her.\""}],"why":"A short call fits into a busy day and can point you to real help."},{"prompt":"Your husband adds: \"And any place that charges fees, we're not going.\"","options":[{"text":"\"Then we ask about government or low-cost options.\"","then":"He thinks. \"Government? Okay. That we can do.\"","best":true},{"text":"\"Then we'll handle Guddi ourselves, at home.\"","then":"\"Yes,\" he says. \"Stricter. That's all she needs.\""},{"text":"\"Then I'll take extra shifts and pay, whatever it costs.\"","then":"He frowns. \"And when will you ever sleep?\""},{"text":"\"Then we'll go only once, just to see what they say.\"","then":"\"Once is fine,\" he says. \"Not more.\""}],"why":"Asking for government and low-cost services keeps help within reach."}],"relearn":"A free helpline like Tele-MANAS 14416 can open low-cost routes; cost worry needn't end the search."},
  {"id":"na-943","cat":"get-the-right-help","type":"role-play","persona":"Divya","source":"first words after opening up","hook":"Your daughter Ananya, 16, sits on your bed and admits she's been drinking at parties for months.","setup":"Her voice is barely above a whisper.","steps":[{"prompt":"Ananya says: \"I didn't know how to tell you. Please don't be angry.\"","options":[{"text":"\"Thank you for trusting me. I'm on your side.\"","then":"Ananya starts to cry. \"I've wanted to stop for a while.\"","best":true},{"text":"\"I knew it. Wait till the rest of the family hears.\"","then":"Ananya freezes. \"Please don't tell them.\""},{"text":"\"How could you do this to us?\"","then":"Ananya pulls her knees up. \"I knew you'd say that.\""},{"text":"\"I'm not angry. Now tell me who you drink with.\"","then":"Ananya tenses. \"Why? So you can call their parents?\""}],"why":"Meeting her honesty with thanks and calm keeps her talking."},{"prompt":"Ananya asks: \"Are you going to tell Papa?\"","options":[{"text":"\"Yes, gently, so we can help you together.\"","then":"Ananya hesitates. \"Okay. Can you be there when he hears?\"","best":true},{"text":"\"No. This stays between us forever.\"","then":"Ananya relaxes. \"Promise?\""},{"text":"\"Of course. He needs to know what you've done.\"","then":"Ananya's face drops. \"He'll never look at me the same.\""},{"text":"\"Let's wait a few months before we tell him.\"","then":"Ananya nods, relieved. \"Okay. Maybe.\""}],"why":"Telling her father gently, and honestly, keeps her trust and brings the family in."},{"prompt":"Ananya says: \"I think I need help, but I'm scared of rehab.\"","options":[{"text":"\"We can start with a counsellor. I'll come with you.\"","then":"Ananya wipes her eyes. \"Just talking? Okay.\"","best":true},{"text":"\"If you'd stopped earlier, you wouldn't need it.\"","then":"Ananya goes silent. \"Forget it.\""},{"text":"\"You don't need help. Just stop going to parties.\"","then":"Ananya looks doubtful. \"I've tried that.\""},{"text":"\"Let's handle it ourselves first, and see how it goes.\"","then":"Ananya nods. \"Okay. I'll try harder.\""}],"why":"Starting with a counsellor, together, makes help feel possible and less frightening."},{"prompt":"That night, Ananya asks: \"Are you disappointed in me?\"","options":[{"text":"\"I'm worried, not disappointed. I love you.\"","then":"Ananya hugs you. \"I love you too, Mumma.\"","best":true},{"text":"\"Honestly, yes. Very disappointed.\"","then":"Ananya pulls away. \"I thought so.\""},{"text":"\"Let's not talk about feelings. Just get better.\"","then":"Ananya nods. \"Okay,\" she says quietly."},{"text":"\"No, I'm proud of you. It's all fixed now.\"","then":"Ananya looks unsure. \"It doesn't feel fixed.\""}],"why":"Honest worry wrapped in love keeps her safe to be honest again."}],"relearn":"Meeting a child's honesty with 'we'll find help together' keeps them open; a shaming reaction shuts them down."},
  {"id":"na-944","cat":"get-the-right-help","type":"spot","hook":"Lensy: spot the two lines that would push a child away from getting help.","scene":[{"id":"a","text":"'Let's find a counsellor and go through this together'","trick":false},{"id":"b","text":"'You're a disgrace, sort yourself out alone'","trick":true},{"id":"c","text":"'This is a health issue and help works'","trick":false},{"id":"d","text":"'Tell anyone and you're out of this house'","trick":true},{"id":"e","text":"'I'm on your side every step of the way'","trick":false}],"why":"The two caught lines shame and threaten, which drive a child to hide; the rest invite them toward help.","relearn":"Shaming and threatening lines push a child away from help; calm, on-your-side lines open the door.","persona":"any","source":"lines that push away"},
  {"id":"na-945","cat":"get-the-right-help","type":"spot","hook":"Lensy: spot the two ideas about getting help that aren't true.","scene":[{"id":"a","text":"Family-inclusive treatment improves a child's outcomes","trick":false},{"id":"b","text":"Asking for help means you've failed as a parent","trick":true},{"id":"c","text":"Effective, evidence-based treatment exists","trick":false},{"id":"d","text":"It's always too late once a habit takes hold","trick":true},{"id":"e","text":"Reaching out early gives the best chance","trick":false}],"why":"The two caught ideas are myths: asking is a strength, not failure, and recovery is real, not 'too late'.","relearn":"Asking isn't failing and it's rarely 'too late'; family-inclusive, early, evidence-based help works.","persona":"any","source":"false ideas about help"},
  {"id":"na-946","cat":"get-the-right-help","type":"spot","hook":"Lensy: spot the two 'help' options that are actually red flags.","scene":[{"id":"a","text":"A recognised de-addiction centre offering assessment","trick":false},{"id":"b","text":"A clinic promising a guaranteed cure in three days","trick":true},{"id":"c","text":"Tele-MANAS 14416, free and any time","trick":false},{"id":"d","text":"A stranger online selling a secret miracle remedy","trick":true},{"id":"e","text":"A counsellor who includes the whole family","trick":false}],"why":"The two caught options are red flags: 'guaranteed cures' and secret online remedies aren't real treatment.","relearn":"'Guaranteed cures' and secret online remedies are red flags; recognised services are real help.","persona":"any","source":"red-flag help options"},
  {"id":"na-947","cat":"get-the-right-help","type":"spot","hook":"Lensy: spot the two reasons-to-delay that should not stop you reaching out.","scene":[{"id":"a","text":"'Let's wait until it gets really bad first'","trick":true},{"id":"b","text":"Saving Tele-MANAS 14416 so you can call early","trick":false},{"id":"c","text":"'People might find out, so let's stay silent'","trick":true},{"id":"d","text":"Treating dependence as a health issue to address","trick":false},{"id":"e","text":"Booking an early assessment before a crisis","trick":false}],"why":"The two caught lines are the delaying traps, waiting for crisis and fear of gossip, that hold help back.","relearn":"Waiting for crisis and fear of gossip are traps; early help moves you forward.","persona":"any","source":"reasons-to-delay traps"},
  {"id":"na-948","cat":"get-the-right-help","type":"spot","hook":"Lensy: spot the two responses that match a need to the WRONG help route.","scene":[{"id":"a","text":"Talk it through any time → Tele-MANAS 14416","trick":false},{"id":"b","text":"A possible overdose now → just wait and watch","trick":true},{"id":"c","text":"A child in distress now → Childline 1098","trick":false},{"id":"d","text":"Worried, not urgent → rush to emergency","trick":true},{"id":"e","text":"Ready for treatment → a de-addiction centre","trick":false}],"why":"The two caught lines route wrongly: a possible overdose needs 112 or a hospital now, not 'wait and watch'.","relearn":"Match route to need: 112 for acute danger, Tele-MANAS to talk, Childline for distress, a centre to treat.","persona":"any","source":"wrong route matches"},
  {"id":"na-949","cat":"get-the-right-help","type":"spot","hook":"Lensy: spot the two things that quietly block a family from getting help.","scene":[{"id":"a","text":"Shame that keeps you from picking up the phone","trick":true},{"id":"b","text":"Saving the helpline numbers on the fridge","trick":false},{"id":"c","text":"Belief that nothing and no one can help","trick":true},{"id":"d","text":"Naming the worry honestly to a counsellor","trick":false},{"id":"e","text":"Bringing your partner into the plan","trick":false}],"why":"The two caught items are the blockers, shame and hopelessness, that stop a family reaching real, available help.","relearn":"Shame and hopelessness block help; saving numbers, honesty and a partner's support open the way to it.","persona":"any","source":"quiet blockers"},
  {"id":"na-950","cat":"get-the-right-help","type":"spot","hook":"Lensy: spot the two moves that hand a child to help without keeping the family connected.","scene":[{"id":"a","text":"Going with your child to the first session","trick":false},{"id":"b","text":"Dropping them at a centre and stepping fully out","trick":true},{"id":"c","text":"Joining family-inclusive sessions when asked","trick":false},{"id":"d","text":"Refusing to be involved once treatment starts","trick":true},{"id":"e","text":"Checking in warmly between appointments","trick":false}],"why":"The two caught moves cut the family out; family involvement is part of what makes treatment hold.","relearn":"Staying connected through treatment helps recovery; dropping a child off and stepping out won't.","persona":"any","source":"stay-connected"},
  {"id":"na-951","cat":"get-the-right-help","type":"spot","hook":"Lensy: spot the two assumptions that wrongly tell a parent help is out of reach.","scene":[{"id":"a","text":"'Good help must be too expensive for us'","trick":true},{"id":"b","text":"A free helpline can point to low-cost options","trick":false},{"id":"c","text":"'The centre is far, so help is impossible'","trick":true},{"id":"d","text":"A phone call can start the help from anywhere","trick":false},{"id":"e","text":"Recovery is real and common with support","trick":false}],"why":"The two caught assumptions, 'too costly' and 'too far', are false: a free phone call opens low-cost routes.","relearn":"Cost and distance needn't block help: a free Tele-MANAS 14416 call opens routes from anywhere.","persona":"any","source":"out-of-reach assumptions"},
  {"id":"na-990","cat":"its-a-health-issue","type":"strike-rewrite","hook":"\"Dependence is a choice; he chooses this every single day.\"","myth":{"un":"Dependence is a choice; he chooses this every single day.","re":"Dependence changes the brain's reward system, so the pull is far stronger than ordinary choice; that's why treatment, not blame, helps.","why":"The changed brain is what makes stopping so hard."},"relearn":"Dependence isn't a daily free choice; the brain's reward system has changed, which is why support and treatment matter.","persona":"Vikram","source":"not a simple choice"},
  {"id":"na-991","cat":"its-a-health-issue","type":"strike-rewrite","hook":"\"No one in our family was ever like this, so it can't be a real condition.\"","myth":{"un":"No one in our family was ever like this, so it can't be a real condition.","re":"Genes, environment and the brain all play a part; dependence can affect any child from any family, with or without a family history.","why":"No single cause means no family is immune."},"relearn":"Dependence is shaped by genes, environment and the brain; it can affect any child, history or not.","persona":"any","source":"any family affected"},
  {"id":"na-992","cat":"its-a-health-issue","type":"strike-rewrite","hook":"\"If I'd raised her right, she'd never have a problem like this.\"","myth":{"un":"If I'd raised her right, she'd never have a problem like this.","re":"Dependence is a health condition shaped by genes, brain and environment; it's not a verdict on your parenting any more than asthma would be.","why":"A health issue is no one's moral failure."},"relearn":"Dependence isn't proof you parented wrong; it's a health condition, not a verdict on you.","persona":"Divya","source":"not a parenting verdict"},
  {"id":"na-993","cat":"its-a-health-issue","type":"strike-rewrite","hook":"\"It's not an illness, he's just been hanging with a bad crowd.\"","myth":{"un":"It's not an illness, he's just been hanging with a bad crowd.","re":"Environment is one real factor, but once dependence sets in it's a health condition in the brain, not just bad company, and it needs treatment.","why":"Naming the crowd alone won't undo the dependence."},"relearn":"Friends may be a factor, but settled dependence is a health condition needing treatment, not just a change of crowd.","persona":"Vikram","source":"more than the crowd"},
  {"id":"na-994","cat":"its-a-health-issue","type":"strike-rewrite","hook":"\"Screen and gaming 'addiction' isn't a real thing, it's not like drugs.\"","myth":{"un":"Screen and gaming 'addiction' isn't a real thing, it's not like drugs.","re":"Gaming disorder is a recognised health condition; screen dependence can genuinely disrupt a child's sleep, mood and life, and deserves help.","why":"Recognised conditions get real help, not dismissal."},"relearn":"Gaming disorder is recognised; screen dependence is real and deserves the same help-first response as any other.","persona":"any","source":"screens count too"},
  {"id":"na-995","cat":"its-a-health-issue","type":"strike-rewrite","hook":"\"There's no point treating it; relapses just prove it's hopeless.\"","myth":{"un":"There's no point treating it; relapses just prove it's hopeless.","re":"Dependence is a chronic but treatable condition; a relapse is a sign to adjust the plan, not proof of failure, much like other long-term illnesses.","why":"Chronic conditions are managed over time, not 'cured' in one go."},"relearn":"A relapse isn't proof it's hopeless; dependence is chronic but treatable, and the plan can be adjusted.","persona":"Vikram","source":"relapse not failure"},
  {"id":"na-996","cat":"its-a-health-issue","type":"strike-rewrite","hook":"\"Counselling is for people who are mentally weak; my child just needs to toughen up.\"","myth":{"un":"Counselling is for people who are mentally weak; my child just needs to toughen up.","re":"Dependence is a health condition, and counselling is evidence-based treatment for it, not a sign of weakness, just as you'd see a doctor for any illness.","why":"Getting treatment is what you'd do for any health problem."},"relearn":"Counselling is real treatment for a health condition, not weakness; 'toughen up' isn't a treatment.","persona":"Kamla","source":"treatment not weakness"},
  {"id":"na-997","cat":"its-a-health-issue","type":"strike-rewrite","hook":"\"She's ruined now; a child who gets into this can never have a normal life.\"","myth":{"un":"She's ruined now; a child who gets into this can never have a normal life.","re":"Recovery is real and common with support; many people who get and stay in treatment rebuild full, ordinary lives.","why":"A treatable condition does not end a life."},"relearn":"Dependence doesn't ruin a child's future; recovery is real and common, and a full life is possible with support.","persona":"any","source":"recovery is common"},
  {"id":"na-998","cat":"its-a-health-issue","type":"strike-rewrite","hook":"\"Calling it a 'health issue' is just making excuses for bad behaviour.\"","myth":{"un":"Calling it a 'health issue' is just making excuses for bad behaviour.","re":"Naming dependence as a health condition isn't excusing it; it points to what actually helps, treatment, while you still hold calm, firm limits.","why":"A diagnosis explains, it doesn't excuse, and it opens the door to help."},"relearn":"Seeing dependence as a health issue isn't an excuse; it shows the route to help while you keep firm, calm limits.","persona":"Vikram","source":"explains not excuses"},
  {"id":"na-999","cat":"its-a-health-issue","type":"strike-rewrite","hook":"\"The stigma doesn't matter; what matters is that he stops.\"","myth":{"un":"The stigma doesn't matter; what matters is that he stops.","re":"Stigma matters a lot: feeling 'bad' or 'hopeless' is exactly what blocks a child from accepting help, so dropping the shame is part of the treatment.","why":"Shame drives dependence underground; safety to be honest lets help in."},"relearn":"Dropping the 'bad/weak/hopeless' stigma isn't soft; it's what lets a child accept the help that helps them stop.","persona":"any","source":"stigma blocks help"},
  {"id":"na-1000","cat":"its-a-health-issue","type":"strike-rewrite","hook":"\"Real addiction is only the hard drugs; her phone habit is nothing to treat.\"","myth":{"un":"Real addiction is only the hard drugs; her phone habit is nothing to treat.","re":"The pattern, loss of control, escalation and disruption of life, is the same across substances and screens; both are health concerns worth a calm look.","why":"Same trio of signs, whatever the habit is about."},"relearn":"Dependence shows the same trio, loss of control, escalation, disruption, on screens as on substances; both deserve help.","persona":"any","source":"same pattern across both"},
  {"id":"na-1001","cat":"its-a-health-issue","type":"sort","hook":"Sort each line: health-condition view, or moral-failing view?","items":[{"id":"a","text":"\"It's treatable; let's find help\""},{"id":"b","text":"\"You've shamed this family\""},{"id":"c","text":"\"Genes and the brain played a part\""},{"id":"d","text":"\"A decent person wouldn't do this\""},{"id":"e","text":"\"Recovery is real, with support\""},{"id":"f","text":"\"This proves his weak character\""}],"bins":[{"id":"health","label":"Health view","valence":"pos"},{"id":"moral","label":"Moral-failing view","valence":"neg"}],"key":{"a":"health","b":"moral","c":"health","d":"moral","e":"health","f":"moral"},"relearn":"'Treatable', 'genes and brain', 'recovery is real' treat it as health; 'shamed the family', 'decent wouldn't', 'weak character' make it a failing.","persona":"any","source":"health vs moral lines"},
  {"id":"na-1002","cat":"its-a-health-issue","type":"sort","hook":"Sort: which of these is TRUE about dependence, and which is a stigma myth?","items":[{"id":"a","text":"It changes the brain's reward system"},{"id":"b","text":"It only happens to 'bad' kids"},{"id":"c","text":"It's treatable, and recovery is real"},{"id":"d","text":"Strong-willed children just stop on their own"},{"id":"e","text":"Family involvement improves outcomes"},{"id":"f","text":"Once dependent, always hopeless"}],"bins":[{"id":"true","label":"True about it","valence":"pos"},{"id":"myth","label":"Stigma myth","valence":"neg"}],"key":{"a":"true","b":"myth","c":"true","d":"myth","e":"true","f":"myth"},"relearn":"True: it changes the brain, it's treatable, family helps. Myths: 'only bad kids', 'just stop with willpower', 'always hopeless'.","persona":"any","source":"true vs stigma myth"},
  {"id":"na-1003","cat":"its-a-health-issue","type":"sort","hook":"Sort each factor: is it part of what shapes dependence, or a blame that doesn't belong?","items":[{"id":"a","text":"Genetics and family history"},{"id":"b","text":"\"It's the mother's fault\""},{"id":"c","text":"How the brain's reward system responds"},{"id":"d","text":"Stress and environment around the child"},{"id":"e","text":"\"He was just born bad\""},{"id":"f","text":"\"This is God's punishment on us\""}],"bins":[{"id":"factor","label":"Real factor","valence":"neutral"},{"id":"blame","label":"Misplaced blame","valence":"neg"}],"key":{"a":"factor","b":"blame","c":"factor","d":"factor","e":"blame","f":"blame"},"relearn":"Genes, brain and environment are real factors; 'mother's fault', 'born bad' and 'God's punishment' are blame that doesn't belong.","persona":"any","source":"factors vs blame"},
  {"id":"na-1004","cat":"its-a-health-issue","type":"sort","hook":"Sort: which responses treat dependence like any other health problem, and which add shame?","items":[{"id":"a","text":"Booking an assessment with a counsellor"},{"id":"b","text":"\"Don't tell anyone, it's a disgrace\""},{"id":"c","text":"Making a treatment plan together"},{"id":"d","text":"Calling her a junkie in front of others"},{"id":"e","text":"Tracking progress calmly over time"},{"id":"f","text":"Punishing her to 'teach a lesson'"}],"bins":[{"id":"health","label":"Health response","valence":"pos"},{"id":"shame","label":"Shame response","valence":"neg"}],"key":{"a":"health","b":"shame","c":"health","d":"shame","e":"health","f":"shame"},"relearn":"Assessment, a plan and calm tracking treat it as health; secrecy-as-disgrace, name-calling and punishment add shame.","persona":"any","source":"health response vs shame"},
  {"id":"na-1005","cat":"its-a-health-issue","type":"sort","hook":"Sort each phrase: does it carry hope a child can recover, or despair that there's no point?","items":[{"id":"a","text":"\"This is treatable; we have a path\""},{"id":"b","text":"\"You're a lost cause now\""},{"id":"c","text":"\"People recover from this every day\""},{"id":"d","text":"\"There's no saving you\""},{"id":"e","text":"\"We'll get the right help and keep going\""},{"id":"f","text":"\"It's pointless, you'll never change\""}],"bins":[{"id":"hope","label":"Carries hope","valence":"pos"},{"id":"despair","label":"Carries despair","valence":"neg"}],"key":{"a":"hope","b":"despair","c":"hope","d":"despair","e":"hope","f":"despair"},"relearn":"'Treatable, we have a path', 'people recover', 'we'll keep going' carry hope; 'lost cause', 'no saving you', 'pointless' carry despair.","persona":"any","source":"hope vs despair"},
  {"id":"na-1006","cat":"its-a-health-issue","type":"sort","hook":"Sort: which beliefs help a parent respond well, and which get in the way?","items":[{"id":"a","text":"\"My child is unwell, not bad\""},{"id":"b","text":"\"He's doing this to spite me\""},{"id":"c","text":"\"Asking for help is a strength\""},{"id":"d","text":"\"We must hide this from everyone\""},{"id":"e","text":"\"Treatment can genuinely work\""},{"id":"f","text":"\"Willpower is all she really needs\""}],"bins":[{"id":"helps","label":"Helps you respond","valence":"pos"},{"id":"blocks","label":"Gets in the way","valence":"neg"}],"key":{"a":"helps","b":"blocks","c":"helps","d":"blocks","e":"helps","f":"blocks"},"relearn":"'Unwell not bad', 'asking help is strength', 'treatment works' help you respond; 'doing it to spite me', 'hide it', 'just willpower' get in the way.","persona":"any","source":"beliefs help vs block"},
  {"id":"na-1007","cat":"its-a-health-issue","type":"sort","hook":"Sort each line: keeps the person, or shrinks them to a label?","items":[{"id":"a","text":"\"My son, who is struggling\""},{"id":"b","text":"\"My son the addict\""},{"id":"c","text":"\"A child with a health problem\""},{"id":"d","text":"\"A junkie, plain and simple\""},{"id":"e","text":"\"She has a treatable condition\""},{"id":"f","text":"\"She IS the problem\""}],"bins":[{"id":"person","label":"A person with it","valence":"pos"},{"id":"label","label":"Just the label","valence":"neg"}],"key":{"a":"person","b":"label","c":"person","d":"label","e":"person","f":"label"},"relearn":"'Who is struggling', 'a child with a problem', 'she has a condition' keep the person; 'the addict', 'a junkie', 'she IS the problem' shrink them to a label.","persona":"any","source":"person not label"},
  {"id":"na-1008","cat":"its-a-health-issue","type":"sort","hook":"Sort: treating it like a health issue, or like a crime?","items":[{"id":"a","text":"Asking a professional what's going on"},{"id":"b","text":"Interrogating her like a suspect"},{"id":"c","text":"Following a treatment plan"},{"id":"d","text":"Demanding a confession"},{"id":"e","text":"Staying connected as she recovers"},{"id":"f","text":"Treating her as guilty till 'cured'"}],"bins":[{"id":"care","label":"Health issue","valence":"pos"},{"id":"crime","label":"Like a crime","valence":"neg"}],"key":{"a":"care","b":"crime","c":"care","d":"crime","e":"care","f":"crime"},"relearn":"Asking a professional, a plan and staying connected treat it as health; interrogation, demanding a confession and treating her as guilty treat it as a crime.","persona":"Kamla","source":"care not crime"},
  {"id":"na-1009","cat":"its-a-health-issue","type":"reflect","hook":"Lensy: if your child had diabetes, you'd never call it a moral failing; dependence deserves that same lens. Sit right?","prompt":"What's your take?","options":["Sits right","Same lens as diabetes","No shame, just help"],"affirm":"You'd treat diabetes with a plan and no shame; giving dependence that same health lens moves you from blame toward what actually helps.","relearn":"Give dependence the lens you'd give any illness like diabetes: a plan, support, and no shame.","persona":"any","source":"diabetes lens"},
  {"id":"na-1010","cat":"its-a-health-issue","type":"reflect","hook":"Lensy: the hardest stigma to drop is sometimes the one you aim at your own parenting. Worth sitting with?","prompt":"What do you feel?","options":["Worth sitting with","I do blame myself","Letting that go helps"],"affirm":"Easing the blame you aim at your own parenting isn't letting your child down; a calmer, less ashamed parent is exactly who can help them best.","relearn":"Dependence isn't a verdict on your parenting; easing self-blame leaves you steadier to help.","persona":"Divya","source":"ease self-blame"},
  {"id":"na-1011","cat":"its-a-health-issue","type":"reflect","hook":"Lensy: 'just stop' sounds simple, until you remember the brain's reward system has changed. Land for you?","prompt":"What's your view?","options":["Lands for me","Explains why it's so hard","It's not about strength"],"affirm":"Knowing dependence changes the brain's reward system reframes 'why won't they just stop' into 'what support will help', which is the question that opens doors.","relearn":"'Just stop' is hard because the brain has changed; the better question is what support will help.","persona":"Vikram","source":"why just stop is hard"},
  {"id":"na-1012","cat":"its-a-health-issue","type":"reflect","hook":"Lensy: seeing your child as unwell rather than bad changes the very tone of your voice. Notice that?","prompt":"What comes up?","options":["I notice it","Changes my tone","Care over contempt"],"affirm":"Holding 'unwell, not bad' softens your tone from contempt to care, and a child can hear care, which is what keeps them reachable.","relearn":"See your child as unwell, not bad; it shifts your tone to care, and care keeps them reachable.","persona":"any","source":"unwell not bad tone"},
  {"id":"na-1013","cat":"its-a-health-issue","type":"reflect","hook":"Lensy: recovery is rarely a straight line, and a wobble isn't a verdict. Sit right with you?","prompt":"What's your take?","options":["Sits right","Wobbles aren't the end","We adjust and keep going"],"affirm":"Recovery from a chronic condition has wobbles; treating a setback as information to adjust the plan, not proof of failure, is how families keep going.","relearn":"Recovery wobbles; a setback is information to adjust the plan, not proof it's hopeless.","persona":"any","source":"wobbles aren't a verdict"},
  {"id":"na-1014","cat":"its-a-health-issue","type":"reflect","hook":"Lensy: there's relief in naming it a health issue, it means there's a path, not a sentence. Resonate?","prompt":"What do you feel?","options":["Resonates","A path, not a sentence","That's a relief"],"affirm":"Naming dependence as a health issue turns a frightening 'sentence' into a treatable path with known help; that reframe is where calm action begins.","relearn":"Calling it a health issue gives you a treatable path, not a life sentence, and that's where calm action starts.","persona":"any","source":"a path not a sentence"},
  {"id":"na-1015","cat":"its-a-health-issue","type":"reflect","hook":"Lensy: you can hold a firm limit AND see this as a health issue at the same time. Both at once, yes?","prompt":"What's your view?","options":["Both at once","Firm and compassionate","Limits aren't punishment"],"affirm":"Seeing dependence as a health issue doesn't mean dropping limits; you can be firm about the behaviour and compassionate about the condition together.","relearn":"A health-issue lens and firm limits go together; you can be firm about the behaviour and kind about the condition.","persona":"Vikram","source":"firm and a health issue"},
  {"id":"na-1016","cat":"its-a-health-issue","type":"reflect","hook":"Lensy: the word 'addict' can shrink a whole child to one struggle. Worth choosing words with care?","prompt":"What comes up?","options":["Worth it","My child is more than this","Words shape how I see them"],"affirm":"Choosing 'my child who is struggling' over 'the addict' keeps the whole person in view, and how you name them shapes how you, and they, see their chances.","relearn":"Name the struggle, not the child; 'my child who is struggling' keeps the whole person, and the hope, in view.","persona":"any","source":"more than the label"},
  {"id":"na-1017","cat":"its-a-health-issue","type":"match","hook":"Match each health-issue truth to the parenting move it points to.","pairs":[{"left":"It changes the brain's reward system","right":"Drop 'willpower'; seek treatment"},{"left":"It's not a moral failing","right":"Respond with care, not contempt"},{"left":"Recovery is real and common","right":"Hold hope through setbacks"},{"left":"Stigma blocks help","right":"Make it safe to be honest"},{"left":"Any child can be affected","right":"Drop the blame on yourself"}],"relearn":"Brain change points to treatment; not-moral to care; recovery to hope; stigma to honesty; any-child to dropping blame.","persona":"any","source":"truth to move"},
  {"id":"na-1018","cat":"its-a-health-issue","type":"match","hook":"Match each stigma label to the truer line that replaces it.","pairs":[{"left":"\"He's just weak-willed\"","right":"His brain's reward system has changed"},{"left":"\"She's a hopeless case\"","right":"Recovery is real with support"},{"left":"\"It's a moral failing\"","right":"It's a treatable condition"},{"left":"\"Bad parenting caused this\"","right":"Genes, brain and environment all matter"},{"left":"\"Once an addict, always\"","right":"It's chronic but manageable"}],"relearn":"Replace 'weak-willed' with brain change, 'hopeless' with recovery, 'moral failing' with treatable, 'bad parenting' with many factors, 'always' with manageable.","persona":"Vikram","source":"label to truth"},
  {"id":"na-1019","cat":"its-a-health-issue","type":"match","hook":"Match each illness step to the same calm step for dependence.","pairs":[{"left":"Asthma: you see a doctor","right":"Dependence: see a counsellor"},{"left":"Diabetes: you follow a plan","right":"Dependence: follow a treatment plan"},{"left":"A fracture: you allow healing time","right":"Dependence: allow recovery time"},{"left":"Any illness: you don't blame the child","right":"Dependence: drop the blame too"},{"left":"A chronic condition: manage flare-ups","right":"Dependence: treat a relapse as a flare-up"}],"relearn":"Treat dependence like any illness: a professional, a plan, time to heal, no blame, relapses as flare-ups.","persona":"any","source":"illness parallels"},
  {"id":"na-1020","cat":"its-a-health-issue","type":"match","hook":"Match each shaming line to the warmer one that keeps your child reachable.","pairs":[{"left":"\"You've disgraced this family\"","right":"\"We'll face this health problem together\""},{"left":"\"You're nothing but a junkie\"","right":"\"You're my child, who is unwell now\""},{"left":"\"You did this to yourself\"","right":"\"Many things led here; let's get help\""},{"left":"\"You'll never amount to anything\"","right":"\"People recover; so can you\""},{"left":"\"Don't expect sympathy\"","right":"\"I'm firm on the limit and still here\""}],"relearn":"Swap shaming lines for warm ones that name a treatable health problem and keep your child reachable.","persona":"Kamla","source":"shame to reachable"},
  {"id":"na-1021","cat":"its-a-health-issue","type":"match","hook":"Match each part of the 'treat it like a health issue' frame to what it gives your child.","pairs":[{"left":"A professional assessment","right":"An honest picture of what's going on"},{"left":"A treatment plan","right":"Clear next steps instead of guesswork"},{"left":"A no-blame stance","right":"Safety to be honest with you"},{"left":"Family involvement","right":"A better chance of recovery"},{"left":"Patience with setbacks","right":"Permission to keep trying"}],"relearn":"The health frame gives a child an honest picture, clear steps, safety to be honest, a better chance, and permission to keep trying.","persona":"any","source":"frame gives the child"},
  {"id":"na-1022","cat":"its-a-health-issue","type":"match","hook":"Match each cause of dependence to where blame does NOT belong.","pairs":[{"left":"Genetics born with","right":"Not the child's choice to inherit"},{"left":"The brain's reward system changing","right":"Not a sign of weak character"},{"left":"Stress in the environment","right":"Not one person's fault to carry"},{"left":"No single, simple cause","right":"Not a tidy story to pin on anyone"},{"left":"A condition, like any other","right":"Not a moral verdict to deliver"}],"relearn":"Genes, brain change, environment and the tangle of causes mean dependence is a condition to treat, not a fault to pin on anyone.","persona":"any","source":"causes not blame"},
  {"id":"na-1023","cat":"its-a-health-issue","type":"match","hook":"Match each thing you CAN control to the thing you cannot, so blame eases.","pairs":[{"left":"Whether you seek help","right":"Whether the brain already changed"},{"left":"Whether you respond with care","right":"Whether genes were inherited"},{"left":"Whether you stay connected","right":"Whether stress reached your child"},{"left":"Whether you hold calm limits","right":"Whether recovery is instant"},{"left":"Whether you drop the shame","right":"Whether the past can be undone"}],"relearn":"You control seeking help, care, staying connected, calm limits, dropping shame; not the brain, genes or instant recovery. Ease the blame.","persona":"Divya","source":"control vs cannot"},
  {"id":"na-1024","cat":"its-a-health-issue","type":"spot","hook":"Spot the two lines that brand your child a moral failure, not someone with a health condition.","scene":[{"id":"a","text":"\"It's treatable; let's get help\"","trick":false},{"id":"b","text":"\"You're a disgrace to this family\"","trick":true},{"id":"c","text":"\"You're unwell, and I'm with you\"","trick":false},{"id":"d","text":"\"A good child would never do this\"","trick":true},{"id":"e","text":"\"Recovery is real; we'll find help\"","trick":false}],"why":"'You're a disgrace' and 'a good child would never' brand the child a moral failure; the rest name a treatable condition with care.","relearn":"Catch the moral-failure lines; dependence is a treatable condition, not a verdict on a child's worth.","persona":"any","source":"catch moral-failure lines"},
  {"id":"na-1025","cat":"its-a-health-issue","type":"spot","hook":"Spot the two stigma myths hiding among these statements.","scene":[{"id":"a","text":"It changes the brain's reward system","trick":false},{"id":"b","text":"Strong-willed kids just stop on their own","trick":true},{"id":"c","text":"It's treatable, and recovery is common","trick":false},{"id":"d","text":"Only kids from 'bad' families get it","trick":true},{"id":"e","text":"Family involvement improves outcomes","trick":false}],"why":"'Strong kids just stop' and 'only bad families' are stigma myths; the brain change, treatability and family help are facts.","relearn":"Catch the willpower and 'only bad families' myths; truth is a brain change, real treatment, and family helping.","persona":"any","source":"catch the myths"},
  {"id":"na-1026","cat":"its-a-health-issue","type":"spot","hook":"Spot the two lines that pile despair on a struggling child instead of hope.","scene":[{"id":"a","text":"\"People recover from this every day\"","trick":false},{"id":"b","text":"\"You're a lost cause now\"","trick":true},{"id":"c","text":"\"This is treatable; we have a path\"","trick":false},{"id":"d","text":"\"There's no saving someone like you\"","trick":true},{"id":"e","text":"\"We'll get the right help and keep going\"","trick":false}],"why":"'Lost cause' and 'no saving you' crush the hope recovery needs; the others hold on to the truth that dependence is treatable and people recover.","relearn":"Catch the despair lines; recovery is real, and hope is part of what helps a child get better.","persona":"any","source":"catch despair lines"},
  {"id":"na-1027","cat":"its-a-health-issue","type":"spot","hook":"Spot the two reactions that treat dependence as a crime to punish, not a health issue.","scene":[{"id":"a","text":"Booking an assessment with a counsellor","trick":false},{"id":"b","text":"Interrogating her like a suspect","trick":true},{"id":"c","text":"Making a calm treatment plan","trick":false},{"id":"d","text":"Demanding a confession and punishment","trick":true},{"id":"e","text":"Staying connected as she recovers","trick":false}],"why":"Interrogation and demanding a confession-and-punishment treat it as a crime; an assessment, a plan and connection treat it as health.","relearn":"Catch the crime reactions; dependence is treated like any health issue, with assessment, a plan and connection.","persona":"Kamla","source":"catch crime reactions"},
  {"id":"na-1028","cat":"its-a-health-issue","type":"spot","hook":"Spot the two lines that wrongly pin the blame on one person.","scene":[{"id":"a","text":"\"Genes, brain and environment all matter\"","trick":false},{"id":"b","text":"\"This is entirely the mother's fault\"","trick":true},{"id":"c","text":"\"There's no single, simple cause\"","trick":false},{"id":"d","text":"\"He was just born a bad seed\"","trick":true},{"id":"e","text":"\"It's a condition, not anyone's failing\"","trick":false}],"why":"'The mother's fault' and 'born a bad seed' pin blame on one person; dependence has many causes and is a condition, not a failing.","relearn":"Catch the single-blame lines; dependence comes from many factors and isn't one person's fault.","persona":"any","source":"catch single-blame lines"},
  {"id":"na-1029","cat":"its-a-health-issue","type":"spot","hook":"Spot the two lines that reduce the whole child to the condition.","scene":[{"id":"a","text":"\"My son, who is struggling right now\"","trick":false},{"id":"b","text":"\"My son the addict\"","trick":true},{"id":"c","text":"\"A child going through a health problem\"","trick":false},{"id":"d","text":"\"A junkie, that's all he is now\"","trick":true},{"id":"e","text":"\"She has a treatable condition\"","trick":false}],"why":"'My son the addict' and 'a junkie, that's all he is' shrink the whole child to the condition; the others keep a person who happens to be unwell.","relearn":"Catch the lines that reduce a child to a label; name the struggle, but keep the whole person in view.","persona":"any","source":"catch label-only lines"},
  {"id":"na-1030","cat":"its-a-health-issue","type":"spot","hook":"Spot the two parent thoughts that would get in the way of helping.","scene":[{"id":"a","text":"\"My child is unwell, not bad\"","trick":false},{"id":"b","text":"\"He's only doing this to spite me\"","trick":true},{"id":"c","text":"\"Asking for help is a strength\"","trick":false},{"id":"d","text":"\"Pure willpower is all she needs\"","trick":true},{"id":"e","text":"\"Treatment can genuinely work\"","trick":false}],"why":"'To spite me' and 'just willpower' block help; 'unwell not bad', 'help is strength' and 'treatment works' open the door.","relearn":"Catch the 'spite' and 'willpower' beliefs; what helps is seeing your child as unwell and trusting treatment.","persona":"any","source":"catch blocking beliefs"},
  {"id":"na-1031","cat":"its-a-health-issue","type":"spot","hook":"Spot the two responses that add shame instead of treating dependence like a health problem.","scene":[{"id":"a","text":"Asking a professional what's going on","trick":false},{"id":"b","text":"\"Keep quiet, this is a disgrace\"","trick":true},{"id":"c","text":"Following a treatment plan","trick":false},{"id":"d","text":"Calling her a junkie in front of relatives","trick":true},{"id":"e","text":"Tracking progress calmly","trick":false}],"why":"'Keep quiet, it's a disgrace' and name-calling add shame; asking a professional, a plan and calm tracking treat it as health.","relearn":"Catch the shame responses; dependence is helped by professionals, a plan and patience, not secrecy and name-calling.","persona":"any","source":"catch shame responses"},
  {"id":"na-1032","cat":"its-a-health-issue","type":"branch","persona":"Vikram","source":"answer the verdict","hook":"Your son Varun, 17, is in treatment for his drinking. Relatives are over for Diwali dinner.","steps":[{"prompt":"Your uncle says, loud enough for Varun to hear, that an addict never changes. What do you do?","options":[{"text":"Say calmly that it's treatable and people do recover","then":"Your uncle raises an eyebrow. Across the table, Varun looks up.","best":true},{"text":"Stay silent and let the comment pass","then":"The table moves on. Varun pushes his plate away and goes quiet."},{"text":"Tell your uncle to leave the house right now","then":"Your uncle stays put, offended, and Varun looks mortified by the scene."},{"text":"Text Varun under the table that your uncle is wrong","then":"Varun reads it and nods. At the table, the comment stands unanswered."}],"why":"Meeting 'never changes' with calm truth, where he can hear it, gives him a hopeful frame."},{"prompt":"Your uncle adds that your side of the family was always 'weak-willed'. What do you do?","options":[{"text":"Say it's a health condition, not weak will","then":"Your uncle grumbles, but an aunt nods along with you.","best":true},{"text":"Agree that willpower runs thin in the family","then":"Varun hears it and stares hard at the table."},{"text":"List your uncle's own failings back to him","then":"Voices rise, and the whole dinner turns into a fight."},{"text":"Laugh it off to keep Diwali dinner peaceful","then":"The tension eases, but the word 'weak' hangs in the air."}],"why":"Naming it as health, not weakness, removes the stigma that blocks recovery."},{"prompt":"After dinner, Varun asks if what your uncle said is true. What do you say?","options":[{"text":"Say it isn't, because this is treatable and people recover","then":"Varun is quiet, then asks how long recovery usually takes.","best":true},{"text":"Say you don't know, and only time will tell","then":"Varun's shoulders sink. \"So you think he's right.\""},{"text":"Say it's true, unless he tries much harder","then":"Varun nods grimly and goes to his room."},{"text":"Tell him to ignore your uncle because he's old-fashioned","then":"Varun nods, but the words still sit with him."}],"why":"Telling him plainly that recovery is real gives him hope to hold on to."},{"prompt":"Next morning, your uncle forwards an 'addicts never change' post to the family WhatsApp group. What do you do?","options":[{"text":"Reply that dependence is treatable and recovery is real","then":"A cousin replies with a thumbs up. The forwards stop.","best":true},{"text":"Leave the group without a word","then":"Relatives start messaging you privately to ask why."},{"text":"Ignore it and hope Varun doesn't see it","then":"Varun sees it anyway, and doesn't mention it."},{"text":"Message your uncle privately and ask him to delete it","then":"He deletes it, annoyed, but most of the family has read it."}],"why":"A calm, true reply challenges the verdict where everyone can see it."}],"debrief":"Meet 'never changes' with calm truth where your child can hear it: dependence is treatable and recovery is real.","relearn":"Answer hopeless verdicts with the truth: dependence is treatable and recovery is real."},
  {"id":"na-1033","cat":"its-a-health-issue","type":"branch","persona":"any","source":"relapse first move","hook":"Your daughter Zoya, 17, relapses after six weeks of real progress with her counsellor.","steps":[{"prompt":"You find out late on a Saturday night. What's your first move?","options":[{"text":"Stay calm, check she's safe, and say you're with her","then":"Zoya's shoulders drop. \"I thought you'd be furious.\"","best":true},{"text":"Decide the treatment has failed","then":"You cancel Monday's session. Zoya looks almost relieved."},{"text":"Take her phone away and ground her for a whole month","then":"Zoya stops speaking to you and starts hiding things again."},{"text":"Say nothing tonight and hope it was a one-off","then":"Zoya goes to bed. Neither of you mentions it on Sunday."}],"why":"A relapse is a flare-up, not failure, and calm keeps her close and talking."},{"prompt":"On Monday, you wonder whether to tell the counsellor. What do you do?","options":[{"text":"Call the counsellor and ask how to adjust the plan","then":"The counsellor says slips happen and adds an extra session this week.","best":true},{"text":"Keep it quiet so the counsellor doesn't think she's failed","then":"Sessions carry on, but the plan doesn't change to fit what happened."},{"text":"Tell the counsellor the treatment clearly isn't working","then":"The counsellor asks you both in. Zoya feels blamed from the start."},{"text":"Let Zoya decide whether to mention it, and stay out of it","then":"Zoya says nothing about it in her next session."}],"why":"Telling the counsellor turns the slip into useful information for adjusting the plan."},{"prompt":"Your mother says Zoya has wasted all that treatment. What do you do?","options":[{"text":"Say slips happen in recovery, and her progress counts","then":"Your mother frowns, but asks how she can help.","best":true},{"text":"Agree it was a waste of money","then":"Zoya overhears and cries in her room."},{"text":"Tell your mother to stay out of it","then":"Your mother goes silent and stays away for a while."},{"text":"Promise her this will definitely be the last time","then":"Your mother nods, and now everyone expects perfection from Zoya."}],"why":"Seeing a relapse as a flare-up of a treatable condition keeps everyone steady and hopeful."}],"debrief":"A relapse is a flare-up of a chronic condition, not failure; stay calm and adjust the plan with help.","relearn":"Treat a relapse as a flare-up to manage, not a failure."},
  {"id":"na-1034","cat":"its-a-health-issue","type":"branch","persona":"Vikram","source":"change the label","hook":"You catch yourself calling your son Sameer 'the addict', even in your own head.","steps":[{"prompt":"You're about to tell your wife about his latest slip. How do you describe him?","options":[{"text":"As 'our son who is struggling', then say what happened","then":"Your wife listens without flinching and asks how Sameer is.","best":true},{"text":"As 'the addict', since that's what he is now","then":"Your wife winces, and the talk turns to whose fault it is."},{"text":"You don't. You keep it to yourself so she won't worry","then":"She hears it later from Sameer and is upset you hid it."},{"text":"As 'our problem child', and move straight to new rules","then":"You agree on rules, but neither of you mentions how he feels."}],"why":"Naming the struggle, not a label, keeps the whole child in view."},{"prompt":"At dinner, Sameer's younger sister calls him 'the addict' too. What do you do?","options":[{"text":"Gently say he's her brother who is struggling","then":"She looks down at her plate. \"Sorry, Bhaiya.\"","best":true},{"text":"Laugh, because it's basically true","then":"Sameer puts down his spoon and leaves the table."},{"text":"Shout at her for being so cruel","then":"She bursts into tears, and dinner is ruined for everyone."},{"text":"Let it go for now, and talk to her in private later","then":"Sameer sits through the rest of dinner with the word hanging there."}],"why":"The words a family uses shape how a child sees himself, and his hope."},{"prompt":"Later, Sameer says he's just an addict now, so what's the point of trying. What do you say?","options":[{"text":"Say he's your son who is struggling, and recovery is real","then":"Sameer looks up. \"You actually believe that?\"","best":true},{"text":"Say he'll stop being one if he just tries a lot harder","then":"Sameer shrugs. \"Then I'm stuck.\""},{"text":"Say nothing, and let him vent","then":"Sameer takes your silence as agreement."},{"text":"Say he shouldn't feel so sorry for himself","then":"Sameer turns away. \"Forget it.\""}],"why":"Separating him from the condition protects the hope he needs to keep going."}],"debrief":"Name the condition, not the child; 'my son who is struggling' keeps the person and the hope in view.","relearn":"Drop 'the addict' for 'my child who is struggling'; naming shapes how you treat them."},
  {"id":"na-1035","cat":"its-a-health-issue","type":"branch","persona":"Divya","source":"ease the self-blame","hook":"Your daughter Ira, 16, is dependent on vaping, and it feels like proof you failed as a parent.","steps":[{"prompt":"You can't sleep, replaying everything you did wrong. What do you do?","options":[{"text":"Remind yourself it has many causes, then plan one next step","then":"You write down two things: call Tele-MANAS 14416, and talk to Ira.","best":true},{"text":"Keep going over your mistakes until morning","then":"By sunrise you're exhausted and still have no plan."},{"text":"Decide it's all your fault, so you must fix it all alone","then":"You try to control everything, and Ira pulls further away."},{"text":"Push the feelings down and focus only on Ira","then":"You get through the day, but snap at everyone by evening."}],"why":"Easing self-blame leaves you steady enough to act."},{"prompt":"Your mother-in-law hints that Ira picked this up from your 'modern ways'. What do you do?","options":[{"text":"Say it has many causes, and your focus is Ira","then":"She purses her lips, but drops the subject.","best":true},{"text":"Agree, and apologise for how you raised her","then":"She nods, satisfied. You feel smaller all evening."},{"text":"Tell her it's really her son's fault, not yours","then":"The argument spreads, and Ira hears the raised voices."},{"text":"Say nothing, and cry about it later on your own","then":"Her words stay with you for days."}],"why":"Refusing blame, for yourself or anyone else, keeps the focus on helping your child."},{"prompt":"That night, Ira says she's sorry for ruining the family. What do you say?","options":[{"text":"Say she's ruined nothing, and you'll get help together","then":"Ira cries, and lets you hold her for a while.","best":true},{"text":"Say you're the one who ruined things, not her","then":"Ira looks confused, and ends up comforting you instead."},{"text":"Say she should be sorry","then":"Ira goes quiet and stops meeting your eyes."},{"text":"Change the subject gently, since it's too painful for you both","then":"Ira goes back to her room, still carrying it."}],"why":"Taking the blame off both of you makes space for help."},{"prompt":"A week later, a friend asks how you're holding up and offers to help. What do you do?","options":[{"text":"Say honestly that it's hard, and accept her offer of help","then":"Your friend drops by with food and sits with you for an hour.","best":true},{"text":"Say you're totally fine and handling it","then":"She nods and moves on. You feel more alone than before."},{"text":"Say it's your fault, so you don't deserve help","then":"Your friend looks worried, but you brush her off."},{"text":"Talk about Ira's progress, and nothing about yourself","then":"She's glad to hear it, but never learns how tired you are."}],"why":"Looking after yourself keeps you steady enough to keep helping your child."}],"debrief":"Dependence isn't a verdict on your parenting; it has many causes, and easing self-blame frees you to help.","relearn":"Don't read dependence as proof you failed; ease self-blame so you can act."},
  {"id":"na-1036","cat":"its-a-health-issue","type":"branch","persona":"any","source":"screens are real too","hook":"Your son Aditya, 13, games most of the night and has stopped seeing his friends.","steps":[{"prompt":"A neighbour says it isn't real addiction, just laziness. What do you do?","options":[{"text":"Say gaming disorder is recognised, and you're getting help","then":"The neighbour looks surprised. \"Really? I didn't know that.\"","best":true},{"text":"Accept that he's lazy and stop looking for help","then":"You drop the idea of a counsellor. The nights get longer."},{"text":"Tell the neighbour to mind her own business","then":"She's offended, and you both walk off annoyed."},{"text":"Agree it's probably just a phase, and wait a while longer","then":"Weeks pass, and Aditya starts skipping school to play."}],"why":"Gaming disorder is recognised, so treating it as a health issue keeps help on track."},{"prompt":"That evening, Aditya's grandfather says you should just smash the console. What do you do?","options":[{"text":"Say it's a health issue that needs a calm plan and help","then":"He sighs. \"Fine. What kind of plan?\"","best":true},{"text":"Agree, and take the console away tonight","then":"Aditya rages, then plays on his phone under the blanket."},{"text":"Say it's harmless, and let Aditya play as he likes","then":"Aditya games till dawn and misses school the next day."},{"text":"Say you'll set a strict two-hour limit starting tonight","then":"Aditya argues it's unfair. The limit starts without his say."}],"why":"A calm plan made with help works where anger and bans backfire."},{"prompt":"A few days later, Aditya quietly asks whether you think he's just lazy. What do you say?","options":[{"text":"Say he isn't lazy, and you'll help him find a way","then":"Aditya looks relieved. \"It is hard. I try and I can't.\"","best":true},{"text":"Say yes, and that he needs to toughen up","then":"Aditya's face falls, and he heads back to his screen."},{"text":"Say it's just a phase he'll grow out of","then":"Aditya shrugs, and nothing changes."},{"text":"Say no, but he should be able to stop if he wants to","then":"Aditya looks down. \"But I can't.\""}],"why":"Naming it as hard to stop, not lazy, lets him accept help without shame."}],"debrief":"Screen and gaming dependence is real and recognised; treat it as a health issue, not a flaw.","relearn":"Gaming disorder is recognised; treat screen dependence as real, not lazy."},
  {"id":"na-1037","cat":"its-a-health-issue","type":"branch","persona":"Kamla","source":"clinic without shame","hook":"You've brought your son Sunny to a de-addiction clinic, and you feel ashamed to be there.","steps":[{"prompt":"In the waiting room, a woman from your lane walks in. What do you do?","options":[{"text":"Nod hello, as you would at any clinic","then":"She smiles back. She's there with her own son.","best":true},{"text":"Cancel and hurry home with Sunny","then":"Sunny misses his first session, and it takes a week to get another."},{"text":"Hide your face and hope she doesn't see you","then":"Sunny notices and slumps lower in his chair."},{"text":"Tell her you're only there for Sunny's stomach","then":"She nods, but Sunny hears you lie about why he's there."}],"why":"Treating it like any clinic visit models calm help-seeking for your son."},{"prompt":"On the way home, Sunny says he's embarrassed to need a clinic at all. What do you say?","options":[{"text":"Say it's health care, and getting help takes strength","then":"Sunny sits up a little straighter.","best":true},{"text":"Say you're embarrassed too","then":"Sunny shrinks further into his seat."},{"text":"Tell him he really should have thought of that before","then":"Sunny stares at the floor and won't talk."},{"text":"Promise him nobody will ever find out","then":"Sunny relaxes, but the clinic now feels like a secret he must keep."}],"why":"Framing the visit as ordinary health care lowers the shame for both of you."},{"prompt":"That evening, Sunny's grandmother asks why he seems so quiet. What do you do?","options":[{"text":"Tell her Sunny is getting treatment, and why it helps","then":"She's quiet a moment, then asks how she can help.","best":true},{"text":"Say Sunny is just tired from school","then":"She accepts it, but you'll need another story next week."},{"text":"Say it's none of her concern","then":"She shrugs and turns back to the TV. Sunny's care stays unspoken at home."},{"text":"Tell her, but call it a one-time check-up and nothing more","then":"She nods, and doesn't expect the weekly visits to follow."}],"why":"Speaking about treatment openly makes it normal at home too."}],"debrief":"A counselling or de-addiction visit is health care like any other; showing up calmly models the help-seeking you want your child to learn.","relearn":"Getting help is ordinary health care."},
  {"id":"na-1038","cat":"its-a-health-issue","type":"branch","persona":"Vikram","source":"am I bad now","hook":"Your son Neel, 15, has been vaping for months. Today he was suspended from school for it.","steps":[{"prompt":"At home, he asks you, scared, if he's a bad person now. What do you say?","options":[{"text":"Tell him he isn't bad, and that this is treatable","then":"Neel lets out a shaky breath. \"I thought you'd hate me.\"","best":true},{"text":"Say that wasn't a good person's act","then":"Neel's face crumples, and he goes to his room."},{"text":"Say you'll talk about it once you've calmed down","then":"Neel waits all evening, sure he's in huge trouble."},{"text":"Say he's good, and that it will never happen again","then":"Neel nods fast, but he has no idea how he'll stop."}],"why":"Separating him from the condition protects the hope he needs."},{"prompt":"The school principal asks you to come in and talk about Neel. What do you do?","options":[{"text":"Go, and ask the school to support him getting help","then":"The principal agrees to a quiet return and a counsellor check-in.","best":true},{"text":"Go, and agree Neel is a bad influence on others","then":"The principal nods, and Neel returns to school feeling marked."},{"text":"Refuse to go, since it's a private family matter","then":"The school decides everything without your input."},{"text":"Go, and promise he'll be punished properly at home","then":"The principal is satisfied, but nobody talks about help."}],"why":"Asking the school to back his recovery keeps him supported, not labelled."},{"prompt":"A week later, Neel asks if the family is ashamed of him. What do you say?","options":[{"text":"Say you're not ashamed, and you'll face this with him","then":"Neel smiles for the first time in days.","best":true},{"text":"Say some relatives are, but you're trying hard not to be","then":"Neel's face falls. \"So they all know.\""},{"text":"Say yes, and he'll have to earn back their respect","then":"Neel nods and pulls further into himself."},{"text":"Say it's better not to talk about that now","then":"Neel drops it, but the question stays with him."}],"why":"Saying you're not ashamed, and standing with him, keeps shame from driving it underground."}],"debrief":"Your child isn't bad but has a treatable condition, and saying so separates them from the illness.","relearn":"Tell a frightened child: not bad, but unwell with something treatable, and still loved."},
  {"id":"na-1039","cat":"its-a-health-issue","type":"role-play","persona":"Kamla","source":"reframe to in-law","hook":"Your daughter Rani's drinking has come out in the family, and your mother-in-law is furious.","setup":"She corners you in the kitchen.","steps":[{"prompt":"Your mother-in-law says: \"That girl is a shame on this family.\"","options":[{"text":"\"She's not a shame. She has a treatable health condition.\"","then":"She scoffs. \"A condition? Drinking is a choice.\"","best":true},{"text":"\"You're right. I don't know how we'll live this down.\"","then":"She nods grimly. \"Then keep her indoors.\""},{"text":"\"Don't you ever call my daughter that again.\"","then":"Her eyes flash. \"Don't raise your voice at me.\""},{"text":"\"Please lower your voice. The neighbours will hear.\"","then":"She hisses. \"So you agree it's shameful.\""}],"why":"Reframing shame as a health condition protects your daughter from stigma."},{"prompt":"Your mother-in-law says: \"She chose to drink. Let her face it.\"","options":[{"text":"\"Maybe it started that way. Now it's hard to stop alone.\"","then":"She pauses. \"So she can't just stop?\"","best":true},{"text":"\"Yes. And now she has to live with it.\"","then":"\"Exactly,\" she says. \"No sympathy.\""},{"text":"\"You don't know the first thing about this.\"","then":"She turns away. \"I know shame when I see it.\""},{"text":"\"She's young, and she'll learn her lesson soon enough.\"","then":"\"Only if you punish her,\" she says."}],"why":"Dependence changes the brain, so 'just choose to stop' isn't how recovery works."},{"prompt":"Your mother-in-law asks: \"And what do you plan to do about her?\"","options":[{"text":"\"Get her treatment, and support her through it.\"","then":"She sighs. \"Fine. But I'll be watching.\"","best":true},{"text":"\"Keep her at home until people forget.\"","then":"She nods. \"Good. No one should see her.\""},{"text":"\"Send her to my mother's village for a while.\"","then":"\"Out of sight,\" she says. \"That's best.\""},{"text":"\"Talk to her myself, and hope that's enough.\"","then":"\"And if it isn't?\" she asks."}],"why":"What helps her is treatment and support, not hiding or blame."}],"relearn":"Reframing 'a shame on the family' as 'a treatable health condition that needs support' protects your child from the stigma that blocks recovery."},
  {"id":"na-1040","cat":"its-a-health-issue","type":"role-play","persona":"Vikram","source":"name it to partner","hook":"Your son Ayaan's gaming has grown out of control, and your wife wants a crackdown.","setup":"She has already hidden his charger in your room.","steps":[{"prompt":"Your wife Farah says: \"We just need to be stricter. He'll snap out of it.\"","options":[{"text":"\"It's a health condition. Strictness alone won't fix it.\"","then":"Farah folds her arms. \"So we do nothing?\"","best":true},{"text":"\"You're right. Let's crack down much harder.\"","then":"Farah nods. \"No phone, no laptop, nothing.\""},{"text":"\"You're too harsh. That's the whole problem.\"","then":"Farah's eyes flash. \"Oh, so it's my fault?\""},{"text":"\"Fine, stricter. But give him his charger back for now.\"","then":"Farah frowns. \"Then what exactly are we doing?\""}],"why":"Naming it as a health condition steers you both toward what actually helps."},{"prompt":"Farah says: \"He could stop if he really wanted to.\"","options":[{"text":"\"It changes the brain's reward system. That's why it's hard.\"","then":"Farah is quiet. \"I didn't know that.\"","best":true},{"text":"\"Maybe he doesn't want to. He's being selfish.\"","then":"Farah nods. \"Exactly what I've been saying.\""},{"text":"\"He wants to. You just don't listen to him.\"","then":"Farah stiffens. \"I listen more than you do.\""},{"text":"\"Let's give him just one more chance to prove that he can.\"","then":"Farah shrugs. \"One more. Then my way.\""}],"why":"Understanding the brain change moves you both past the willpower myth."},{"prompt":"Farah asks: \"Then what do we actually do?\"","options":[{"text":"\"See a counsellor, and agree screen rules with him.\"","then":"Farah thinks. \"With him? Not just for him?\"","best":true},{"text":"\"Take everything away until he begs.\"","then":"Farah hesitates. \"Said like that, it sounds harsh.\""},{"text":"\"Leave it. He'll grow out of it.\"","then":"Farah stares. \"That's worse than my idea.\""},{"text":"\"I'll handle it. You don't need to be involved.\"","then":"Farah looks hurt. \"He's my son too.\""}],"why":"Professional help plus limits made with him work better than a crackdown."},{"prompt":"Farah asks: \"And what if he says we're on our phones all the time too?\"","options":[{"text":"\"He'd have a point. If we cut back too, it works better.\"","then":"Farah sighs. \"Okay. Phones in the basket at dinner. All of us.\"","best":true},{"text":"\"That's different. The rules are for him, not us adults.\"","then":"\"Good,\" Farah says. \"We're the adults.\""},{"text":"\"He'd mean you. You're the one always on it.\"","then":"Farah flushes. \"Don't make this about me.\""},{"text":"\"I'll put mine away. You do as you like.\"","then":"Farah shrugs. \"Your choice.\""}],"why":"Children learn habits by watching, so limits the whole family keeps work better."}],"relearn":"Naming dependence as a brain-based health condition steers a couple from 'just be stricter' toward the treatment that actually helps."},
  {"id":"na-1041","cat":"its-a-health-issue","type":"role-play","persona":"any","source":"counter I'm weak","hook":"Your son Dhruv, 16, has tried again and again to stop smoking, and keeps failing.","setup":"He throws his school bag down at the door.","steps":[{"prompt":"Dhruv says: \"I'm too weak to ever stop. What's the point?\"","options":[{"text":"\"It's not weakness. This changed your brain, and help works.\"","then":"Dhruv pauses. \"Changed my brain? Seriously?\"","best":true},{"text":"\"You do need to find some willpower from somewhere.\"","then":"Dhruv slumps. \"That's exactly what I don't have.\""},{"text":"\"If you'd never started, you wouldn't be in this mess.\"","then":"Dhruv glares. \"Great. Very helpful.\""},{"text":"\"You're not weak. Just try once more, properly this time.\"","then":"Dhruv sighs. \"I have tried properly.\""}],"why":"Naming it as a brain change, not weakness, replaces self-blame with a real reason to keep going."},{"prompt":"Dhruv asks: \"So why can my friends stop and I can't?\"","options":[{"text":"\"People are different. It isn't about being strong.\"","then":"Dhruv thinks. \"So it's not just me being pathetic.\"","best":true},{"text":"\"Maybe they just want it more than you do, beta.\"","then":"Dhruv's face falls. \"Thanks a lot.\""},{"text":"\"They probably haven't really stopped either.\"","then":"Dhruv frowns. \"They have, though.\""},{"text":"\"Don't compare. Just focus on yourself.\"","then":"Dhruv shrugs. \"Easy to say.\""}],"why":"Genes, brain and surroundings all play a part, so no one is to blame."},{"prompt":"Dhruv says: \"Even if I got help, I'd probably mess it up.\"","options":[{"text":"\"Then we keep going. Recovery can take a few tries.\"","then":"Dhruv looks up. \"You'd stick with me that long?\"","best":true},{"text":"\"You won't mess it up if you really focus.\"","then":"Dhruv shakes his head. \"You sound like everyone else.\""},{"text":"\"Then don't bother, if you've already decided.\"","then":"Dhruv shrugs. \"Fine. I won't.\""},{"text":"\"Don't think like that. Just stay positive.\"","then":"Dhruv rolls his eyes. \"Sure. Positive.\""}],"why":"Expecting setbacks, and staying with him, makes it safe to try."}],"relearn":"Telling a child it's not weakness but a treatable brain condition replaces hopeless self-blame with a realistic reason to keep going."},
  {"id":"na-1042","cat":"its-a-health-issue","type":"role-play","persona":"Priya","source":"push back to teacher","hook":"The class teacher calls you in after your daughter Kavya, 15, is caught vaping.","setup":"She sits across from you in the staffroom.","steps":[{"prompt":"The teacher says: \"Honestly, Kavya is just a bad kid now.\"","options":[{"text":"\"She's not bad. Any child can face this health issue.\"","then":"The teacher pauses. \"I hadn't thought of it like that.\"","best":true},{"text":"\"I know. We're so ashamed. I don't know what went wrong.\"","then":"The teacher nods. \"These things happen in some homes.\""},{"text":"\"How dare you. You're the one who failed her.\"","then":"The teacher stiffens. \"Please lower your voice.\""},{"text":"\"She's a good girl. This was just a one-off.\"","then":"The teacher raises an eyebrow. \"It's the third time this term.\""}],"why":"Refusing the 'bad kid' label protects her from stigma at school."},{"prompt":"The teacher asks: \"So what are you planning to do about it?\"","options":[{"text":"\"We're getting her help. Can the school support that?\"","then":"The teacher nods. \"Our counsellor could check in with her.\"","best":true},{"text":"\"Punish her at home until she learns.\"","then":"The teacher nods. \"Good. Firmness works.\""},{"text":"\"That's our family's business, not the school's.\"","then":"The teacher shrugs. \"Then we'll just follow school rules.\""},{"text":"\"We'll handle it quietly at home, ourselves.\"","then":"\"Alright,\" the teacher says. \"Let us know.\""}],"why":"Asking the school to back her help keeps her supported instead of labelled."},{"prompt":"The teacher says: \"Other parents may not want their kids around her.\"","options":[{"text":"\"Then I hope the school helps them see it's a health issue.\"","then":"The teacher thinks. \"We could hold a talk on it for parents.\"","best":true},{"text":"\"Then maybe she should change schools.\"","then":"The teacher looks relieved. \"It might be easier.\""},{"text":"\"Those parents should mind their own children.\"","then":"The teacher sighs. \"That won't help her.\""},{"text":"\"Then please don't tell anyone at all why she was caught.\"","then":"The teacher nods. \"Of course. But people talk.\""}],"why":"Naming dependence as a health issue any child can face shields her from being shut out."}],"relearn":"Refusing the 'bad kid' label and naming dependence as a health issue any child can face shields your daughter from stigma at school."},
  {"id":"na-1043","cat":"its-a-health-issue","type":"role-play","persona":"any","source":"reassure before counsellor","hook":"Your daughter Mehak, 17, has her first counselling session for her drinking tomorrow.","setup":"She can't sleep and comes to find you.","steps":[{"prompt":"Mehak says: \"The counsellor will think I'm a hopeless case.\"","options":[{"text":"\"You're not hopeless. Helping people recover is their job.\"","then":"Mehak hugs her knees. \"You think they've seen worse?\"","best":true},{"text":"\"Well, just try not to look too far gone when you're in there.\"","then":"Mehak's face tightens. \"Great. So I do look bad.\""},{"text":"\"Then don't go, if it worries you that much.\"","then":"Mehak hesitates. \"Maybe I won't.\""},{"text":"\"Don't worry. They'll fix you up in no time at all.\"","then":"Mehak frowns. \"Fix me? Like I'm broken?\""}],"why":"Reassuring her that recovery is real lowers the shame that keeps her from help."},{"prompt":"Mehak asks: \"What if they tell you everything I say?\"","options":[{"text":"\"What you say is yours, unless you're ever unsafe.\"","then":"Mehak relaxes a little. \"Okay. That's fair.\"","best":true},{"text":"\"They'd better. I have a right to know.\"","then":"Mehak goes stiff. \"Then I'll say nothing.\""},{"text":"\"I'll ask them to, just to be on the safe side.\"","then":"Mehak looks hurt. \"So it's not really private.\""},{"text":"\"They won't tell me anything, ever. I promise.\"","then":"Mehak nods. \"Promise? Even if something's wrong?\""}],"why":"Being honest about privacy, and its limits, builds the trust she needs."},{"prompt":"Mehak asks: \"Will you come with me tomorrow?\"","options":[{"text":"\"Yes. I'll be in the waiting room the whole time.\"","then":"Mehak smiles, tired. \"Okay. I think I can sleep now.\"","best":true},{"text":"\"You're seventeen. You can manage on your own.\"","then":"Mehak shrugs. \"Fine. Whatever.\""},{"text":"\"Yes, and I'll sit in the session with you.\"","then":"Mehak hesitates. \"I'd rather talk alone.\""},{"text":"\"I'll drop you off and pick you up after.\"","then":"Mehak nods slowly. \"So I wait on my own.\""}],"why":"Being there, while giving her room to talk, helps her take the step."}],"relearn":"Reassuring a child that dependence is treatable and counsellors help people recover lowers the shame that keeps her from accepting help."},
  {"id":"na-1044","cat":"its-a-health-issue","type":"role-play","persona":"Divya","source":"ease partner's self-blame","hook":"Your son Om, 17, is in treatment for his drinking. Your husband Suresh has gone very quiet.","setup":"Tonight he sits alone on the balcony.","steps":[{"prompt":"Suresh says: \"I made our son this way. It's my fault.\"","options":[{"text":"\"This has many causes. It isn't your verdict to carry.\"","then":"Suresh rubs his face. \"Then why does it feel like it is?\"","best":true},{"text":"\"Honestly, yes. You probably did cause a lot of this.\"","then":"Suresh's shoulders sag. \"I knew it.\""},{"text":"\"Don't be silly. Let's not talk about it.\"","then":"Suresh nods. \"Fine.\" He turns back to the street."},{"text":"\"No, it's my fault, not yours. I was the one at home.\"","then":"Suresh looks up. \"So now we both carry it?\""}],"why":"Easing self-blame keeps both parents steady enough to help."},{"prompt":"Suresh says: \"I drank in front of him all those years.\"","options":[{"text":"\"Then let's both look at our habits now. That helps him too.\"","then":"Suresh is quiet. \"You'd do that with me?\"","best":true},{"text":"\"Yes, and that's why he's like this.\"","then":"Suresh winces. \"So it is my fault.\""},{"text":"\"That doesn't matter now. Forget it.\"","then":"Suresh frowns. \"It does matter, though.\""},{"text":"\"Then just stop drinking now, and he'll follow your lead.\"","then":"Suresh sighs. \"If only it were that simple.\""}],"why":"Honestly looking at your own habits helps your child, without blame."},{"prompt":"Suresh asks: \"How do I even face him, feeling like this?\"","options":[{"text":"\"Calmly. He needs us steady, not crushed.\"","then":"Suresh takes a breath. \"Steady. Okay. I can try that.\"","best":true},{"text":"\"Stay out of it until you feel better.\"","then":"Suresh nods. \"Maybe that's best.\""},{"text":"\"Tell him it's all your fault, so he knows.\"","then":"Suresh hesitates. \"Would that help him, or me?\""},{"text":"\"Just act normal, and hide how you feel.\"","then":"Suresh nods. \"I've been doing that for years.\""}],"why":"Facing him steady helps him more than guilt ever could."}],"relearn":"Easing a partner's self-blame keeps both parents steady enough to help, because dependence has many causes and isn't a verdict on them."},
  {"id":"na-1045","cat":"its-a-health-issue","type":"role-play","persona":"Vikram","source":"reframe the slip","hook":"Your son Parth, 16, has been doing well in treatment for his gaming, until last night.","setup":"This morning he won't look at you.","steps":[{"prompt":"Parth says: \"See? I'm a failure. I told you so.\"","options":[{"text":"\"A slip isn't failure. Recovery wobbles sometimes.\"","then":"Parth glances up. \"So you're not angry?\"","best":true},{"text":"\"You're right. This is hopeless.\"","then":"Parth's face drops. \"Then why bother?\""},{"text":"\"I'm disappointed. I really thought you'd changed.\"","then":"Parth flinches. \"Yeah. Me too.\""},{"text":"\"It's fine. Let's pretend it never happened.\"","then":"Parth looks relieved. \"So we don't tell anyone?\""}],"why":"Reframing a slip as a normal wobble keeps him in recovery instead of giving up."},{"prompt":"Parth asks: \"Do I have to tell my counsellor?\"","options":[{"text":"\"Yes. We'll tell her together and adjust the plan.\"","then":"Parth sighs. \"Okay. If you're there.\"","best":true},{"text":"\"No. Let's keep this one between us.\"","then":"Parth nods. \"Good. She'd be so disappointed.\""},{"text":"\"Yes, and I'll tell her how badly you messed up.\"","then":"Parth stiffens. \"Then I'm not going.\""},{"text":"\"That's up to you. It's your treatment.\"","then":"Parth shrugs. \"Then I won't.\""}],"why":"Telling the counsellor turns a slip into information that makes the plan stronger."},{"prompt":"Parth says: \"Maybe I should just delete every game and quit cold.\"","options":[{"text":"\"Let's ask your counsellor what fits. Big swings rarely last.\"","then":"Parth nods. \"Yeah. Last time I lasted two days.\"","best":true},{"text":"\"Great idea. Do it right now.\"","then":"Parth deletes them. \"Done.\" By evening, they're back."},{"text":"\"You'll never manage that. Don't bother.\"","then":"Parth drops his phone on the bed. \"Thanks for the faith.\""},{"text":"\"I'll take your phone and keep it safe until you're better.\"","then":"Parth's jaw sets. \"So you don't trust me at all.\""}],"why":"Adjusting the plan with help works better than dramatic all-or-nothing moves."},{"prompt":"That evening, Parth asks: \"Are you going to tell everyone I slipped?\"","options":[{"text":"\"No. Just Mumma and your counsellor, so we can help.\"","then":"Parth nods. \"Okay. Not Dadi, though.\"","best":true},{"text":"\"The whole family should know, so they can watch you.\"","then":"Parth groans. \"Great. Now everyone will watch me.\""},{"text":"\"Maybe, if it helps you learn your lesson.\"","then":"Parth goes pale. \"That's not fair.\""},{"text":"\"No, and let's never speak of it again.\"","then":"Parth looks unsure. \"Not even to Mumma?\""}],"why":"Keeping it within the people helping him protects his dignity and his recovery."}],"relearn":"Reframing a slip as a normal wobble to manage, not proof of failure, keeps a child in recovery instead of giving up."},
  {"id":"na-1046","cat":"its-a-health-issue","type":"role-play","persona":"any","source":"hold the stance","hook":"Your son Abhay, 18, is getting treatment for his drinking. You meet an old friend for coffee.","setup":"She leans in when you mention Abhay.","steps":[{"prompt":"Your friend says: \"If it were my kid, I'd have thrown him out.\"","options":[{"text":"\"He's unwell. Throwing him out would cut him off from help.\"","then":"She sits back. \"I hadn't thought of it like that.\"","best":true},{"text":"\"Maybe you're right. Tough love might be what he needs.\"","then":"She nods firmly. \"Trust me. It works.\""},{"text":"\"That's a horrible thing to say about a child.\"","then":"She bristles. \"I'm only being honest.\""},{"text":"\"We've thought about it, but we're not there yet.\"","then":"\"Not yet?\" she says. \"Don't wait too long.\""}],"why":"He has a treatable illness, and staying connected is what his recovery depends on."},{"prompt":"Your friend asks: \"He's an adult now. Isn't it on him?\"","options":[{"text":"\"It's his recovery, but he does better with family behind him.\"","then":"She thinks. \"I suppose everyone needs someone.\"","best":true},{"text":"\"You're right. I'll stop helping and let him sort it out.\"","then":"She nods. \"Best thing you can do.\""},{"text":"\"He'll always be my child. I'll handle all of it for him.\"","then":"She raises an eyebrow. \"And does he get a say?\""},{"text":"\"Let's not talk about it. It's too personal.\"","then":"She shrugs. \"Fine. But think about what I said.\""}],"why":"Family support strongly improves recovery, even for a young adult."},{"prompt":"At a wedding a month later, your friend asks: \"What do your relatives say about how you're handling it?\"","options":[{"text":"\"That we're soft. But I can hold limits and stand by him.\"","then":"She smiles a little. \"That takes more than I'd have guessed.\"","best":true},{"text":"\"That we're too soft. Maybe they're right.\"","then":"She nods. \"Show him who's boss.\""},{"text":"\"I don't care what anyone thinks of us.\"","then":"She shrugs. \"You will when they talk.\""},{"text":"\"Nothing much. I've told them all he's completely fine now.\"","then":"She raises an eyebrow. \"And if he has a bad week?\""}],"why":"Being firm about behaviour while standing by him is what keeps him safe."}],"relearn":"Holding the line that dependence is a treatable illness, not a reason to cut a child off, keeps the connection that recovery depends on."},
  {"id":"na-1047","cat":"its-a-health-issue","type":"branch","persona":"Vikram","source":"more than willpower","hook":"Your son Tushar, 16, has tried to quit vaping on his own three times, and failed each time.","steps":[{"prompt":"He tells you he feels weak and defeated. What do you do?","options":[{"text":"Say it takes more than willpower, and offer to find a counsellor","then":"Tushar looks up. \"So it's not just me being useless?\"","best":true},{"text":"Tell him to just try harder this time","then":"Tushar nods, then starts hiding his vape better."},{"text":"Say you'll check his room daily to keep him on track","then":"Tushar's face hardens. \"So now you're watching me.\""},{"text":"Say you believe in him, and he'll manage it next time for sure","then":"Tushar forces a smile, but looks more worried than before."}],"why":"Failed solo attempts aren't weakness; dependence often needs real treatment."},{"prompt":"Your father says boys today are soft, and in his day they just stopped. What do you do?","options":[{"text":"Say it changes the brain, which is why stopping is hard","then":"Your father frowns. \"The brain? I didn't know that.\"","best":true},{"text":"Agree that Tushar just needs to toughen up and stop","then":"Tushar hears it and walks out of the room."},{"text":"Remind your father of his own years of heavy smoking","then":"Your father goes red, and the room goes quiet."},{"text":"Change the subject, to keep the peace at home for now","then":"Your father nods to himself, sure he's right."}],"why":"Explaining the brain change busts the willpower myth and eases the shame."},{"prompt":"You find a counsellor, but the first free slot is in three weeks. What do you do?","options":[{"text":"Book it, and call Tele-MANAS 14416 for support meanwhile","then":"The counsellor on the phone helps you plan the next three weeks.","best":true},{"text":"Decide three weeks is too long and drop it","then":"Tushar's hope fades, and the vaping continues."},{"text":"Tell Tushar to stop on his own until then","then":"Tushar tries again, fails, and feels worse."},{"text":"Book it, and simply wait quietly until the day comes","then":"The three weeks pass slowly, with no support in between."}],"why":"Getting support while you wait keeps momentum and shows him help is already here."},{"prompt":"Tushar asks if needing help means he'll never be normal. What do you say?","options":[{"text":"Say many people recover with help, and so can he","then":"Tushar exhales. \"Okay. I'll give it a real try.\"","best":true},{"text":"Say he'll be normal again once he stops","then":"Tushar shrugs. \"If I could stop, I would have.\""},{"text":"Say he should stop worrying about being normal","then":"Tushar goes quiet, still unsure."},{"text":"Say he'll be fully cured in a few weeks","then":"Tushar brightens. \"A few weeks? That's all?\""}],"why":"Recovery is real and common with support, which gives him a reason to keep going."}],"debrief":"Failed solo attempts aren't weakness; dependence often needs treatment, not willpower.","relearn":"'Just try harder' isn't a plan; name it a health issue and get real treatment."},
  {"id":"na-1080","type":"strike-rewrite","persona":"Vikram","source":"fear teaches hiding","relearn":"Scary punishments teach a child to hide; calm limits plus connection keep them reachable.","hook":"\"If I catch them, a big scary punishment will fix this for good.\"","myth":{"un":"If I catch them, a big scary punishment will fix this for good.","re":"Big, scary punishments mostly teach a child to hide better; calm limits plus connection keep them coming to you.","why":"Fear teaches hiding, not honesty."},"cat":"respond-dont-rupture"},
  {"id":"na-1081","type":"strike-rewrite","persona":"Kamla","source":"not a character flaw","relearn":"Dependence isn't bad character; shame deepens it, calm help lifts it.","hook":"\"A good kid would just stop, so if mine can't, something is wrong with them.\"","myth":{"un":"A good kid would just stop, so if mine can't, something is wrong with them.","re":"Dependence isn't a verdict on your child's character; it's a treatable health issue, and shaming them only deepens it.","why":"It's a health issue, not a character flaw."},"cat":"respond-dont-rupture"},
  {"id":"na-1082","type":"strike-rewrite","persona":"Vikram","source":"warmth not coldness","relearn":"Going cold removes the connection that keeps a child safe; warmth reaches them.","hook":"\"If I go cold and distant, they'll feel the loss and shape up.\"","myth":{"un":"If I go cold and distant, they'll feel the loss and shape up.","re":"Going cold removes the connection that keeps a child safe; warmth, not the silent treatment, is what reaches them.","why":"Warmth reaches; coldness pushes away."},"cat":"respond-dont-rupture"},
  {"id":"na-1083","type":"strike-rewrite","persona":"Divya","source":"calm voice lands","relearn":"Yelling makes a child shut down; a steady, lowered voice lets your words land.","hook":"\"Yelling shows I'm serious, and being serious is what gets through.\"","myth":{"un":"Yelling shows I'm serious, and being serious is what gets through.","re":"Yelling makes a child brace and shut down; a steady, lowered voice is what actually lets your words land.","why":"A calm voice lands; a raised one bounces off."},"cat":"respond-dont-rupture"},
  {"id":"na-1084","type":"strike-rewrite","persona":"Vikram","source":"open door over surveillance","relearn":"Secret surveillance erodes trust and teaches hiding; an open door keeps them talking.","hook":"\"Reading every message and tracking their phone is just me keeping them safe.\"","myth":{"un":"Reading every message and tracking their phone is just me keeping them safe.","re":"Secret surveillance teaches a child to hide and erodes trust; an open door keeps them talking far better than spying.","why":"An open door beats a hidden tracker."},"cat":"respond-dont-rupture"},
  {"id":"na-1085","type":"strike-rewrite","persona":"Kamla","source":"safety not shame","relearn":"Shame hides dependence; safety to be honest is what makes help possible.","hook":"\"If I make them feel ashamed enough, the shame will stop them.\"","myth":{"un":"If I make them feel ashamed enough, the shame will stop them.","re":"Shame doesn't stop dependence, it hides it; a child safe to be honest is the one you can actually help.","why":"Safety to be honest is what helps."},"cat":"respond-dont-rupture"},
  {"id":"na-1086","type":"strike-rewrite","persona":"Vikram","source":"stay don't threaten","relearn":"Abandonment threats cut a child's lifeline; staying while firm keeps them safe.","hook":"\"Threatening to throw them out will shock them into changing.\"","myth":{"un":"Threatening to throw them out will shock them into changing.","re":"Threats to abandon a child cut the lifeline they most need; staying, even while firm, is what keeps them safe.","why":"Stay, even when you set a limit."},"cat":"respond-dont-rupture"},
  {"id":"na-1087","type":"strike-rewrite","persona":"Priya","source":"connection over a lecture","relearn":"One angry lecture rarely changes dependence; calm connection over time keeps a child reachable.","hook":"\"One firm 'because I said so' lecture should sort the whole thing out.\"","myth":{"un":"One firm 'because I said so' lecture should sort the whole thing out.","re":"A single angry lecture rarely changes dependence; calm, repeated connection over time is what keeps a child reachable.","why":"Connection over time, not one lecture."},"cat":"respond-dont-rupture"},
  {"id":"na-1088","type":"strike-rewrite","persona":"Vikram","source":"a lie signals fear","relearn":"A lie about use signals fear; name it calmly and keep the door open.","hook":"\"If they lied to me, the only response is to stop trusting them completely.\"","myth":{"un":"If they lied to me, the only response is to stop trusting them completely.","re":"A lie about use is a sign of fear, not proof to write a child off; name it calmly and keep the door open.","why":"A lie signals fear; keep the door open."},"cat":"respond-dont-rupture"},
  {"id":"na-1089","type":"strike-rewrite","persona":"Divya","source":"calm is firm","relearn":"A calm talk isn't going soft; it keeps a child honest and willing to accept help.","hook":"\"Talking about it gently just lets them off the hook.\"","myth":{"un":"Talking about it gently just lets them off the hook.","re":"A calm talk isn't going soft; it's the firm, steady route that keeps a child honest and willing to accept help.","why":"Calm is firm, not soft."},"cat":"respond-dont-rupture"},
  {"id":"na-1090","type":"strike-rewrite","persona":"Kamla","source":"care is strength","relearn":"Showing calm worry isn't weakness; it tells a child they matter and keeps them reachable.","hook":"\"If I show I'm upset and worried, that's weakness they'll use against me.\"","myth":{"un":"If I show I'm upset and worried, that's weakness they'll use against me.","re":"Showing calm worry isn't weakness; it tells a child they matter to you, which is exactly what keeps them reachable.","why":"Honest care is strength, not weakness."},"cat":"respond-dont-rupture"},
  {"id":"na-1091","cat":"respond-dont-rupture","type":"branch","persona":"Vikram","source":"calm-confront","hook":"Looking for his tiffin box, you find vape pods in your son Aarav's school bag. Your heart is pounding.","steps":[{"prompt":"Aarav is in the next room with his headphones on. What do you do?","options":[{"text":"Wait until you've calmed down before you talk to him","then":"By evening your hands are steady, and you know what you want to say.","best":true},{"text":"Go in now and demand answers while it's fresh","then":"Aarav jumps up, flustered, and says the pods are a friend's before you finish."},{"text":"Put the pods back and say nothing for now","then":"Nothing changes at home, and the pods stay on your mind all day."},{"text":"Throw them away and start writing a firm lecture","then":"The pods are gone. Your notes for the lecture keep getting angrier."}],"why":"Cooling down first means your worry comes out, not your panic."},{"prompt":"That night you sit down with Aarav to talk properly. How do you open?","options":[{"text":"Ask straight away who gave them to him, so you can call their parents","then":"Aarav's face closes. \"Nobody. Forget it,\" he says, and turns away."},{"text":"Tell him how let down his grandparents would feel if they knew","then":"Aarav stares at the floor and says sorry, just to make it end."},{"text":"Start with his marks and slowly work your way round to the pods","then":"He talks about exams, puzzled, and tenses when the pods come up."},{"text":"Tell him what you found, and that you're worried and want to understand","then":"Aarav braces, then slowly admits a few friends vape after tuition.","best":true}],"why":"Calm worry and a real question invite him to talk instead of defend himself."},{"prompt":"Aarav says everyone in his class vapes and it's no big deal. What do you say?","options":[{"text":"Ban tuition outings and time with friends until he stops for good","then":"Aarav goes silent. A week later you find a new pod hidden in his shoe."},{"text":"Agree it's probably a phase he'll grow out of, and drop it","then":"Aarav relaxes. The pods keep turning up, and the topic never comes back."},{"text":"Say you're worried, not angry, and ask what vaping does for him","then":"Aarav shrugs, then says it takes the edge off exam stress. The real talk begins.","best":true},{"text":"Say you're worried and will check his bag every week now","then":"Aarav nods stiffly. From then on the bag is spotless and he says less."}],"why":"Staying calm and curious keeps him talking, which is how you can help."}],"debrief":"Cool down first, then open with calm worry, not a shouting confrontation.","relearn":"Confronting hot makes a teen lie; cooling down then opening with worry keeps them talking."},
  {"id":"na-1092","cat":"respond-dont-rupture","type":"branch","persona":"Kamla","source":"limit-together","hook":"Your son Sonu has been gaming on your old phone till 3am and has missed school twice this week.","steps":[{"prompt":"At 3am you see the screen glowing under his blanket again. What do you do?","options":[{"text":"Snatch the phone and say he'll never touch it again","then":"Sonu shouts back. Neither of you sleeps, and the morning starts in a fight."},{"text":"Let it go tonight because you're too tired to fight","then":"He plays on. In the morning he can't wake up for school again."},{"text":"Tell him quietly to sleep now and that you'll talk tomorrow","then":"Sonu grumbles but switches off. You both get a few hours of sleep.","best":true},{"text":"Take the phone quietly and hide it where he won't find it","then":"Sonu searches the house at dawn and blames his sister for taking it."}],"why":"Ending the night calmly and saving the talk for daytime stops it becoming a war."},{"prompt":"The next afternoon Sonu is calmer and sitting near you. How do you raise the gaming?","options":[{"text":"Announce a new rule: no phone after eight, full stop","then":"Sonu says it's unfair and walks off before you can explain."},{"text":"Explain why sleep matters and ask him to help set a limit","then":"Sonu thinks, then offers to stop at ten on school nights.","best":true},{"text":"Tell him the neighbours' children are doing much better","then":"Sonu's face falls. He says he's always the one who gets compared."},{"text":"Ask what he loves about the game and leave the limit for later","then":"He lights up describing his team. The 3am nights carry on."}],"why":"Explaining why and asking him to shape the limit makes it his rule too."},{"prompt":"That night Sonu says his friends all play till 3am and nobody minds. What do you say?","options":[{"text":"Say their rules aren't yours, and ask what would help him stop","then":"Sonu suggests an alarm to warn him when to stop. You agree to try it.","best":true},{"text":"Let him play late on weekends as long as he goes to school","then":"Sonu grins. By Sunday he's up till four, and Monday is a struggle."},{"text":"Warn him the phone goes to the kabadiwala if he argues again","then":"Sonu stops arguing. That night you hear the phone buzz under his pillow."},{"text":"Say you'll ask his teacher to talk sense into him","then":"Sonu groans and says school is bad enough already."}],"why":"Holding firm while solving it with him keeps both the limit and his trust."},{"prompt":"A week later Sonu stays up till one on a school night. What do you do?","options":[{"text":"Take the phone away for a month","then":"Sonu stops talking to you and borrows a friend's phone after school."},{"text":"Let it pass, since one late night isn't worth a fight","then":"The next night it's two, and the late nights become normal again."},{"text":"Tell him you knew he'd never change","then":"Sonu shrugs. \"Then why should I even try,\" he says."},{"text":"Calmly say one is too late, and ask what kept him up","then":"He admits a match ran late. Together you agree a stop time and an alarm.","best":true}],"why":"Staying calm and asking what got in the way keeps the limit alive without breaking the bond."}],"debrief":"Set the limit with the child and explain it warmly, rather than a furious confiscation.","relearn":"An angry forever-ban breeds sneaking; a warm, explained limit holds the rule and the bond."},
  {"id":"na-1093","cat":"respond-dont-rupture","type":"branch","persona":"Divya","source":"honesty-safe","hook":"Your daughter Ishita tells you she drank beer with friends at a party last night.","steps":[{"prompt":"She looks terrified of what you'll say. What do you do first?","options":[{"text":"Thank her for telling you, then take a breath","then":"Ishita's shoulders drop. \"I thought you'd be furious,\" she whispers.","best":true},{"text":"Ground her for a month so she knows this is serious","then":"Ishita nods, eyes wet. \"I shouldn't have told you,\" she says quietly."},{"text":"Ask who else was there so you can call their parents","then":"Ishita panics. \"Please don't. They'll never talk to me again.\""},{"text":"Tell her it's normal at her age and let the matter go","then":"Ishita looks relieved. Neither of you brings it up again until bedtime."}],"why":"Thanking her first shows her that honesty is safe with you."},{"prompt":"At bedtime, Ishita adds that her friends kept pushing and she didn't want to seem boring. What do you say?","options":[{"text":"Tell her those friends are trouble and she must drop them","then":"Ishita bristles. \"You don't even know them,\" she says."},{"text":"Tell her you drank at her age too, so it's fine","then":"She laughs, surprised. The worry you felt goes unsaid."},{"text":"Say you understand and move straight to rules for next time","then":"Ishita nods along. She doesn't tell you the part that scared her."},{"text":"Ask how it felt to be pushed, and listen","then":"She says she felt stuck. You hear how hard saying no was for her.","best":true}],"why":"Listening first shows you the pressure she faced before you make any plan."},{"prompt":"The next party is in two weeks, and Ishita wants to go. What do you do?","options":[{"text":"Forbid all parties until she turns eighteen, to keep her safe","then":"Ishita goes silent. Later you see her messaging friends about the party anyway."},{"text":"Let her go and trust that it won't happen a second time","then":"She goes. You lie awake with no plan if things go wrong."},{"text":"Plan together how she'll say no and how she can reach you","then":"Ishita suggests a code word by text. You agree to fetch her, no questions asked.","best":true},{"text":"Let her go only if she promises she'll never drink again","then":"Ishita promises quickly. Neither of you quite believes it will hold."}],"why":"A plan made together gives her a way out and keeps her coming to you."}],"debrief":"Reward honesty with calm and a plan, not a harsher punishment for the truth.","relearn":"Punishing honesty teaches secrecy; thanking and planning keeps a teen truthful."},
  {"id":"na-1094","cat":"respond-dont-rupture","type":"branch","persona":"Vikram","source":"slip-not-child","hook":"Your son Kabir had stopped vaping for six weeks. Tonight you smell it on his jacket again.","steps":[{"prompt":"You feel disappointment rising in your chest. What do you do?","options":[{"text":"Tell him he's proven he'll never change","then":"Kabir's face goes blank. \"Then why should I even try,\" he mutters."},{"text":"Pretend you didn't notice, to protect his progress","then":"Kabir keeps it hidden, and you both act as if the six weeks go on."},{"text":"Say nothing and stay cold with him for a few days","then":"The house goes quiet. Kabir eats in his room and avoids your eyes."},{"text":"Tell him you're disappointed in the slip, not in him","then":"Kabir looks up, surprised. \"I thought you'd give up on me,\" he says.","best":true}],"why":"Separating the slip from him keeps him connected and willing to keep trying."},{"prompt":"Later that week, Kabir admits he's vaping again and says he's useless. What do you say?","options":[{"text":"Tell him to stop being so dramatic and just quit for good this time","then":"Kabir clams up. \"You don't get it,\" he says, and leaves the room."},{"text":"Agree that maybe he isn't ready yet and try again after exams","then":"He looks relieved. The vape is back in his pocket the next day."},{"text":"Say slips happen in recovery, and six weeks shows he can do it","then":"Kabir is quiet, then asks if you'll help him start again.","best":true},{"text":"Tell him you're proud anyway and change the subject","then":"He smiles weakly. What made him slip never comes up."}],"why":"Slips are common in recovery. Naming his progress keeps hope and effort alive."},{"prompt":"A few days later you think about what comes next. What do you do?","options":[{"text":"Search his room every day from now on so it can't happen again","then":"Kabir notices things moved and starts keeping the vape at a friend's."},{"text":"Ask Kabir what led to the slip and plan the next weeks together","then":"He names exam stress and one friend. You agree on what to try next.","best":true},{"text":"Leave it to him this time, since he knows what worked before","then":"Kabir struggles on alone, unsure you're still with him."},{"text":"Promise him a new phone if he stays off it for a month","then":"Kabir agrees fast. The reward, not the reasons, becomes the focus."}],"why":"Working out what led to it, together, turns a slip into something to learn from."}],"debrief":"Be disappointed in the slip, not the child; rejection can end the effort to recover.","relearn":"Reject the slip, not the child; 'you'll never change' can make a relapsing child give up."},
  {"id":"na-1095","cat":"respond-dont-rupture","type":"branch","persona":"Priya","source":"named-calmly","hook":"Your daughter Meher's friend Sana is over. You hear Meher say she hardly ever vapes, though you find pods daily.","steps":[{"prompt":"The girls are laughing in the next room. What do you do right now?","options":[{"text":"Walk in and tell Sana how much Meher really vapes","then":"Meher goes red. Sana leaves early, and Meher won't look at you."},{"text":"Leave it for now and plan to talk to Meher alone later","then":"The girls carry on chatting. You make a note to find a quiet moment.","best":true},{"text":"Message Sana's mother to warn her about Meher's vaping","then":"Sana's mother calls back upset. By evening Meher knows, and she's furious."},{"text":"Let it go, since what she tells her friends is her own business","then":"The moment passes, and the pods stay on your mind all evening."}],"why":"Waiting for a private moment spares her humiliation and keeps the door open."},{"prompt":"That evening Meher is alone, scrolling on the sofa. How do you begin?","options":[{"text":"Say you overheard her, and ask how she's really doing","then":"Meher sighs. \"It's more than I said,\" she admits. \"I don't know how to stop.\"","best":true},{"text":"Tell her you caught her lying and demand the real number","then":"Meher folds her arms. \"Fine. I lied. Happy now,\" she snaps."},{"text":"Ask about her day and hope she brings up the vaping herself","then":"She chats about school. The vaping never comes up."},{"text":"Leave a printout about vaping harms on her pillow","then":"Meher finds it, crumples it, and avoids you all evening."}],"why":"Naming it calmly and asking how she is makes her feel seen, not ambushed."},{"prompt":"At bedtime Meher says she knows you've found her pods, and begs you not to tell her father. What do you do?","options":[{"text":"Promise to keep it just between the two of you, for now","then":"Meher relaxes. You're left carrying it alone, with no plan and no help."},{"text":"Tell her father at dinner in front of everyone","then":"Meher goes silent at the table and leaves her food untouched."},{"text":"Say it depends on whether she has stopped vaping by Sunday","then":"Meher nods. By Sunday she's simply hiding it better."},{"text":"Promise not to shame her, and offer to tell her father together","then":"Meher hesitates, then agrees if you sit with her while she says it.","best":true}],"why":"Being honest about next steps, and taking them with her, keeps her trust and brings in support."}],"debrief":"Name a lie calmly and privately later, not by humiliating a child in front of others.","relearn":"Public exposure shuts a teen down; a calm private 'how are you really' opens them up."},
  {"id":"na-1096","cat":"respond-dont-rupture","type":"branch","persona":"Kamla","source":"reach-the-pain","hook":"Your son Deepak, 15, has been smoking. He tells a cousin it's the only thing that calms him when home feels tense.","steps":[{"prompt":"You find him alone on the terrace with a cigarette. What do you do?","options":[{"text":"Lecture him about the rule he has broken","then":"Deepak waits for you to finish, then goes downstairs without a word."},{"text":"Snatch the cigarette and say he's wasting money","then":"Deepak shrugs and says everyone here has their own way of coping."},{"text":"Ask which shop sold them so you can stop the shopkeeper","then":"Deepak names a shop and goes quiet. What's bothering him stays unsaid."},{"text":"Sit beside him and ask what's been making things so hard","then":"Deepak stubs it out. After a long silence he says home feels heavy lately.","best":true}],"why":"Asking what's hard reaches the pain that the habit is covering."},{"prompt":"Later Deepak says, \"You wouldn't understand. You've got enough problems.\" What do you do?","options":[{"text":"Agree you have enough problems and leave it there","then":"Deepak nods, as if he expected that, and goes to his room."},{"text":"Tell him he's too young to worry about grown-up things","then":"He clams up. \"See, I told you,\" he mutters."},{"text":"Tell him you're on his side and want to hear it anyway","then":"Deepak looks at you properly for the first time in weeks and starts to talk.","best":true},{"text":"Say you understand and promise that things will get better soon","then":"Deepak says okay. He doesn't believe it, and neither do you."}],"why":"Showing you're on his side, whatever is going on, makes it safe for him to share."},{"prompt":"A few days on, Deepak admits he smokes daily now and can't cut down. What do you do?","options":[{"text":"Tell him to just stop, since it's all about willpower","then":"Deepak tries for a day, fails, and hides it from you after that."},{"text":"Say it's hard, not weak, and suggest calling Tele-MANAS 14416 together","then":"Deepak hesitates, then agrees to sit beside you while you call.","best":true},{"text":"Keep it inside the family and handle it quietly between you","then":"Weeks pass. Deepak keeps smoking, and no one outside knows how hard it is."},{"text":"Promise to sort out home first and deal with the smoking later","then":"Deepak nods. The smoking goes on while you wait for things to settle."}],"why":"Dependence is a health issue, and early help works best with family alongside."}],"debrief":"Respond to the pain underneath the habit, not just the broken rule.","relearn":"A rule-only lecture misses the pain; asking 'what's hard' and taking their side reaches it."},
  {"id":"na-1097","cat":"respond-dont-rupture","type":"branch","persona":"Vikram","source":"repair-bridge","hook":"You bring up your daughter Riya's phone use at dinner. She storms off and slams her bedroom door.","steps":[{"prompt":"You hear her crying through the door. What do you do?","options":[{"text":"Bang on the door and demand that she come out and talk to you now","then":"Riya turns her music up loud. The wall between you gets thicker."},{"text":"Give her some time, and say softly that you'll come back soon","then":"The crying slows. After a while, the house goes quiet.","best":true},{"text":"Shout that door-slamming isn't allowed in this house","then":"Riya shouts back through the door, and your wife asks you both to stop."},{"text":"Slip a note under the door saying sorry you raised it","then":"Riya reads it but stays inside. The phone topic now feels off-limits."}],"why":"Space lets her feelings settle, so she can hear you when you return."},{"prompt":"An hour later her door is still shut and the house is quiet. What do you do?","options":[{"text":"Knock gently and say you're here for her, not to fight","then":"After a pause, the door opens a crack. Riya lets you sit on the bed.","best":true},{"text":"Wait for her to come to you, however long it takes","then":"Riya stays in her room all evening. Neither of you makes the first move."},{"text":"Send her a long text listing why her phone use worries you","then":"Riya reads it, replies with a single \"ok\", and switches off her light."},{"text":"Knock and tell her she's overreacting to a simple question","then":"\"Just go away, Papa,\" she says, and the door stays shut."}],"why":"Coming back calm shows her the relationship is safe even after a flare-up."},{"prompt":"Next morning Riya says you always make her feel she's in trouble. What do you say?","options":[{"text":"Say that's only because she keeps getting herself into trouble","then":"Riya rolls her eyes and leaves for school without breakfast."},{"text":"Apologise for ever raising her phone at all","then":"Riya smiles, relieved. The late-night scrolling carries on untouched."},{"text":"Tell her you only worry about her because you love her so much","then":"Riya sighs. \"I know. That's not the point, though,\" she says."},{"text":"Say that's not what you want, and ask how to raise things better","then":"Riya thinks. \"Maybe not at dinner, in front of everyone,\" she says.","best":true}],"why":"Hearing her out without defending yourself rebuilds the bridge for the next talk."},{"prompt":"That weekend Riya dozes off over her homework after another late night. What do you do?","options":[{"text":"Raise her phone use at dinner, with the whole family listening","then":"Riya's jaw tightens. She eats fast and leaves the table."},{"text":"Quietly change the wifi password at ten every night","then":"Riya finds out and switches to her data pack instead, annoyed."},{"text":"Ask her for a walk and share one thing you've noticed","then":"Riya admits she scrolls till two most nights and feels tired all day.","best":true},{"text":"Say nothing, since raising her phone only causes fights","then":"Weeks pass. The dark circles under Riya's eyes deepen."}],"why":"A calm, private moment lets the real conversation happen without another flare-up."}],"debrief":"After a flare-up, give space and return calm; forcing it while flooded backfires.","relearn":"Forcing talk while a teen is flooded deepens the wall; space then a calm return reopens it."},
  {"id":"na-1098","cat":"respond-dont-rupture","type":"branch","persona":"Divya","source":"steady-not-snap","hook":"It's late and you've barely slept all week. Your son Arjun, 12, is still gaming after two reminders.","steps":[{"prompt":"He ignores you a third time, and you feel close to exploding. What do you do?","options":[{"text":"Take a breath and step into the kitchen for a minute","then":"The kettle boils. Your jaw unclenches, and you can think again.","best":true},{"text":"Yell at him with everything you've been holding in","then":"Arjun flinches, then yells back. You both say things you don't mean."},{"text":"Unplug the TV mid-game without a word","then":"Arjun shouts that he's lost his progress and storms off."},{"text":"Give up and go to bed, too tired to deal with it","then":"Arjun plays till midnight, and tomorrow starts with both of you exhausted."}],"why":"A short pause lets you respond from care instead of your last nerve."},{"prompt":"The next evening you want to talk about last night. How do you start?","options":[{"text":"Tell him last night was all his fault for not listening to you","then":"Arjun crosses his arms and says you never let him finish anything."},{"text":"Say nothing and hope tonight goes better","then":"Tonight goes the same way, and your patience is thin by eight."},{"text":"Announce that he's banned from gaming for a week","then":"Arjun says it's unfair and sulks through dinner."},{"text":"Admit you've been worn out, and ask to agree a stop time","then":"Arjun softens. \"I was being annoying too,\" he admits.","best":true}],"why":"Being honest about your tiredness and agreeing a plan together lowers the heat for both of you."},{"prompt":"Later you notice how drained you've been all week. What do you do about it?","options":[{"text":"Push through, since parents shouldn't need breaks","then":"By Friday your fuse is shorter than ever."},{"text":"Hand Arjun the tablet whenever you need some quiet","then":"The house is quieter, and his gaming creeps longer each day."},{"text":"Ask family or a friend to take some evenings so you can rest","then":"Your sister offers to take Tuesdays. You feel less alone, and steadier.","best":true},{"text":"Promise yourself you'll just be more patient from now on","then":"The promise lasts two days. Then tiredness wins again."}],"why":"Looking after yourself is part of responding well. A rested parent stays steady."}],"debrief":"Step away to steady yourself first, so exhaustion doesn't become rupture.","relearn":"An exhausted outburst ruptures trust; pausing to steady yourself lets you respond from care."},
  {"id":"na-1099","cat":"respond-dont-rupture","type":"branch","persona":"Priya","source":"keep-promise","hook":"Your son Vihaan, 14, hovers at your door and asks whether you'll be angry if he tells you something.","steps":[{"prompt":"He adds that it's about something he's been using. What do you say?","options":[{"text":"Say that depends entirely on what he's done","then":"Vihaan backs away. \"Forget it. It's nothing,\" he says."},{"text":"Warn him you might explode, but he should tell you anyway","then":"Vihaan hesitates, then says it's nothing important after all."},{"text":"Promise that honesty won't be met with rage, and mean it","then":"Vihaan sits down. \"Okay,\" he says. \"I've been vaping since Diwali.\"","best":true},{"text":"Say he should know by now that he can tell you anything","then":"Vihaan isn't sure what that means, and he lingers at the door."}],"why":"A clear promise of calm makes it safe enough for him to tell you the truth."},{"prompt":"Later, Vihaan admits he can't go a single day without vaping now. What do you do?","options":[{"text":"Go quiet and cold, since at least you're not shouting","then":"Vihaan watches your face and wishes he'd said nothing."},{"text":"Stay calm, thank him, and say you'll find help together","then":"Vihaan exhales. \"I thought you'd throw me out,\" he says quietly.","best":true},{"text":"Tell him how deeply he has disappointed you","then":"Vihaan's eyes fill. He says he knew this would happen."},{"text":"Take away his phone and pocket money on the spot","then":"Vihaan stares. \"This is why I didn't want to tell you.\""}],"why":"Staying calm when the truth is hard is what builds real trust."},{"prompt":"A month later Vihaan comes to you, nervous. A teacher caught him vaping at school and will call you. What do you do?","options":[{"text":"Stay calm and ask him what happened","then":"Vihaan relaxes a little and tells you the whole story before the call comes.","best":true},{"text":"Tell him you're too angry to talk about it tonight","then":"Vihaan nods, and quietly decides not to tell you next time."},{"text":"Ban him from going out with friends after school","then":"Vihaan agrees, but starts hiding his vape more carefully."},{"text":"Say you're calm but tired of him always letting you down","then":"Vihaan's face drops at the word always. He says little more."}],"why":"Staying calm each time he's honest keeps the door open for the next hard talk."}],"debrief":"Promise honesty won't meet rage, and keep it, so a child stays able to tell you things.","relearn":"Refusing calm makes silence feel safer; promising and keeping calm keeps a child honest."},
  {"id":"na-1100","cat":"respond-dont-rupture","type":"branch","persona":"Vikram","source":"stay-the-safe-adult","hook":"Your son Ayaan, 16, was caught drinking on a school trip. Now every relative has advice.","steps":[{"prompt":"Your brother-in-law says you must come down hard and take everything away. What do you do?","options":[{"text":"Thank him, and say you'll handle it calmly with Ayaan","then":"He mutters that you're too soft, but he lets it drop for now.","best":true},{"text":"Agree, and take Ayaan's phone and bike that evening","then":"Ayaan goes silent and stops coming out of his room."},{"text":"Argue with him loudly in front of the family","then":"The row spills into the family WhatsApp group, and Ayaan reads every message."},{"text":"Say nothing and let him think you'll crack down","then":"He assumes you agree and tells the others you're cracking down."}],"why":"Holding your approach politely keeps you the steady adult Ayaan can trust."},{"prompt":"At a family lunch, an aunt tells Ayaan in front of everyone that he's shamed the family. What do you do?","options":[{"text":"Add that he should be ashamed, since she's right","then":"Ayaan's face burns. He leaves the table and doesn't come back."},{"text":"Stay quiet, so the lunch stays peaceful for everyone","then":"Ayaan sits through it alone. On the drive home he won't speak."},{"text":"Laugh it off and steer the talk to cricket","then":"The table moves on, but Ayaan still looks shaken."},{"text":"Step in calmly and say you and Ayaan are dealing with it","then":"The aunt goes quiet. Ayaan glances at you, surprised and grateful.","best":true}],"why":"Stepping in shields him from public shame, which only drives the problem deeper."},{"prompt":"That night Ayaan asks what happens now, since everyone says you should punish him. What do you say?","options":[{"text":"Say he'll be punished hard, as the relatives want","then":"Ayaan looks away, says he figured, and shuts his door."},{"text":"Say it's all forgotten, since it was just one trip","then":"Ayaan relaxes. Nothing about the drinking gets talked through."},{"text":"Say there will be clear limits, and you're on his side","then":"Ayaan listens, then asks what the limits are. You work them out together.","best":true},{"text":"Say it depends on how sorry he acts in front of family","then":"Ayaan nods stiffly and starts performing sorry at every visit."}],"why":"Being firm about the behaviour and fully there for him are not opposites."},{"prompt":"A week later your mother calls. The relatives keep asking her what you're doing about Ayaan. What do you tell her?","options":[{"text":"Promise her you'll come down hard, as they all want","then":"She sounds relieved. You hang up dreading the scene you've promised."},{"text":"Explain your approach and ask for her support","then":"Your mother is quiet, then asks how she can help.","best":true},{"text":"Snap that it's none of her business","then":"She hangs up hurt, and the family grapevine gets busier."},{"text":"Agree to let her talk some sense into Ayaan","then":"She lectures Ayaan on the phone for an hour. He dodges her calls after that."}],"why":"Explaining your approach can turn family pressure into family support."}],"debrief":"Hold the calm, connected approach even under family pressure to crack down.","relearn":"A pressured crackdown shames a child; staying the calm, steady adult keeps them reachable."},
  {"id":"na-1101","cat":"respond-dont-rupture","type":"branch","persona":"Kamla","source":"door-open","hook":"Your daughter Pooja, 17, often comes home smelling of alcohol, but she insists nothing is wrong.","steps":[{"prompt":"Tonight she walks in late and heads straight for her room. What do you do?","options":[{"text":"Block her way until she finally admits she's been drinking","then":"Pooja pushes past you, shouting, and locks herself in."},{"text":"Pretend not to notice anything, so there's no scene tonight","then":"Pooja slips into her room. The smell lingers in the hallway."},{"text":"Say calmly that you've noticed, and you're there when she's ready","then":"Pooja pauses at her door. \"Nothing's wrong,\" she says, softer than usual.","best":true},{"text":"Ask her straight out whether she's been drinking again tonight","then":"\"No,\" Pooja says flatly, and closes her door."}],"why":"Naming what you notice without demanding a confession stops her digging in."},{"prompt":"Over the next week Pooja stays distant and denies anything is wrong. What do you do?","options":[{"text":"Check her phone while she sleeps, to find proof of the drinking","then":"You find nothing clear, and she notices her phone has been moved."},{"text":"Keep your warm routines and gently name what you see now and then","then":"Pooja starts sitting with you at breakfast again, though she says little.","best":true},{"text":"Tell her she's lying and that you're done trusting her word","then":"Pooja stops speaking to you at all."},{"text":"Stop mentioning it, since she clearly doesn't want to talk","then":"Things feel calmer on the surface. The late nights continue."}],"why":"Staying warm and honest keeps the door open for when she's ready."},{"prompt":"One night Pooja says quietly that maybe she's been drinking too much. What do you do?","options":[{"text":"Thank her, stay calm, and ask what help she'd like","then":"Pooja cries a little and says she wants to cut down but can't.","best":true},{"text":"Tell her you knew it all along","then":"Pooja stiffens. \"Then why did I bother telling you,\" she says."},{"text":"Tell her to stop from tomorrow, simple as that","then":"Pooja nods. The next weekend, she's back to hiding it."},{"text":"Promise to keep it a secret from everyone","then":"Pooja is relieved, and you're left with no plan and no help."}],"why":"Meeting her first admission with calm makes it easier for her to accept help."}],"debrief":"Keep gently naming what you see and stay warm, rather than forcing a confession.","relearn":"Forcing a confession makes a child dig in; warm, gentle noticing keeps the door open."},
  {"id":"na-1102","type":"match","persona":"any","source":"rupture vs connect","relearn":"Each rupturing reaction has a calm, connecting twin that keeps a struggling child reachable.","hook":"Match each rupturing reaction to the calm, connecting one that reaches a child.","pairs":[{"left":"'You're a liar'","right":"'Help me understand what's going on'"},{"left":"'Get out of my sight'","right":"'Let's sit down, I'm right here'"},{"left":"'You've ruined this family'","right":"'We'll get through this together'"},{"left":"'I'm done with you'","right":"'I'm not going anywhere'"},{"left":"'How dare you do this'","right":"'I'm worried, not angry'"}],"cat":"respond-dont-rupture"},
  {"id":"na-1103","type":"match","persona":"any","source":"steady moves","relearn":"Defensiveness, silence, relapse, lies and lashing out each meet a steady move that keeps a child reachable.","hook":"Match each hard moment with the steady move that keeps the door open.","pairs":[{"left":"They're defensive","right":"Lower your voice and the stakes"},{"left":"They go silent","right":"Sit nearby, no pressure to talk yet"},{"left":"They relapse","right":"Disappointment without rejection"},{"left":"They lie","right":"Name it calmly, keep the door open"},{"left":"They lash out","right":"Stay steady, don't match the heat"}],"cat":"respond-dont-rupture"},
  {"id":"na-1104","type":"match","persona":"Vikram","source":"feeling to response","relearn":"Each strong parent feeling has a calm response that keeps it from rupturing the relationship.","hook":"Match each parent feeling to the calm response that doesn't let it become a rupture.","pairs":[{"left":"Furious","right":"Step away, breathe, come back steady"},{"left":"Terrified","right":"Name the worry, stay in the room"},{"left":"Betrayed","right":"Address the behaviour, keep the bond"},{"left":"Helpless","right":"Reach for help, you're not alone"},{"left":"Ashamed","right":"Drop the blame, focus on the child"}],"cat":"respond-dont-rupture"},
  {"id":"na-1105","type":"match","persona":"any","source":"slam vs open","relearn":"Each door-slamming line has a door-opening twin that keeps a struggling child willing to talk.","hook":"Match each 'door-slamming' line to the 'door-opening' one that works better.","pairs":[{"left":"'Because I said so'","right":"'Here's why this worries me'"},{"left":"'You always do this'","right":"'This isn't like you, what's going on'"},{"left":"'Figure it out yourself'","right":"'Let's figure this out together'"},{"left":"'I can't even look at you'","right":"'I love you, that hasn't changed'"},{"left":"'Wait till I tell everyone'","right":"'This stays between us for now'"}],"cat":"respond-dont-rupture"},
  {"id":"na-1106","type":"match","persona":"Priya","source":"what calm protects","relearn":"Each calm-response goal protects something a struggling child needs: the bond, being heard, the truth, dignity.","hook":"Match each calm-response goal to what it protects.","pairs":[{"left":"Stay connected","right":"The lifeline that keeps them safe"},{"left":"Keep your voice low","right":"Their ability to actually hear you"},{"left":"Hold a warm limit","right":"The boundary and the bond"},{"left":"Reward honesty","right":"Their willingness to tell you the truth"},{"left":"Avoid public shame","right":"Their dignity and the open door"}],"cat":"respond-dont-rupture"},
  {"id":"na-1107","type":"match","persona":"any","source":"calm openings","relearn":"Each thing a frightened child says has a calm reply that keeps the conversation, and the help, possible.","hook":"Match each first thing a child says to a calm opening reply.","pairs":[{"left":"'Are you going to yell?'","right":"'No. Tell me what's going on'"},{"left":"'You'll hate me'","right":"'Nothing changes how I love you'"},{"left":"'I couldn't stop'","right":"'That's exactly why we'll get help'"},{"left":"'It's not a big deal'","right":"'Okay. I'd still like to understand'"},{"left":"'I'm scared to say'","right":"'Take your time, I'm right here'"}],"cat":"respond-dont-rupture"},
  {"id":"na-1108","type":"match","persona":"Vikram","source":"crackdown vs connect","relearn":"Each crackdown instinct has a connected alternative that keeps a child reachable and trusting.","hook":"Match each instinct to crack down with the connected alternative that works better.","pairs":[{"left":"Grab the phone in anger","right":"Agree a screen plan together"},{"left":"Forbid all their friends","right":"Ask which ones they trust"},{"left":"Threaten to throw them out","right":"Promise you're staying, firmly"},{"left":"Read their messages secretly","right":"Ask them directly, openly"},{"left":"Shame them in front of others","right":"Talk privately, with respect"}],"cat":"respond-dont-rupture"},
  {"id":"na-1109","type":"match","persona":"any","source":"phrase to moment","relearn":"Each calm phrase fits a specific hard moment and keeps a struggling child reachable through it.","hook":"Match each calm phrase to the moment it fits best.","pairs":[{"left":"'I'm worried, not angry'","right":"On first discovering use"},{"left":"'We'll face this together'","right":"When they feel alone in it"},{"left":"'A slip isn't the end'","right":"After a relapse"},{"left":"'You can be honest with me'","right":"When they're afraid to tell you"},{"left":"'Let's get the right help'","right":"When it's bigger than home"}],"cat":"respond-dont-rupture"},
  {"id":"na-1110","cat":"respond-dont-rupture","type":"role-play","persona":"Vikram","source":"first words","hook":"Your son Ishaan, 16, has just told you he's been vaping for a year. He won't meet your eyes.","setup":"You're alone in the car, parked outside home.","steps":[{"prompt":"Ishaan mumbles: \"So yeah. That's it. Go ahead and yell.\"","options":[{"text":"\"I knew it. You've let this whole family down.\"","then":"Ishaan stares out of the window. \"Yeah. I always do.\""},{"text":"\"I'm really glad you told me. I'm worried, not angry.\"","then":"Ishaan glances over, surprised. \"You're not going to yell?\"","best":true},{"text":"\"A whole year? How could you be so stupid about this?\"","then":"Ishaan's jaw tightens. \"This is why I didn't tell you.\""},{"text":"\"It's fine. Lots of boys your age try it once or twice.\"","then":"Ishaan looks relieved. \"So it's not a big deal, then.\""}],"why":"Gratitude and calm worry show him that telling you was safe."},{"prompt":"Ishaan asks: \"So what are you going to do about it?\"","options":[{"text":"\"Nothing without you. We'll make a plan together.\"","then":"Ishaan nods. \"Okay. What kind of plan?\"","best":true},{"text":"\"Search your room every week from now on.\"","then":"Ishaan's face closes. \"Great. So now I'm a criminal.\""},{"text":"\"Tell your grandparents, so they can talk to you.\"","then":"Ishaan groans. \"Please don't. Dadi will cry for a week.\""},{"text":"\"I'll decide once I've calmed down. Go inside.\"","then":"Ishaan gets out quietly. \"Okay,\" he says, unsure what's coming."}],"why":"Making the plan with him keeps him part of the solution."},{"prompt":"That night at home, Ishaan admits: \"I've tried to quit twice. I keep going back.\"","options":[{"text":"\"Then try harder this time. It's only about willpower.\"","then":"Ishaan looks away. \"Right. Like I haven't been trying.\""},{"text":"\"Then there's no pocket money until you stop for good.\"","then":"Ishaan goes quiet. \"I'll find the money anyway,\" he mutters."},{"text":"\"We'll keep this between us and handle it here at home.\"","then":"Ishaan nods. \"Okay. But I already tried that on my own.\""},{"text":"\"That's not weakness. Let's find someone who can help us.\"","then":"Ishaan exhales. \"Okay. I'd actually like that.\"","best":true}],"why":"Seeing it as a health issue, not weakness, opens the door to real help."}],"relearn":"Open with gratitude and calm worry, not anger, so a child stays safe to be honest."},
  {"id":"na-1111","cat":"respond-dont-rupture","type":"role-play","persona":"Divya","source":"lift the shame","hook":"Your daughter Kavya has been trying to stop drinking. Tonight she breaks down in her room.","setup":"You sit beside her on the bed.","steps":[{"prompt":"Kavya sobs: \"I hate myself. Why can't I just stop like a normal person?\"","options":[{"text":"\"Well, you should have thought of that before.\"","then":"Kavya turns away. \"I knew you'd say that,\" she sobs."},{"text":"\"Don't say that. You're perfect, and everything's fine.\"","then":"Kavya shakes her head. \"It's not fine. You don't get it.\""},{"text":"\"Just be stronger. You can stop if you really want to.\"","then":"Kavya whispers, \"I do want to. That's what scares me.\""},{"text":"\"You're not bad. It's a health thing, and we'll get help.\"","then":"Kavya wipes her face. \"A health thing? Not just me being weak?\"","best":true}],"why":"Naming it as a health issue lifts the shame that keeps her stuck."},{"prompt":"Kavya asks: \"Are you ashamed of me?\"","options":[{"text":"\"A little, honestly. But I'll get over it.\"","then":"Kavya pulls away. \"I knew it,\" she whispers."},{"text":"\"Not ashamed. Just worried what the family will say.\"","then":"Kavya's face falls. \"So it's about them.\""},{"text":"\"No. I'm proud you're trying, and I love you.\"","then":"Kavya leans into your shoulder. \"I thought you would be.\"","best":true},{"text":"\"Let's not do feelings now. Let's make a plan.\"","then":"Kavya nods. \"Okay,\" she says, but her shoulders stay tight."}],"why":"Hearing that your love is steady makes it safe for her to keep trying."},{"prompt":"Kavya asks: \"What if I try and I still can't stop?\"","options":[{"text":"\"You will, if you just decide to and stick with it.\"","then":"Kavya looks unsure. \"I've decided so many times already.\""},{"text":"\"Slips can happen. We'll keep going, with help.\"","then":"Kavya breathes out. \"Okay. Will you come with me to talk to someone?\"","best":true},{"text":"\"Then we'll deal with that when it happens, not now.\"","then":"Kavya nods. \"Okay,\" she says, but the fear stays in her eyes."},{"text":"\"Let's keep it between us, and you try again first.\"","then":"Kavya hesitates. \"On my own again?\""}],"why":"Recovery is real and common with support, and hope helps her keep going."}],"relearn":"Lift the shame: name it as a health issue you'll get help for, not a moral failing."},
  {"id":"na-1112","cat":"respond-dont-rupture","type":"role-play","persona":"Kamla","source":"reopen the door","hook":"You raised your son Manoj's drinking this morning. He has barely said a word to you since.","setup":"It's evening, and he's on the steps outside.","steps":[{"prompt":"Manoj mutters: \"I don't want to talk about it.\"","options":[{"text":"\"Fine, sulk then. And don't come crying to me later on.\"","then":"Manoj gets up. \"I won't,\" he says, and walks off down the lane."},{"text":"\"No need to talk now. I'm on your side whenever you're ready.\"","then":"Manoj shrugs. \"Okay,\" he mumbles, and stays when you sit beside him.","best":true},{"text":"\"We're talking about it now, whether you like it or not.\"","then":"Manoj stands. \"Then I'm going out,\" he says."},{"text":"\"Okay. I'm sorry I ever brought it up this morning.\"","then":"Manoj nods, relieved. \"Good. Just forget it.\""}],"why":"Presence without pressure tells him the door is still open."},{"prompt":"A few days later Manoj asks: \"Why do you even care what I do?\"","options":[{"text":"\"Because I love you, and I can see you're not okay.\"","then":"Manoj looks down. \"I'm not,\" he admits quietly.","best":true},{"text":"\"Because you're bringing shame on this whole house.\"","then":"Manoj laughs bitterly. \"There it is.\""},{"text":"\"I don't, if that's really how you want it to be.\"","then":"Manoj stares. \"Right. Thought so.\""},{"text":"\"Because I'm your mother. Worrying is simply my job.\"","then":"Manoj shrugs. \"Job done, then.\""}],"why":"Telling him plainly that you care, and why, keeps the bridge standing."},{"prompt":"Manoj admits: \"I drink so I don't have to think. It's the only thing that works.\"","options":[{"text":"\"Then just stop thinking so much. Keep yourself busy.\"","then":"Manoj shakes his head. \"It doesn't work like that, Amma.\""},{"text":"\"You're far too young to have problems that real.\"","then":"Manoj's face closes. \"Forget I said anything.\""},{"text":"\"I understand. I won't tell a soul about this. I promise.\"","then":"Manoj nods. \"Good. Let's just leave it there.\""},{"text":"\"That sounds heavy. We could call Tele-MANAS 14416 together.\"","then":"Manoj is quiet for a while. \"Would you sit with me while I call?\"","best":true}],"why":"Offering to find help together turns his trust into a way forward."}],"relearn":"Offer presence without pressure so a shut-down child knows the door is still open."},
  {"id":"na-1113","cat":"respond-dont-rupture","type":"role-play","persona":"Vikram","source":"name the lie kindly","hook":"Your son Siddharth, 16, said he was studying at Neel's. You've learnt he was drinking at a party.","setup":"Next morning, he's in the kitchen making tea.","steps":[{"prompt":"Siddharth says: \"Morning. Studying went fine, by the way.\"","options":[{"text":"\"You're a liar. I'll never believe a word you say again.\"","then":"Siddharth's face hardens. \"Then why ask me anything?\""},{"text":"\"Really? Which chapter did you study, then?\"","then":"Siddharth fumbles, then says, \"Fine. I wasn't there. Happy?\""},{"text":"\"Your mother and I know exactly where you really were.\"","then":"Siddharth goes pale. \"Who told you?\""},{"text":"\"I know you weren't at Neel's. You can be honest with me.\"","then":"Siddharth sets the cup down. \"Okay. I was at a party.\"","best":true}],"why":"Naming the lie calmly gives him room to tell the truth instead of defending it."},{"prompt":"Siddharth says: \"I lied because you'd never have let me go.\"","options":[{"text":"\"Then you won't go anywhere without me for a month.\"","then":"\"See? This is exactly why I lied,\" he snaps."},{"text":"\"Fine. From now on, you can go wherever you like.\"","then":"Siddharth blinks. \"Seriously?\" He looks more confused than pleased."},{"text":"\"Maybe. But I'd rather know where you are, even if I say no.\"","then":"Siddharth shrugs. \"Would you really have let me go, though?\"","best":true},{"text":"\"I understand. Let's just forget about it, this one time.\"","then":"Siddharth smiles, relieved. \"Thanks, Papa. You're the best.\""}],"why":"Taking his reason seriously while asking for honesty keeps the talk real."},{"prompt":"Siddharth admits: \"I had a few drinks. Everyone did. It was no big deal.\"","options":[{"text":"\"No big deal? You could have ended up in hospital!\"","then":"Siddharth rolls his eyes. \"Now you're being dramatic.\""},{"text":"\"Thanks for telling me. How did you get home?\"","then":"Siddharth hesitates. \"A friend's brother drove us. He'd had a few too.\"","best":true},{"text":"\"If it was no big deal, why did you lie about it?\"","then":"Siddharth goes red. \"Because of exactly this,\" he says."},{"text":"\"Okay. As long as you were with friends, I suppose.\"","then":"Siddharth relaxes. \"Exactly. It was fine.\""}],"why":"Staying curious instead of scared helps you learn what really happened."},{"prompt":"Siddharth asks: \"So what happens now? Am I grounded forever?\"","options":[{"text":"\"No. But next time, call me for a lift, any hour. No lecture.\"","then":"Siddharth looks surprised. \"Any hour? Okay. Deal.\"","best":true},{"text":"\"Yes. No parties at all for you until you finish school.\"","then":"Siddharth goes quiet. \"Fine,\" he says, already planning around it."},{"text":"\"Nothing happens, as long as you never lie again.\"","then":"Siddharth nods. \"Okay.\" Nothing else about the party gets talked through."},{"text":"\"I'll call the host's parents before every party now.\"","then":"Siddharth groans. \"Great. Now everyone will know.\""}],"why":"A no-questions lift keeps him safe and gives him a reason to tell you the truth."}],"relearn":"Name a lie calmly and reassure your love is steady, so honesty stays possible."},
  {"id":"na-1114","cat":"respond-dont-rupture","type":"role-play","persona":"Priya","source":"slip not the end","hook":"Your daughter Zoya, 16, had stopped drinking for two months. Last night she drank at a wedding.","setup":"This morning she can't look at you over breakfast.","steps":[{"prompt":"Zoya says quietly: \"I've ruined everything, haven't I?\"","options":[{"text":"\"A slip isn't the end. I'm disappointed it happened, not in you.\"","then":"Zoya's eyes fill. \"I thought you'd be so angry.\"","best":true},{"text":"\"After everything? I should have known you'd never change.\"","then":"Zoya pushes her plate away. \"Then why even try?\""},{"text":"\"Don't worry about it. One drink at a wedding is nothing.\"","then":"Zoya looks up, unsure. \"But I promised myself I wouldn't.\""},{"text":"\"Let's not talk about it. Just start again today.\"","then":"Zoya nods. \"Okay,\" she says, but her shoulders stay hunched."}],"why":"Separating the slip from her keeps her willing to try again."},{"prompt":"Zoya asks: \"Do you think I'll ever really stop?\"","options":[{"text":"\"Honestly, I'm not sure anymore after this.\"","then":"Zoya flinches. \"I knew it,\" she says quietly."},{"text":"\"That's up to you now. I can't do this one for you.\"","then":"Zoya's shoulders sink. \"So I'm on my own.\""},{"text":"\"You will, if you promise me it never happens again.\"","then":"Zoya nods quickly. \"I promise,\" she says, sounding scared."},{"text":"\"Yes. Slips happen in recovery. I'm still with you.\"","then":"Zoya breathes out. \"Okay. I really want to keep going.\"","best":true}],"why":"Knowing slips are common, and that you're still with her, keeps hope alive."},{"prompt":"Zoya admits: \"Everyone kept handing me drinks. I didn't know how to say no.\"","options":[{"text":"\"Then no more weddings or functions for you this season.\"","then":"Zoya's face falls. \"So I get punished for being honest.\""},{"text":"\"You should have just been stronger than that.\"","then":"Zoya looks down. \"I know. I'm weak,\" she whispers."},{"text":"\"That's hard. Let's plan what you'll say next time.\"","then":"Zoya thinks. \"Maybe I just hold a juice the whole time.\"","best":true},{"text":"\"I'll tell all the relatives to stop offering you drinks.\"","then":"Zoya winces. \"Please don't. Then everyone will know.\""}],"why":"Planning for the next pressure together turns a slip into a lesson."}],"relearn":"Separate the slip from the child so a relapse doesn't end their willingness to try."},
  {"id":"na-1115","cat":"respond-dont-rupture","type":"role-play","persona":"Divya","source":"steady before speaking","hook":"You find a half-empty bottle of rum hidden in your son Nikhil's cupboard.","setup":"He walks in just as you're holding it.","steps":[{"prompt":"Nikhil blurts: \"Mumma, that's not what it looks like.\"","options":[{"text":"\"Don't you dare look at me like that after what you've done.\"","then":"Nikhil backs out of the room. \"Forget it,\" he mutters."},{"text":"\"Then what is it? Tell me right now!\"","then":"Nikhil stammers. \"It's my friend's. I was just keeping it.\""},{"text":"\"I need a minute to steady myself. Then I want to hear you.\"","then":"Nikhil stands still, waiting. \"Okay,\" he says quietly.","best":true},{"text":"\"It's okay. We don't need to make a big thing of it.\"","then":"Nikhil relaxes. \"Thanks,\" he says, and slips out before you say more."}],"why":"Naming your need to steady yourself stops worry turning into an outburst."},{"prompt":"Later Nikhil says: \"It's only a few sips on weekends. Everyone my age does it.\"","options":[{"text":"\"Everyone? You're still a child, and you're drinking!\"","then":"Nikhil rolls his eyes. \"See, this is why I hide stuff.\""},{"text":"\"Maybe. But I'm worried. How did it start?\"","then":"Nikhil shrugs. \"Some older boys in the building. It just happened.\"","best":true},{"text":"\"Okay. If it's only a few sips, I suppose it's fine.\"","then":"Nikhil nods quickly. \"Yeah. Totally fine.\""},{"text":"\"Let's not argue. I'll pour it away, and we move on.\"","then":"Nikhil watches you empty it. \"Okay,\" he says, and leaves."}],"why":"Staying curious about how it started shows you what's really going on."},{"prompt":"That night, Nikhil knocks on your door and asks: \"So what happens now?\"","options":[{"text":"\"We'll both sleep on it and make a plan together tomorrow.\"","then":"Nikhil nods. \"Okay. Tomorrow,\" he says, looking relieved.","best":true},{"text":"\"Now you lose your phone until I say otherwise.\"","then":"Nikhil's jaw sets. \"Great. Thanks for listening.\""},{"text":"\"Nothing. Let's forget this ever happened.\"","then":"Nikhil nods. \"Deal,\" he says, a little too quickly."},{"text":"\"I'll decide tonight, once I've thought it through alone.\"","then":"Nikhil shrugs. \"Whatever you decide,\" he says flatly."}],"why":"Making the plan once you're both calm keeps him part of it."}],"relearn":"Name your need to steady yourself, so worry leads to listening, not an outburst."},
  {"id":"na-1116","cat":"respond-dont-rupture","type":"role-play","persona":"Vikram","source":"promise calm","hook":"Your daughter Tara, 13, has seemed jumpy for weeks. Tonight she hovers by your chair.","setup":"The TV is on, but she isn't watching it.","steps":[{"prompt":"Tara asks: \"Papa, if I tell you something, will you be angry?\"","options":[{"text":"\"No. Whatever it is, I'd rather know and help. Tell me.\"","then":"Tara takes a breath. \"Okay,\" she says, and sits on the arm of your chair.","best":true},{"text":"\"That depends on what you've done, doesn't it.\"","then":"Tara steps back. \"Never mind. It's nothing.\""},{"text":"\"Why? What have you done now?\"","then":"Tara's face closes. \"Nothing. Forget it.\""},{"text":"\"Of course not. But first, is it something really bad?\"","then":"Tara hesitates. \"Maybe. I don't know. Forget it.\""}],"why":"A clear promise of calm makes it safe for her to speak."},{"prompt":"A little later, Tara says: \"I've been vaping at school. I can't stop now.\"","options":[{"text":"\"At thirteen? What kind of friends are you mixing with?\"","then":"Tara stiffens. \"My friends aren't the problem.\""},{"text":"\"You promised me you'd never do anything like this.\"","then":"Tara bursts into tears. \"I know. I'm sorry.\""},{"text":"\"Okay. Then just stop, starting from tomorrow morning.\"","then":"Tara nods, then whispers, \"I've tried that.\""},{"text":"\"Thank you for telling me. We'll figure this out together.\"","then":"Tara's shoulders drop. \"I thought you'd go crazy.\"","best":true}],"why":"Staying calm and thankful, right when it's hard, earns her trust."},{"prompt":"Tara asks: \"Are you going to tell the school?\"","options":[{"text":"\"Yes, tomorrow morning. They need to know about this.\"","then":"Tara panics. \"Then everyone will find out, Papa.\""},{"text":"\"No. We'll keep it inside the family, just between us.\"","then":"Tara nods, relieved. \"Good. Let's never talk about it again.\""},{"text":"\"Not behind your back. We'll see a counsellor together.\"","then":"Tara thinks. \"Okay. If you come with me.\"","best":true},{"text":"\"Only if a teacher catches you vaping at school again.\"","then":"Tara nods slowly. \"So I just have to not get caught.\""}],"why":"Getting help together, without going behind her back, keeps her trust."}],"relearn":"Promise calm so a frightened child feels safe enough to tell you the truth."},
  {"id":"na-1117","cat":"respond-dont-rupture","type":"role-play","persona":"Kamla","source":"reach the pain","hook":"Your son Ravi, 15, has been smoking with older boys in the lane.","setup":"Tonight you raise it as he eats his dinner.","steps":[{"prompt":"Ravi snaps: \"I only do it because home feels too hard. Okay?\"","options":[{"text":"\"After all I do for you? How ungrateful can you be.\"","then":"Ravi pushes his plate away. \"See? I can't say anything here.\""},{"text":"\"Home is hard for everyone here. That's no excuse for smoking.\"","then":"Ravi shrugs. \"Then there's nothing to talk about.\""},{"text":"\"That tells me something hurts. Help me understand what's hard.\"","then":"Ravi puts his spoon down. \"Everything. The money. The shouting. All of it.\"","best":true},{"text":"\"I know. I'm sorry. Let's just not talk about it.\"","then":"Ravi nods. \"Fine,\" he says, and eats the rest in silence."}],"why":"Hearing the pain behind the habit, instead of defending yourself, lets the real issue surface."},{"prompt":"Later that night, Ravi asks: \"Why should I stop when nothing here is going to change?\"","options":[{"text":"\"You're right. Nothing is going to change around here.\"","then":"Ravi nods grimly. \"So what's the point, then.\""},{"text":"\"Home isn't yours to fix, beta. I'm getting us help.\"","then":"Ravi looks up. \"What kind of help?\" he asks, listening now.","best":true},{"text":"\"Because smoking will ruin your whole future.\"","then":"Ravi rolls his eyes. \"Everyone says that.\""},{"text":"\"I'll make sure everything changes. I promise.\"","then":"Ravi looks away. \"You can't promise that, Amma.\""}],"why":"Telling him home isn't his to fix, and that you're getting support, lifts a weight off him."},{"prompt":"Ravi admits: \"When I feel stuck at home, smoking is the only thing that calms me.\"","options":[{"text":"\"Let's find you someone to talk to. We can call Tele-MANAS 14416.\"","then":"Ravi hesitates. \"Would you sit with me while I call?\"","best":true},{"text":"\"Just ignore it all and focus on your studies, beta.\"","then":"Ravi shrugs. \"I try. It doesn't help.\""},{"text":"\"Don't tell anyone outside the family how things are here.\"","then":"Ravi goes quiet. \"Fine. I won't,\" he says, and looks away."},{"text":"\"I'll try to keep things calmer at home so you don't need to.\"","then":"Ravi nods. \"Okay,\" he says, not sounding sure."}],"why":"Outside help supports him, and you, far better than carrying it alone."}],"relearn":"Hear the pain behind the habit instead of getting defensive, so the real issue can surface."},
  {"id":"na-1118","type":"reflect","persona":"any","source":"calm keeps safer","relearn":"A child sure of your calm comes to you; that's safer than one hiding from anger.","hook":"Lensy: a child braced for your anger hides; a child sure of your calm comes to you. Which keeps them safer?","prompt":"What do you think?","options":["Calm keeps them safer","They come to me","Sureness wins"],"affirm":"A child sure of your calm comes to you, and that's far safer than one hiding from your anger.","cat":"respond-dont-rupture"},
  {"id":"na-1119","type":"reflect","persona":"any","source":"firm and there","relearn":"You can hold a firm limit and be unconditionally there for your child at the same time.","hook":"Lensy: you can hold a firm limit and stay unconditionally there for your child at the same time. Sit right?","prompt":"What do you think?","options":["Sits right","Firm and there","Both at once"],"affirm":"Holding a firm limit and being unconditionally there for your child are not opposites; you can do both at once.","cat":"respond-dont-rupture"},
  {"id":"na-1120","type":"reflect","persona":"any","source":"keep the lifeline","relearn":"Connection is the lifeline; cutting it as punishment removes what keeps a child safe.","hook":"Lensy: connection is a child's lifeline; cutting it as punishment removes the very thing keeping them safe. Agree?","prompt":"What do you think?","options":["I agree","Keep the lifeline","Don't cut it"],"affirm":"Connection is a child's lifeline; cutting it as punishment removes the very thing that keeps them safe.","cat":"respond-dont-rupture"},
  {"id":"na-1121","type":"reflect","persona":"Priya","source":"lower the voice","relearn":"Lowering your voice instead of raising it lets your words land with a struggling child.","hook":"Lensy: when you lower your voice instead of raising it, a struggling child can finally hear you. Worth trying?","prompt":"What do you think?","options":["Worth trying","Lower the voice","Let it land"],"affirm":"Lowering your voice instead of raising it lets your words actually land with a struggling child.","cat":"respond-dont-rupture"},
  {"id":"na-1122","type":"reflect","persona":"any","source":"honesty grows with calm","relearn":"Honesty met with calm grows; honesty met with rage turns into silence.","hook":"Lensy: honesty met with calm becomes more honesty; honesty met with rage becomes silence. Which do you want?","prompt":"What do you think?","options":["More honesty","Meet it calm","Keep them talking"],"affirm":"Honesty met with calm grows into more honesty; honesty met with rage turns into silence.","cat":"respond-dont-rupture"},
  {"id":"na-1123","type":"reflect","persona":"Divya","source":"steady for them","relearn":"Tending your own calm is how you stay the steady adult a child can lean on.","hook":"Lensy: looking after your own calm isn't selfish, it's how you stay the steady adult your child can lean on. True?","prompt":"What do you think?","options":["True","Steady for them","Calm first"],"affirm":"Tending your own calm isn't selfish; it's how you stay the steady adult your child can lean on.","cat":"respond-dont-rupture"},
  {"id":"na-1124","type":"reflect","persona":"any","source":"slip not verdict","relearn":"A slip is information, not a verdict; a calm response keeps a child trying.","hook":"Lensy: a slip is information, not a verdict; how you respond decides whether they keep trying. Sit right?","prompt":"What do you think?","options":["Sits right","Keep them trying","Slip, not verdict"],"affirm":"A slip is information, not a verdict, and a calm response is what keeps a child willing to keep trying.","cat":"respond-dont-rupture"},
  {"id":"na-1125","type":"reflect","persona":"Vikram","source":"own it calmly","relearn":"Owning the response calmly beats handing down a punishment and walking away.","hook":"Lensy: owning the response yourself, calmly, beats handing your child a punishment and walking away. Agree?","prompt":"What do you think?","options":["I agree","Own it calmly","Stay in it"],"affirm":"Owning the response yourself, staying calm and present, beats handing down a punishment and walking away.","cat":"respond-dont-rupture"},
  {"id":"na-1126","type":"spot","persona":"any","source":"rupture vs reach","relearn":"Screaming threats and public humiliation rupture the connection; the calm, warm responses keep a child reachable.","hook":"Spot the two responses that would rupture the connection a struggling child needs.","scene":[{"id":"a","text":"Calm concern and an open door","trick":false},{"id":"b","text":"Screaming and threats to throw them out","trick":true},{"id":"c","text":"'We'll face this together'","trick":false},{"id":"d","text":"Humiliating them in front of relatives","trick":true},{"id":"e","text":"A steady, lowered voice","trick":false}],"why":"Screaming threats and public humiliation rupture the connection; the calm, warm responses keep a child reachable.","cat":"respond-dont-rupture"},
  {"id":"na-1127","type":"spot","persona":"any","source":"hide vs talk","relearn":"Secret snooping and punishing honesty both teach a child to hide; the calm, trusting moves keep them talking.","hook":"Spot the two reactions that teach a child to hide instead of talk.","scene":[{"id":"a","text":"Thanking them for being honest","trick":false},{"id":"b","text":"Secretly reading all their messages","trick":true},{"id":"c","text":"Promising calm, then keeping it","trick":false},{"id":"d","text":"Punishing them harder for telling the truth","trick":true},{"id":"e","text":"Sitting with them, no pressure","trick":false}],"why":"Secret snooping and punishing honesty both teach a child to hide; the calm, trusting moves keep them talking.","cat":"respond-dont-rupture"},
  {"id":"na-1128","type":"spot","persona":"any","source":"shame vs lift","relearn":"'You should be ashamed' and 'you're a disgrace' shame a child and deepen dependence; the others lift it.","hook":"Spot the two lines that would shame a struggling child.","scene":[{"id":"a","text":"'I'm worried about you'","trick":false},{"id":"b","text":"'You should be ashamed of yourself'","trick":true},{"id":"c","text":"'This is a health thing we'll treat'","trick":false},{"id":"d","text":"'You're a disgrace to this family'","trick":true},{"id":"e","text":"'I'm right here with you'","trick":false}],"why":"'You should be ashamed' and 'you're a disgrace' shame a child and deepen dependence; the others lift it.","cat":"respond-dont-rupture"},
  {"id":"na-1129","type":"spot","persona":"Vikram","source":"limit vs rupture","relearn":"A raging confiscation and an abandonment threat rupture the bond; the calm, shared moves hold both rule and relationship.","hook":"Spot the two moves that turn a limit into a rupture.","scene":[{"id":"a","text":"Explaining why the limit matters","trick":false},{"id":"b","text":"Snatching the device in a rage","trick":true},{"id":"c","text":"Setting the rule together","trick":false},{"id":"d","text":"Adding a threat to abandon them","trick":true},{"id":"e","text":"Staying warm while holding the rule","trick":false}],"why":"A raging confiscation and an abandonment threat rupture the bond; the calm, shared moves hold both rule and relationship.","cat":"respond-dont-rupture"},
  {"id":"na-1130","type":"spot","persona":"any","source":"give-up vs keep-trying","relearn":"'You'll never change' and 'I'm done with you' make a relapsing child give up; the others keep them trying.","hook":"Spot the two reactions that would push a relapsing child to give up.","scene":[{"id":"a","text":"'A slip isn't the end'","trick":false},{"id":"b","text":"'You've proven you'll never change'","trick":true},{"id":"c","text":"'Let's keep going together'","trick":false},{"id":"d","text":"'I'm done trying with you'","trick":true},{"id":"e","text":"'I'm disappointed in the slip, not in you'","trick":false}],"why":"'You'll never change' and 'I'm done with you' make a relapsing child give up; the others keep them trying.","cat":"respond-dont-rupture"},
  {"id":"na-1131","type":"spot","persona":"Priya","source":"panic vs calm","relearn":"Exploding on discovery and a furious ultimatum are panic responses; the calm, paced ones keep a child reachable.","hook":"Spot the two responses driven by panic rather than calm care.","scene":[{"id":"a","text":"Taking a breath before speaking","trick":false},{"id":"b","text":"Exploding the moment you find out","trick":true},{"id":"c","text":"Naming your worry steadily","trick":false},{"id":"d","text":"Issuing a furious ultimatum on the spot","trick":true},{"id":"e","text":"Stepping away to steady yourself first","trick":false}],"why":"Exploding on discovery and a furious ultimatum are panic responses; the calm, paced ones keep a child reachable.","cat":"respond-dont-rupture"},
  {"id":"na-1132","type":"spot","persona":"any","source":"cut vs keep connection","relearn":"The silent treatment and 'you're dead to me' cut the connection that keeps a child safe; the others protect it.","hook":"Spot the two reactions that cut off the connection keeping a child safe.","scene":[{"id":"a","text":"Staying present even when it's hard","trick":false},{"id":"b","text":"Giving the silent treatment for days","trick":true},{"id":"c","text":"'I'm not going anywhere'","trick":false},{"id":"d","text":"'You're dead to me now'","trick":true},{"id":"e","text":"Holding the bond while holding a limit","trick":false}],"why":"The silent treatment and 'you're dead to me' cut the connection that keeps a child safe; the others protect it.","cat":"respond-dont-rupture"},
  {"id":"na-1133","type":"sort","persona":"any","source":"open or slam","relearn":"'On your side', calm curiosity and togetherness keep the door open; 'dead to me', screaming and public shame slam it shut.","hook":"Sort each response: keeps the door open, or slams it shut?","items":[{"id":"a","text":"'Let's talk, I'm on your side'"},{"id":"b","text":"'You're dead to me'"},{"id":"c","text":"Staying calm and curious"},{"id":"d","text":"Screaming and threats"},{"id":"e","text":"'We'll face this together'"},{"id":"f","text":"Humiliating them publicly"}],"bins":[{"id":"open","label":"Keeps it open","valence":"pos"},{"id":"slam","label":"Slams it shut","valence":"neg"}],"key":{"a":"open","b":"slam","c":"open","d":"slam","e":"open","f":"slam"},"cat":"respond-dont-rupture"},
  {"id":"na-1134","type":"sort","persona":"any","source":"calm or rupture","relearn":"Low voice, warm limits and 'I'm worried, not angry' are calm connection; threats, secret snooping and shaming rupture.","hook":"Sort each move: calm connection, or rupture?","items":[{"id":"a","text":"Lowering your voice"},{"id":"b","text":"Threatening to throw them out"},{"id":"c","text":"Naming a limit warmly"},{"id":"d","text":"Reading their phone in secret"},{"id":"e","text":"'I'm worried, not angry'"},{"id":"f","text":"Shaming them into silence"}],"bins":[{"id":"calm","label":"Calm connection","valence":"pos"},{"id":"rupture","label":"Rupture","valence":"neg"}],"key":{"a":"calm","b":"rupture","c":"calm","d":"rupture","e":"calm","f":"rupture"},"cat":"respond-dont-rupture"},
  {"id":"na-1135","type":"sort","persona":"any","source":"honest or hide","relearn":"Thanks, kept calm and 'you can be honest' keep a child truthful; punishing honesty, snooping and exploding teach hiding.","hook":"Sort each reaction: keeps a child honest, or teaches them to hide?","items":[{"id":"a","text":"Thanking them for telling you"},{"id":"b","text":"Punishing harder for honesty"},{"id":"c","text":"Promising calm and keeping it"},{"id":"d","text":"Secret surveillance"},{"id":"e","text":"'You can be honest with me'"},{"id":"f","text":"Exploding when they admit it"}],"bins":[{"id":"honest","label":"Keeps them honest","valence":"pos"},{"id":"hide","label":"Teaches hiding","valence":"neg"}],"key":{"a":"honest","b":"hide","c":"honest","d":"hide","e":"honest","f":"hide"},"cat":"respond-dont-rupture"},
  {"id":"na-1136","type":"sort","persona":"Vikram","source":"trying or give up","relearn":"'A slip isn't the end' and steady support keep a child trying; 'you'll never change' and writing them off make them give up.","hook":"Sort each response to a relapse: keeps them trying, or makes them give up?","items":[{"id":"a","text":"'A slip isn't the end'"},{"id":"b","text":"'You'll never change'"},{"id":"c","text":"Disappointment without rejection"},{"id":"d","text":"'I'm done with you'"},{"id":"e","text":"'Let's keep going together'"},{"id":"f","text":"Writing them off completely"}],"bins":[{"id":"trying","label":"Keeps them trying","valence":"pos"},{"id":"giveup","label":"Makes them give up","valence":"neg"}],"key":{"a":"trying","b":"giveup","c":"trying","d":"giveup","e":"trying","f":"giveup"},"cat":"respond-dont-rupture"},
  {"id":"na-1137","type":"sort","persona":"any","source":"steady or panic","relearn":"Breathing first, cooling down and returning calm are steady; exploding, ultimatums and shouting on discovery are panic.","hook":"Sort each reaction: calm and steady, or panic-driven?","items":[{"id":"a","text":"Taking a breath first"},{"id":"b","text":"Exploding on the spot"},{"id":"c","text":"Stepping away to cool down"},{"id":"d","text":"A furious ultimatum"},{"id":"e","text":"Coming back when you're calm"},{"id":"f","text":"Shouting the moment you find out"}],"bins":[{"id":"steady","label":"Calm and steady","valence":"pos"},{"id":"panic","label":"Panic-driven","valence":"neg"}],"key":{"a":"steady","b":"panic","c":"steady","d":"panic","e":"steady","f":"panic"},"cat":"respond-dont-rupture"},
  {"id":"na-1138","type":"sort","persona":"Priya","source":"connect or control","relearn":"Asking openly and 'you can come to me' build connection; secret tracking and reading messages are control that erodes trust.","hook":"Sort each line: connection, or control-and-surveillance?","items":[{"id":"a","text":"'How are you really doing?'"},{"id":"b","text":"Tracking their phone secretly"},{"id":"c","text":"'You can come to me'"},{"id":"d","text":"Reading their messages"},{"id":"e","text":"Asking them openly and directly"},{"id":"f","text":"Following them without telling them"}],"bins":[{"id":"connect","label":"Connection","valence":"pos"},{"id":"control","label":"Control & surveillance","valence":"neg"}],"key":{"a":"connect","b":"control","c":"connect","d":"control","e":"connect","f":"control"},"cat":"respond-dont-rupture"},
  {"id":"na-1139","type":"sort","persona":"any","source":"both or sacrifice","relearn":"Warm explained limits and firm-but-open rules hold both limit and bond; cold ultimatums, caving and cutting off sacrifice one.","hook":"Sort each response: holds limit and bond, or sacrifices one?","items":[{"id":"a","text":"Warm limit, explained"},{"id":"b","text":"A cold, rejecting ultimatum"},{"id":"c","text":"Firm rule, open door"},{"id":"d","text":"Caving with no limit at all"},{"id":"e","text":"Staying connected while firm"},{"id":"f","text":"Cutting them off entirely"}],"bins":[{"id":"both","label":"Holds limit and bond","valence":"pos"},{"id":"sacrifice","label":"Sacrifices one","valence":"neg"}],"key":{"a":"both","b":"sacrifice","c":"both","d":"sacrifice","e":"both","f":"sacrifice"},"cat":"respond-dont-rupture"},
  {"id":"na-1170","cat":"screens-and-modelling","type":"strike-rewrite","persona":"Vikram","source":"phone at the table","hook":"\"Me scrolling at dinner has nothing to do with my son's gaming.\"","myth":{"un":"Me scrolling at dinner has nothing to do with my son's gaming.","re":"Children read what we model; a parent glued to a phone at meals quietly teaches that screens come before people.","why":"Kids copy the habits they see at home."},"relearn":"Your own screen habits are part of the picture; children learn balance largely by watching you."},
  {"id":"na-1171","cat":"screens-and-modelling","type":"strike-rewrite","persona":"Vikram","source":"set with not for","hook":"\"Good screen rules are the ones I impose; the child just obeys.\"","myth":{"un":"Good screen rules are the ones I impose; the child just obeys.","re":"Limits agreed with the child, that the whole family keeps, stick far better than rules handed down and policed.","why":"Shared rules get buy-in; imposed ones invite hiding."},"relearn":"Agree screen limits with your child and keep them yourself too; unilateral crackdowns rarely hold."},
  {"id":"na-1172","cat":"screens-and-modelling","type":"strike-rewrite","persona":"Kamla","source":"one rule for all","hook":"\"One rule for the kids, another for me. That's just being the parent.\"","myth":{"un":"One rule for the kids, another for me. That's just being the parent.","re":"One rule for the child and another for the parent reads as unfair and tells the child the limit isn't real.","why":"Children trust limits the adults keep too."},"relearn":"A limit the parent keeps too has integrity; do-as-I-say-not-as-I-do quietly undoes the rule."},
  {"id":"na-1173","cat":"screens-and-modelling","type":"strike-rewrite","persona":"Divya","source":"outlets matter","hook":"\"Helping with screens just means taking the phone away.\"","myth":{"un":"Helping with screens just means taking the phone away.","re":"Removing screens leaves a gap; offering real outlets, like sport, friends, or hobbies, is the other half of helping.","why":"A void pulls a child back to the habit."},"relearn":"Offer appealing offline things alongside any limit; just removing the screen leaves a void."},
  {"id":"na-1174","cat":"screens-and-modelling","type":"strike-rewrite","persona":"Kamla","source":"tend your own","hook":"\"Sorting out my own drinking can wait till my child is fixed.\"","myth":{"un":"Sorting out my own drinking can wait till my child is fixed.","re":"Honestly tending your own habit is part of helping the child: modelling change matters more than any lecture.","why":"What you do speaks louder than what you say."},"relearn":"Tend your own substance and screen habits too; it is part of helping the child, not separate from it."},
  {"id":"na-1175","cat":"screens-and-modelling","type":"strike-rewrite","persona":"Priya","source":"night phones","hook":"\"There's no harm in everyone keeping their phone in bed at night.\"","myth":{"un":"There's no harm in everyone keeping their phone in bed at night.","re":"A no-devices-at-night rule the whole family keeps protects sleep: the thing screen habits erode first.","why":"Late screens steal the sleep growing kids need."},"relearn":"Devices out of bedrooms at night is a healthy boundary; it protects the sleep screens disrupt first."},
  {"id":"na-1176","cat":"screens-and-modelling","type":"strike-rewrite","persona":"Vikram","source":"slip-ups model honesty","hook":"\"I should hide my own slip-ups so the kids never see me fail.\"","myth":{"un":"I should hide my own slip-ups so the kids never see me fail.","re":"Owning a slip-up calmly shows a child that habits can be repaired. That's a more useful lesson than looking perfect.","why":"Honesty about habits is itself the model."},"relearn":"Owning your own slip-ups honestly models repair and growth; hiding them models only secrecy."},
  {"id":"na-1177","cat":"screens-and-modelling","type":"strike-rewrite","persona":"Divya","source":"screens are real","hook":"\"Phone and gaming 'addiction' isn't real. It's just a harmless phase.\"","myth":{"un":"Phone and gaming 'addiction' isn't real. It's just a harmless phase.","re":"Screen and gaming dependence is real and can genuinely disrupt sleep, mood and school; it counts, like substances do.","why":"Gaming disorder is a recognised condition."},"relearn":"Don't dismiss screens as 'just a phase'; gaming and phone dependence are real and disrupt a child's life."},
  {"id":"na-1178","cat":"screens-and-modelling","type":"sort","persona":"any","source":"healthy or backfires","hook":"Sort: a screen boundary that's healthy, or one that backfires?","items":[{"id":"a","text":"Screen-free times agreed with the kids"},{"id":"b","text":"A sudden, angry, total ban"},{"id":"c","text":"No devices in bedrooms at night"},{"id":"d","text":"Rules for the child, none for the parent"},{"id":"e","text":"A short screen-free hour before bed"},{"id":"f","text":"Confiscating the phone whenever you feel like it"}],"bins":[{"id":"healthy","label":"Healthy","valence":"pos"},{"id":"backfire","label":"Backfires","valence":"neg"}],"key":{"a":"healthy","b":"backfire","c":"healthy","d":"backfire","e":"healthy","f":"backfire"},"relearn":"Agreed screen-free times and no devices at night are healthy; angry total bans and one-rule-for-the-child backfire."},
  {"id":"na-1179","cat":"screens-and-modelling","type":"sort","persona":"Kamla","source":"models which","hook":"Sort: models a healthy habit, or models the opposite?","items":[{"id":"a","text":"Unwinding with a walk, not a drink"},{"id":"b","text":"A drink every evening to relax"},{"id":"c","text":"Phone away during family time"},{"id":"d","text":"Doom-scrolling on the sofa for hours"},{"id":"e","text":"Talking about a hard day out loud"},{"id":"f","text":"Smoking on the balcony to cope"}],"bins":[{"id":"healthy","label":"Models healthy","valence":"pos"},{"id":"opposite","label":"Models the opposite","valence":"neg"}],"key":{"a":"healthy","b":"opposite","c":"healthy","d":"opposite","e":"healthy","f":"opposite"},"relearn":"Coping without substances and phone-free family time model healthy habits; nightly drinking and doom-scrolling model the opposite."},
  {"id":"na-1180","cat":"screens-and-modelling","type":"sort","persona":"any","source":"model or undermine","hook":"Sort: a parent's own screen habit that models balance, or one that undermines your rules?","items":[{"id":"a","text":"Phone left in another room overnight"},{"id":"b","text":"Scrolling at the dinner table yourself"},{"id":"c","text":"Saying out loud when you put your phone away"},{"id":"d","text":"Checking work email all weekend"},{"id":"e","text":"Same screen-off time for everyone"},{"id":"f","text":"Doom-scrolling in bed at night"}],"bins":[{"id":"models","label":"Models balance","valence":"pos"},{"id":"undermines","label":"Undermines the rules","valence":"neg"}],"key":{"a":"models","b":"undermines","c":"models","d":"undermines","e":"models","f":"undermines"},"relearn":"Kids copy what you do, not what you say: your own table-scrolling and late-night use undermine the rules you set."},
  {"id":"na-1181","cat":"screens-and-modelling","type":"sort","persona":"any","source":"agreed or imposed","hook":"Sort: part of making a family screen plan together, or imposing it?","items":[{"id":"a","text":"Asking the kids what feels fair"},{"id":"b","text":"Announcing the rules with no discussion"},{"id":"c","text":"Limits that apply to parents too"},{"id":"d","text":"Threatening to seize phones on a whim"},{"id":"e","text":"Reviewing the plan together later"},{"id":"f","text":"Changing the rules when you're angry"}],"bins":[{"id":"together","label":"Made together","valence":"pos"},{"id":"imposed","label":"Imposed","valence":"neg"}],"key":{"a":"together","b":"imposed","c":"together","d":"imposed","e":"together","f":"imposed"},"relearn":"A plan made together (asking what's fair, limits for parents too, reviewing it) beats rules announced, threatened and changed in anger."},
  {"id":"na-1182","cat":"screens-and-modelling","type":"sort","persona":"Divya","source":"outlet or numbing","hook":"Sort: a healthy outlet for stress, or numbing it?","items":[{"id":"a","text":"Calling a friend after a hard day"},{"id":"b","text":"Scrolling till 2am to switch off"},{"id":"c","text":"A walk or a bit of sport"},{"id":"d","text":"A drink to take the edge off"},{"id":"e","text":"Naming the feeling out loud"},{"id":"f","text":"Gaming for hours to avoid it"}],"bins":[{"id":"outlet","label":"Healthy outlet","valence":"pos"},{"id":"numb","label":"Numbing","valence":"neg"}],"key":{"a":"outlet","b":"numb","c":"outlet","d":"numb","e":"outlet","f":"numb"},"relearn":"Friends, movement and naming feelings are healthy outlets; late scrolling, a drink or hours of gaming numb the stress instead."},
  {"id":"na-1183","cat":"screens-and-modelling","type":"sort","persona":"Priya","source":"connection or screens","hook":"Sort: a small habit that builds connection, or that lets screens win?","items":[{"id":"a","text":"Phones in a basket at dinner"},{"id":"b","text":"Everyone on their own screen at meals"},{"id":"c","text":"A device-free bedtime routine"},{"id":"d","text":"A TV on through every conversation"},{"id":"e","text":"A daily walk or chat together"},{"id":"f","text":"Replying to messages mid-conversation"}],"bins":[{"id":"connect","label":"Builds connection","valence":"pos"},{"id":"screens","label":"Lets screens win","valence":"neg"}],"key":{"a":"connect","b":"screens","c":"connect","d":"screens","e":"connect","f":"screens"},"relearn":"Phones away at meals, a device-free bedtime and time together build connection; screens at meals and mid-chat replies let screens win."},
  {"id":"na-1184","cat":"screens-and-modelling","type":"sort","persona":"Kamla","source":"own habit honestly","hook":"Sort: tending your own habit honestly, or hiding it?","items":[{"id":"a","text":"Saying 'I'm cutting down too'"},{"id":"b","text":"Drinking once the kids are asleep"},{"id":"c","text":"Keeping the same screen limits yourself"},{"id":"d","text":"Hiding the bottles from the family"},{"id":"e","text":"Asking for help with your own habit"},{"id":"f","text":"Pretending you don't have one"}],"bins":[{"id":"honest","label":"Tending it honestly","valence":"pos"},{"id":"hiding","label":"Hiding it","valence":"neg"}],"key":{"a":"honest","b":"hiding","c":"honest","d":"hiding","e":"honest","f":"hiding"},"relearn":"Saying you're cutting down, keeping the same limits and seeking help tend a habit honestly; drinking in secret and hiding it don't."},
  {"id":"na-1185","cat":"screens-and-modelling","type":"sort","persona":"any","source":"morning or night phone","hook":"Sort: a phone habit that protects sleep, or that wrecks it?","items":[{"id":"a","text":"Charging phones outside the bedroom"},{"id":"b","text":"Scrolling in bed until you drop off"},{"id":"c","text":"A wind-down hour with no screens"},{"id":"d","text":"Checking notifications at 1am"},{"id":"e","text":"An alarm clock instead of the phone"},{"id":"f","text":"Gaming late into the night"}],"bins":[{"id":"protect","label":"Protects sleep","valence":"pos"},{"id":"wreck","label":"Wrecks sleep","valence":"neg"}],"key":{"a":"protect","b":"wreck","c":"protect","d":"wreck","e":"protect","f":"wreck"},"relearn":"Charging phones outside the room, a screen-free wind-down and a real alarm clock protect sleep; late scrolling, 1am checks and night gaming wreck it."},
  {"id":"na-1186","cat":"screens-and-modelling","type":"sort","persona":"any","source":"replace or just remove","hook":"Sort: crowding the habit out with better things, or just leaving a gap?","items":[{"id":"a","text":"Signing up for a sport together"},{"id":"b","text":"Taking the console and saying nothing"},{"id":"c","text":"Planning weekend outings"},{"id":"d","text":"Banning games with no alternative"},{"id":"e","text":"Inviting friends over to play"},{"id":"f","text":"Leaving long, empty, dull evenings"}],"bins":[{"id":"replace","label":"Crowds it out","valence":"pos"},{"id":"gap","label":"Just a gap","valence":"neg"}],"key":{"a":"replace","b":"gap","c":"replace","d":"gap","e":"replace","f":"gap"},"relearn":"Sport, outings and friends crowd a habit out with better things; taking the device and leaving empty time just creates a gap that pulls back."},
  {"id":"na-1187","cat":"screens-and-modelling","type":"sort","persona":"Vikram","source":"firm and warm or harsh","hook":"Sort: firm-and-warm about screens, or just harsh?","items":[{"id":"a","text":"'The limit holds, and I'm on your side'"},{"id":"b","text":"'Give it here, you're hopeless'"},{"id":"c","text":"Sitting with them while they switch off"},{"id":"d","text":"Mocking them for being 'addicted'"},{"id":"e","text":"Explaining the why calmly, once"},{"id":"f","text":"Shouting and grabbing the device"}],"bins":[{"id":"firmwarm","label":"Firm and warm","valence":"pos"},{"id":"harsh","label":"Just harsh","valence":"neg"}],"key":{"a":"firmwarm","b":"harsh","c":"firmwarm","d":"harsh","e":"firmwarm","f":"harsh"},"relearn":"You can hold the limit and stay on the child's side; shaming, mocking 'addiction' and grabbing the device are harsh and push the child away."},
  {"id":"na-1188","cat":"screens-and-modelling","type":"sort","persona":"any","source":"self-care or self-blame","hook":"Sort: looking at your own habits with care, or with self-blame?","items":[{"id":"a","text":"'I can build a healthier habit'"},{"id":"b","text":"'I've ruined my kids already'"},{"id":"c","text":"Asking for support, no shame"},{"id":"d","text":"'I'm a terrible parent'"},{"id":"e","text":"Trying one small change this week"},{"id":"f","text":"Giving up because it's too late"}],"bins":[{"id":"care","label":"With care","valence":"pos"},{"id":"blame","label":"Self-blame","valence":"neg"}],"key":{"a":"care","b":"blame","c":"care","d":"blame","e":"care","f":"blame"},"relearn":"Looking at your habits with care, like one small change or asking for support, helps; self-blame and 'it's too late' just stall you."},
  {"id":"na-1189","cat":"screens-and-modelling","type":"branch","persona":"Vikram","source":"caught scrolling","hook":"At dinner you told your daughter Myra, 12, to put her phone away. Now she catches you checking cricket scores.","steps":[{"prompt":"Myra raises an eyebrow and points at your phone. What do you do?","options":[{"text":"Say \"fair point\" and put yours away too","then":"Myra grins, satisfied, and dinner carries on with both phones down.","best":true},{"text":"Snap that the rules are for her, not for you","then":"Myra goes quiet, but her phone slides back onto her lap."},{"text":"Slip your phone into your pocket and say nothing","then":"Myra rolls her eyes. The double standard hangs in the air."},{"text":"Explain you're checking something important for work","then":"Myra shrugs. \"Mine's important too,\" she says, reaching for it."}],"why":"Owning the slip gives the rule integrity and shows her how to take feedback."},{"prompt":"The next evening you want to make the dinner rule clear for everyone. How do you do it?","options":[{"text":"Tell Myra her phone goes in a drawer, while yours stays out for calls","then":"Myra points out the unfairness, and the drawer stays empty."},{"text":"Leave it unspoken and hope she follows your lead","then":"Some nights work and others don't, and no one is sure what the rule is."},{"text":"Fine Myra ten rupees each time she breaks it","then":"Myra pays twice, then starts eating in her room with her phone."},{"text":"Suggest a phone basket by the door that you use too","then":"Myra adds a sign to the basket that says Papa included.","best":true}],"why":"A clear rule that everyone keeps, you included, is one she can trust."},{"prompt":"A week later a work call buzzes during dinner. What do you do?","options":[{"text":"Take the call at the table and wave for everyone to be quiet","then":"Myra watches, then quietly takes out her own phone."},{"text":"Ignore it, but check your messages under the table","then":"Myra spots the glow and raises an eyebrow again."},{"text":"Say it's urgent, step away briefly, then come back","then":"Myra nods. You're back in two minutes, and the phone stays away till dinner ends.","best":true},{"text":"Scrap the rule, since work makes it impossible","then":"Within a week, phones creep back to the table."}],"why":"Naming a real exception openly keeps the rule honest instead of breaking it quietly."},{"prompt":"One night Myra asks why you wanted phones off at dinner in the first place. What do you say?","options":[{"text":"Say that's simply how things work in this house","then":"Myra shrugs. The rule feels like an order, not something you share."},{"text":"Say you want dinner to be real talking time, for you too","then":"Myra thinks, then tells you about a fight with her best friend.","best":true},{"text":"Say screens are rotting her brain","then":"Myra laughs it off and says her friends' parents don't think so."},{"text":"Say her class teacher recommended it at the parents' meeting","then":"Myra nods, unconvinced, and the rule feels like someone else's."}],"why":"Sharing your honest reason makes the limit feel shared, not imposed."}],"debrief":"Own the slip and keep the same limit yourself; one rule for the child teaches the limit isn't real.","relearn":"Model the limits you set; owning a slip gives the rule integrity."},
  {"id":"na-1190","cat":"screens-and-modelling","type":"branch","persona":"Priya","source":"plan together","hook":"You want family screen limits, but rules that are simply announced never last in your house.","steps":[{"prompt":"Your children, Aditi and Kunal, are glued to screens again this weekend. What do you do?","options":[{"text":"Announce strict new rules, with no discussion this time","then":"Both children say it's unfair and start working around it by Monday."},{"text":"Call a family meeting to make a screen plan together","then":"Aditi groans, but Kunal is curious. Everyone agrees to Sunday evening.","best":true},{"text":"Leave it, since rules never work here anyway","then":"Screen time creeps up, and the weekend disappears into phones."},{"text":"Write the rules yourself and ask them to sign","then":"They sign without reading, and nothing really changes."}],"why":"Plans everyone shapes get buy-in, while imposed ones get worked around."},{"prompt":"On Sunday evening, screens come up while the family is together. Where do you start?","options":[{"text":"Ask everyone, you included, what bothers them about screens","then":"Kunal says you're always on your laptop. Aditi agrees, laughing.","best":true},{"text":"Hand out a list of your rules and ask for questions","then":"The children read in silence and have no questions."},{"text":"List all the harm that screens do to children","then":"Aditi zones out halfway, and Kunal starts fidgeting."},{"text":"Ask the children what limits they'll accept, leaving yours out","then":"They suggest a few limits, then ask what yours will be."}],"why":"Starting with everyone's view, yours included, makes it a family plan."},{"prompt":"Kunal says the parents should follow the plan too. What do you do?","options":[{"text":"Say parents need phones for work, so it's different","then":"Kunal folds his arms and says it isn't a family plan, then."},{"text":"Agree, but plan to keep checking your phone quietly","then":"Two days later Kunal catches you, and the plan starts to wobble."},{"text":"Tell Kunal not to be cheeky with his elders","then":"Kunal goes quiet, and Aditi rolls her eyes."},{"text":"Agree, and add your own limits to the plan","then":"Kunal looks surprised, then suggests a phone-free hour after dinner for all.","best":true}],"why":"Including yourself makes the limits fair, so the children are more likely to keep them."},{"prompt":"Aditi wants weekends with no limits at all. What do you do?","options":[{"text":"Refuse flatly, since the plan is the plan","then":"Aditi shrugs and says she'll just use a friend's phone."},{"text":"Agree to no weekend limits at all, just to keep the peace","then":"The weekends swallow the plan, and Mondays are a struggle."},{"text":"Ask what she'd do with the time, and look for a middle ground","then":"Aditi suggests longer screen time on Saturday but none after nine.","best":true},{"text":"Say you'll think about it and decide later on your own","then":"Aditi feels brushed off, and her interest in the plan fades."}],"why":"Negotiating fairly keeps her invested in a plan she helped to shape."},{"prompt":"A month later the plan is slipping for everyone. What do you do?","options":[{"text":"Add punishments for anyone who breaks it","then":"The children start hiding their screen time instead of talking about it."},{"text":"Call another family meeting to adjust it together","then":"Everyone admits what's hard, and you agree on two small changes.","best":true},{"text":"Stick the plan back on the fridge as a reminder","then":"The children glance at it and walk past."},{"text":"Blame the children for not taking it seriously","then":"Kunal points out that you've slipped too, and the talk turns sour."}],"why":"Revisiting the plan together keeps it alive and fair for everyone."}],"debrief":"Make the plan with the child, parents included; agreed limits stick where imposed ones slide.","relearn":"A family plan everyone shapes, parents too, beats rules announced from above."},
  {"id":"na-1191","cat":"screens-and-modelling","type":"branch","persona":"Divya","source":"fill the gap","hook":"You want your son Dev to game less. He says there's nothing else to do around here.","steps":[{"prompt":"Dev is back on his console the moment he gets home. What do you do?","options":[{"text":"Take the console away until further notice","then":"Dev sulks in his room, bored, then gets on his phone instead."},{"text":"Let it go, since there really isn't much else here","then":"Evenings fill up with gaming, and it grows each week."},{"text":"Tell him to go outside and find something to do","then":"Dev walks round the block once and comes back to the console."},{"text":"Ask what he used to enjoy before gaming took over","then":"Dev thinks, then says he loved football before his friends moved away.","best":true}],"why":"Starting from what he enjoys helps you find things that can compete with gaming."},{"prompt":"At the weekend Dev says he misses football, but there's no one nearby to play with. What do you do?","options":[{"text":"Say that's his problem to solve, not yours","then":"Dev shrugs and goes back to gaming."},{"text":"Buy him a new football and leave it at that","then":"The ball sits in the corner, and Dev is still gaming."},{"text":"Look together for a local club he could join","then":"Dev finds a Saturday group two streets away and agrees to try it.","best":true},{"text":"Let him game as long as he walks for an hour first","then":"Dev walks with his phone in hand, then games late into the night."}],"why":"Helping him find real options fills the gap the console was filling."},{"prompt":"A few weeks later, Dev asks how much gaming he's allowed on weeknights. What do you do?","options":[{"text":"Say none at all, not on any school night this term","then":"Dev looks crushed and starts gaming at a friend's house."},{"text":"Agree a daily limit together, with time for other things","then":"Dev suggests an hour after homework, and you shake on it.","best":true},{"text":"Say as much as he wants, if his marks stay up","then":"His marks hold for a while, but his sleep slips."},{"text":"Set the limit on your own and tell him about it later","then":"Dev hears the rule second-hand and grumbles about it."}],"why":"A limit he helps to set, next to real outlets, is one he can keep."}],"debrief":"Pair any limit with appealing offline things; removing the device alone leaves a void that pulls back.","relearn":"Fill the gap with better things when you cut screen time; a void just pulls a child back."},
  {"id":"na-1192","cat":"screens-and-modelling","type":"branch","persona":"Kamla","source":"own drinking first","hook":"You worry about your son Raju's smoking. Your own evening drink has become a nightly habit too.","steps":[{"prompt":"Raju says you drink every night, so he doesn't see why he can't smoke. What do you do?","options":[{"text":"Say that's different, because you're an adult and he isn't","then":"Raju scoffs, asks how it's different, and walks out."},{"text":"Admit it's fair and say you'll look at your drinking too","then":"Raju blinks, surprised. \"Really?\" he asks, less defensive.","best":true},{"text":"Drink only after he's asleep from now on","then":"The bottle moves to the back of the cupboard, but Raju still notices."},{"text":"Say you'll talk about your own drinking once he has quit","then":"Raju shrugs. \"Then we'll both wait,\" he says."}],"why":"Owning your side makes your worry about his habit believable."},{"prompt":"That night you feel guilty about your own drinking. What do you do?","options":[{"text":"Treat it kindly, as a habit you can work on","then":"The guilt softens into a plan: no drink on weeknights to start.","best":true},{"text":"Crack down on Raju harder to make up for it","then":"Raju feels picked on and starts smoking away from home."},{"text":"Tell yourself one drink is nothing and move on","then":"The nightly drink continues, and so do Raju's cigarettes."},{"text":"Keep the guilt to yourself and tell no one","then":"The guilt grows quietly, and nothing changes for either of you."}],"why":"Compassion for yourself makes change possible, while guilt alone keeps things stuck."},{"prompt":"A week later Raju asks, a little shyly, whether you've changed anything. What do you do?","options":[{"text":"Say you've stopped completely, even though you haven't","then":"Raju spots a glass in the sink the next morning and goes quiet."},{"text":"Say that grown-ups' habits aren't his business","then":"Raju shrugs, and the talk about smoking goes cold."},{"text":"Turn the talk back to his smoking instead","then":"Raju sighs. \"It's always about me,\" he mutters."},{"text":"Tell him honestly how it's going, even the hard parts","then":"Raju admits he's been trying to cut down too, and it's harder than he thought.","best":true}],"why":"Being honest about your own progress, however it's going, shows him change is real work."},{"prompt":"Raju says he wants to quit but can't manage it alone. What do you do?","options":[{"text":"Tell him he just has to try harder, like you are","then":"Raju looks deflated. \"I am trying,\" he says."},{"text":"Keep it within the family and handle it yourselves","then":"Weeks pass, and neither of you gets the help you need."},{"text":"Suggest calling Tele-MANAS 14416 together, for both of you","then":"Raju nods. \"Only if you talk to them too,\" he says, half smiling.","best":true},{"text":"Say you'll look into help once your drinking is sorted","then":"Raju waits, and his cigarettes keep going."}],"why":"Getting help together shows him that asking for support is a strength."}],"debrief":"Tend your own habit alongside his, with compassion; what you model carries further than what you say.","relearn":"Address your own habit too, kindly; ignoring it undercuts policing the child's."},
  {"id":"na-1193","cat":"screens-and-modelling","type":"branch","persona":"Priya","source":"night phone limit","hook":"Your daughter Saanvi, 14, wants her phone in her room at night like her friends. Her sleep is already suffering.","steps":[{"prompt":"She asks again at bedtime, phone in hand. What do you do?","options":[{"text":"Let her keep it, since one night won't hurt","then":"She scrolls past midnight and drags herself to school."},{"text":"Take her phone away for a week, angrily","then":"Saanvi feels singled out and starts hiding an old phone."},{"text":"Say no tonight, and keep yours by your own bed","then":"Saanvi glares at your phone glowing on the bedside table."},{"text":"Suggest phones out of every bedroom at night, yours included","then":"Saanvi frowns. \"Yours too?\" She thinks about it, surprised.","best":true}],"why":"A rule the whole house keeps feels fair and protects everyone's sleep."},{"prompt":"The next night, Saanvi says she needs her phone in her room as an alarm. What do you do?","options":[{"text":"Tell her to wake up on her own, like you did at her age","then":"She oversleeps twice and blames the new rule."},{"text":"Let the phone stay in her room, for the alarm only","then":"The alarm turns into scrolling again by midnight."},{"text":"Get her an alarm clock, and one for yourself too","then":"Saanvi picks a bright blue one, grumbling but amused.","best":true},{"text":"Say that's her problem to sort out","then":"Saanvi sighs and says you never help with anything."}],"why":"Solving the practical snag together keeps the rule workable."},{"prompt":"After a week, you notice your husband Anil takes his phone to bed every night. What do you do?","options":[{"text":"Let it go, since adults need their phones","then":"Saanvi notices within two days and asks why he gets a pass."},{"text":"Ask him privately to keep his phone out of the bedroom","then":"He sheepishly agrees, and that night his bedside table is empty.","best":true},{"text":"Call him out in front of Saanvi at dinner","then":"Anil gets defensive, and dinner turns into an argument."},{"text":"Say nothing, and just keep your own phone out of your room","then":"Saanvi spots his phone glowing and asks why Papa is different."}],"why":"Keeping the rule the same for every adult is what makes it believable to her."},{"prompt":"A month on, Saanvi says she misses late-night chats with her friends. What do you do?","options":[{"text":"Agree a cut-off time for chats before phones go out","then":"Saanvi sets her friends a goodnight time, and they go along with it.","best":true},{"text":"Tell her those late chats don't really matter","then":"Saanvi goes quiet and feels her world isn't taken seriously."},{"text":"Drop the night rule, so she can chat again","then":"Within a week, late-night scrolling is back."},{"text":"Allow chats in her room at weekends, with no set time","then":"Weekend chats stretch till two, and Mondays are rough."}],"why":"Adjusting the rule with her keeps it fair while still protecting sleep."}],"debrief":"Set no-devices-at-night for the whole family; a shared rule protects sleep without singling anyone out.","relearn":"No devices in bedrooms at night is a healthy boundary the family keeps."},
  {"id":"na-1194","cat":"screens-and-modelling","type":"branch","persona":"Vikram","source":"stressed and scrolling","hook":"After a brutal week at work, you've spent every evening scrolling on the sofa. Now your children do the same.","steps":[{"prompt":"Your son Ansh flops beside you with his phone, just like you. What do you do?","options":[{"text":"Admit you've been scrolling to cope and suggest a walk","then":"Ansh looks surprised, then shrugs and grabs his shoes.","best":true},{"text":"Tell him to get off his phone and do his homework","then":"Ansh looks at your phone and doesn't move."},{"text":"Decide it's harmless enough, and keep on scrolling beside him","then":"The two of you scroll side by side until dinner."},{"text":"Put your own phone down, but say nothing about why","then":"Ansh doesn't notice and keeps on scrolling."}],"why":"Naming your own habit and offering another way shows him stress has other outlets."},{"prompt":"Your daughter Pia asks why you've been so glued to your phone lately. What do you say?","options":[{"text":"Insist you're hardly on it at all, and she's imagining it","then":"Pia raises an eyebrow and goes back to her own phone."},{"text":"Say adults need to relax, and it's none of her business","then":"Pia shrugs, and the question hangs in the air."},{"text":"Say you're checking important things for work, not scrolling","then":"Pia nods, but she knows the reels aren't work."},{"text":"Say work's been hard and scrolling is how you switch off","then":"Pia nods. \"Me too, after exams,\" she says.","best":true}],"why":"Being honest about how you cope teaches her more than any rule would."},{"prompt":"You want the family to wind down differently in the evenings. What do you do?","options":[{"text":"Ban all phones after dinner, but for the children only","then":"The children grumble, then watch you take yours to the balcony."},{"text":"Download a calming meditation app on each of their phones","then":"The app sits unused, one more thing on their phones."},{"text":"Ask everyone to pick one screen-free thing to do together","then":"Ansh picks carrom, Pia picks music, and the evenings start to change.","best":true},{"text":"Change your own habit first, and fix theirs later on","then":"Weeks pass, and the evenings look the same."}],"why":"Choosing new wind-downs together makes them something everyone wants to do."},{"prompt":"Another hard week comes, and you feel the pull of the sofa and your phone. What do you do?","options":[{"text":"Scroll just for tonight, since you've more than earned it","then":"Tonight becomes the whole week, and the children follow your lead."},{"text":"Say it's been a hard week, and suggest a game of cards","then":"Pia deals the cards. By the second round, you're all laughing.","best":true},{"text":"Push through the stress alone, with no break at all","then":"You're snappy by Thursday, and the children keep their distance."},{"text":"Tell the children to go and do something while you rest","then":"They drift to their phones as soon as you look away."}],"why":"Children learn how to cope by watching what you do on hard days."}],"debrief":"Model a healthier wind-down rather than 'do as I say'; kids copy how you actually handle stress.","relearn":"Children learn to cope by watching you; outlets you use yourself teach more than any rule."},
  {"id":"na-1195","cat":"screens-and-modelling","type":"branch","persona":"any","source":"review the limit","hook":"The family screen plan you agreed a month ago is being ignored by everyone, including you.","steps":[{"prompt":"Tonight all four of you are on phones at dinner. What do you do?","options":[{"text":"Bring back the old rules, with a punishment for breaking them","then":"The children groan. It feels like a crackdown, and phones start going under the table."},{"text":"Give up on the plan, since no one is keeping it","then":"Screen time drifts, and the plan is soon forgotten."},{"text":"Suggest a family chat this weekend to look at the plan again","then":"Everyone looks up, a little guilty. Your daughter says Sunday works.","best":true},{"text":"Put your phone away and hope the others follow","then":"Nobody notices, and everyone else keeps scrolling."}],"why":"Revisiting the plan calmly, together, gives it a fair second chance."},{"prompt":"At the weekend, everyone is home with nothing planned. How do you raise the screen plan?","options":[{"text":"List everyone's slips, one by one","then":"The children get defensive, and the talk turns into blame."},{"text":"Admit you slipped too, and ask what made the plan hard","then":"Your son says the homework rule clashed with his online classes.","best":true},{"text":"Say it failed because the children didn't try","then":"Your daughter points at your phone, and the room goes quiet."},{"text":"Skip the past and read out a new, stricter plan","then":"The children nod along, but nobody really agrees."}],"why":"Owning your part first makes it safe for everyone to be honest."},{"prompt":"Your son says the plan was unrealistic in exam weeks. What do you do?","options":[{"text":"Agree to adjust it for exam weeks, together","then":"He suggests phone-free study breaks. Everyone agrees to try.","best":true},{"text":"Say rules are rules, exam weeks or not","then":"He sighs and stops making suggestions."},{"text":"Drop all limits during exams","then":"Exam weeks turn into late-night scrolling."},{"text":"Let him set his own exam rule, with no one else's input","then":"He picks a rule no one else knows about, and it quietly slips."}],"why":"A living plan that fits real life is one people can keep."},{"prompt":"The new plan is ready. How do you keep it from slipping again?","options":[{"text":"Make yourself the family's screen police","then":"The children start saving their screen time for when you're out."},{"text":"Print it out and trust that's enough","then":"The printout curls on the fridge as old habits slide back."},{"text":"Set a stiff penalty for the first person who slips","then":"The first slip is yours, and the penalty is quietly dropped."},{"text":"Agree to check in on it together every month","then":"The first check-in is short, and everyone suggests one small tweak.","best":true}],"why":"Regular, calm check-ins keep the plan fair and alive."}],"debrief":"Revisit and adjust the plan together when it slips; a living, fair plan beats a crackdown or no plan.","relearn":"Review screen limits together when they slip; a plan everyone keeps is the goal."},
  {"id":"na-1196","cat":"screens-and-modelling","type":"branch","persona":"Kamla","source":"hard day no drink","hook":"It's been a draining day at work and at home. Your children are watching how you unwind.","steps":[{"prompt":"You sit down, bone tired, and the evening stretches ahead. What do you do?","options":[{"text":"Call your sister and take a walk where the children can see","then":"You come back lighter. Munni asks if she can come next time.","best":true},{"text":"Pour a drink, since it's been one of those days","then":"Munni watches, and quietly learns that a hard day means a drink."},{"text":"Snap at the children, then scroll on the sofa","then":"The children tiptoe around you, and the evening goes quiet."},{"text":"Tell the children you're fine and push on with chores","then":"You finish the chores, but you're short-tempered by dinner."}],"why":"Letting them see you cope without a substance teaches a habit that protects them."},{"prompt":"Later, Munni says she's stressed about her exams. What do you do?","options":[{"text":"Tell her stress is part of life and to get on with it","then":"Munni shrugs and turns to her phone."},{"text":"Tell her to watch something to take her mind off it","then":"She watches three episodes and still feels anxious."},{"text":"Say you're too tired tonight, maybe tomorrow","then":"Munni nods and goes quiet. Tomorrow, she doesn't bring it up."},{"text":"Suggest you both step out for a walk and talk","then":"Munni tells you about a test she's dreading, and you talk it through.","best":true}],"why":"Sharing healthy ways to handle stress is how children learn to cope."},{"prompt":"At the weekend, a relative says a drink is how grown-ups relax. What do you say?","options":[{"text":"Agree, and accept a drink in front of the children","then":"The children watch, and the idea settles in."},{"text":"Lecture him about alcohol in front of everyone","then":"He bristles, and the visit sours."},{"text":"Say you'd rather unwind in ways the children can copy","then":"The relative shrugs. Munni hears it, and remembers.","best":true},{"text":"Say nothing and change the subject","then":"The idea hangs there, unanswered, in front of the children."}],"why":"Saying plainly how you choose to cope teaches the children as much as doing it."}],"debrief":"Let them see you cope without numbing; how you unwind on a hard day is a lesson they're filing away.","relearn":"Kids learn to handle stress by watching you; coping without substances models a habit that protects them."},
  {"id":"na-1197","cat":"screens-and-modelling","type":"branch","persona":"Vikram","source":"firm and connected","hook":"Your son Kiaan, 13, has blown past the agreed game time again. You feel the urge to grab the console.","steps":[{"prompt":"It's half an hour past the limit, and he's in the middle of a match. What do you do?","options":[{"text":"Grab the console and tell him he's turning into an addict","then":"Kiaan's face burns. He storms off and slams his door."},{"text":"Let it slide tonight, just to avoid another fight","then":"He plays for another hour, and the limit stops meaning much."},{"text":"Calmly say time's up and give him two minutes to finish","then":"Kiaan groans, finishes the round, and switches off.","best":true},{"text":"Switch off the wifi from your phone without a word","then":"The match cuts out. Kiaan yells, sure it was you."}],"why":"Holding the limit calmly, with a moment to finish, keeps the rule and his trust."},{"prompt":"Later, Kiaan says the limit is too short for his game. What do you do?","options":[{"text":"Say the limit stays as it is, and that's the end of it","then":"Kiaan goes silent and starts gaming at a friend's after school."},{"text":"Listen, and offer to review it together at the weekend","then":"Kiaan explains that matches run long. You agree to talk on Saturday.","best":true},{"text":"Give him an extra hour on the spot to keep the peace","then":"The next night he asks for two."},{"text":"Say it's his own fault for starting a match so late","then":"Kiaan shrugs, says whatever, and leaves the room."}],"why":"Being willing to talk keeps him inside the rule instead of working around it."},{"prompt":"At the weekend, Kiaan asks for longer on Saturdays and Sundays. What do you do?","options":[{"text":"Agree a fair change and write it down together","then":"Kiaan grins and pins the new timings on his wall.","best":true},{"text":"Refuse any change so he learns that rules are rules","then":"Kiaan nods stiffly. The limit feels like yours, not his."},{"text":"Say yes to whatever he asks so he's happy","then":"Weekend gaming stretches from breakfast till dinner."},{"text":"Agree, but only once his marks go up","then":"Kiaan agrees, then feels the deal is out of reach."}],"why":"Changing the limit together, when it's fair, keeps it a shared agreement."},{"prompt":"A week later, Kiaan runs over again and mumbles that he's sorry. What do you do?","options":[{"text":"Say sorry isn't enough, and cut his game time in half","then":"Kiaan stops apologising and starts hiding how long he plays."},{"text":"Let it go completely this time, since he apologised","then":"The next night he runs over again."},{"text":"Tell him you knew he'd never stick to a limit","then":"Kiaan's face drops. \"Then why do we even bother,\" he mutters."},{"text":"Accept it, hold the limit, and say you're on his side","then":"Kiaan relaxes. \"Thanks, Papa. I'll set an alarm.\"","best":true}],"why":"Being firm about the limit and warm with him are not opposites."}],"debrief":"Hold the limit and stay warm; firm about the behaviour and on the child's side are not opposites.","relearn":"You can be firm about the limit and unconditionally there for the child at the same time."},
  {"id":"na-1198","cat":"screens-and-modelling","type":"branch","persona":"Divya","source":"too tired to model","hook":"Exhausted with your new baby, you're on your phone non-stop and feel guilty about it.","steps":[{"prompt":"It's 3am and the baby is feeding. You're scrolling again. What do you tell yourself?","options":[{"text":"That you've already ruined things for your baby","then":"The guilt keeps you awake long after the feed ends."},{"text":"That you'll quit your phone completely from tomorrow","then":"The vow feels strong for a moment, then heavy."},{"text":"That it doesn't matter, so there's no point thinking about it","then":"You keep scrolling, and the guilt stays in the background."},{"text":"That you're tired, not failing, and one small change can help","then":"The guilt loosens a little, and you think about what might work.","best":true}],"why":"Kindness to yourself, not blame, is what makes change possible."},{"prompt":"In the morning you think about what to change. What do you pick?","options":[{"text":"Delete every app and go cold turkey","then":"By the afternoon you've reinstalled most of them."},{"text":"Promise to halve your screen time, starting tomorrow","then":"Tomorrow comes, and so does the scrolling."},{"text":"Leave your phone outside the bedroom for night feeds","then":"The first night you reach for it twice, then find yourself humming to the baby.","best":true},{"text":"Ask your partner to hide your phone from you","then":"They do, and you spend the evening hunting for it, annoyed."}],"why":"One small, specific change is easier to keep than a big promise."},{"prompt":"A week later, you're still scrolling through some of the night feeds. What do you do?","options":[{"text":"Decide you've failed and give up","then":"The phone creeps back into every feed."},{"text":"Go easy on yourself, and focus on one small change","then":"You feel steadier, and the next night is a little easier.","best":true},{"text":"Add three more rules to make up for it","then":"The new rules feel crushing, and you drop them all by Sunday."},{"text":"Keep it to yourself and quietly feel bad about it","then":"The quiet guilt makes the next night feed harder."}],"why":"Treating slips kindly keeps a small change going."}],"debrief":"Look at your habits with care, not blame; one small, kept change beats an all-or-nothing vow.","relearn":"Tend your own habits with self-compassion; small kept changes model more than a doomed total ban."},
  {"id":"na-1199","cat":"screens-and-modelling","type":"branch","persona":"any","source":"weekend outlets","hook":"Your children spend every weekend on screens. You want to shift that without a battle.","steps":[{"prompt":"It's Saturday morning, and both are already on their tablets. What do you do?","options":[{"text":"Declare a screen-free weekend, with no plan","then":"By noon everyone is bored and sneaking back to screens."},{"text":"Suggest a family outing and let them choose where","then":"After some grumbling, they pick the lake and a plate of chaat.","best":true},{"text":"Join them on screens for some peace","then":"The whole family scrolls through the morning."},{"text":"Take the tablets and send them outside to play","then":"They sit on the steps, sulking, until you give in."}],"why":"Offering something better, together, crowds screens out without a fight."},{"prompt":"On Sunday you all head out for a walk, but your son keeps checking his phone. What do you do?","options":[{"text":"Give him a job, like finding the best chaat stall","then":"He puts the phone away and leads the hunt.","best":true},{"text":"Take the phone and put it in your pocket","then":"He sulks the whole way, and the outing sours."},{"text":"Say nothing, since at least he came along","then":"He's there in body, but his eyes stay on the screen."},{"text":"Lecture him about screen addiction on the way","then":"He rolls his eyes, and his sister joins in."}],"why":"Drawing him into the fun works better than forcing the phone away."},{"prompt":"The next weekend comes around. How do you plan it?","options":[{"text":"Plan every hour yourself to keep them busy","then":"The packed schedule tires everyone, and they flop onto screens by evening."},{"text":"Do nothing, since one outing was enough","then":"The screens creep back to fill the weekend."},{"text":"Promise an hour of screens after each outing","then":"The outings become a countdown to screen time."},{"text":"Ask everyone to pick one thing, and take turns","then":"Your daughter picks cycling, and screens barely come up.","best":true}],"why":"Letting everyone choose turns outlets into something the family owns."},{"prompt":"Your son says his friends all game at weekends and he's missing out. What do you do?","options":[{"text":"Say his friends' families are none of your concern","then":"He goes quiet and starts gaming secretly at night."},{"text":"Drop the outings so he can game with his friends","then":"The weekends slide back to screens for everyone."},{"text":"Agree some weekend gaming time alongside the family plans","then":"He relaxes, and joins the next outing without complaint.","best":true},{"text":"Tell him family outings are compulsory, like school","then":"He comes along, but under protest every time."}],"why":"Balancing his gaming with family time keeps the outlets without a battle."}],"debrief":"Offer something better the family joins, rather than a bare ban; outlets crowd screens out gently.","relearn":"Offering outlets the family does together helps more than a screen-free decree."},
  {"id":"na-1200","cat":"screens-and-modelling","type":"match","persona":"any","source":"habit practices","hook":"Match each habit area to a simple family practice that helps.","pairs":[{"left":"Screens at meals","right":"Phones in a basket, eat together"},{"left":"Stress and boredom","right":"Healthy outlets, not numbing"},{"left":"Modelling","right":"Parents keep the same rules"},{"left":"Sleep","right":"No devices in bedrooms at night"},{"left":"Cutting screen time","right":"Crowd it out with better things"}],"relearn":"Phones away at meals, real outlets for stress, parents keeping the rules, device-free nights and crowding out the habit each protect a child."},
  {"id":"na-1201","cat":"screens-and-modelling","type":"match","persona":"Kamla","source":"modelling teaches","hook":"Match each modelling choice to what it teaches a child.","pairs":[{"left":"Parents off phones at dinner","right":"Connection comes before screens"},{"left":"Coping without a drink","right":"Stress has other outlets"},{"left":"Owning your own slip-ups","right":"Honesty and repair"},{"left":"Keeping the limits you set","right":"Rules are real, not for show"},{"left":"Asking for help yourself","right":"Reaching out is a strength"}],"relearn":"Phones away, coping without a drink, owning slips, keeping your own limits and asking for help each teach a child something that protects them."},
  {"id":"na-1202","cat":"screens-and-modelling","type":"match","persona":"any","source":"healthy vs backfire","hook":"Match each backfiring move to the healthier version of the same goal.","pairs":[{"left":"Sudden total screen ban","right":"Agreed, gradual screen limits"},{"left":"Rules only for the child","right":"Limits the whole family keeps"},{"left":"Grabbing the device in anger","right":"Holding the limit calmly"},{"left":"Just removing the screen","right":"Offering an appealing outlet"},{"left":"Imposing rules from above","right":"Making the plan together"}],"relearn":"Each backfiring move has a healthier twin: agreed limits, whole-family rules, calm limits, real outlets and a plan made together."},
  {"id":"na-1203","cat":"screens-and-modelling","type":"match","persona":"Priya","source":"plan parts","hook":"Match each part of a good family screen plan to why it works.","pairs":[{"left":"Made with the kids","right":"They actually buy in"},{"left":"Applies to parents too","right":"It feels fair and real"},{"left":"Screen-free times set","right":"Connection gets protected"},{"left":"Reviewed together later","right":"It can flex, not snap"},{"left":"Calm, not in anger","right":"Limits stay limits, not punishments"}],"relearn":"A plan made with the kids, covering parents, with set screen-free times, reviewed calmly together, holds because it's fair and flexible."},
  {"id":"na-1204","cat":"screens-and-modelling","type":"match","persona":"Divya","source":"stress outlets","hook":"Match each kind of stress to a healthy outlet you can model.","pairs":[{"left":"A draining day","right":"A walk or a call with a friend"},{"left":"Restless boredom","right":"A hobby or a bit of sport"},{"left":"Feeling overwhelmed","right":"Naming it out loud, asking for help"},{"left":"Trouble winding down","right":"A screen-free hour before bed"},{"left":"Snappy and tired","right":"A short break, not a scroll"}],"relearn":"A walk, a hobby, naming the feeling, a screen-free wind-down and a real break are outlets you can model instead of numbing the stress."},
  {"id":"na-1205","cat":"screens-and-modelling","type":"match","persona":"Kamla","source":"own habit honestly","hook":"Match each honest step on your own habit to what the child learns from it.","pairs":[{"left":"'I'm cutting down too'","right":"Change is possible and shared"},{"left":"Keeping your own limit","right":"The rule is for everyone"},{"left":"Naming a slip calmly","right":"A slip can be repaired"},{"left":"Asking for support","right":"Help-seeking is a strength"},{"left":"No hiding the habit","right":"Honesty beats secrecy"}],"relearn":"Cutting down, keeping your own limit, naming a slip, asking for support and not hiding the habit each teach the child a habit that protects them."},
  {"id":"na-1206","cat":"screens-and-modelling","type":"match","persona":"any","source":"sleep practices","hook":"Match each sleep-protecting practice to the screen problem it solves.","pairs":[{"left":"Charge phones outside the room","right":"No 1am notification checks"},{"left":"A screen-free wind-down hour","right":"An easier time falling asleep"},{"left":"An alarm clock, not the phone","right":"No reason to grab it in bed"},{"left":"No gaming after a set time","right":"Late-night gaming doesn't steal sleep"},{"left":"A shared bedtime for the family","right":"Parents model the limit too"}],"relearn":"Charging phones outside, a wind-down hour, a real alarm clock, a gaming cut-off and a shared bedtime each fix a way screens steal sleep."},
  {"id":"na-1207","cat":"screens-and-modelling","type":"match","persona":"Vikram","source":"firm and warm","hook":"Match each firm-and-warm line to the moment it fits.","pairs":[{"left":"Time's up on the game","right":"'Limit holds, and I'm on your side'"},{"left":"They call it unfair","right":"'I get it; the rule's for me too'"},{"left":"They're upset switching off","right":"'I'll sit with you while you do'"},{"left":"You slipped on your own limit","right":"'My mistake. I'll follow it too'"},{"left":"They ask why the rule exists","right":"'So screens don't run our evenings'"}],"relearn":"Firm-and-warm lines hold the limit while staying on the child's side: for time's up, 'unfair', upset, your own slip and the why."},
  {"id":"na-1208","cat":"screens-and-modelling","type":"reflect","persona":"Kamla","source":"look at our habits","hook":"Lensy: kids learn how to handle stress, screens and substances largely by watching us. Worth a look at our own?","prompt":"What do you think?","options":["Worth a look","Start with mine","They do watch us"],"affirm":"Children learn how to handle stress, screens and substances largely by watching their parents, so our own habits matter.","relearn":"Kids learn habits by watching us; our own are worth a look."},
  {"id":"na-1209","cat":"screens-and-modelling","type":"reflect","persona":"Vikram","source":"my own phone","hook":"Lensy: before setting your child's screen limit, what does your own phone use look like at home?","prompt":"Sit with it:","options":["Honestly, a lot","Better than it was","Worth tidying up"],"affirm":"Noticing your own phone use without shame is the start; the limits you keep yourself give the ones you set real weight.","relearn":"The limits you keep yourself give the ones you set real weight."},
  {"id":"na-1210","cat":"screens-and-modelling","type":"reflect","persona":"Divya","source":"kind to the parent","hook":"Lensy: tired parents model 'cope by scrolling' too. There's no shame in it, just something to notice gently.","prompt":"How does that land?","options":["I do that","Kind to notice","One small change"],"affirm":"Looking at your own habits with kindness, not blame, is exactly the honest, self-compassionate model a child learns the most from.","relearn":"Look at your own habits with kindness, not blame; that's the model."},
  {"id":"na-1211","cat":"screens-and-modelling","type":"reflect","persona":"Priya","source":"one screen-free thing","hook":"Lensy: what's one screen-free thing your family already enjoys together that you could lean into more?","prompt":"Picture it:","options":["A walk","A game or sport","Cooking together"],"affirm":"Leaning into a screen-free thing your family already enjoys crowds screens out gently, better than any ban, and it builds connection.","relearn":"Lean into screen-free things you enjoy; it crowds screens out gently."},
  {"id":"na-1212","cat":"screens-and-modelling","type":"reflect","persona":"any","source":"what they'd copy","hook":"Lensy: if your child copied exactly how you handle a stressful evening, how would you feel about that?","prompt":"What comes up?","options":["Mostly okay","One thing to shift","Worth thinking on"],"affirm":"Asking what your child would copy is a gentle, honest mirror, and noticing one thing to shift is already part of helping them.","relearn":"Ask what your child would copy; noticing one thing to shift helps."},
  {"id":"na-1213","cat":"screens-and-modelling","type":"reflect","persona":"Kamla","source":"firm and there","hook":"Lensy: you can hold a screen limit and still be fully on your child's side. Both at once, how does that feel?","prompt":"What do you think?","options":["A relief","Hard but true","Worth trying"],"affirm":"Holding a limit and staying unconditionally on your child's side are not opposites; together they keep the rule and the bond.","relearn":"Hold the limit and stay on your child's side; not opposites."},
  {"id":"na-1214","cat":"screens-and-modelling","type":"reflect","persona":"any","source":"plan together","hook":"Lensy: a screen plan made with your kids tends to stick. What's one thing you'd want in yours?","prompt":"Imagine it:","options":["Screen-free meals","No phones at night","Limits for us too"],"affirm":"A screen plan your kids help shape, including limits for the parents, gets the buy-in that makes it actually hold.","relearn":"A plan your kids help shape, parents included, gets the buy-in to hold."},
  {"id":"na-1215","cat":"screens-and-modelling","type":"spot","persona":"Vikram","source":"backfiring moves","hook":"Spot the two screen moves that backfire.","scene":[{"id":"a","text":"Agreed screen-free times for everyone","trick":false},{"id":"b","text":"A sudden, angry, total ban","trick":true},{"id":"c","text":"No devices in bedrooms at night","trick":false},{"id":"d","text":"One rule for the child, none for the parent","trick":true},{"id":"e","text":"Offering good offline things to do","trick":false}],"why":"A sudden angry ban and one-rule-for-the-child backfire; agreed times, device-free nights and real outlets help.","relearn":"Agreed limits, device-free nights and outlets help; angry total bans and double standards backfire."},
  {"id":"na-1216","cat":"screens-and-modelling","type":"spot","persona":"Kamla","source":"models the opposite","hook":"Spot the two habits that model the opposite of what you want.","scene":[{"id":"a","text":"Unwinding with a walk after work","trick":false},{"id":"b","text":"A drink every evening to relax","trick":true},{"id":"c","text":"Phone away during family time","trick":false},{"id":"d","text":"Doom-scrolling for hours on the sofa","trick":true},{"id":"e","text":"Talking about a hard day out loud","trick":false}],"why":"A nightly drink and hours of doom-scrolling model numbing; walks, phone-free time and talking model healthy coping.","relearn":"Coping without substances and phone-free time model healthy habits; nightly drinking and doom-scrolling model the opposite."},
  {"id":"na-1217","cat":"screens-and-modelling","type":"spot","persona":"Priya","source":"imposed not agreed","hook":"Spot the two moves that impose rules instead of agreeing them.","scene":[{"id":"a","text":"Asking the kids what feels fair","trick":false},{"id":"b","text":"Announcing rules with no discussion","trick":true},{"id":"c","text":"Limits that apply to parents too","trick":false},{"id":"d","text":"Threatening to seize phones on a whim","trick":true},{"id":"e","text":"Reviewing the plan together later","trick":false}],"why":"Announcing rules and threatening seizures impose; asking what's fair, parent limits and joint reviews make the plan together.","relearn":"A plan made together holds; rules announced and threatened from above invite hiding and resentment."},
  {"id":"na-1218","cat":"screens-and-modelling","type":"spot","persona":"any","source":"wrecks sleep","hook":"Spot the two phone habits that wreck sleep.","scene":[{"id":"a","text":"Charging phones outside the bedroom","trick":false},{"id":"b","text":"Scrolling in bed until you drop off","trick":true},{"id":"c","text":"A screen-free wind-down hour","trick":false},{"id":"d","text":"Checking notifications at 1am","trick":true},{"id":"e","text":"Using an alarm clock, not the phone","trick":false}],"why":"Scrolling in bed and 1am checks wreck sleep; charging phones outside, a wind-down hour and an alarm clock protect it.","relearn":"Charging phones outside, a wind-down hour and a real alarm clock protect sleep; late scrolling and night checks wreck it."},
  {"id":"na-1219","cat":"screens-and-modelling","type":"spot","persona":"Vikram","source":"harsh not firm-warm","hook":"Spot the two responses that are harsh, not firm-and-warm.","scene":[{"id":"a","text":"'The limit holds, and I'm on your side'","trick":false},{"id":"b","text":"'Give it here, you're hopeless'","trick":true},{"id":"c","text":"Sitting with them while they switch off","trick":false},{"id":"d","text":"Mocking them for being 'addicted'","trick":true},{"id":"e","text":"Explaining the why calmly, once","trick":false}],"why":"'You're hopeless' and mocking 'addiction' shame the child; the others hold the limit while staying on their side.","relearn":"Hold the limit and stay warm; shaming and mocking 'addiction' are harsh and push the child away."},
  {"id":"na-1220","cat":"screens-and-modelling","type":"spot","persona":"Divya","source":"numbing not outlet","hook":"Spot the two ways of handling stress that numb it rather than help.","scene":[{"id":"a","text":"Calling a friend after a hard day","trick":false},{"id":"b","text":"Scrolling till 2am to switch off","trick":true},{"id":"c","text":"A walk or a bit of sport","trick":false},{"id":"d","text":"A drink to take the edge off","trick":true},{"id":"e","text":"Naming the feeling out loud","trick":false}],"why":"Late scrolling and a drink numb the stress; friends, movement and naming the feeling are real outlets you can model.","relearn":"Friends, movement and naming feelings are healthy outlets; late scrolling and a drink numb the stress instead."},
  {"id":"na-1221","cat":"screens-and-modelling","type":"spot","persona":"Kamla","source":"hiding not honest","hook":"Spot the two moves that hide a habit instead of tending it honestly.","scene":[{"id":"a","text":"Saying 'I'm cutting down too'","trick":false},{"id":"b","text":"Drinking once the kids are asleep","trick":true},{"id":"c","text":"Keeping the same screen limits yourself","trick":false},{"id":"d","text":"Hiding the bottles from the family","trick":true},{"id":"e","text":"Asking for help with your own habit","trick":false}],"why":"Secret drinking and hidden bottles conceal the habit; saying you're cutting down, keeping limits and asking for help tend it honestly.","relearn":"Cutting down openly, keeping your own limits and asking for help tend a habit honestly; secret drinking and hiding it don't."},
  {"id":"na-1222","cat":"screens-and-modelling","type":"role-play","persona":"Kamla","source":"own the hypocrisy","hook":"You've just told your son Sonu, 12, that his phone time ends at eight.","setup":"He glances at your phone, buzzing with WhatsApp forwards.","steps":[{"prompt":"Sonu says: \"It's so unfair. You're always on your phone.\"","options":[{"text":"\"Don't be cheeky. The rules are for you, not me.\"","then":"Sonu mutters. \"Then I'll just use it after you sleep.\""},{"text":"\"I'm a grown-up, beta. I've earned my bit of phone time.\"","then":"Sonu rolls his eyes. \"And I haven't?\""},{"text":"\"Those are just family forwards, beta. They don't count.\"","then":"Sonu raises an eyebrow. \"You watch them for an hour, Amma.\""},{"text":"\"You're right. I'll keep the same limit, with you.\"","then":"Sonu stares. \"You'll stop at eight too?\"","best":true}],"why":"Owning the double standard gives the rule integrity and models honesty."},{"prompt":"Sonu asks: \"What if something urgent comes up after eight?\"","options":[{"text":"\"Then you ask me first, and I'll decide.\"","then":"Sonu frowns. \"And who decides for you, Amma?\""},{"text":"\"Nothing's that urgent. I'll switch mine off at eight too.\"","then":"Sonu laughs. \"What if Nani calls, though?\""},{"text":"\"Urgent calls, yes, for both of us. The rest can wait.\"","then":"Sonu nods slowly. \"Okay. Same rule for you and me.\"","best":true},{"text":"\"Then keep it on, just in case something comes up.\"","then":"Sonu grins. \"Something always comes up, Amma.\""}],"why":"Naming fair exceptions openly keeps the limit honest for both of you."},{"prompt":"At half past eight, Sonu says: \"Amma, you're still scrolling.\"","options":[{"text":"\"Just one more minute. This one's important.\"","then":"Sonu picks his phone back up. \"Me too, then.\""},{"text":"\"Fair catch. I'm putting it down now.\"","then":"Sonu grins. \"Mine goes next to yours,\" he says, and puts it on the shelf.","best":true},{"text":"\"Stop policing me and go to sleep.\"","then":"Sonu shrugs. \"Fine,\" he says, and takes his phone to bed."},{"text":"\"Sorry. This limit was a bad idea anyway.\"","then":"Sonu cheers. \"No more limit!\""}],"why":"Owning a slip straight away keeps the limit real for both of you."}],"relearn":"Owning the double standard and committing to the same limit gives the rule integrity and models honesty."},
  {"id":"na-1223","cat":"screens-and-modelling","type":"role-play","persona":"Priya","source":"family agreement","hook":"You want a family tech agreement that everyone shapes, not rules you hand down.","setup":"First you raise it with your husband Anil over chai.","steps":[{"prompt":"Anil asks: \"Why not just set rules for the kids? It's quicker.\"","options":[{"text":"\"You're right. Let's just announce them to the kids tonight.\"","then":"Anil nods. \"Great. You tell them, then.\""},{"text":"\"Rules they help make are ones they keep. And we're in it too.\"","then":"Anil laughs. \"Us too? Fine. What should be in it?\"","best":true},{"text":"\"Fine. I'll just take their phones whenever I feel like it.\"","then":"Anil raises an eyebrow. \"That'll go down well.\""},{"text":"\"Because I'm tired of always being the strict one.\"","then":"Anil shrugs. \"So this is about you, then.\""}],"why":"Explaining why shared rules work brings your partner on board first."},{"prompt":"That evening your daughter Tanvi asks: \"Is this a list of things we can't do?\"","options":[{"text":"\"No. Let's make it together. What should be in it?\"","then":"Tanvi thinks. \"No phones at dinner. For everyone.\"","best":true},{"text":"\"Mostly, yes. But it's for your own good.\"","then":"Tanvi sighs. \"Then why ask us anything?\""},{"text":"\"Only the big rules. Papa and I will decide those.\"","then":"Tanvi shrugs. \"So it's your list, then.\""},{"text":"\"It's whatever you want it to be.\"","then":"Tanvi grins. \"Unlimited gaming, then.\""}],"why":"Asking the children what goes in makes it their agreement too."},{"prompt":"Your son Rohan asks: \"Papa's always on his laptop at night. Does that count?\"","options":[{"text":"\"Papa's work is different. It's not the same.\"","then":"Rohan crosses his arms. \"Then it's not a family agreement.\""},{"text":"\"Let's not start blaming each other.\"","then":"Rohan rolls his eyes. \"So that's a no.\""},{"text":"\"Ask Papa yourself, not me.\"","then":"Anil shrugs. \"Let's talk about it another day,\" he says."},{"text":"\"Yes. Screens at night count for all of us.\"","then":"Anil groans, then laughs. \"Okay. Laptop off by ten.\"","best":true}],"why":"An agreement that binds parents too is one children believe in."},{"prompt":"Tanvi asks: \"Can we put it somewhere we'll all see it?\"","options":[{"text":"\"I'll type it up later and send it on WhatsApp.\"","then":"Tanvi shrugs. \"Okay,\" she says, already losing interest."},{"text":"\"No need. We all know what we agreed.\"","then":"Rohan frowns. \"Do we, though?\""},{"text":"\"Yes. Let's write it out together for the fridge.\"","then":"Tanvi grabs the markers. \"Everyone has to sign,\" she says.","best":true},{"text":"\"Sure, and I'll add a list of punishments right under it.\"","then":"Tanvi's smile fades. \"I thought this was different.\""}],"why":"Writing it together and keeping it visible makes it an agreement everyone owns."}],"relearn":"Proposing a fair plan everyone shapes, parents included, gets far more buy-in than arbitrary rules imposed from above."},
  {"id":"na-1224","cat":"screens-and-modelling","type":"role-play","persona":"Vikram","source":"firm and warm","hook":"Game time is up, and your son Yash, 12, is pushing back hard.","setup":"He clutches the controller, eyes fixed on the screen.","steps":[{"prompt":"Yash begs: \"Five more minutes, Papa! Please! We're about to win!\"","options":[{"text":"\"Off. Now. You're completely addicted to that thing.\"","then":"Yash throws the controller down. \"I'm not an addict!\""},{"text":"\"Fine. Play for as long as it takes you to win.\"","then":"Yash cheers. Forty minutes later he's still losing, and you switch it off mid-match."},{"text":"\"Time's up. I'm on your side. Finish this round, then off.\"","then":"Yash groans. \"Okay. Just this round,\" he says.","best":true},{"text":"\"Switch it off right now. We'll talk about it tomorrow.\"","then":"Yash switches off, jaw tight. \"You never listen,\" he mutters."}],"why":"Holding the limit while showing you're on his side keeps the rule and the bond."},{"prompt":"At bedtime Yash says: \"Game time always ends at the worst moment. It's so unfair.\"","options":[{"text":"\"I hear you, beta. But rules are rules in this house.\"","then":"Yash rolls his eyes. \"That's what you always say.\""},{"text":"\"That's frustrating. Next time you'll get a ten-minute warning.\"","then":"Yash sulks, then mutters. \"Fine. Ten minutes' warning.\"","best":true},{"text":"\"You're right. Tomorrow you can play as long as you like.\"","then":"Yash brightens. \"Deal!\""},{"text":"\"Stop whining. You're behaving like a baby.\"","then":"Yash's face reddens. \"Just leave me alone.\""}],"why":"Acknowledging his frustration and planning for next time keeps him on side."},{"prompt":"On Saturday Yash asks: \"Will you play a match with me on Sunday?\"","options":[{"text":"\"Yes. I'd like that. Show me how it works.\"","then":"Yash lights up. \"Really? I'll teach you everything.\"","best":true},{"text":"\"I don't play silly games.\"","then":"Yash's face falls. \"Forget it, then.\""},{"text":"\"Only if your homework is all done first.\"","then":"Yash sighs. \"It's always homework first.\""},{"text":"\"Maybe. We'll see how busy I am.\"","then":"Yash shrugs. \"You're always busy,\" he mutters."}],"why":"Joining his world shows you're on his side, not just policing the limit."}],"relearn":"Holding the limit while staying on the child's side keeps the rule and the relationship; shaming as 'addicted' pushes them away."},
  {"id":"na-1225","cat":"screens-and-modelling","type":"role-play","persona":"Divya","source":"offer an outlet","hook":"Your son Om, 10, has gamed all afternoon, and you want him to take a break.","setup":"You ask him to switch off for a while.","steps":[{"prompt":"Om groans: \"But there's nothing else to do!\"","options":[{"text":"\"How about we kick a ball downstairs for a bit?\"","then":"Om hesitates. \"Only if I get to be goalie.\"","best":true},{"text":"\"Just stop gaming and find something else to do.\"","then":"Om shrugs. \"Like what? There's nothing,\" he says."},{"text":"\"Read a book, then. You have loads of them.\"","then":"Om sighs. \"I've read them all,\" he says, not moving."},{"text":"\"Fine. Carry on, but don't complain later.\"","then":"Om grins. \"Thanks!\" He's back in the game before you finish."}],"why":"A specific, appealing outlet crowds out the habit better than a bare no."},{"prompt":"Next afternoon Om asks: \"Can we play football downstairs? You and me?\"","options":[{"text":"\"I'll sit on the bench and check my phone.\"","then":"Om's face drops. \"Then what's the point?\""},{"text":"\"Go by yourself. I've got work to do.\"","then":"Om slumps. \"Then I'll just game,\" he mutters."},{"text":"\"I'll join in once I finish my calls.\"","then":"Om waits by the door. \"You always say that,\" he sighs."},{"text":"\"I'll play. You might have to go easy on me.\"","then":"Om laughs. \"No chance, Mumma.\"","best":true}],"why":"Joining in shows you mean it, and makes the new activity fun."},{"prompt":"A few days later, Om asks: \"What am I allowed to do today?\"","options":[{"text":"\"No games at all today. Go outside.\"","then":"Om slumps. \"So it's a punishment,\" he mutters."},{"text":"\"Whatever you want. I'm busy today.\"","then":"Om cheers. \"Gaming, then!\""},{"text":"\"Let's plan some screen time and some outside time together.\"","then":"Om thinks. \"An hour of gaming, then cycling?\"","best":true},{"text":"\"You decide, but I'll be checking you're not gaming.\"","then":"Om nods warily. \"So I'm being watched?\""}],"why":"A balanced plan made together keeps outlets in his day, not just limits."}],"relearn":"Offering an appealing outlet crowds the habit out; a bare 'just stop' leaves a void that pulls the child back."},
  {"id":"na-1226","cat":"screens-and-modelling","type":"role-play","persona":"Kamla","source":"name your own change","hook":"You've been cutting down on your own drinking. Your daughter Munni, 13, has noticed.","setup":"She finds you making tea instead of your usual evening drink.","steps":[{"prompt":"Munni asks: \"Amma, why aren't you having your drink tonight?\"","options":[{"text":"\"That's grown-up stuff, beta. Never you mind about me.\"","then":"Munni shrugs. \"Okay, Amma,\" she says, and goes back to her room."},{"text":"\"I just didn't feel like one tonight. That's all.\"","then":"Munni nods. \"Okay,\" she says, not quite convinced."},{"text":"\"I'm cutting down. I want to be healthier.\"","then":"Munni sits beside you. \"I didn't know you were trying,\" she says.","best":true},{"text":"\"Don't make a fuss about it. It's nothing.\"","then":"Munni goes quiet. \"Sorry,\" she says."}],"why":"Naming your change honestly shows her that habits can be worked on."},{"prompt":"The next evening, Munni asks: \"Is it hard, not having your drink?\"","options":[{"text":"\"Not at all. It's easy enough if you're strong inside.\"","then":"Munni looks thoughtful. \"So people who can't are weak?\""},{"text":"\"Some evenings, yes. Having a plan and people helps.\"","then":"Munni nods slowly. \"I'm glad you told me,\" she says.","best":true},{"text":"\"A bit. But let's not talk about me right now, beta.\"","then":"Munni shrugs. \"Okay,\" she says, and the moment passes."},{"text":"\"Why? Are you drinking?\"","then":"Munni pulls back. \"No! I was only asking.\""}],"why":"Being honest that change is hard, and needs support, teaches her the truth about habits."},{"prompt":"A few days later Munni asks: \"Can I help you with it somehow?\"","options":[{"text":"\"You can. Let's walk after dinner some evenings.\"","then":"Munni grins. \"Starting tonight?\"","best":true},{"text":"\"No. It's my problem, not yours.\"","then":"Munni looks hurt. \"I just wanted to help.\""},{"text":"\"Yes. Keep an eye on me and tell me off when I slip.\"","then":"Munni hesitates. \"I don't want to boss you, Amma.\""},{"text":"\"Just don't tell anyone about it.\"","then":"Munni nods, uneasy. \"Okay. I won't.\""}],"why":"Sharing healthy time with her, instead of making her police you, keeps her a child."},{"prompt":"One evening Munni says: \"You had a drink last night. I saw.\"","options":[{"text":"\"Don't spy on me.\"","then":"Munni flinches. \"I wasn't spying,\" she says, and leaves."},{"text":"\"It was only one small drink. That doesn't really count.\"","then":"Munni frowns. \"You said you were cutting down.\""},{"text":"\"See? I'm hopeless at this. I might as well give up.\"","then":"Munni's eyes fill. \"Please don't give up, Amma.\""},{"text":"\"You're right. I slipped. I'm still working on it.\"","then":"Munni nods. \"That's okay, Amma. Tomorrow's another day.\"","best":true}],"why":"Owning a slip honestly shows her that change has bumps and still goes on."}],"relearn":"Naming your own change honestly models that habits can be worked on; brushing it off teaches secrecy instead."},
  {"id":"na-1227","cat":"screens-and-modelling","type":"role-play","persona":"Vikram","source":"own a slip","hook":"You made a screen-free meals rule. Tonight you're answering emails at dinner.","setup":"Your daughter Myra, 12, puts her fork down.","steps":[{"prompt":"Myra says: \"Papa. Phone. You made the rule.\"","options":[{"text":"\"Fair catch. My mistake. Phone's going away.\"","then":"Myra smiles and picks her fork back up. \"Thank you.\"","best":true},{"text":"\"Mind your own business and eat.\"","then":"Myra goes quiet. \"Fine,\" she mutters, sliding her own phone out."},{"text":"\"This is work, beta. Work emails don't count.\"","then":"Myra raises an eyebrow. \"My chats are important too.\""},{"text":"\"Just one email. Two minutes.\"","then":"Myra waits, arms folded. \"It's been ten minutes, Papa.\""}],"why":"Owning the slip on the spot keeps the rule real for everyone."},{"prompt":"Myra asks: \"So can I check my phone at dinner if it's important?\"","options":[{"text":"\"Yes, if it's something really important to you.\"","then":"Myra grins. \"Everything's important, Papa.\""},{"text":"\"No. Children don't have important things.\"","then":"Myra's face falls. \"Wow. Thanks.\""},{"text":"\"Let's just drop the rule. It's too hard.\"","then":"Myra frowns. \"Really? I actually liked our phone-free dinners.\""},{"text":"\"No. Neither of us, except in a real emergency.\"","then":"Myra thinks. \"Okay. That's fair, I guess.\"","best":true}],"why":"One rule for both of you, with fair exceptions, keeps it believable."},{"prompt":"The next evening, Myra teases: \"Want me to hold your phone during dinner?\"","options":[{"text":"\"Very funny. I can manage by myself.\"","then":"Myra shrugs. \"Okay. We'll see.\""},{"text":"\"Stop making fun of your father.\"","then":"Myra's grin vanishes. \"Sorry,\" she says, and dinner is quiet."},{"text":"\"Yes, please. Keep it with yours till we're done.\"","then":"Myra laughs. \"Deal,\" she says, and tucks both phones in a drawer.","best":true},{"text":"\"No need. I'll just keep it face down on the table.\"","then":"Myra rolls her eyes when it buzzes. \"Face down, Papa?\""}],"why":"Accepting her help with good humour models repair and keeps the rule shared."}],"relearn":"Owning a slip and recommitting to the rule models repair and keeps the limit real; brushing it off undoes it."},
  {"id":"na-1228","cat":"screens-and-modelling","type":"role-play","persona":"Priya","source":"set night rule together","hook":"You want devices out of bedrooms at night without it feeling like a punishment.","setup":"At dinner, you raise it with your son Vivaan, 15.","steps":[{"prompt":"Vivaan asks: \"Is this because I was online late last night?\"","options":[{"text":"\"Yes. Hand it over at bedtime or lose it for a week.\"","then":"Vivaan pushes his plate away. \"That's so unfair.\""},{"text":"\"No. I want all our phones out of the bedrooms, mine too.\"","then":"Vivaan blinks. \"You too? Even Papa?\"","best":true},{"text":"\"Partly. You clearly can't control yourself.\"","then":"Vivaan's face hardens. \"Great. Thanks.\""},{"text":"\"It's nothing personal. Just give me your phone at ten.\"","then":"Vivaan frowns. \"And where will yours be?\""}],"why":"A shared rule doesn't single him out, so it feels fair."},{"prompt":"Vivaan asks: \"Where would the phones even go?\"","options":[{"text":"\"A charging spot in the hall, maybe. You choose where.\"","then":"Vivaan shrugs. \"The shelf by the door, I guess.\"","best":true},{"text":"\"In my room, where I can keep an eye on all of them.\"","then":"Vivaan groans. \"So you can read my messages?\""},{"text":"\"Anywhere. Just not your room.\"","then":"Vivaan smirks. \"The bathroom, then.\""},{"text":"\"Locked in the cupboard every night.\"","then":"Vivaan laughs, not happily. \"Like a prison.\""}],"why":"Letting him choose the spot makes the rule partly his."},{"prompt":"Vivaan asks: \"What if my friends message me at night?\"","options":[{"text":"\"Then keep it on silent in your room.\"","then":"Vivaan nods. \"Deal.\" By midnight it's glowing, and you move it to the hall."},{"text":"\"Your friends should all be asleep by then too.\"","then":"Vivaan rolls his eyes. \"They're not, though.\""},{"text":"\"Then maybe you need friends who sleep at night.\"","then":"Vivaan goes quiet. \"Forget it,\" he says."},{"text":"\"They can wait till morning. Blame the family rule.\"","then":"Vivaan grins. \"I'll tell them my mum's strict.\"","best":true}],"why":"An easy way to explain the rule to friends helps him keep it."},{"prompt":"A week later Vivaan says: \"I miss falling asleep to music.\"","options":[{"text":"\"Take the phone in, but only for music.\"","then":"Vivaan agrees. \"Just music,\" he says. By Friday, he's scrolling."},{"text":"\"Music isn't important. Sleep is.\"","then":"Vivaan shrugs. \"Okay,\" he says, a little flat."},{"text":"\"Want the old radio? It has no screen.\"","then":"Vivaan laughs. \"A radio? Okay. I'll try it.\"","best":true},{"text":"\"We'll see. Maybe next month.\"","then":"Vivaan sighs. \"So that's a no.\""}],"why":"Solving his real need without undoing the rule keeps it working."}],"relearn":"A shared no-devices-at-night rule that includes the parents protects sleep without singling the child out."},
  {"id":"na-1229","cat":"screens-and-modelling","type":"role-play","persona":"Divya","source":"kind to yourself","hook":"You feel guilty that your toddler, Pari, sees you on your phone all the time.","setup":"Your friend Nisha drops by with samosas.","steps":[{"prompt":"Nisha asks: \"So how are you really doing?\"","options":[{"text":"\"I've already messed it all up, so what's the point.\"","then":"Nisha frowns. \"Hey. That's not true at all.\""},{"text":"\"All good. Pari keeps me busy. You know how it is.\"","then":"Nisha glances at your buzzing phone. \"Mm. You look tired, though.\""},{"text":"\"I'm quitting my phone completely from tomorrow.\"","then":"Nisha raises an eyebrow. \"Completely? With a toddler?\""},{"text":"\"I'm on my phone too much. I want one small change.\"","then":"Nisha nods. \"Same here, honestly. I'm always on mine.\"","best":true}],"why":"Naming the habit kindly, with one small step, makes change possible."},{"prompt":"Nisha nods at the phone in your hand and asks: \"If you changed one small thing about how you use that, what would it be?\"","options":[{"text":"\"Never touching it at all while she's awake.\"","then":"Nisha laughs gently. \"That's a lot. Is it realistic?\""},{"text":"\"I don't know. Nothing ever works for me.\"","then":"Nisha shrugs. \"Okay,\" she says, not sure how to help."},{"text":"\"No phone during Pari's bath and bedtime.\"","then":"Nisha nods. \"That's doable. I might try it too.\"","best":true},{"text":"\"Maybe I'll download some app to limit it.\"","then":"Nisha shrugs. \"Worth a try, I suppose.\""}],"why":"A small, specific change is one you can actually keep."},{"prompt":"A week later, Nisha texts: \"How's the phone thing going?\"","options":[{"text":"\"Badly. I slipped twice, so I've given up.\"","then":"Nisha writes back: \"Two slips? That's still a pretty decent week.\""},{"text":"\"Most days it works. I slipped twice, and that's okay.\"","then":"Nisha replies with a heart. \"Proud of you. Let's keep checking in.\"","best":true},{"text":"\"All fine. Anyway, how are your kids?\"","then":"Nisha tells you about her week. \"Anyway, catch up soon?\""},{"text":"\"Great. I've barely touched my phone all week, honestly.\"","then":"Nisha sends a thumbs-up. \"Wow! Teach me your ways.\""}],"why":"Being honest about slips, and kind about them, keeps a small change going."}],"relearn":"Naming the habit with self-compassion and one small change models honest repair; 'I've ruined it' just stalls you."},
  {"id":"na-1260","cat":"spot-the-signs","type":"strike-rewrite","hook":"\"It's just a phase, every teen games a lot, there's nothing to notice.\"","myth":{"un":"It's just a phase, every teen games a lot, there's nothing to notice.","re":"Most heavy gaming is a phase, but when it takes over sleep, school and mood for months, that pattern is worth a calm, closer look.","why":"The pattern over time, not one big night, is what tells you."},"relearn":"Most heavy gaming is a phase, but a months-long pattern that takes over sleep, school and mood is worth a closer look.","persona":"Vikram","source":"phase vs pattern"},
  {"id":"na-1261","cat":"spot-the-signs","type":"strike-rewrite","hook":"\"If my child were really hooked, I'd obviously be able to tell at a glance.\"","myth":{"un":"If my child were really hooked, I'd obviously be able to tell at a glance.","re":"Early signs are quiet and easy to miss, so children often hide them; that's why calm noticing over time matters more than one glance.","why":"Hidden early signs are normal, not a failure of yours."},"relearn":"Early signs are quiet and hidden; calm noticing over time matters more than expecting to tell at a glance.","persona":"Kamla","source":"quiet signs"},
  {"id":"na-1262","cat":"spot-the-signs","type":"strike-rewrite","hook":"\"Only kids from troubled homes get into this, so my family is safe.\"","myth":{"un":"Only kids from troubled homes get into this, so my family is safe.","re":"Dependence can affect a child from any home; assuming it could never be yours is the very blind spot that misses early signs.","why":"No family is immune, so staying alert helps every kid."},"relearn":"Dependence can affect a child from any home; assuming it could never be yours is the blind spot that misses early signs.","persona":"Priya","source":"any home"},
  {"id":"na-1263","cat":"spot-the-signs","type":"strike-rewrite","hook":"\"Tiredness and bad moods are just teenage hormones, never a warning sign.\"","myth":{"un":"Tiredness and bad moods are just teenage hormones, never a warning sign.","re":"Often they are just growing up, but when sleep and mood crash alongside a habit, the cluster together is worth gently checking.","why":"It's the cluster over time, not one tired day, that signals."},"relearn":"Tiredness and moods are often just growing up; a cluster of crashing sleep and mood around a habit is worth checking.","persona":"Divya","source":"cluster not one"},
  {"id":"na-1264","cat":"spot-the-signs","type":"strike-rewrite","hook":"\"Wanting to be left alone in their room always means something is wrong.\"","myth":{"un":"Wanting to be left alone in their room always means something is wrong.","re":"Wanting privacy is an ordinary part of growing up; it's withdrawal from everything they once loved that's worth a gentle check.","why":"Privacy is normal; losing interest in everything is the flag."},"relearn":"Wanting privacy is ordinary; withdrawal from everything they once loved is the flag worth checking gently.","persona":"any","source":"privacy vs withdrawal"},
  {"id":"na-1265","cat":"spot-the-signs","type":"strike-rewrite","hook":"\"Reading every message on their phone is just good, responsible parenting.\"","myth":{"un":"Reading every message on their phone is just good, responsible parenting.","re":"Secret snooping usually breaks trust and pushes a worried child further away; staying close and noticing openly reveals far more.","why":"You're trying to reach your child, not catch them out."},"relearn":"Secret snooping breaks trust and pushes a child away; staying close and noticing openly reveals far more.","persona":"Vikram","source":"noticing not snooping"},
  {"id":"na-1266","cat":"spot-the-signs","type":"strike-rewrite","hook":"\"Vaping is harmless, so there's nothing to watch for there.\"","myth":{"un":"Vaping is harmless, so there's nothing to watch for there.","re":"Vapes can hook a young brain on nicotine, so the same signs apply: hiding it, needing more, and feeling edgy without it.","why":"It can build dependence like any other habit."},"relearn":"Vapes can hook a young brain; watch the same signs: hiding it, needing more, and feeling edgy without it.","persona":"any","source":"vapes count"},
  {"id":"na-1267","cat":"spot-the-signs","type":"strike-rewrite","hook":"\"One bad school report proves my child has a serious problem.\"","myth":{"un":"One bad school report proves my child has a serious problem.","re":"One rough term isn't a verdict; a steady slide in school alongside other changes over time is what's worth a calm closer look.","why":"One worrying moment is never the whole story."},"relearn":"One bad report isn't a verdict; a steady slide alongside other changes over time is what's worth a closer look.","persona":"Priya","source":"one moment"},
  {"id":"na-1268","cat":"spot-the-signs","type":"strike-rewrite","hook":"\"Spending all night on their phone can't really harm their health.\"","myth":{"un":"Spending all night on their phone can't really harm their health.","re":"Late-night screens genuinely wreck sleep, which drags down mood, focus and health; screen overuse counts, not only substances.","why":"Lost sleep alone can disrupt a whole young life."},"relearn":"Late-night screens wreck sleep, which drags down mood, focus and health; screen overuse counts too.","persona":"Divya","source":"sleep counts"},
  {"id":"na-1269","cat":"spot-the-signs","type":"strike-rewrite","hook":"\"Gaming too much is just a bad habit, not anything a doctor would name.\"","myth":{"un":"Gaming too much is just a bad habit, not anything a doctor would name.","re":"Gaming disorder is a recognised condition: losing control of gaming, putting it above everything, and continuing despite the harm.","why":"Naming it means real help exists for it."},"relearn":"Gaming disorder is recognised: losing control, putting gaming above all else, and continuing despite the harm.","persona":"any","source":"recognised condition"},
  {"id":"na-1270","cat":"spot-the-signs","type":"strike-rewrite","hook":"\"If I just panic and act fast the moment I worry, I'll keep my child safe.\"","myth":{"un":"If I just panic and act fast the moment I worry, I'll keep my child safe.","re":"Panic usually leads to accusations that make a child hide more; calm curiosity over time is what actually keeps them reachable.","why":"Calm keeps the door open; panic slams it."},"relearn":"Panic leads to accusations that make a child hide; calm curiosity over time keeps them reachable.","persona":"Kamla","source":"calm not panic"},
  {"id":"na-1271","cat":"spot-the-signs","type":"sort","hook":"Sort: a calm way to notice, or a way that pushes your child away?","items":[{"id":"a","text":"Asking gently how they're really doing"},{"id":"b","text":"Secretly going through their bag"},{"id":"c","text":"Watching the pattern over weeks"},{"id":"d","text":"Reading their chats behind their back"},{"id":"e","text":"Saying you've noticed and you care"},{"id":"f","text":"Demanding answers with threats"}],"bins":[{"id":"calm","label":"Calm noticing","valence":"pos"},{"id":"push","label":"Pushes them away","valence":"neg"}],"key":{"a":"calm","b":"push","c":"calm","d":"push","e":"calm","f":"push"},"relearn":"Asking gently, watching the pattern and saying you care are calm noticing; secret searches, snooping and threats push a child away.","persona":"any","source":"notice not chase"},
  {"id":"na-1272","cat":"spot-the-signs","type":"sort","hook":"Sort: a real sign of screen dependence, or just a kid who enjoys games?","items":[{"id":"a","text":"Can't stop even when they're missing meals"},{"id":"b","text":"Loves a new game this week"},{"id":"c","text":"Gaming chosen over friends and sport, always"},{"id":"d","text":"Plays a lot on a free weekend"},{"id":"e","text":"Furious meltdown the moment screens go off"},{"id":"f","text":"Excited to show you their high score"}],"bins":[{"id":"sign","label":"Real sign","valence":"uhoh"},{"id":"fine","label":"Just enjoying it","valence":"pos"}],"key":{"a":"sign","b":"fine","c":"sign","d":"fine","e":"sign","f":"fine"},"relearn":"Can't-stop, choosing games over all else, and meltdowns at the end are signs; loving a game or a weekend play isn't.","persona":"Priya","source":"screen sign vs fun"},
  {"id":"na-1273","cat":"spot-the-signs","type":"sort","hook":"Sort: a steady warning sign of a substance habit, or an everyday teen thing?","items":[{"id":"a","text":"A smell they keep trying to cover up"},{"id":"b","text":"Wanting to pick their own clothes"},{"id":"c","text":"Money going missing again and again"},{"id":"d","text":"A messy room for a few days"},{"id":"e","text":"New secretive friends they won't talk about"},{"id":"f","text":"Staying out a bit later with known friends"}],"bins":[{"id":"watch","label":"Worth watching","valence":"uhoh"},{"id":"everyday","label":"Everyday teen","valence":"pos"}],"key":{"a":"watch","b":"everyday","c":"watch","d":"everyday","e":"watch","f":"everyday"},"relearn":"A covered smell, repeated missing money and hidden new friends are worth watching; clothes, a messy room and known friends aren't.","persona":"Kamla","source":"substance sign vs everyday"},
  {"id":"na-1274","cat":"spot-the-signs","type":"sort","hook":"Sort: the three signs of dependence, or things that are simply not signs?","items":[{"id":"a","text":"Losing control over how much they do it"},{"id":"b","text":"Having a favourite singer"},{"id":"c","text":"Needing more and more over time"},{"id":"d","text":"Enjoying a film night with the family"},{"id":"e","text":"It disrupting sleep, school and mood"},{"id":"f","text":"Wanting to redecorate their room"}],"bins":[{"id":"core","label":"A core sign","valence":"uhoh"},{"id":"not","label":"Not a sign","valence":"pos"}],"key":{"a":"core","b":"not","c":"core","d":"not","e":"core","f":"not"},"relearn":"Loss of control, escalation, and disruption of sleep, school and mood are the core signs; tastes and ordinary choices aren't.","persona":"any","source":"core trio"},
  {"id":"na-1275","cat":"spot-the-signs","type":"sort","hook":"Sort: a stance that reaches your child, or one that just tries to catch them?","items":[{"id":"a","text":"Curiosity about what's really going on"},{"id":"b","text":"Setting traps to prove they lied"},{"id":"c","text":"Keeping the door open to talk"},{"id":"d","text":"Collecting evidence to confront them"},{"id":"e","text":"Letting them know you're on their side"},{"id":"f","text":"Treating one worry as a guilty verdict"}],"bins":[{"id":"reach","label":"Reaches them","valence":"pos"},{"id":"catch","label":"Tries to catch them","valence":"neg"}],"key":{"a":"reach","b":"catch","c":"reach","d":"catch","e":"reach","f":"catch"},"relearn":"Curiosity, an open door and being on their side reach a child; traps, evidence-gathering and treating a worry as a verdict only catch them.","persona":"Vikram","source":"reach not catch"},
  {"id":"na-1276","cat":"spot-the-signs","type":"sort","hook":"Sort: worth a gentle check now, or fine to leave be?","items":[{"id":"a","text":"Dropping every hobby they used to love"},{"id":"b","text":"Trying out a new haircut"},{"id":"c","text":"Edgy and snappish without their phone"},{"id":"d","text":"Sleeping in on a Sunday"},{"id":"e","text":"Grades sliding term after term"},{"id":"f","text":"Wanting to choose their own subjects"}],"bins":[{"id":"check","label":"Gently check","valence":"uhoh"},{"id":"leave","label":"Fine to leave","valence":"pos"}],"key":{"a":"check","b":"leave","c":"check","d":"leave","e":"check","f":"leave"},"relearn":"Dropping every hobby, edginess without a phone and a term-after-term slide are worth a gentle check; a haircut, a lie-in and choosing subjects aren't.","persona":"Divya","source":"check or leave"},
  {"id":"na-1277","cat":"spot-the-signs","type":"sort","hook":"Sort: what reading a worry calmly looks like, or what panic looks like?","items":[{"id":"a","text":"Taking a breath before you speak"},{"id":"b","text":"Shouting the moment you suspect"},{"id":"c","text":"Choosing a quiet time to talk"},{"id":"d","text":"Searching the house in a fury"},{"id":"e","text":"Staying warm even while worried"},{"id":"f","text":"Issuing an ultimatum on the spot"}],"bins":[{"id":"calm","label":"Calm","valence":"pos"},{"id":"panic","label":"Panic","valence":"neg"}],"key":{"a":"calm","b":"panic","c":"calm","d":"panic","e":"calm","f":"panic"},"relearn":"A breath, a quiet time and staying warm are calm; shouting, a furious search and an on-the-spot ultimatum are panic.","persona":"any","source":"calm vs panic"},
  {"id":"na-1278","cat":"spot-the-signs","type":"sort","hook":"Sort: a clue worth holding lightly, or solid proof you can act on alone?","items":[{"id":"a","text":"A single odd evening you can't explain"},{"id":"b","text":"A months-long pattern across many areas"},{"id":"c","text":"A rumour from one classmate"},{"id":"d","text":"Repeated, matching signs over time"},{"id":"e","text":"A one-off bad mood"},{"id":"f","text":"Sleep, school and mood all slipping together"}],"bins":[{"id":"light","label":"Hold lightly","valence":"neutral"},{"id":"pattern","label":"A real pattern","valence":"uhoh"}],"key":{"a":"light","b":"pattern","c":"light","d":"pattern","e":"light","f":"pattern"},"relearn":"One odd evening, a rumour or a single bad mood is a clue to hold lightly; a months-long pattern across many areas is a real pattern.","persona":"any","source":"clue vs pattern"},
  {"id":"na-1279","cat":"spot-the-signs","type":"sort","hook":"Sort: a sign the habit is running the child, or the child still running their life?","items":[{"id":"a","text":"Skipping meals and friends to keep doing it"},{"id":"b","text":"Saving up for a concert they love"},{"id":"c","text":"Lying about where the time and money went"},{"id":"d","text":"Busy with studies, sport and friends"},{"id":"e","text":"Unable to stop even when they want to"},{"id":"f","text":"Planning a trip with their cousins"}],"bins":[{"id":"habit","label":"Habit in charge","valence":"uhoh"},{"id":"child","label":"Child in charge","valence":"pos"}],"key":{"a":"habit","b":"child","c":"habit","d":"child","e":"habit","f":"child"},"relearn":"Skipping life, lying and being unable to stop mean the habit's in charge; a busy, planning, saving kid is in charge.","persona":"Kamla","source":"who's in charge"},
  {"id":"na-1280","cat":"spot-the-signs","type":"sort","hook":"Sort: a thing that helps you read the whole picture, or a thing that narrows it?","items":[{"id":"a","text":"Talking with their teacher about how they're doing"},{"id":"b","text":"Judging it all on one screenshot"},{"id":"c","text":"Noticing changes across home, school and friends"},{"id":"d","text":"Fixating on a single bad night"},{"id":"e","text":"Watching gently over several weeks"},{"id":"f","text":"Deciding everything from one rumour"}],"bins":[{"id":"whole","label":"Whole picture","valence":"pos"},{"id":"narrow","label":"Narrows it","valence":"neg"}],"key":{"a":"whole","b":"narrow","c":"whole","d":"narrow","e":"whole","f":"narrow"},"relearn":"A teacher's view and watching across settings over weeks reads the whole picture; one screenshot, night or rumour narrows it.","persona":"Vikram","source":"whole picture"},
  {"id":"na-1281","cat":"spot-the-signs","type":"sort","hook":"Sort: a genuine red flag, or a green flag that things are alright?","items":[{"id":"a","text":"Hiding the habit and getting defensive about it"},{"id":"b","text":"Openly telling you they tried something once"},{"id":"c","text":"Withdrawing from the whole family"},{"id":"d","text":"Coming to you when something upset them"},{"id":"e","text":"Needing it just to feel normal"},{"id":"f","text":"Balancing screens with sleep and friends"}],"bins":[{"id":"red","label":"Red flag","valence":"neg"},{"id":"green","label":"Green flag","valence":"pos"}],"key":{"a":"red","b":"green","c":"red","d":"green","e":"red","f":"green"},"relearn":"Hiding it, withdrawing from everyone and needing it to feel normal are red flags; being open, coming to you and keeping balance are green ones.","persona":"Priya","source":"red vs green"},
  {"id":"na-1282","cat":"spot-the-signs","type":"match","hook":"Match each warning sign to the calm question it invites, not a panic.","pairs":[{"left":"Withdrawing from everyone","right":"\"Has something been weighing on you lately?\""},{"left":"Money going missing","right":"\"Can we talk about where it's been going?\""},{"left":"Crashing sleep","right":"\"What's keeping you up at night?\""},{"left":"Grades sliding","right":"\"What's making school feel harder?\""},{"left":"A new secretive crowd","right":"\"Tell me about the friends you spend time with.\""}],"relearn":"Each warning sign is best met with a calm, curious question that opens a talk, not an accusation that shuts it down.","persona":"any","source":"sign to question"},
  {"id":"na-1283","cat":"spot-the-signs","type":"match","hook":"Match the ordinary teen thing to the version of it that's worth a check.","pairs":[{"left":"Wanting privacy","right":"Hiding their whole life from you"},{"left":"Liking games","right":"Gaming over sleep, food and school"},{"left":"Trying something once","right":"Needing more and more of it"},{"left":"A bad mood now and then","right":"Mood crashing for weeks on end"},{"left":"Seeing friends a lot","right":"Dropping everyone for one crowd"}],"relearn":"The ordinary thing tips into a concern when it takes over: secrecy about everything, escalation, and disruption of a whole life.","persona":"any","source":"ordinary to concern"},
  {"id":"na-1284","cat":"spot-the-signs","type":"match","hook":"Match each of the three core signs to a plain everyday example of it.","pairs":[{"left":"Loss of control","right":"Means to stop at one, can't"},{"left":"Escalation","right":"The old amount stops being enough"},{"left":"Disrupted sleep","right":"Up half the night, wrecked by morning"},{"left":"Disrupted school","right":"Missing classes and homework slips"},{"left":"Disrupted bonds","right":"Pulling away from family and old friends"}],"relearn":"The signs are loss of control and escalation, plus disruption spreading across sleep, school and relationships.","persona":"any","source":"core signs examples"},
  {"id":"na-1285","cat":"spot-the-signs","type":"match","hook":"Match each stance to whether it reaches the child or only catches them.","pairs":[{"left":"Secretly reading their phone","right":"Catches them, breaks trust"},{"left":"Saying you've noticed, gently","right":"Reaches them, keeps the door open"},{"left":"Setting a trap to prove a lie","right":"Catches them, drives it underground"},{"left":"Staying curious over time","right":"Reaches them, you learn what's real"},{"left":"Confronting with accusations","right":"Catches them, they shut down"}],"relearn":"Snooping and accusations catch a child and break trust; noticing openly and staying curious reach them and keep them honest.","persona":"Vikram","source":"reach or catch match"},
  {"id":"na-1286","cat":"spot-the-signs","type":"match","hook":"Match each habit area to a sign it may have tipped into dependence.","pairs":[{"left":"Phone and social media","right":"Anxious and edgy the moment it's away"},{"left":"Vaping or smoking","right":"Hiding it and a smell they cover up"},{"left":"Alcohol","right":"Needing more to feel the same"},{"left":"Online gaming","right":"Rage when asked to log off"},{"left":"Late-night screens","right":"Exhausted and foggy every morning"}],"relearn":"Each habit shows the same trio in its own way: hiding it, needing more, and distress or disruption when it stops.","persona":"any","source":"habit area signs"},
  {"id":"na-1287","cat":"spot-the-signs","type":"match","hook":"Match each one-off moment to the over-time pattern that would actually worry you.","pairs":[{"left":"One late night","right":"Weeks of barely sleeping"},{"left":"One skipped class","right":"A term of missed classes"},{"left":"One quiet day","right":"Months of pulling away"},{"left":"One white lie","right":"Constant lying about a habit"},{"left":"One rough mood","right":"Mood low for weeks together"}],"relearn":"A single moment is rarely the story; it's the same thing repeating and spreading over time that's worth a closer look.","persona":"Divya","source":"one-off to pattern"},
  {"id":"na-1288","cat":"spot-the-signs","type":"match","hook":"Match each red flag to why it counts as more than ordinary growing up.","pairs":[{"left":"Can't stop when they try","right":"Control over the habit is slipping"},{"left":"Needs more each time","right":"Tolerance is building up"},{"left":"Skips meals and friends for it","right":"It's crowding out normal life"},{"left":"Hides and lies about it","right":"Shame is keeping it in the dark"},{"left":"Edgy and low without it","right":"They feel they depend on it"}],"relearn":"Red flags count because they show slipping control, rising tolerance, life crowded out, secrecy and a felt dependence.","persona":"any","source":"why it's a flag"},
  {"id":"na-1289","cat":"spot-the-signs","type":"reflect","hook":"Lensy: noticing early and calmly, not in a panic, gives you the best chance to help. Sit right?","prompt":"What do you think?","options":["Sits right","Calm beats panic","Early helps"],"affirm":"Noticing signs early and calmly, instead of panicking or ignoring them, gives you the best chance to help your child.","relearn":"Noticing early and calmly, not in a panic, gives you the best chance to help.","persona":"any","source":"notice early calm"},
  {"id":"na-1290","cat":"spot-the-signs","type":"reflect","hook":"Lensy: the aim is to reach your child, not to catch them out. Feel the difference?","prompt":"What's your take?","options":["Feel it","Reach, not catch","Makes sense"],"affirm":"Reaching your child keeps the door open to help; catching them out makes a worried child hide what you most need to understand.","relearn":"The aim is to reach your child, not to catch them out.","persona":"any","source":"reach not catch reflect"},
  {"id":"na-1291","cat":"spot-the-signs","type":"reflect","hook":"Lensy: one worrying moment isn't a verdict on your child. How does that land?","prompt":"Where do you land?","options":["It lands","Not a verdict","The pattern matters"],"affirm":"One worrying moment isn't a verdict; it's the steady pattern over time, read calmly, that tells you whether to look closer.","relearn":"One worrying moment isn't a verdict; the pattern over time is what matters.","persona":"Vikram","source":"not a verdict"},
  {"id":"na-1292","cat":"spot-the-signs","type":"reflect","hook":"Lensy: screens and gaming can disrupt a child's life as truly as substances. Sound fair?","prompt":"What do you feel?","options":["Sounds fair","Screens count too","Worth watching"],"affirm":"Screen and gaming dependence is real and recognised; it can disrupt sleep, mood and life, so it's worth watching, not waving off.","relearn":"Screens and gaming can disrupt a child's life as truly as substances.","persona":"Priya","source":"screens count reflect"},
  {"id":"na-1293","cat":"spot-the-signs","type":"reflect","hook":"Lensy: dependence can touch a child from any family, including a loving one. Does that free you up?","prompt":"What's your sense?","options":["Frees me up","Any family","Less self-blame"],"affirm":"Dependence can affect a child from any family; knowing it isn't a verdict on you frees you to notice and act, without shame.","relearn":"Dependence can affect a child from any family; it isn't a verdict on you.","persona":"Kamla","source":"any family reflect"},
  {"id":"na-1294","cat":"spot-the-signs","type":"reflect","hook":"Lensy: wanting privacy and wanting friends are ordinary; losing interest in everything is the flag. Ring true?","prompt":"What do you think?","options":["Rings true","Ordinary vs flag","Good to know"],"affirm":"Wanting privacy and friends is just growing up; it's withdrawing from everything they once loved that's worth a gentle check.","relearn":"Privacy and friends are ordinary; losing interest in everything is the flag.","persona":"any","source":"ordinary vs flag reflect"},
  {"id":"na-1295","cat":"spot-the-signs","type":"reflect","hook":"Lensy: noticing is about staying close, not standing guard over them. Sit well with you?","prompt":"What's your take?","options":["Sits well","Close, not guard","Connection first"],"affirm":"Calm noticing comes from closeness, not surveillance; staying connected shows you far more than standing guard ever could.","relearn":"Noticing is about staying close, not standing guard.","persona":"Divya","source":"close not guard"},
  {"id":"na-1296","cat":"spot-the-signs","type":"reflect","hook":"Lensy: trusting your gut and checking gently can sit together, without jumping to the worst. Agree?","prompt":"Where do you sit?","options":["Agree","Gut plus gentle","Both can be true"],"affirm":"You can trust a worry and still check gently; honouring your gut without jumping to the worst keeps you steady and your child reachable.","relearn":"Trust your gut and check gently, without jumping to the worst.","persona":"any","source":"gut and gentle"},
  {"id":"na-1297","cat":"spot-the-signs","type":"spot","hook":"Spot the two reactions that would push a worried teen to hide more.","scene":[{"id":"a","text":"Asking gently how they've been","trick":false},{"id":"b","text":"Searching their bag without asking","trick":true},{"id":"c","text":"Saying you're here whenever they're ready","trick":false},{"id":"d","text":"Shouting accusations across the room","trick":true},{"id":"e","text":"Choosing a calm moment to check in","trick":false}],"why":"Searching their bag and shouting accusations make a worried teen hide more; gentle, calm noticing keeps them reachable.","relearn":"Snooping and accusations push a teen to hide; calm noticing keeps the door open.","persona":"Vikram","source":"push to hide"},
  {"id":"na-1298","cat":"spot-the-signs","type":"spot","hook":"Spot the two real warning signs hidden among ordinary teen things.","scene":[{"id":"a","text":"Wanting a bit more privacy","trick":false},{"id":"b","text":"Can't stop gaming even when they miss meals","trick":true},{"id":"c","text":"Enjoying time with their friends","trick":false},{"id":"d","text":"Money keeps going missing for a habit","trick":true},{"id":"e","text":"Trying a new hobby this month","trick":false}],"why":"Can't-stop and money going missing for a habit are the real warning signs; privacy, friends and a new hobby are ordinary.","relearn":"Loss of control and things going missing for a habit are signs; privacy, friends and hobbies are ordinary.","persona":"Priya","source":"signs among ordinary"},
  {"id":"na-1299","cat":"spot-the-signs","type":"spot","hook":"Spot the two lines that wave off a real screen problem.","scene":[{"id":"a","text":"\"His sleep is wrecked, let's look at this together.\"","trick":false},{"id":"b","text":"\"Gaming can't really be a problem, only drugs count.\"","trick":true},{"id":"c","text":"\"Let's notice the pattern over a few weeks.\"","trick":false},{"id":"d","text":"\"It's just a phase, no need to pay attention.\"","trick":true},{"id":"e","text":"\"Screens can disrupt a life too, worth watching.\"","trick":false}],"why":"\"Only drugs count\" and \"just a phase\" wave off a real screen problem; gaming and screen dependence is recognised and worth watching.","relearn":"Don't wave off screens; gaming and screen dependence is real.","persona":"Divya","source":"waving off screens"},
  {"id":"na-1300","cat":"spot-the-signs","type":"spot","hook":"Spot the two panic moves in how this parent reads a worry.","scene":[{"id":"a","text":"Taking a breath before saying anything","trick":false},{"id":"b","text":"Tearing the room apart in a fury","trick":true},{"id":"c","text":"Picking a quiet time to talk","trick":false},{"id":"d","text":"Threatening to throw them out","trick":true},{"id":"e","text":"Staying warm even while worried","trick":false}],"why":"Tearing the room apart and threatening to throw them out are the panic moves; a breath, a quiet time and warmth are the calm way.","relearn":"Panic moves like a furious search and threats break trust; calm noticing keeps a child safe.","persona":"Kamla","source":"panic moves"},
  {"id":"na-1301","cat":"spot-the-signs","type":"spot","hook":"Spot the two snooping moves dressed up as caring.","scene":[{"id":"a","text":"Asking openly about their day","trick":false},{"id":"b","text":"Reading their private chats in secret","trick":true},{"id":"c","text":"Telling them you've noticed and care","trick":false},{"id":"d","text":"Tracking their phone without telling them","trick":true},{"id":"e","text":"Inviting them to talk anytime","trick":false}],"why":"Reading chats and tracking the phone in secret are snooping that breaks trust; asking openly and saying you care keep the door open.","relearn":"Secret snooping breaks trust; open noticing and care keep a child reachable.","persona":"any","source":"snooping as caring"},
  {"id":"na-1302","cat":"spot-the-signs","type":"spot","hook":"Spot the two over-reactions to a single worrying evening.","scene":[{"id":"a","text":"Holding the worry lightly for now","trick":false},{"id":"b","text":"Declaring them an addict on the spot","trick":true},{"id":"c","text":"Watching how the next weeks go","trick":false},{"id":"d","text":"Punishing them hard before you know","trick":true},{"id":"e","text":"Keeping the conversation open","trick":false}],"why":"Labelling them an addict and punishing hard before you know are over-reactions to one evening; holding it lightly and watching the pattern is steadier.","relearn":"One evening isn't a verdict; hold a worry lightly and watch the pattern over time.","persona":"Vikram","source":"one evening overreaction"},
  {"id":"na-1303","cat":"spot-the-signs","type":"spot","hook":"Spot the two signs the habit is taking over, not just being enjoyed.","scene":[{"id":"a","text":"Excited to share a win with you","trick":false},{"id":"b","text":"Skipping school again to keep doing it","trick":true},{"id":"c","text":"Still making time for friends","trick":false},{"id":"d","text":"Lying about how much and how often","trick":true},{"id":"e","text":"Happy to switch it off for dinner","trick":false}],"why":"Skipping school for it and lying about how much show the habit taking over; sharing wins, keeping friends and switching off don't.","relearn":"Skipping life and lying about a habit show it taking over; enjoying it with balance doesn't.","persona":"Priya","source":"taking over"},
  {"id":"na-1304","cat":"spot-the-signs","type":"spot","hook":"Spot the two assumptions that would make you miss a real sign.","scene":[{"id":"a","text":"\"Let me stay alert and see the whole picture.\"","trick":false},{"id":"b","text":"\"It could never happen to my child.\"","trick":true},{"id":"c","text":"\"I'll notice changes across home and school.\"","trick":false},{"id":"d","text":"\"Good kids just don't get hooked.\"","trick":true},{"id":"e","text":"\"I'll keep the door open and keep watching.\"","trick":false}],"why":"\"Never my child\" and \"good kids don't\" are the assumptions that miss real signs; staying alert catches them early.","relearn":"Assuming it could never be your kid is the blind spot; staying alert catches signs early.","persona":"Kamla","source":"blind-spot assumptions"},
  {"id":"na-1305","cat":"spot-the-signs","type":"branch","persona":"Vikram","source":"slide and withdrawal","hook":"Your son Aarav's marks have slipped all term, and lately he mostly stays in his room.","steps":[{"prompt":"His report card arrives today with two red marks. What do you do?","options":[{"text":"Wait for a calm moment and ask how he's really been","then":"That evening Aarav shrugs, then says school has felt pointless for a while.","best":true},{"text":"Ground him until he explains what he's hiding","then":"Aarav says there's nothing to explain and shuts his door."},{"text":"Sign the report and say nothing, to keep things easy","then":"Aarav looks relieved. The quiet in the house carries on."},{"text":"Book extra tuition so the marks come back up","then":"Aarav goes without complaint, but seems more tired and quiet than before."}],"why":"A calm, curious question invites him to share, where a demand makes a worried teen deny and pull away."},{"prompt":"At dinner a few days later, Aarav says he's tired and leaves half his food. What do you do?","options":[{"text":"Say he seems low, and ask what's been hard","then":"Aarav is quiet, then says he can't sleep and feels behind in everything.","best":true},{"text":"Tell him to eat properly and stop being moody","then":"He says fine and eats in silence. He's back in his room in minutes."},{"text":"Check his phone later while he's asleep","then":"You find nothing clear, and feel uneasy about having looked."},{"text":"Ask his sister what's going on with him","then":"His sister says he's quiet at school too. Aarav still hasn't said a word to you."}],"why":"Naming what you see and asking gently keeps the door open for him to talk to you directly."},{"prompt":"A week later, his class teacher calls: Aarav has been sleeping through lessons. What do you do?","options":[{"text":"Tell Aarav about the call, calmly, and offer help","then":"Aarav looks at the floor, then says his nights have been bad for weeks.","best":true},{"text":"Promise the teacher he'll be punished at home","then":"The teacher sounds unsure. Aarav overhears and stops speaking to you."},{"text":"Decide it's exam stress and wait for exams to pass","then":"Exams come and go. Aarav stays up later and talks to you less."},{"text":"Ask the teacher to watch him closely and report back","then":"The teacher agrees. You get updates, but Aarav still hasn't talked to you."}],"why":"Bringing it to him calmly, with an offer of help, keeps him talking to you instead of hiding."}],"debrief":"Meet a slide and withdrawal with a calm, curious check-in, not a demand that makes a worried teen shut down.","relearn":"A calm check-in opens a withdrawn teen up; demands make them deny and pull away."},
  {"id":"na-1306","cat":"spot-the-signs","type":"branch","persona":"Kamla","source":"smoke and money","hook":"This week you smelled smoke on your son Ravi's shirt, and 200 rupees went missing from your tin.","steps":[{"prompt":"Ravi comes home from school and drops his bag. What do you do?","options":[{"text":"Calmly name what you've noticed and ask to talk","then":"Ravi freezes, then mutters that some older boys at the tea stall smoke.","best":true},{"text":"Turn out his pockets and accuse him on the spot","then":"You find nothing. Ravi shouts that you never trust him and storms out."},{"text":"Hide the money tin and say nothing for now","then":"The money stops going missing. The smell of smoke doesn't."},{"text":"Lecture him about how hard you work for that money","then":"Ravi stares at the floor until you finish, then goes out without a word."}],"why":"Naming it calmly makes him feel met, not cornered, so the truth has room to come out."},{"prompt":"Two days later you see Ravi at the corner with some older boys, a cigarette in his hand. What do you do?","options":[{"text":"Wait until he's home, then calmly say what you saw","then":"Ravi says he only tried it because the others did. He looks scared of what you'll do.","best":true},{"text":"March over and drag him home in front of everyone","then":"Ravi is humiliated in front of the boys. At home he won't look at you."},{"text":"Pretend you didn't see, so he doesn't feel caught","then":"Ravi never learns you know, and the smoking carries on."},{"text":"Ask the tea-stall owner to keep the boys away","then":"The owner shrugs. The boys just move to another corner."}],"why":"Raising it privately and calmly keeps his dignity, so he can be honest instead of defensive."},{"prompt":"You can't tell whether Ravi is hooked or just trying it. What do you do?","options":[{"text":"Call Tele-MANAS 14416 to ask how to support him","then":"The counsellor listens and helps you plan how to talk to Ravi without shaming him.","best":true},{"text":"Decide it's just a phase that all boys go through","then":"Weeks pass. Ravi still smells of smoke, and money still goes missing."},{"text":"Stop giving him any pocket money at all","then":"Ravi says nothing. A few days later your purse is lighter instead."},{"text":"Ask the school to check his bag every day","then":"The school says it can't do that. Ravi hears you asked and is furious."}],"why":"Talking it through with trained help early gives you a calm plan before it grows."},{"prompt":"Evenings after school are when Ravi drifts back to that corner. What do you do?","options":[{"text":"Ask him what he'd enjoy doing after school instead","then":"Ravi thinks, then mentions the cricket the boys on the next street play.","best":true},{"text":"Lock him inside every evening after school","then":"Ravi sulks at the window and slips out the moment you step away."},{"text":"Mention the smoking every time you see him","then":"Ravi starts avoiding you whenever he comes in."},{"text":"Sign him up for evening tuition he hasn't asked for","then":"Ravi goes twice, then skips it and goes back to the corner."}],"why":"An outlet he picks himself gives him somewhere better to be, which a ban alone never does."}],"debrief":"Name what you've noticed calmly and invite a talk, rather than searching and accusing, which drives it underground.","relearn":"Naming a worry calmly invites honesty; searching and accusing drive it underground."},
  {"id":"na-1307","cat":"spot-the-signs","type":"branch","persona":"Priya","source":"rage at logoff","hook":"Your daughter Meher, 12, shouts and slams doors every time you ask her to stop gaming.","steps":[{"prompt":"It happens again tonight, the third time this week. What do you do?","options":[{"text":"Take it seriously, and talk once she's calm","then":"Next morning Meher admits she thinks about the game all through school.","best":true},{"text":"Tell yourself gaming is harmless and let it go","then":"The shouting becomes part of every evening."},{"text":"Delete the game while she's at school","then":"Meher sobs, then downloads it again on a friend's phone."},{"text":"Give her an extra hour so evenings stay peaceful","then":"Tonight is quiet. Tomorrow she asks for two more hours."}],"why":"Rage at logging off can be a sign of a real grip, so it's worth exploring together."},{"prompt":"That weekend, Meher skips her best friend's birthday party to keep playing. What do you do?","options":[{"text":"Ask gently what the game gives her","then":"Meher says in the game she's good at something, and at school she isn't.","best":true},{"text":"Tell her she's addicted and it's embarrassing","then":"Meher's face closes. \"You don't get it,\" she says, and turns back to the screen."},{"text":"Let it go, since there will be other parties","then":"Meher plays until midnight. Her friend doesn't invite her next time."},{"text":"Make her go to the party right now","then":"Meher goes, sulks through it, and plays twice as long when she's back."}],"why":"Curiosity about what the game gives her shows you the grip, and what she might be missing."},{"prompt":"A month on, stopping still ends in tears most nights. What do you do?","options":[{"text":"Talk to a counsellor about what you're seeing","then":"The counsellor asks about sleep and school, and suggests a family session.","best":true},{"text":"Ban all gaming until her behaviour improves","then":"Meher stops talking to you and plays at her cousin's house instead."},{"text":"Wait, since most kids grow out of it","then":"The tears turn into silence. Meher games later into the night."},{"text":"Keep trying new rules on your own for now","then":"Each new rule lasts a few days, and the tears come back every time."}],"why":"When a grip lasts despite your efforts, a counsellor can help, and earlier help works best."}],"debrief":"Treat rage at switching off as a sign worth exploring, not a harmless quirk to ignore.","relearn":"Rage at logging off is worth exploring; brushing screens off as harmless misses a real grip."},
  {"id":"na-1308","cat":"spot-the-signs","type":"branch","persona":"Vikram","source":"one odd message","hook":"A message flashes on your son Kabir's charging phone: \"got the stuff, see u at 6\".","steps":[{"prompt":"Kabir is in the shower and doesn't know you saw it. What do you do?","options":[{"text":"Hold it lightly and watch the whole picture","then":"You note it and carry on. At six, Kabir heads out with his football kit.","best":true},{"text":"Decide it proves he's using and confront him","then":"Kabir is stunned. \"It's the team jerseys, Papa.\" He stays cold all evening."},{"text":"Scroll quickly through the rest of his messages","then":"You find nothing more, and Kabir notices his phone has been moved."},{"text":"Ask his friend's father if he knows anything","then":"The father has no idea, and now both families are worried."}],"why":"One message isn't proof. Watching the whole picture avoids a false alarm and keeps trust."},{"prompt":"Over the next two weeks, what do you pay attention to?","options":[{"text":"His sleep, mood, friends and schoolwork","then":"Kabir seems his usual self: tired after practice, noisy with friends, behind in maths.","best":true},{"text":"Every message that arrives on his phone","then":"You feel on edge each time it buzzes, and Kabir starts keeping it face down."},{"text":"Whether he goes out at six again","then":"He does, twice. You still don't know where, or why."},{"text":"Nothing. You'd rather not think about it","then":"The worry sits at the back of your mind, never looked at."}],"why":"Changes in sleep, mood and life over time tell you far more than one message can."},{"prompt":"One evening Kabir is chatting to you in the kitchen. What do you do?","options":[{"text":"Ask how things are with his friends these days","then":"Kabir talks for ten minutes about his team, his coach and a friend's new bike.","best":true},{"text":"Ask to see his chats, just to be sure","then":"Kabir's face drops. He asks what you think you'll find."},{"text":"Keep it light and steer clear of anything personal","then":"The chat stays on cricket scores. You learn nothing about how he's doing."},{"text":"Tell him you'll check his phone from now on","then":"Kabir's smile drops. He stops leaving his phone around."}],"why":"Everyday chats keep you close enough to notice real changes, without making him feel watched."}],"debrief":"Hold a single ambiguous clue lightly and watch the whole picture, rather than treating it as proof.","relearn":"One message isn't proof; hold it lightly and watch the whole picture."},
  {"id":"na-1309","cat":"spot-the-signs","type":"branch","persona":"any","source":"secret tracking","hook":"Your daughter Tanvi, 15, guards her phone lately, and a colleague swears by a hidden tracking app.","steps":[{"prompt":"The app is one tap away. What do you do?","options":[{"text":"Skip it. Stay close and notice openly instead","then":"You close the app. That evening Tanvi lets you sit with her while she sketches.","best":true},{"text":"Install it secretly so you know everything","then":"It works. You read her chats every night and start dreading what you'll find."},{"text":"Install it, but only look in an emergency","then":"Two days later a late reply worries you, and you look anyway."},{"text":"Take her phone away until she's less secretive","then":"Tanvi borrows a friend's old phone and becomes more secretive, not less."}],"why":"Open noticing keeps her trust, and her trust is what keeps her coming to you."},{"prompt":"At a family function, Tanvi spends the whole evening texting in a corner. What do you do?","options":[{"text":"Sit with her a while and ask about her evening","then":"Tanvi puts the phone face down and says a friend is going through a breakup.","best":true},{"text":"Take the phone and tell her to join the family","then":"Tanvi hands it over, sits in silence, and leaves early with a headache."},{"text":"Let it go, since functions bore every teenager","then":"Tanvi texts until you leave, and says almost nothing to you all evening."},{"text":"Ask her cousin who she's always texting","then":"Her cousin tells Tanvi you asked. She won't speak to you on the drive home."}],"why":"Showing interest in her, not her phone, is how you learn what's really going on."},{"prompt":"A month later, Tanvi comes home upset and heads straight to her room. What do you do?","options":[{"text":"Knock, sit with her, and let her talk when ready","then":"After a while Tanvi says something has gone wrong in a group chat, but not what.","best":true},{"text":"Check her phone that night to find out what happened","then":"You find the group chat. Now you know, but you can't say how you know."},{"text":"Give her space and wait for her to come to you","then":"She stays in her room all evening. Next day she acts as if nothing happened."},{"text":"Tell her she spends too much time on that phone","then":"Tanvi turns away. \"This is why I don't tell you anything.\""}],"why":"Being present and patient lets her bring the problem to you, which no tracking app can do."},{"prompt":"Two days later, Tanvi admits a school group chat has been mocking her for weeks. What do you do?","options":[{"text":"Believe her, say it's not her fault, and ask what would help","then":"Tanvi cries a little, then asks if you'll help her tell her class teacher.","best":true},{"text":"Tell her to leave the group and delete the app tonight","then":"Tanvi says leaving would make it worse at school, and stops telling you more."},{"text":"Ask to see every message so you know exactly what was said","then":"Tanvi hands over the phone and goes silent while you scroll."},{"text":"Ring the other girls' parents that evening to complain","then":"Tanvi begs you not to. At school the next day, the messages get worse."}],"why":"Believing her and letting her choose the next step keeps her coming to you, and gets her real support."}],"debrief":"Choose open noticing and connection over secret surveillance, which breaks the trust you most need.","relearn":"Open noticing keeps a child close; secret tracking breaks trust and pushes them away."},
  {"id":"na-1310","cat":"spot-the-signs","type":"branch","persona":"Divya","source":"nagging worry","hook":"For weeks something has felt off with your son Ishaan: he's always tired, and snappy when his phone is out of reach.","steps":[{"prompt":"You're exhausted, and part of you hopes it's nothing. What do you do?","options":[{"text":"Take it seriously enough to look closer, gently","then":"Over the next few days you notice he's on the phone past midnight most nights.","best":true},{"text":"Talk yourself out of it so you needn't deal with it","then":"The worry fades for a few days, then comes back stronger."},{"text":"Tell him you're worried he's hooked on that phone","then":"Ishaan rolls his eyes. \"You always overreact.\" He hides the phone better."},{"text":"Ask your mother, who says boys are always like this","then":"You feel reassured for an evening. Nothing changes for Ishaan."}],"why":"Looking closer, gently, lets you catch a real issue early without a rupture."},{"prompt":"One night you see his phone glowing under the door at 1 a.m. What do you do?","options":[{"text":"Next day, ask calmly about the late nights","then":"Ishaan admits he can't fall asleep without playing, and he's tired all day.","best":true},{"text":"Burst in and take the phone right then","then":"Ishaan shouts that it's unfair. Nobody sleeps much after that."},{"text":"Leave it, since you're too tired to face a fight","then":"The glow is there again the next night, and the next."},{"text":"Switch off the Wi-Fi at night without telling him","then":"Ishaan switches to mobile data. The late nights carry on."}],"why":"Raising it calmly the next day invites honesty, where a midnight fight teaches hiding."},{"prompt":"You're still unsure whether this is serious or a phase. What do you do?","options":[{"text":"Call Tele-MANAS 14416 to talk it through","then":"The counsellor asks a few questions and suggests two calm steps to try first.","best":true},{"text":"Search online late at night for answers","then":"You find ten opinions and feel more anxious than before."},{"text":"Wait a few more months to see if it settles","then":"Months pass. Ishaan's marks and moods slide further."},{"text":"Ask his school to have a word with him about screens","then":"A teacher lectures him in class. Ishaan comes home embarrassed and angry."}],"why":"You don't need to be certain to ask. Talking it through early gives you a clear next step."}],"debrief":"Take a nagging worry seriously enough to look closer gently, rather than dismissing it to avoid the discomfort.","relearn":"Don't dismiss a nagging worry; look closer gently and catch issues early."},
  {"id":"na-1311","cat":"spot-the-signs","type":"branch","persona":"Divya","source":"night phone","hook":"Your daughter Sana has been on her phone past 2 a.m. for weeks, and mornings are a struggle.","steps":[{"prompt":"Tonight you wake up and see her screen glowing at 2. What do you do?","options":[{"text":"Tell her gently it's late, and talk tomorrow","then":"Sana mumbles \"okay\" and puts the phone face down. The room goes dark.","best":true},{"text":"Snatch the phone away there and then","then":"Sana screams, you both shout, and neither of you sleeps."},{"text":"Let it go, since you were a night owl too","then":"Sana sleeps through her alarm and misses the school bus again."},{"text":"Change the Wi-Fi password without a word","then":"Sana uses her data pack instead and stays up just as late."}],"why":"Raising it calmly, at a better time, lets you tackle the real issue instead of starting a fight."},{"prompt":"At breakfast, Sana is too tired to eat and says she has a test today. What do you do?","options":[{"text":"Ask what keeps her up at night, and listen","then":"Sana says her group chat goes on till 2, and she's scared of missing out.","best":true},{"text":"Tell her this is what staying up all night does","then":"Sana pushes her plate away and leaves without a word."},{"text":"Write a note so she can skip the test","then":"Sana is relieved. The late nights carry on."},{"text":"Make her strong chai and say nothing","then":"Sana drinks it gratefully. Nothing about the nights changes."}],"why":"Listening first shows you what drives the late nights, so you solve the right thing."},{"prompt":"That weekend, you sit down to sort out the nights. How do you go about it?","options":[{"text":"Agree a phone-free bedtime with Sana, using her ideas","then":"Sana suggests charging it in the kitchen after 10:30, if weekends can be later.","best":true},{"text":"Announce a rule: phone handed in at 9, no discussion","then":"Sana agrees tightly, then keeps an old phone hidden in her room."},{"text":"Leave it to her to sort out on her own","then":"Sana says she'll try. By Wednesday she's up past midnight again."},{"text":"Agree a bedtime for Sana, but keep your own phone in bed","then":"Sana agrees, then points out your screen lights up the room at night too."}],"why":"Limits made together, and kept by the whole family, are the ones that last."},{"prompt":"Two weeks later, you find Sana on her phone at midnight again. What do you do?","options":[{"text":"Ask what got in the way, and rethink the nights together","then":"Sana says it was exam stress. You agree to try a wind-down routine together.","best":true},{"text":"Take the phone away for a month","then":"Sana stops talking to you and finds ways around it."},{"text":"Give up, since nothing seems to work","then":"Within a week, the 2 a.m. nights are back."},{"text":"Warn her, calmly, that one more late night means no phone","then":"Sana nods, tense. From then on, she hides her late nights."}],"why":"Slips are normal. Working it out calmly keeps her talking, where threats push it into hiding."}],"debrief":"Raise disrupted sleep gently and solve it together, not by snatching the phone in anger.","relearn":"Naming lost sleep and solving it together beats an angry grab that teaches hiding."},
  {"id":"na-1312","cat":"spot-the-signs","type":"branch","persona":"Kamla","source":"party report","hook":"Your sister-in-law calls to say your son Imran, 16, was seen drinking at a wedding last night.","steps":[{"prompt":"Imran is still asleep, and the family WhatsApp group is buzzing. What do you do?","options":[{"text":"Once he's up, ask him calmly and listen first","then":"Imran goes red, then says a cousin gave him two glasses and he felt sick after.","best":true},{"text":"Wake him and shout before he can say a word","then":"Imran shouts back that everyone drinks at weddings and slams the door."},{"text":"Reply in the group that he'll be punished","then":"The group goes quiet. Imran sees it and feels humiliated in front of everyone."},{"text":"Say nothing to Imran and hope it was a one-off","then":"Imran never learns you know. The next wedding is in three weeks."}],"why":"Listening first gets you the real story and makes it safe for him to be honest."},{"prompt":"All day, relatives keep calling to give you their opinion. What do you do?","options":[{"text":"Thank them, and say you're handling it with Imran","then":"Most calls stop. One aunt still insists he needs to be taught a lesson.","best":true},{"text":"Agree with them that Imran has shamed the family","then":"Word spreads further, and Imran hears what you said about him."},{"text":"Ask each of them what else they've seen him do","then":"You hear three versions, all different, and Imran hears you're asking around."},{"text":"Stop answering the phone for a few days","then":"The calls keep coming. Relatives start calling Imran instead."}],"why":"Keeping it between you and Imran protects his trust, so he keeps coming to you."},{"prompt":"Next month, Imran asks to go to a friend's birthday party. What do you do?","options":[{"text":"Agree a plan together: no drinking, and a ride home","then":"Imran rolls his eyes, but agrees to no drinking and to call you for the ride.","best":true},{"text":"Refuse, since you can't trust him anymore","then":"Imran goes quiet. That night he says he's going to a friend's to study."},{"text":"Say yes and don't mention the wedding","then":"Imran goes. You spend the evening worrying, with no plan between you."},{"text":"Say yes only if he swears on your life he won't drink","then":"Imran swears at once, a little too quickly. The drinking is never really talked about."}],"why":"A clear limit and a plan made together keep him safer, and keep him calling you."}],"debrief":"Check in calmly and listen first when you hear a worrying report, not exploding before you know.","relearn":"Listening first gets the real story; branding a teen before you know makes them secretive."},
  {"id":"na-1313","cat":"spot-the-signs","type":"role-play","persona":"Vikram","source":"first reply to an admission","hook":"Riya, 17, has just told you she's been vaping to cope with board exam stress.","setup":"She sits on the edge of her bed, not meeting your eyes.","steps":[{"prompt":"Riya says: \"Please don't freak out. I just couldn't handle the pressure.\"","options":[{"text":"\"Thank you for telling me. Let's tackle the stress together.\"","then":"Riya breathes out. \"I didn't think you'd take it like this.\"","best":true},{"text":"\"I knew it. You're grounded, and I'm taking your phone.\"","then":"Riya's face shuts. \"This is why I never tell you anything.\""},{"text":"\"Vaping is disgusting. I thought you were smarter than this.\"","then":"Riya's eyes fill. \"Forget I said anything.\""},{"text":"\"It's only vaping. At least it's nothing worse.\"","then":"Riya looks unsure. \"So it's fine, then?\""}],"why":"Thanking her for telling you keeps her talking, and that is what makes help possible."},{"prompt":"Riya asks: \"Are you going to tell everyone?\"","options":[{"text":"\"Not the family. But I'd like us to see a counsellor together.\"","then":"Riya hesitates. \"A counsellor? Okay. If you come too.\"","best":true},{"text":"\"Only if you do it again.\"","then":"Riya nods slowly. You can see her deciding to hide it next time."},{"text":"\"No one. We'll handle it ourselves and never speak of it again.\"","then":"Riya looks relieved. The stress, and the vaping, stay hidden."},{"text":"\"Your teachers should know, so they can keep an eye on you.\"","then":"Riya panics. \"Papa, no! Then everyone will find out.\""}],"why":"Guarding her privacy while bringing in real help avoids both shame and secrecy."},{"prompt":"Riya says quietly: \"I don't know if I can just stop.\"","options":[{"text":"\"You won't do it alone. We'll find help that works.\"","then":"Riya nods. \"Okay. What happens first?\"","best":true},{"text":"\"Of course you can. It's just a matter of willpower.\"","then":"Riya looks away. \"Then I guess I'm just weak.\""},{"text":"\"Then I'll check your bag every day until you do.\"","then":"Riya stiffens. \"So you don't trust me at all now.\""},{"text":"\"Just try your best, and we'll see how it goes.\"","then":"Riya agrees. Neither of you knows what to do when it gets hard."}],"why":"Stopping is hard because dependence changes the brain. Real support helps; willpower alone doesn't."},{"prompt":"Riya asks: \"What about the exams, though? That's why I started.\"","options":[{"text":"\"Let's plan your study with breaks, and I'll help.\"","then":"Riya half smiles. \"Maybe walks in the evening too?\"","best":true},{"text":"\"Just study harder and you won't need to vape.\"","then":"Riya's shoulders drop. \"That's literally the problem.\""},{"text":"\"Forget the exams. Your health matters more than marks.\"","then":"Riya looks panicked. \"I can't just forget them!\""},{"text":"\"Everyone has exam stress. You'll survive it.\"","then":"\"Yeah,\" Riya says flatly, and the talk fizzles out."}],"why":"Easing the stress underneath gives her a healthier way to cope, not just a rule."}],"relearn":"Meeting a hard admission with thanks and a focus on the underlying stress keeps a teen talking; punishment-first slams the door on the next honest conversation."},
  {"id":"na-1314","cat":"spot-the-signs","type":"role-play","persona":"Priya","source":"name the pattern","hook":"Ayaan, 13, explodes whenever you ask him to stop gaming.","setup":"Tonight he's calm, eating dinner beside you.","steps":[{"prompt":"Ayaan asks between bites: \"Can I play for another hour after dinner?\"","options":[{"text":"\"First, can we talk? Stopping seems really hard lately.\"","then":"Ayaan's fork pauses. \"It's not hard. You just stop me at the worst moment.\"","best":true},{"text":"\"You're addicted to that thing, and it's pathetic.\"","then":"Ayaan pushes his plate away. \"Whatever. I'm done eating.\""},{"text":"\"Fine, one more hour, as long as there's no shouting after.\"","then":"Ayaan grins. \"Deal.\" An hour later, the shouting starts anyway."},{"text":"\"No. And after last night, maybe never again.\"","then":"Ayaan glares. \"That's so unfair!\""}],"why":"Naming the pattern with curiosity invites him in, where a label shuts him down."},{"prompt":"Ayaan says: \"Everyone plays. You just don't understand games.\"","options":[{"text":"\"Maybe not. What happens inside when you have to stop?\"","then":"Ayaan thinks. \"My head is still in the game. I get really angry.\"","best":true},{"text":"\"I understand that you shout at me every single night.\"","then":"Ayaan crosses his arms. \"Because you yell first.\""},{"text":"\"Other kids don't scream when their parents say stop.\"","then":"Ayaan goes red. \"So I'm the bad kid now.\""},{"text":"\"You're right. I'll stay out of it from now on.\"","then":"Ayaan looks surprised, then relieved. Nothing changes."}],"why":"Being curious about what he feels helps you understand the grip the game has on him."},{"prompt":"Ayaan mumbles: \"I don't even like how angry I get.\"","options":[{"text":"\"Thanks for telling me. Want to make a plan together?\"","then":"Ayaan nods. \"Maybe a warning before I have to stop?\"","best":true},{"text":"\"Then just stop getting angry. It's up to you.\"","then":"Ayaan shrugs. \"It's not that easy.\""},{"text":"\"Then you won't mind if I take the console away for good.\"","then":"Ayaan's face falls. \"I knew telling you was a mistake.\""},{"text":"\"Don't worry. All boys your age get like this.\"","then":"Ayaan looks relieved, and the talk ends there."}],"why":"Honouring his honesty and planning together builds on it, instead of punishing it."}],"relearn":"Naming the pattern with curiosity opens a talk; shaming labels shut a child down and deepen the habit."},
  {"id":"na-1315","cat":"spot-the-signs","type":"role-play","persona":"Kamla","source":"lead with calm","hook":"Washing clothes, you find a strip of pills you don't recognise in your son Suresh's pocket.","setup":"Suresh, 17, walks in and sees it in your hand.","steps":[{"prompt":"Suresh freezes and asks: \"Why are you going through my things?\"","options":[{"text":"\"I found this in the wash. I'm not angry. Help me understand.\"","then":"Suresh sits down slowly. \"A friend gave them to me. For sleep.\"","best":true},{"text":"\"How could you do this to us? I can't even look at you.\"","then":"Suresh walks out, then comes back an hour later, silent."},{"text":"\"Don't change the subject. What are these, and who gave them?\"","then":"Suresh's jaw sets. \"Nobody. They're nothing.\""},{"text":"\"Sorry, I wasn't snooping. Let's forget I found it.\"","then":"Suresh takes the strip back, then shrugs as if it's nothing."}],"why":"Leading with calm keeps him talking, where panic and blame make him hide."},{"prompt":"Suresh says: \"Everyone in my class takes something for stress. It's normal.\"","options":[{"text":"\"I hear you. What's been stressing you so much?\"","then":"Suresh sighs. \"Exams, money, everything. I can't switch off at night.\"","best":true},{"text":"\"I don't care what others do. You'll stop from today.\"","then":"Suresh nods coldly. \"Fine.\" You can tell he doesn't mean it."},{"text":"\"If everyone does it, then I suppose it's okay.\"","then":"Suresh looks relieved, but watches you warily."},{"text":"\"Then give me the names of these friends of yours.\"","then":"Suresh laughs bitterly. \"So you can shame them too?\""}],"why":"Asking about the stress beneath it shows care, and keeps him telling you the truth."},{"prompt":"Suresh asks: \"So what now? Are you going to punish me?\"","options":[{"text":"\"No. I want us to get proper advice, together.\"","then":"Suresh hesitates. \"Like a doctor?\" You nod.","best":true},{"text":"\"Yes. No phone and no friends until you stop.\"","then":"Suresh stares at the floor. \"Then I'll just hide it better.\""},{"text":"\"No. Let's just forget this ever happened.\"","then":"Suresh relaxes. The strip goes back in his bag."},{"text":"\"I'll decide once I've talked to your uncle about it.\"","then":"Suresh groans. \"Now the whole family will know.\""}],"why":"Framing it as getting help, not punishment, keeps him willing to accept support."}],"relearn":"Leading with calm curiosity keeps a child reachable; leading with panic and blame makes them hide."},
  {"id":"na-1316","cat":"spot-the-signs","type":"role-play","persona":"Divya","source":"sleep and mood","hook":"Your daughter Kavya, 15, has seemed tired and low for weeks now.","setup":"She's scrolling on the sofa after school.","steps":[{"prompt":"Kavya notices you watching and sighs: \"What now?\"","options":[{"text":"\"You've seemed low lately. How are things, really?\"","then":"Kavya shrugs. \"Tired. Everything feels like a lot.\"","best":true},{"text":"\"Snap out of it. You're being lazy and dramatic.\"","then":"Kavya rolls over to face the wall. \"Thanks, Mumma.\""},{"text":"\"You're on that phone again. No wonder you're so tired.\"","then":"Kavya tosses the phone aside. \"Fine. Happy now?\""},{"text":"\"I'm booking a doctor. Something is clearly wrong with you.\"","then":"Kavya sits up, alarmed. \"Wrong with me? What does that mean?\""}],"why":"Naming what you've noticed, with care, invites her to tell you how things really are."},{"prompt":"Kavya says: \"I just can't sleep. My brain won't stop at night.\"","options":[{"text":"\"That sounds exhausting. What goes round in your head?\"","then":"Kavya hesitates. \"Friends stuff. And I keep checking my phone.\"","best":true},{"text":"\"Then no phone after dinner, starting from today.\"","then":"Kavya groans. \"That's not even the problem.\""},{"text":"\"Everyone your age has trouble sleeping. It'll pass.\"","then":"Kavya shrugs. \"I guess.\" She looks more alone than before."},{"text":"\"Try warm milk and bed by ten. That will fix it.\"","then":"Kavya nods politely. Nothing about the nights changes."}],"why":"Curious questions about what's behind it show you the whole picture, not just one symptom."},{"prompt":"Kavya admits: \"Some nights I scroll till 3. Then school feels impossible.\"","options":[{"text":"\"Thank you. Shall we work out the nights together?\"","then":"Kavya nods slowly. \"Maybe the phone charges outside my room?\"","best":true},{"text":"\"Till 3? That's it. I'm taking the phone every night.\"","then":"Kavya's face shuts. \"I shouldn't have told you.\""},{"text":"\"Oh, beta, you poor thing. Sleep in tomorrow, then.\"","then":"Kavya smiles weakly. The 3 a.m. nights carry on."},{"text":"\"Just put it down when you're tired. It's that simple.\"","then":"Kavya sighs. \"It's not simple. That's the point.\""}],"why":"Thanking her and solving it together keeps her honest, where a snap decision shuts her down."},{"prompt":"A week later, Kavya says quietly: \"It's not just the sleep. I feel low most days.\"","options":[{"text":"\"I'm glad you told me. Shall we see a counsellor together?\"","then":"Kavya is quiet, then nods. \"Okay. If you come with me.\"","best":true},{"text":"\"It's the late nights. Fix those and the rest will sort itself out.\"","then":"Kavya nods, and stops mentioning how she feels."},{"text":"\"Low about what? You have everything you need.\"","then":"Kavya's face falls. \"Forget it.\""},{"text":"\"Let's keep you busy. More classes will take your mind off it.\"","then":"Kavya sighs. Her week fills up, and the low feeling stays."}],"why":"When low mood lasts, a counsellor can help, and asking early is a strength."}],"relearn":"Naming the pattern with care invites honesty; dismissing it as laziness shuts the door."},
  {"id":"na-1317","cat":"spot-the-signs","type":"role-play","persona":"any","source":"open not snoop","hook":"Farhan, 14, has new friends, has quit football and is out most evenings. You want to raise it openly.","setup":"He's lacing his shoes to go out again.","steps":[{"prompt":"Farhan says without looking up: \"I'll be back by eight.\"","options":[{"text":"\"I've noticed some changes, and I care. Can we talk later?\"","then":"Farhan pauses. \"Changes like what?\" But he agrees to talk after dinner.","best":true},{"text":"\"I read your messages, so don't bother lying to me.\"","then":"Farhan goes white, then furious. \"You read my phone?\""},{"text":"\"Who are these new friends? I want their names and numbers.\"","then":"Farhan sighs. \"Why? So you can call their parents?\""},{"text":"\"Okay. Have fun.\"","then":"Farhan grins and is gone. After dinner, he catches you watching him and frowns."}],"why":"Saying openly that you've noticed, and why, lets you reach him instead of catching him out."},{"prompt":"After dinner, Farhan asks: \"Is this about my new friends? You don't even know them.\"","options":[{"text":"\"You're right. I don't. Tell me about them.\"","then":"Farhan eyes you, then grins. \"Adil's funny. You'd like him, actually.\"","best":true},{"text":"\"I know enough. They're a bad influence on you.\"","then":"Farhan's voice rises. \"You've never even met them!\""},{"text":"\"Then invite them home so I can check them out.\"","then":"Farhan groans. \"Like I'd bring anyone here now.\""},{"text":"\"Forget it. Do whatever you want.\"","then":"Farhan shrugs and puts his earphones in. The question hangs there all week."}],"why":"Asking about his world shows you want to know him, not catch him out."},{"prompt":"On Sunday, Farhan says: \"I know you're wondering. Football just felt pointless.\"","options":[{"text":"\"Fair enough. What are you into these days?\"","then":"Farhan hesitates. \"Music, maybe. Adil's cousin makes beats.\"","best":true},{"text":"\"You'll go back to football, or there's no going out.\"","then":"Farhan's jaw clenches. \"Fine. I'll go and just sit there.\""},{"text":"\"That's how it starts. Next you'll lose interest in everything.\"","then":"Farhan rolls his eyes. \"Wow. Dramatic much?\""},{"text":"\"Okay, as long as your marks don't drop.\"","then":"Farhan nods. The conversation ends at marks."}],"why":"Dropping one hobby is ordinary. Staying curious lets you notice if it ever spreads to everything."}],"relearn":"Open noticing keeps trust; admitting to snooping breaks it and proves your aim was to catch, not reach."},
  {"id":"na-1318","cat":"spot-the-signs","type":"role-play","persona":"Vikram","source":"on your side","hook":"Your son Neel, 17, has come home late smelling of alcohol twice this month.","setup":"It's the next morning, and he's avoiding your eyes.","steps":[{"prompt":"Neel mutters: \"Go on, then. Say it.\"","options":[{"text":"\"I'm on your side. Let's figure this out together.\"","then":"Neel looks up, surprised. \"You're not going to shout?\"","best":true},{"text":"\"One more slip and you're out of this house.\"","then":"Neel's face goes blank. \"Fine.\" He leaves for college without breakfast."},{"text":"\"I'm so disappointed. I raised you better than this.\"","then":"Neel flushes. \"Yeah. I know. I'm a disappointment.\""},{"text":"\"Say what? Boys will be boys. Just be careful.\"","then":"Neel shrugs, relieved. \"Okay.\" He looks as if he wants to say more, but doesn't."}],"why":"Knowing you're on his side makes it safe for him to be honest about what's happening."},{"prompt":"That evening, Neel finds you and says: \"It's the guys from college. They all drink on weekends.\"","options":[{"text":"\"And how has it been for you, on those nights?\"","then":"Neel hesitates. \"Honestly? I drink more than I planned, some nights.\"","best":true},{"text":"\"All of them? Then you need a new set of friends.\"","then":"Neel scoffs. \"Right. I'll just go and make new ones.\""},{"text":"\"Well, I drank in college too. You'll grow out of it.\"","then":"Neel grins, relieved, then glances toward the kitchen."},{"text":"\"Not in my house. From now on, you're home by eight.\"","then":"Neel stares. \"I'm seventeen, not seven.\""}],"why":"Staying curious instead of arguing helps him tell you the real picture."},{"prompt":"Later, Neel asks: \"Are you going to tell Mumma?\"","options":[{"text":"\"She should know. We'll tell her together, calmly.\"","then":"Neel groans, then nods. \"Okay. But you'll be there?\"","best":true},{"text":"\"No. This stays between us. I promise.\"","then":"Neel relaxes. \"Thanks. She'd never let me go out again.\""},{"text":"\"Of course. She'll deal with you tonight.\"","then":"Neel's face tightens. \"Great. So it's two against one.\""},{"text":"\"Only if it happens again. So make sure it doesn't.\"","then":"Neel nods. You can see him planning not to get caught."}],"why":"Both parents working as one, calmly, gives him support instead of secrets or a pile-on."},{"prompt":"Neel says quietly: \"What if I can't stop drinking so much when I'm with them?\"","options":[{"text":"\"Then let's find someone who can help. I'll come too.\"","then":"Neel exhales. \"Okay. I don't want to feel like this.\"","best":true},{"text":"\"Then you'll stay home every weekend until you can.\"","then":"Neel nods, angry. \"Fine. I'll find a way round it.\""},{"text":"\"Of course you can. It's just about willpower.\"","then":"Neel looks down. \"Then I must be really weak.\""},{"text":"\"Don't worry. It's a phase. It'll pass after college.\"","then":"Neel shrugs. \"I hope so.\" The weekends go on the same."}],"why":"Offering real help, and going with him, shows him he's not alone with it."}],"relearn":"Reassuring a child you're on their side keeps them honest; ultimatums make them hide what's really happening."},
  {"id":"na-1319","cat":"spot-the-signs","type":"role-play","persona":"Priya","source":"door open","hook":"Nothing seems wrong with Zoya, 14, but a classmate of hers was caught with a vape at school.","setup":"Zoya brings it up on the drive home.","steps":[{"prompt":"Zoya says: \"Everyone's talking about it. She's suspended now.\"","options":[{"text":"\"That sounds hard for her. How do you feel about it?\"","then":"Zoya shrugs. \"Weird. She's actually really nice.\"","best":true},{"text":"\"You'd better not be getting into anything like that.\"","then":"Zoya stiffens. \"Why would you even say that?\""},{"text":"\"Good. Maybe that will teach the others a lesson.\"","then":"Zoya goes quiet and looks out of the window."},{"text":"\"Stay away from that girl from now on. Understood?\"","then":"Zoya's voice rises. \"She's my friend, Mumma.\""}],"why":"Curiosity about how she feels shows her you're safe to talk to, not quick to judge."},{"prompt":"Zoya asks: \"Would you freak out if it was me?\"","options":[{"text":"\"I'd worry. But I'd want to help, not punish.\"","then":"Zoya thinks. \"Okay. That's good to know.\"","best":true},{"text":"\"Of course. And you'd be grounded for life.\"","then":"Zoya laughs tightly. \"Noted. Never telling you anything.\""},{"text":"\"It would never be you. You're a good girl.\"","then":"Zoya looks away. \"Right.\" She stares out of the window."},{"text":"\"Why? Is there something you want to tell me?\"","then":"Zoya bristles. \"It was a question! Forget it.\""}],"why":"Admitting you'd worry, and promising help, makes you someone she can come to."},{"prompt":"As you park, Zoya asks: \"Okay. Can we drop it now?\"","options":[{"text":"\"Sure. If anything ever feels too big, come to me.\"","then":"Zoya nods, and squeezes your hand before she gets out.","best":true},{"text":"\"Fine. But I'll be checking your bag from now on.\"","then":"Zoya gets out and shuts the car door hard behind her."},{"text":"\"Sure. We never have to talk about this again.\"","then":"Zoya relaxes. You've closed the door you meant to open."},{"text":"\"Not yet. Promise me you'll never touch a vape.\"","then":"Zoya sighs. \"Fine. I promise.\" It sounds automatic."}],"why":"An open, no-judgement invitation keeps her willing to come to you if she ever needs to."}],"relearn":"An open, no-judgement invitation keeps a teen willing to come to you; a threat makes sure they won't."},
  {"id":"na-1350","cat":"tools-and-safety","type":"branch","persona":"Kamla","source":"plan ahead","hook":"You suspect your son Vijay is using something, but you have no plan for if you find out.","steps":[{"prompt":"He's out with friends tonight, and you can't stop worrying. What do you do?","options":[{"text":"Save Tele-MANAS 14416 and decide how you'll stay calm","then":"You save the number and tell yourself: breathe, listen, then act.","best":true},{"text":"Wait until you actually catch him, then work out what to do","then":"The worry churns all evening. You still have no idea what you'd say."},{"text":"Search his room tonight for proof","then":"You find an empty packet you don't understand, and your panic grows."},{"text":"Ask the neighbour to keep an eye on where he goes","then":"The neighbour agrees, and soon other people are talking about Vijay."}],"why":"Planning before a crisis means you meet the moment steady, not scrambling."},{"prompt":"Vijay comes home late, red-eyed, and heads straight for his room. What do you do?","options":[{"text":"Check he's okay, then talk calmly in the morning","then":"He mumbles that he's fine. In the morning he's wary, but sits down when you ask.","best":true},{"text":"Stop him at the door and demand to know what he's taken","then":"Vijay pushes past you. The shouting wakes the whole house."},{"text":"Pretend you didn't notice anything","then":"Vijay slips into his room. The next night he's late again."},{"text":"Call his elder brother over to deal with him","then":"His brother arrives angry. Vijay locks his door and won't come out."}],"why":"A calm talk when he's clear-headed keeps him reachable; a doorway fight drives it underground."},{"prompt":"Next morning, you still don't know what Vijay is using, or how often. What do you do?","options":[{"text":"Call Tele-MANAS 14416 to talk through next steps","then":"The counsellor helps you plan what to say to Vijay, and when.","best":true},{"text":"Keep it inside the family and tell no one","then":"Weeks pass. You carry it alone, and nothing changes."},{"text":"Give him an ultimatum: stop, or leave the house","then":"Vijay goes to stay with a friend and stops answering your calls."},{"text":"Wait and see whether it happens again","then":"It does, twice more, and you're no nearer a plan."}],"why":"Talking it through with trained help early gives the best chance, before a crisis."}],"debrief":"Prepare before a crisis: know the signs, plan a calm response, and save Tele-MANAS 14416 today.","relearn":"Plan your calm response and save the numbers before you need them, not in the middle of a crisis."},
  {"id":"na-1351","cat":"tools-and-safety","type":"branch","persona":"Vikram","source":"acute danger","hook":"You find your daughter Ananya, 17, unconscious on her bed, and you can't wake her.","steps":[{"prompt":"You fear she's taken something, and panic hits. What do you do?","options":[{"text":"Call 112 right now","then":"The operator stays on the line and tells you help is coming.","best":true},{"text":"Wait an hour to see if she sleeps it off","then":"Minutes feel like hours. She doesn't stir, and you finally call 112."},{"text":"Splash water on her face until she wakes","then":"She stirs a little but doesn't wake. You call 112, precious minutes later."},{"text":"Call your brother to ask what he thinks","then":"Your brother panics too and tells you to call 112. Time has slipped by."}],"why":"Acute danger like a possible overdose is an emergency. Calling 112 gets help fastest."},{"prompt":"While you wait, your mother wants to hide an empty pill strip so no one judges Ananya. What do you do?","options":[{"text":"Keep it to show the medical team","then":"When help arrives, the medic reads the strip and gets to work at once.","best":true},{"text":"Let her hide it, to protect Ananya's name","then":"The medics have to guess what Ananya took, which slows them down."},{"text":"Argue with your mother about who's to blame","then":"You're both shouting when the ambulance arrives, and no one is beside Ananya."},{"text":"Ring her friends to ask what she took","then":"No one answers. You're still dialling when the ambulance arrives."}],"why":"Honest information helps medics treat her quickly. Her health matters more than gossip."},{"prompt":"Ananya is safe in hospital, and a doctor suggests follow-up support. What do you do?","options":[{"text":"Accept, and ask how the family can be part of it","then":"The doctor refers you to a counsellor who will see Ananya and you together.","best":true},{"text":"Take her home and never mention it again","then":"Ananya comes home. The silence around what happened grows heavier."},{"text":"Say you'll handle it within the family","then":"The doctor looks concerned. You leave with no plan for what comes next."},{"text":"Tell Ananya how much she scared and shamed you","then":"Ananya turns her face to the wall and won't speak to you."}],"why":"Follow-up help, with the family involved, gives her the best chance of recovering well."}],"debrief":"A possible overdose or any acute danger is an emergency: call 112 or go to a hospital at once.","relearn":"Acute danger like a possible overdose is an emergency; get medical help now, never wait it out."},
  {"id":"na-1352","cat":"tools-and-safety","type":"branch","persona":"any","source":"shared plan","hook":"Your help plan for your son Rahul lives only in your head. Your partner has no idea what to do.","steps":[{"prompt":"Next week you'll be away for work. What do you do?","options":[{"text":"Walk your partner through the plan and the numbers","then":"Your partner saves Tele-MANAS 14416 and asks what staying calm would look like.","best":true},{"text":"Keep it in your head, since you'll only be gone a week","then":"You leave. On every call home, you hope nothing happens while you're away."},{"text":"Leave a long note about it in a drawer, just in case","then":"Your partner never opens the drawer, and doesn't know the note is there."},{"text":"Ask your partner to call you if anything happens","then":"Your partner agrees, but you'll be in meetings and hard to reach."}],"why":"A plan only works if whoever is home can use it, so share the numbers and the steps."},{"prompt":"One evening your partner says, \"If I ever caught Rahul using, I'd lose it.\" What do you do?","options":[{"text":"Agree a calm first response you'll both use","then":"You settle on three words for the fridge: breathe, listen, help.","best":true},{"text":"Say that's fair, since he'd deserve it","then":"Your partner nods. Now you both expect to explode."},{"text":"Say you'll handle it, so they never have to","then":"Your partner relaxes. Everything still depends on you being home."},{"text":"Change the subject so neither of you gets upset","then":"The moment passes, and your partner's plan is still to lose it."}],"why":"Agreeing a calm response in advance keeps either of you steady if the moment comes."},{"prompt":"Rahul's grandmother looks after him most afternoons. What do you do?","options":[{"text":"Share the key numbers with her too, simply","then":"She writes them in her diary and asks what Tele-MANAS is. You explain.","best":true},{"text":"Leave her out of it, so she doesn't worry","then":"She's the one at home at four o'clock, and she has no plan."},{"text":"Ask her to watch Rahul closely and report everything","then":"She starts questioning Rahul daily. He starts staying out till dinner."},{"text":"Assume she'd call you first anyway","then":"She would, but you're often in meetings with your phone on silent."}],"why":"Every carer who's home needs the numbers, so anyone can act quickly."},{"prompt":"A month later, you wonder whether the plan still holds. What do you do?","options":[{"text":"Run through it together over chai","then":"You go through it together, and both save 112 for emergencies too.","best":true},{"text":"Assume it's fine, since nothing has happened","then":"The plan fades a little more each week."},{"text":"Write a longer, more detailed plan on your own","then":"It's thorough, but no one else has read it."},{"text":"Quiz your partner and correct every mistake","then":"Your partner bristles and stops wanting to talk about it."}],"why":"A short, shared check-in keeps the plan fresh for everyone who might need it."}],"debrief":"A help plan only works if everyone caring for the child shares it: numbers saved, steps agreed.","relearn":"Share saved numbers and the calm-response plan with every carer, so anyone home can act."},
  {"id":"na-1353","cat":"tools-and-safety","type":"branch","persona":"Divya","source":"real route","hook":"Your friend Nandini says her son has barely left his room in weeks except for school, gaming all night.","steps":[{"prompt":"She asks you where she should even turn. What do you do?","options":[{"text":"Point her to Tele-MANAS 14416 and a counsellor","then":"Nandini saves the number and says she'll call after work.","best":true},{"text":"Tell her every family sorts this out on its own","then":"Nandini nods, and goes home to try harder alone."},{"text":"Suggest she throws the console out tonight","then":"Nandini says she's tried that twice. It didn't last a week."},{"text":"Say it's only a phase and he'll grow out of it","then":"Nandini looks relieved, and puts the worry aside for now."}],"why":"Dependence usually needs trained help, and Tele-MANAS 14416 and counsellors know what works."},{"prompt":"Nandini worries that asking for help means admitting she failed as a mother. What do you do?","options":[{"text":"Tell her it's a health issue, and asking is a strength","then":"Nandini's eyes fill. \"I needed to hear that,\" she says.","best":true},{"text":"Agree it's embarrassing, so she should keep it private","then":"Nandini decides to tell no one, not even her husband."},{"text":"Say it's really the father's job to deal with this","then":"Nandini sighs. Her husband works late, and nothing moves."},{"text":"Change the subject to spare her feelings","then":"Nandini goes quiet. The worry stays with her, unspoken."}],"why":"Dependence isn't a verdict on the parent, and asking for help models what you want a child to learn."},{"prompt":"A week later, Nandini texts: her son says he's fine and nobody needs to fix him. What do you do?","options":[{"text":"Say she can still get advice for herself","then":"Nandini calls. The counsellor offers to guide her until her son is ready.","best":true},{"text":"Tell her to force him into the car and take him","then":"Nandini tries. It ends in a shouting match on the stairs."},{"text":"Say there's nothing more she can do, then","then":"Nandini stops trying. Her son's door stays shut."},{"text":"Offer to go over and talk to her son yourself","then":"Her son is polite to you, and nothing changes."}],"why":"Parents can get guidance even before a child is ready, and family involvement helps."}],"debrief":"For a child's dependence, route to real help early: Tele-MANAS 14416 and a counsellor know what works.","relearn":"Dependence usually needs professional help; route early to Tele-MANAS 14416 and a counsellor."},
  {"id":"na-1354","cat":"tools-and-safety","type":"branch","persona":"Vikram","source":"calm response","hook":"You've found vape pods in your son Jai's bag, and money keeps going missing from your wallet.","steps":[{"prompt":"You're furious, and he's due home in an hour. What do you do?","options":[{"text":"Take a breath and plan a calm talk for tonight","then":"By the time Jai walks in, you know what you want to say, and how.","best":true},{"text":"Corner him angrily the second he walks in","then":"Jai denies everything, shouts back and locks himself in his room."},{"text":"Leave the pods on his bed so he knows you know","then":"Jai sees them, says nothing, and avoids you all evening."},{"text":"Call a friend and vent until he gets home","then":"You feel lighter, but have no plan, and snap at him anyway."}],"why":"A planned calm response keeps him reachable, where an ambush drives it underground."},{"prompt":"At dinner, Jai looks tense and barely eats. What do you do?","options":[{"text":"Afterwards, say what you found and ask to talk it through","then":"Jai goes quiet, then says the older boys at tuition all vape.","best":true},{"text":"Bring up the pods in front of the whole family","then":"Jai's sister gasps. Jai leaves the table without a word."},{"text":"Say nothing, and hope he raises it himself","then":"He doesn't. The evening ends with nothing said."},{"text":"Ask him lightly, at the table, whether anything's bothering him","then":"Jai says \"Nothing\" too fast, and changes the subject."}],"why":"Naming what you found, privately and without an ambush, gives him room to be honest."},{"prompt":"Later that week, you still don't know how much Jai is vaping. What do you do?","options":[{"text":"Call Tele-MANAS 14416 and keep talking with Jai","then":"The counsellor suggests how to talk about cravings without blame.","best":true},{"text":"Search his bag every morning before school","then":"Jai starts leaving his bag at a friend's house."},{"text":"Stop all his pocket money until he quits","then":"Jai says nothing. A week later, money goes missing again."},{"text":"Let it go, since vapes are safer than cigarettes","then":"Jai vapes more openly, and soon he's asking you for more money."}],"why":"Expert advice plus a calm, ongoing conversation works far better than policing him."},{"prompt":"Your partner wants to tell the extended family so they can keep an eye on Jai. What do you do?","options":[{"text":"Keep it private, and bring in a counsellor together","then":"Your partner hesitates, then agrees to come to the first session.","best":true},{"text":"Agree, since more eyes on him means he'll behave","then":"Soon every aunt has an opinion, and Jai stops coming to family lunches."},{"text":"Let your partner decide, to avoid a fight","then":"Your partner tells everyone. Jai finds out from a cousin."},{"text":"Tell your partner they're overreacting","then":"Your partner feels dismissed, and you both stop talking about Jai."}],"why":"Professional, family-inclusive help protects his dignity, where a family audience adds shame."}],"debrief":"Plan a calm, connected response. Cornering and shaming push dependence into hiding.","relearn":"A planned calm response keeps a child reachable; an angry confrontation drives it underground."},
  {"id":"na-1355","cat":"tools-and-safety","type":"branch","persona":"Kamla","source":"confidential help","hook":"Your daughter Pooja, 16, has been drinking, and you fear asking for help means police or gossip.","steps":[{"prompt":"You lie awake, unsure who you can safely tell. What do you do?","options":[{"text":"Ring Tele-MANAS 14416, a confidential health line","then":"The counsellor listens without judging and explains what help can look like.","best":true},{"text":"Stay silent so no one ever finds out","then":"Weeks pass. Pooja's drinking carries on, and you carry it alone."},{"text":"Confide in the neighbour you're closest to","then":"She's kind, but by Sunday the whole lane seems to know."},{"text":"Lock away every bottle and say nothing to Pooja","then":"Pooja finds drink elsewhere, and you still haven't talked."}],"why":"A confidential health line lets you get support quietly, and treats it as the health issue it is."},{"prompt":"At a family visit, Pooja's aunt smells drink on her and warns that any centre would shame the family. What do you do?","options":[{"text":"Explain it's a health issue, and treatment is care","then":"Her aunt frowns, but says she won't stand in the way.","best":true},{"text":"Agree, and keep Pooja away from any centre","then":"Pooja is kept away from any help, and her drinking goes on quietly."},{"text":"Stop speaking to the aunt altogether","then":"The family splits into sides, and the talk turns to the feud, not Pooja."},{"text":"Only consider a centre far away, where no one knows you","then":"You spend weeks searching for somewhere far enough. No help starts."}],"why":"Treating it as the health issue it is removes the shame that blocks help."},{"prompt":"Pooja asks if getting help means she'll be in trouble. What do you do?","options":[{"text":"Say it's about her health, and you'll be with her","then":"Pooja lets out a breath. \"Okay. Only if you come.\"","best":true},{"text":"Say she should have thought of that before drinking","then":"Pooja goes silent and refuses to talk about help."},{"text":"Promise that nobody will ever know anything, ever","then":"Pooja relaxes. You're not sure you can keep that promise."},{"text":"Tell her she'll be in trouble if she doesn't go","then":"Pooja goes, sullen, and says as little as possible."}],"why":"Framing help as care, and staying beside her, makes it feel safe to accept."}],"debrief":"Tele-MANAS 14416 is confidential health support. Reaching out is a strength, not exposure.","relearn":"Tele-MANAS 14416 gives confidential addiction and mental-health support; reaching out is a strength."},
  {"id":"na-1356","cat":"tools-and-safety","type":"branch","persona":"any","source":"save the numbers","hook":"Months ago you wrote the help numbers on a scrap of paper and put it somewhere safe.","steps":[{"prompt":"Today you search the kitchen drawer and can't find it anywhere. What do you do?","options":[{"text":"Save them in your phone and on the fridge today","then":"By evening, Tele-MANAS 14416, Childline 1098 and 112 are in your phone and on the fridge.","best":true},{"text":"Trust you'll remember them if it ever comes up","then":"A week later you try to recall them and get only 112."},{"text":"Write them on another scrap and tuck it in your wallet","then":"The new scrap is safer, but no one else at home knows it exists."},{"text":"Plan to look them up again when you have more time","then":"The weeks get busy, and the numbers stay unsaved."}],"why":"In a panicked moment memory fails, so numbers saved in advance are there when you need them."},{"prompt":"Your daughter sees you looking up helplines and asks if something's wrong. What do you do?","options":[{"text":"Say they're good numbers for any family to have","then":"She nods, and saves Tele-MANAS 14416 in her own phone too.","best":true},{"text":"Tell her it's nothing and quickly close the screen","then":"She shrugs, but looks at you a little uneasily."},{"text":"Say they're in case she or her brother gets into trouble","then":"She bristles. \"Why would we get into trouble?\""},{"text":"Tell her she's too young to worry about such things","then":"She goes back to her homework, curious and a little shut out."}],"why":"Talking openly about help numbers makes help-seeking normal for the whole family."},{"prompt":"A month later, you wonder if everyone at home could find the numbers in a hurry. What do you do?","options":[{"text":"Check that everyone at home has them saved","then":"Your partner hadn't. You save them together in two minutes.","best":true},{"text":"Assume they'd simply ask you if needed","then":"They would, but you're not always home when it matters."},{"text":"Keep the numbers to yourself so no one worries","then":"Only you know them, and you're out most evenings."},{"text":"Plan to sort it out if things ever get serious","then":"Things feel fine, so it never happens."}],"why":"Saved numbers only help if everyone at home can reach them in a hurry."}],"debrief":"Saved numbers belong on your phone and the fridge before they're needed, not on a lost scrap.","relearn":"Keep help numbers saved on your phone and fridge, ready before any crisis arrives."},
  {"id":"na-1357","cat":"tools-and-safety","type":"branch","persona":"Vikram","source":"stay involved","hook":"Your son Aditya, 17, has started counselling for his drinking. It took months to get here.","steps":[{"prompt":"After his first session, you wonder whether your part is done. What do you do?","options":[{"text":"Ask the counsellor how the family can be involved","then":"The counsellor invites you to a family session every two weeks.","best":true},{"text":"Hand it over to the counsellor and step back","then":"Aditya goes alone. At home, nobody mentions counselling at all."},{"text":"Ask Aditya to tell you everything said in each session","then":"Aditya stiffens. \"It's supposed to be private.\""},{"text":"Relax, since the hard part is clearly over","then":"You breathe easier. Aditya still has hard evenings you don't see."}],"why":"Family involvement strongly improves how recovery goes, so stay part of it."},{"prompt":"The counsellor asks both parents to a family session on a weekday. What do you do?","options":[{"text":"Take the time off and go together","then":"In the session, Aditya says evenings at home are when cravings hit hardest.","best":true},{"text":"Send your partner, since you can't miss work","then":"Your partner goes alone. Aditya notices you weren't there."},{"text":"Say you'll come once he's further along","then":"The counsellor nods. The first sessions go ahead without you."},{"text":"Go, but spend the session defending your parenting","then":"The session turns into an argument, and Aditya goes quiet."}],"why":"Showing up tells him you're in this with him, and helps the whole family learn what works."},{"prompt":"Some evenings, Aditya seems restless and on edge. What do you do?","options":[{"text":"Ask if he'd like a walk or a game of carrom","then":"Aditya shrugs, then says a walk might help. You go round the block twice.","best":true},{"text":"Remind him how much the counselling is costing","then":"Aditya's face shuts, and he goes to his room."},{"text":"Leave him alone, since that's what counselling is for","then":"He spends the evening alone and restless, on his phone."},{"text":"Ask him every hour whether he's had a drink","then":"By the third time, Aditya snaps and walks out."}],"why":"Offering your company and a healthy outlet helps on hard evenings, without policing him."},{"prompt":"Your own evening drink usually sits on the dinner table. What do you do?","options":[{"text":"Stop drinking at home while he recovers","then":"Aditya notices, and says quietly that it helps.","best":true},{"text":"Keep it, since it's your home and your choice","then":"Aditya watches your glass through dinner and leaves early."},{"text":"Keep drinking, but only after he's gone to bed","then":"Aditya still smells it, and finds the bottles in the cupboard."},{"text":"Tell him your drinking is different because you're an adult","then":"Aditya shrugs. \"Sure, Papa.\" He doesn't sound convinced."}],"why":"Your own habits are part of the picture. Changing them shows him he's not alone in this."},{"prompt":"Two months in, Aditya slips and comes home drunk after a friend's party. What do you do?","options":[{"text":"See he's safe, then talk calmly the next day","then":"Next day Aditya apologises, and you both raise it at the next session.","best":true},{"text":"Tell him the counselling was a waste of money","then":"Aditya stops going to his sessions for two weeks."},{"text":"Say nothing, so you don't upset his progress","then":"The slip goes unmentioned, and he feels he must hide the next one."},{"text":"Tell him you're done, and he's on his own now","then":"Aditya looks stricken, and stays out late the next night too."}],"why":"Slips are common in recovery. Staying calm and connected keeps him in treatment."}],"debrief":"Recovery isn't a drop-off; family involvement strongly improves outcomes, so keep showing up.","relearn":"Stay involved through treatment; family-inclusive help works better than leaving it to others."},
  {"id":"na-1358","type":"match","persona":"any","hook":"Match each situation to the right India route.","pairs":[{"left":"Needing to talk or find help","right":"Tele-MANAS 14416"},{"left":"A child in distress or danger","right":"Childline 1098"},{"left":"A possible overdose right now","right":"Emergency 112 or a hospital"},{"left":"Structured treatment over weeks","right":"A de-addiction counsellor"},{"left":"A calm question at 2am","right":"Tele-MANAS, open any time"}],"relearn":"Tele-MANAS 14416 for support, Childline 1098 for a child in danger, 112 for acute danger, a counsellor for treatment.","source":"route map","cat":"tools-and-safety"},
  {"id":"na-1359","type":"match","persona":"any","hook":"Match each tool to the job it does.","pairs":[{"left":"A signs-and-help-finder","right":"Knowing what to watch for"},{"left":"A calm-response plan","right":"Staying steady at discovery"},{"left":"Saved help lines","right":"Reaching support fast"},{"left":"A healthy outlet ready","right":"Something to offer, not just remove"},{"left":"A shared family plan","right":"Anyone home can act"}],"relearn":"The core kit is a signs-and-help-finder, a calm-response plan, saved lines, healthy outlets, and a shared plan.","source":"the kit","cat":"tools-and-safety"},
  {"id":"na-1360","type":"match","persona":"Vikram","hook":"Match each calm move to why it helps.","pairs":[{"left":"Saving numbers in advance","right":"No scrambling mid-crisis"},{"left":"Planning what you'll say","right":"You stay calm, not reactive"},{"left":"Agreeing the plan with your partner","right":"Either of you can respond"},{"left":"Knowing the acute-danger signs","right":"You spot when it's an emergency"},{"left":"Keeping the door open","right":"Your child stays reachable"}],"relearn":"Saving numbers, planning words, agreeing the plan, knowing danger signs and staying open all keep you ready and calm.","source":"why it helps","cat":"tools-and-safety"},
  {"id":"na-1361","type":"match","persona":"any","hook":"Match each worry to the calmer next step.","pairs":[{"left":"I don't know if it's serious","right":"Call Tele-MANAS 14416 to talk it through"},{"left":"He's in danger right now","right":"Childline 1098 or 112"},{"left":"I keep losing my temper","right":"A written calm-response plan"},{"left":"I can't do this alone","right":"A de-addiction counsellor"},{"left":"I forget the numbers","right":"Saved on phone and fridge"}],"relearn":"Every worry has a calmer step: a line to call, a plan to follow, a counsellor to lean on, numbers saved ready.","source":"worry to step","cat":"tools-and-safety"},
  {"id":"na-1362","type":"match","persona":"Kamla","hook":"Match each helpline to who it's for.","pairs":[{"left":"Tele-MANAS 14416","right":"Mental-health and addiction support"},{"left":"Childline 1098","right":"A child in distress or danger"},{"left":"Emergency 112","right":"Acute danger or a possible overdose"},{"left":"A de-addiction centre","right":"Assessment and structured treatment"},{"left":"A counsellor","right":"A steady plan over time"}],"relearn":"Tele-MANAS for support, Childline for a child in danger, 112 for emergencies, de-addiction and counsellors for treatment.","source":"who it's for","cat":"tools-and-safety"},
  {"id":"na-1363","type":"match","persona":"any","hook":"Match each part of a calm-response plan to its purpose.","pairs":[{"left":"A breath before you speak","right":"You answer, not react"},{"left":"A line you've rehearsed","right":"The words don't fail you"},{"left":"The saved number ready","right":"Help is one tap away"},{"left":"An agreement to stay close","right":"You don't cut off connection"},{"left":"A note of the danger signs","right":"You know when it's an emergency"}],"relearn":"A calm-response plan is a breath, a rehearsed line, a saved number, a promise to stay close, and known danger signs.","source":"plan parts","cat":"tools-and-safety"},
  {"id":"na-1364","type":"match","persona":"any","hook":"Match each line to whether it points toward help or away.","pairs":[{"left":"\"Let's call someone who knows\"","right":"Toward help"},{"left":"\"We'll handle it in secret\"","right":"Away from help"},{"left":"\"It's a health issue we can treat\"","right":"Toward care"},{"left":"\"He just needs more willpower\"","right":"Away from care"},{"left":"\"Let's get him to a counsellor\"","right":"Toward treatment"}],"relearn":"Naming it a treatable health issue and reaching out points toward help; secrecy and 'willpower' point away.","source":"toward or away","cat":"tools-and-safety"},
  {"id":"na-1365","type":"match","persona":"Divya","hook":"Match each step to the right time to do it.","pairs":[{"left":"Save the numbers","right":"Before any crisis"},{"left":"Plan your calm words","right":"In a quiet moment"},{"left":"Call 112","right":"The instant there's acute danger"},{"left":"Reach a counsellor","right":"Early, not after a crisis"},{"left":"Join family sessions","right":"All through recovery"}],"relearn":"Prepare in calm moments, call 112 the instant of acute danger, reach a counsellor early, and stay involved throughout.","source":"the right time","cat":"tools-and-safety"},
  {"id":"na-1366","type":"strike-rewrite","persona":"Vikram","hook":"\"Saving helpline numbers is overkill; I'll just search online if it ever happens.\"","myth":{"un":"Saving helpline numbers is overkill; I'll just search online if it ever happens.","re":"Save them now: in a frightening moment you won't have the calm to search, but a saved number is one tap away.","why":"Mid-crisis is the hardest time to plan, so the prep is done in advance."},"relearn":"Save help numbers in advance; in a crisis you won't have the calm to look them up.","source":"save in advance","cat":"tools-and-safety"},
  {"id":"na-1367","type":"strike-rewrite","persona":"any","hook":"\"If there's an overdose, I should wait and see before bothering anyone.\"","myth":{"un":"If there's an overdose, I should wait and see before bothering anyone.","re":"A possible overdose is an emergency: call 112 or get to a hospital at once, every time.","why":"Acute danger is never downplayed; fast medical help is what keeps a child safe."},"relearn":"A possible overdose is an emergency; call 112 or go to a hospital now, never wait and see.","source":"never wait","cat":"tools-and-safety"},
  {"id":"na-1368","type":"strike-rewrite","persona":"any","hook":"\"A help app or quiz can fix my child's dependence on its own.\"","myth":{"un":"A help app or quiz can fix my child's dependence on its own.","re":"Tools help you notice and respond, but treatment comes from counsellors and de-addiction services.","why":"Support tools point to real care; they don't replace it."},"relearn":"Help tools point you to care but don't replace it; counsellors and de-addiction services provide treatment.","source":"tools point to care","cat":"tools-and-safety"},
  {"id":"na-1369","type":"strike-rewrite","persona":"Kamla","hook":"\"Calling a helpline means the police get involved and I lose my child.\"","myth":{"un":"Calling a helpline means the police get involved and I lose my child.","re":"Tele-MANAS 14416 is confidential health support; it's there to help, not to punish you.","why":"It's framed as a treatable health issue, and reaching out is a strength."},"relearn":"Tele-MANAS 14416 is confidential health support, not punishment; reaching out is a strength.","source":"confidential not police","cat":"tools-and-safety"},
  {"id":"na-1370","type":"strike-rewrite","persona":"Vikram","hook":"\"I'll wait for a full-blown crisis before I bother getting help.\"","myth":{"un":"I'll wait for a full-blown crisis before I bother getting help.","re":"Get help early, before a crisis; earlier help gives the best chance, like with any health issue.","why":"Waiting for crisis lets a treatable problem grow harder to turn around."},"relearn":"Get help early, before a crisis; earlier support gives the best chance of recovery.","source":"help early","cat":"tools-and-safety"},
  {"id":"na-1371","type":"strike-rewrite","persona":"any","hook":"\"A calm-response plan is pointless; I'll just know what to do in the moment.\"","myth":{"un":"A calm-response plan is pointless; I'll just know what to do in the moment.","re":"Plan it now: a few decided steps keep you steady so the moment of discovery doesn't become a rupture.","why":"In the heat of discovery, fear takes over; a plan is what keeps you connected."},"relearn":"A calm-response plan keeps you steady so discovery doesn't become a rupture with your child.","source":"plan keeps you steady","cat":"tools-and-safety"},
  {"id":"na-1372","type":"strike-rewrite","persona":"Divya","hook":"\"Knowing one helpline is enough; the same number covers everything.\"","myth":{"un":"Knowing one helpline is enough; the same number covers everything.","re":"Know the route map: Tele-MANAS 14416 to talk, Childline 1098 for a child in danger, 112 for acute danger.","why":"Different situations need different routes, so knowing all three saves time when it counts."},"relearn":"Know all three routes: Tele-MANAS 14416 to talk, Childline 1098 for danger, 112 for acute danger.","source":"know the route map","cat":"tools-and-safety"},
  {"id":"na-1373","type":"sort","persona":"any","hook":"Sort: prepared before a crisis, or a risky gap?","items":[{"id":"a","text":"Helpline numbers saved on the fridge"},{"id":"b","text":"A calm-response plan you've thought through"},{"id":"c","text":"Both parents knowing the danger signs"},{"id":"d","text":"No idea who to call if it happens"},{"id":"e","text":"Assuming it'll never be your family"},{"id":"f","text":"Planning only once you're mid-panic"}],"bins":[{"id":"prep","label":"Prepared","valence":"pos"},{"id":"gap","label":"Risky gap","valence":"neg"}],"key":{"a":"prep","b":"prep","c":"prep","d":"gap","e":"gap","f":"gap"},"relearn":"Saved numbers, a plan and known signs are preparation; no plan and 'never us' denial are risky gaps.","source":"prepared or gap","cat":"tools-and-safety"},
  {"id":"na-1374","type":"sort","persona":"any","hook":"Sort: which line fits which need?","items":[{"id":"a","text":"Talk through a worry any time"},{"id":"b","text":"A child in distress or danger"},{"id":"c","text":"Addiction support over the phone"},{"id":"d","text":"A possible overdose right now"},{"id":"e","text":"Immediate danger to a child"},{"id":"f","text":"A medical emergency at home"}],"bins":[{"id":"manas","label":"Tele-MANAS 14416","valence":"neutral"},{"id":"child","label":"Childline 1098","valence":"neutral"},{"id":"emerg","label":"Emergency 112","valence":"neutral"}],"key":{"a":"manas","c":"manas","b":"child","e":"child","d":"emerg","f":"emerg"},"relearn":"Tele-MANAS 14416 to talk or for addiction support, Childline 1098 for a child in danger, 112 for a medical emergency.","source":"line for the need","cat":"tools-and-safety"},
  {"id":"na-1375","type":"sort","persona":"Vikram","hook":"Sort: a wise move in a serious moment, or one to avoid?","items":[{"id":"a","text":"Calling 112 for acute danger"},{"id":"b","text":"Reaching Tele-MANAS when unsure"},{"id":"c","text":"Staying calm and connected"},{"id":"d","text":"Hiding it to dodge embarrassment"},{"id":"e","text":"Punishing instead of getting help"},{"id":"f","text":"Waiting out a possible overdose"}],"bins":[{"id":"wise","label":"Wise move","valence":"pos"},{"id":"avoid","label":"To avoid","valence":"neg"}],"key":{"a":"wise","b":"wise","c":"wise","d":"avoid","e":"avoid","f":"avoid"},"relearn":"Calling for acute danger, reaching a line, and staying connected are wise; hiding, punishing and waiting it out aren't.","source":"wise or avoid","cat":"tools-and-safety"},
  {"id":"na-1376","type":"sort","persona":"any","hook":"Sort: belongs in your help kit, or doesn't belong?","items":[{"id":"a","text":"Saved helpline numbers"},{"id":"b","text":"A calm-response plan"},{"id":"c","text":"A counsellor's contact"},{"id":"d","text":"A secret you tell no one"},{"id":"e","text":"A threat to scare them straight"},{"id":"f","text":"A list of punishments"}],"bins":[{"id":"kit","label":"In the kit","valence":"pos"},{"id":"out","label":"Not in the kit","valence":"neg"}],"key":{"a":"kit","b":"kit","c":"kit","d":"out","e":"out","f":"out"},"relearn":"The help kit holds saved numbers, a calm plan and a counsellor; secrecy, threats and punishment lists don't belong.","source":"in the kit","cat":"tools-and-safety"},
  {"id":"na-1377","type":"sort","persona":"Kamla","hook":"Sort: act now, or this can wait?","items":[{"id":"a","text":"Your child collapsed and won't wake"},{"id":"b","text":"A possible overdose tonight"},{"id":"c","text":"Immediate danger to your child"},{"id":"d","text":"Booking a counsellor this week"},{"id":"e","text":"Reading up on signs tomorrow"},{"id":"f","text":"Planning a calm chat for Sunday"}],"bins":[{"id":"now","label":"Act now (112)","valence":"uhoh"},{"id":"plan","label":"Plan calmly","valence":"pos"}],"key":{"a":"now","b":"now","c":"now","d":"plan","e":"plan","f":"plan"},"relearn":"Collapse, a possible overdose and immediate danger mean act now on 112; counselling and calm chats are planned steps.","source":"now or plan","cat":"tools-and-safety"},
  {"id":"na-1378","type":"sort","persona":"any","hook":"Sort: each step into when you do it.","items":[{"id":"a","text":"Save the numbers"},{"id":"b","text":"Write your calm-response plan"},{"id":"c","text":"Learn the warning signs"},{"id":"d","text":"Call 112 for acute danger"},{"id":"e","text":"Reach a counsellor for ongoing help"},{"id":"f","text":"Join recovery sessions"}],"bins":[{"id":"before","label":"Prepare before","valence":"pos"},{"id":"during","label":"In the moment / after","valence":"tell"}],"key":{"a":"before","b":"before","c":"before","d":"during","e":"during","f":"during"},"relearn":"Save numbers, plan and learn signs beforehand; call 112 in the moment, then reach a counsellor and join recovery.","source":"when you do it","cat":"tools-and-safety"},
  {"id":"na-1379","type":"sort","persona":"Vikram","hook":"Sort: steadies you in the moment, or makes a rupture?","items":[{"id":"a","text":"Taking a breath before speaking"},{"id":"b","text":"Keeping the door open"},{"id":"c","text":"Leaning on your saved plan"},{"id":"d","text":"Shouting the second you find out"},{"id":"e","text":"Threatening to throw them out"},{"id":"f","text":"Cutting off all contact in anger"}],"bins":[{"id":"steady","label":"Steadies you","valence":"pos"},{"id":"rupture","label":"Makes a rupture","valence":"neg"}],"key":{"a":"steady","b":"steady","c":"steady","d":"rupture","e":"rupture","f":"rupture"},"relearn":"A breath, an open door and your plan steady you; shouting, threats and cutting off contact rupture the bond.","source":"steady or rupture","cat":"tools-and-safety"},
  {"id":"na-1380","type":"sort","persona":"any","hook":"Sort: a true help fact, or a myth to drop?","items":[{"id":"a","text":"Get help early, before a crisis"},{"id":"b","text":"Family involvement improves recovery"},{"id":"c","text":"Dependence is a treatable health issue"},{"id":"d","text":"You should fix it secretly, alone"},{"id":"e","text":"Wait for an overdose before acting"},{"id":"f","text":"Strong willpower is all it takes"}],"bins":[{"id":"true","label":"True","valence":"pos"},{"id":"myth","label":"Myth to drop","valence":"neg"}],"key":{"a":"true","b":"true","c":"true","d":"myth","e":"myth","f":"myth"},"relearn":"Early, family-inclusive help for a treatable health issue is true; secrecy, waiting for crisis and 'just willpower' are myths.","source":"true or myth","cat":"tools-and-safety"},
  {"id":"na-1381","type":"reflect","persona":"any","hook":"Lensy: the best time to save the helpline numbers is now, in a calm moment, not mid-crisis. Sit with that?","prompt":"What's your take?","options":["I'll save them now","Calm beats panic","Better ready than scrambling"],"affirm":"Saving Tele-MANAS 14416 and the others in a calm moment means they're there the instant you ever need them.","relearn":"Save your help numbers in a calm moment now; mid-crisis is the hardest time to find them.","source":"save them now","cat":"tools-and-safety"},
  {"id":"na-1382","type":"reflect","persona":"Kamla","hook":"Lensy: in any acute danger, getting help fast comes before any worry about shame or trouble. Clear?","prompt":"What do you feel?","options":["Safety first","Help before shame","Clear"],"affirm":"In acute danger, a child's safety and fast help always come before any worry about shame or what others think.","relearn":"In acute danger, get help fast; safety always comes before shame or worry.","source":"safety first","cat":"tools-and-safety"},
  {"id":"na-1383","type":"reflect","persona":"Vikram","hook":"Lensy: you can hold a firm limit and stay warmly connected at the same time. Does that land?","prompt":"What's your take?","options":["Both at once","Firm and close","That lands"],"affirm":"Being firm about the behaviour and unconditionally there for your child are not opposites; you can do both.","relearn":"You can be firm about the behaviour and warmly there for the child at the same time.","source":"firm and connected","cat":"tools-and-safety"},
  {"id":"na-1384","type":"reflect","persona":"any","hook":"Lensy: reaching out for help is a strength you're modelling, not a failure you're hiding. Feel that?","prompt":"What do you think?","options":["It's a strength","I'm modelling it","Feels right"],"affirm":"Asking for help models exactly the help-seeking you want your child to learn; it's a strength, not a failure.","relearn":"Reaching out for help is a strength and models the help-seeking you want your child to learn.","source":"asking is strength","cat":"tools-and-safety"},
  {"id":"na-1385","type":"reflect","persona":"Divya","hook":"Lensy: a calm-response plan isn't about being perfect; it's so the hard moment doesn't become a rupture. Okay?","prompt":"How does that sit?","options":["Not perfection","Steady, not scared","Okay"],"affirm":"A calm-response plan keeps you steady enough that the moment of discovery stays a conversation, not a rupture.","relearn":"A calm-response plan keeps you steady so discovery stays a conversation, not a rupture.","source":"not perfection","cat":"tools-and-safety"},
  {"id":"na-1386","type":"reflect","persona":"any","hook":"Lensy: you don't have to carry this alone; a counsellor and a helpline are on your team. Sit with it?","prompt":"What's your take?","options":["Not alone","Help is on my team","I'll lean on it"],"affirm":"Tele-MANAS 14416 and a de-addiction counsellor are on your team; you were never meant to carry this alone.","relearn":"You don't have to carry this alone; a helpline and a counsellor are there to share the load.","source":"not alone","cat":"tools-and-safety"},
  {"id":"na-1387","type":"reflect","persona":"any","hook":"Lensy: knowing all three routes means you waste no seconds deciding who to call. Worth it?","prompt":"What do you feel?","options":["Worth it","No seconds wasted","I'll learn all three"],"affirm":"Knowing Tele-MANAS 14416 to talk, Childline 1098 for danger and 112 for acute danger means no fumbling when it counts.","relearn":"Know all three routes so you waste no time deciding who to call when it matters.","source":"three routes","cat":"tools-and-safety"},
  {"id":"na-1388","type":"reflect","persona":"Vikram","hook":"Lensy: prepared, you can meet a hard discovery with care instead of panic. Does that steady you?","prompt":"What's your take?","options":["It steadies me","Care, not panic","Yes"],"affirm":"With the signs known, a plan ready and numbers saved, you can meet a hard moment with care, not panic.","relearn":"Being prepared lets you meet a hard discovery with care and calm instead of panic.","source":"care not panic","cat":"tools-and-safety"},
  {"id":"na-1389","type":"spot","persona":"any","hook":"Spot the two moves that would leave you unready in a crisis.","scene":[{"id":"a","text":"Numbers saved on your phone","trick":false},{"id":"b","text":"A calm-response plan written down","trick":false},{"id":"c","text":"\"I'll just figure it out in the moment\"","trick":true},{"id":"d","text":"Both carers knowing the signs","trick":false},{"id":"e","text":"\"It'll never happen to us\"","trick":true}],"why":"\"I'll figure it out in the moment\" and \"it'll never happen to us\" leave you unready; mid-crisis is the hardest time to plan.","relearn":"Prepare now: saved numbers, a written plan and known signs beat 'I'll figure it out' and 'never us'.","source":"unready moves","cat":"tools-and-safety"},
  {"id":"na-1390","type":"spot","persona":"Vikram","hook":"Spot the two responses that would push your child's problem underground.","scene":[{"id":"a","text":"A calm, planned talk","trick":false},{"id":"b","text":"Shouting and a sudden crackdown","trick":true},{"id":"c","text":"Keeping the door open","trick":false},{"id":"d","text":"Threatening to throw them out","trick":true},{"id":"e","text":"Reaching for help together","trick":false}],"why":"Shouting crackdowns and throw-them-out threats drive dependence into hiding; calm, connected responses keep a child reachable.","relearn":"Calm, connected responses keep a child reachable; crackdowns and threats push the problem underground.","source":"underground moves","cat":"tools-and-safety"},
  {"id":"na-1391","type":"spot","persona":"Kamla","hook":"Spot the two lines that delay the help your child needs.","scene":[{"id":"a","text":"\"Let's call Tele-MANAS to talk it through\"","trick":false},{"id":"b","text":"\"We'll keep this secret from everyone\"","trick":true},{"id":"c","text":"\"A counsellor can guide us\"","trick":false},{"id":"d","text":"\"He just needs more willpower\"","trick":true},{"id":"e","text":"\"It's a health issue we can treat\"","trick":false}],"why":"Secrecy and 'just willpower' delay real help; dependence is a treatable health issue that usually needs professional support.","relearn":"Reaching out and naming it a treatable health issue help; secrecy and 'just willpower' delay the care that works.","source":"delay lines","cat":"tools-and-safety"},
  {"id":"na-1392","type":"spot","persona":"any","hook":"Spot the two acute-danger signs that mean call 112 now.","scene":[{"id":"a","text":"Snappy and tired after a late night","trick":false},{"id":"b","text":"Unconscious and won't wake up","trick":true},{"id":"c","text":"Wanting more privacy lately","trick":false},{"id":"d","text":"Struggling to breathe after taking something","trick":true},{"id":"e","text":"Bored on a slow Sunday","trick":false}],"why":"Being unconscious or struggling to breathe after taking something is acute danger: call 112 or get to a hospital now.","relearn":"Unresponsive or struggling to breathe after taking something is an emergency; call 112 at once.","source":"call-now signs","cat":"tools-and-safety"},
  {"id":"na-1393","type":"spot","persona":"any","hook":"Spot the two things that don't belong in your calm-response plan.","scene":[{"id":"a","text":"A breath before you speak","trick":false},{"id":"b","text":"Saved help numbers","trick":false},{"id":"c","text":"A list of punishments ready","trick":true},{"id":"d","text":"A promise to stay connected","trick":false},{"id":"e","text":"A threat to scare them straight","trick":true}],"why":"A punishment list and a scare-them-straight threat aren't calm response; they cause rupture and drive the problem into hiding.","relearn":"A calm-response plan is a breath, saved numbers and staying connected, not punishments or threats.","source":"not in the plan","cat":"tools-and-safety"},
  {"id":"na-1394","type":"spot","persona":"Divya","hook":"Spot the two claims about getting help that are false.","scene":[{"id":"a","text":"Get help early, before a crisis","trick":false},{"id":"b","text":"Calling a health line gets the police involved","trick":true},{"id":"c","text":"Family involvement improves recovery","trick":false},{"id":"d","text":"An app alone can treat dependence","trick":true},{"id":"e","text":"A counsellor offers a steady plan","trick":false}],"why":"Tele-MANAS 14416 is confidential health support, not police; and tools point to care but an app can't replace treatment.","relearn":"Early, family-inclusive professional help works; a health line isn't police, and an app can't replace treatment.","source":"false claims","cat":"tools-and-safety"},
  {"id":"na-1395","type":"spot","persona":"any","hook":"Spot the two routes that would slow you down in a real emergency.","scene":[{"id":"a","text":"Call 112 for acute danger","trick":false},{"id":"b","text":"Search the web for a number first","trick":true},{"id":"c","text":"Go straight to a hospital","trick":false},{"id":"d","text":"Wait to see if it passes","trick":true},{"id":"e","text":"Use the number already saved","trick":false}],"why":"Searching from scratch or waiting it out wastes time in acute danger; call 112 or use a saved number and go now.","relearn":"In acute danger, call 112 or use a saved number now; searching from scratch or waiting wastes vital time.","source":"slow routes","cat":"tools-and-safety"},
  {"id":"na-1396","cat":"tools-and-safety","type":"role-play","persona":"Vikram","source":"ready numbers","hook":"Your partner Shalini agrees you need the help numbers, but wants them kept \"somewhere safe\".","setup":"She's holding the slip you wrote them on.","steps":[{"prompt":"Shalini says: \"I'll put this in the cupboard with the documents.\"","options":[{"text":"\"Let's save them in both our phones and on the fridge tonight.\"","then":"Shalini hesitates. \"The fridge? Everyone will see them.\"","best":true},{"text":"\"Good idea. We'll find them if we ever really need them.\"","then":"Shalini tucks the slip away. \"There. Safe.\""},{"text":"\"Give it to me. I'll keep it in my wallet.\"","then":"Shalini hands it over. \"Fine. Your job, then.\""},{"text":"\"Actually, let's just search online if it ever comes to that.\"","then":"Shalini shrugs and drops the slip in the drawer."}],"why":"Numbers in both phones and on the fridge are there the instant anyone needs them."},{"prompt":"Shalini asks: \"Should the children know about these numbers at all?\"","options":[{"text":"\"Yes. It shows them asking for help is normal.\"","then":"Shalini thinks. \"Okay. As long as we explain it calmly.\"","best":true},{"text":"\"No. Let's keep them where the children can't see.\"","then":"Shalini nods. \"Better safe than scared.\""},{"text":"\"Yes. A little fear might keep them in line.\"","then":"Shalini frowns. \"That's not what these numbers are for.\""},{"text":"\"We just won't tell them what the numbers are for.\"","then":"Shalini laughs. \"They'll ask anyway, you know.\""}],"why":"Seeing help numbers openly teaches children that asking for help is normal and strong."},{"prompt":"Shalini asks: \"What about my mother? She's here most afternoons.\"","options":[{"text":"\"Let's save them in her phone too, and show her.\"","then":"Shalini smiles. \"She'll want them written big.\"","best":true},{"text":"\"Leave her out of it. She'll only fuss.\"","then":"Shalini shrugs. \"Fine. I hope nothing happens while she's here.\""},{"text":"\"She can just call one of us if anything happens.\"","then":"Shalini hesitates. \"And if we don't pick up?\""},{"text":"\"Let's tell her everything we're worried about, in detail.\"","then":"Shalini winces. \"She'll tell the whole family by Sunday.\""}],"why":"Everyone who cares for the children needs the numbers ready, not just the two of you."}],"relearn":"Save help numbers in both phones and on the fridge now, so they're ready before any crisis."},
  {"id":"na-1397","cat":"tools-and-safety","type":"role-play","persona":"Kamla","source":"make the call","hook":"Friends have brought your son Gopal, 15, home after drinking, and he can barely respond.","setup":"Your brother-in-law is standing over him.","steps":[{"prompt":"Your brother-in-law says: \"Let him sleep. He'll be fine by morning.\"","options":[{"text":"\"This is an emergency. I'm calling 112 now.\"","then":"He steps back. \"Okay, okay. Call.\"","best":true},{"text":"\"Maybe you're right. Let's give it a little while.\"","then":"He nods. An hour later Gopal is harder to rouse, and you call 112."},{"text":"\"Help me get him to bed, and I'll sit with him.\"","then":"You sit beside Gopal. He isn't waking, and fear makes you call 112."},{"text":"\"Let me call his friends and ask what he drank.\"","then":"The friends don't answer. Minutes pass before you call 112."}],"why":"When a child can barely respond, it's an emergency. Calling 112 at once can't wait."},{"prompt":"While you wait, your brother-in-law says: \"Don't tell them he was drinking. People will talk.\"","options":[{"text":"\"The doctors need the truth. I'm telling them.\"","then":"He sighs. \"Fine. His health comes first.\"","best":true},{"text":"\"You're right. I'll say he just fainted.\"","then":"He nods, relieved. The doctors will have less to go on."},{"text":"\"I'll decide what to tell them when they get here.\"","then":"He shrugs. The question is still hanging when the ambulance arrives."},{"text":"\"I'll tell them, and I'll tell them whose fault it is.\"","then":"He bristles. \"So now it's my fault?\""}],"why":"Telling doctors the truth helps them treat him fast. His health matters more than gossip."},{"prompt":"At the hospital, a nurse says: \"He'll be okay. Has this happened before?\"","options":[{"text":"\"I'm not sure. Where can we get support after this?\"","then":"The nurse writes down Tele-MANAS 14416 and a de-addiction clinic nearby.","best":true},{"text":"\"Never. He's a good boy. This was just bad luck.\"","then":"The nurse nods and writes down \"first time\"."},{"text":"\"It won't happen again. I'll make sure of that.\"","then":"The nurse nods. \"If it does, come straight back.\""},{"text":"\"Please don't write any of this down anywhere.\"","then":"The nurse pauses. \"It helps his care if we do.\""}],"why":"After an emergency, asking for follow-up support treats it as the health issue it is."}],"relearn":"In acute danger, treat it as an emergency: call 112 and go to a hospital now, no waiting."},
  {"id":"na-1398","cat":"tools-and-safety","type":"role-play","persona":"any","source":"steer to help","hook":"Your neighbour Lakshmi quietly tells you that her son Karthik has started using.","setup":"You're both waiting for the milk van.","steps":[{"prompt":"Lakshmi whispers: \"Please don't tell anyone. I'd die of shame.\"","options":[{"text":"\"I won't. But it's a health issue, not a disgrace.\"","then":"Lakshmi looks up. \"You don't think we've failed?\"","best":true},{"text":"\"Best to keep it quiet, so no one judges you.\"","then":"Lakshmi nods. \"Yes. We'll manage it ourselves somehow.\""},{"text":"\"Of course. Honestly, I'd feel just as ashamed in your place.\"","then":"Lakshmi sighs. \"So you see why I can't tell anyone.\""},{"text":"\"Which boys is he with? I'll warn my children.\"","then":"Lakshmi pulls back. \"Please don't spread it.\""}],"why":"Keeping her confidence while lifting the shame helps her see that help is possible."},{"prompt":"Lakshmi says: \"His father says we just need to be much stricter with him.\"","options":[{"text":"\"Strictness alone often drives it underground.\"","then":"Lakshmi frowns. \"Then what else is there?\"","best":true},{"text":"\"Maybe his father is right. Boys need a firm hand.\"","then":"Lakshmi nods slowly. \"I suppose so.\""},{"text":"\"Stay out of it, and let his father deal with it.\"","then":"Lakshmi looks lost. \"And I just watch?\""},{"text":"\"Send Karthik to relatives in the village for a while.\"","then":"Lakshmi considers it. \"Out of sight, at least.\""}],"why":"Crackdowns tend to push dependence underground, where calm help keeps him reachable."},{"prompt":"The next morning, Lakshmi says: \"He came home at two again. But a hospital scares me.\"","options":[{"text":"\"Tele-MANAS 14416 is a calm place to start. You just talk.\"","then":"Lakshmi repeats the number under her breath.","best":true},{"text":"\"A hospital is the only option, so you'll have to face it.\"","then":"Lakshmi goes pale. \"Then maybe not yet.\""},{"text":"\"Try a strict hostel for him, far away from those friends.\"","then":"Lakshmi looks unsure. \"Would he even agree?\""},{"text":"\"Just keep him at home until it passes.\"","then":"Lakshmi sighs. \"He goes out anyway.\""}],"why":"A confidential phone line makes the first step small, so it's easier to take."},{"prompt":"A week later, Lakshmi says: \"Karthik is worse. I want help, but I'm scared of being judged.\"","options":[{"text":"\"Shall I sit with you while you ring Tele-MANAS 14416?\"","then":"Lakshmi hesitates, then nods. \"Tomorrow morning, after he leaves.\"","best":true},{"text":"\"Then don't ask anyone. It's your family's business.\"","then":"Lakshmi nods, relieved and still stuck."},{"text":"\"You have to get help today, or it's on you.\"","then":"Lakshmi's eyes fill. \"I know. I'm a terrible mother.\""},{"text":"\"Give me Karthik's number. I'll talk sense into him.\"","then":"Lakshmi hesitates. \"He'll know I told you.\""}],"why":"Offering to be beside her respects her pace and makes the first call feel possible."}],"relearn":"Dependence is a treatable health issue; Tele-MANAS 14416 is a confidential, calm place to start, not a disgrace."},
  {"id":"na-1399","cat":"tools-and-safety","type":"role-play","persona":"Vikram","source":"calmer plan","hook":"You and your partner Meenakshi suspect your son Rishi, 16, is using something.","setup":"She's been searching his room all afternoon.","steps":[{"prompt":"Meenakshi says: \"The moment I find proof, we come down hard. No phone, no friends, nothing.\"","options":[{"text":"\"A crackdown will push him away. Let's keep him close.\"","then":"Meenakshi stops. \"So we just let it slide?\"","best":true},{"text":"\"Fine. Let's come down hard on him and scare him out of it.\"","then":"Meenakshi nods. \"Good. I'll keep looking.\""},{"text":"\"Stop searching. You'll never find anything anyway.\"","then":"Meenakshi glares. \"Then what do you suggest?\""},{"text":"\"Let's wait and see what you find first.\"","then":"Meenakshi keeps opening drawers. \"Fine. But then no mercy.\""}],"why":"Crackdowns drive dependence underground; staying close keeps him reachable."},{"prompt":"Meenakshi sits on his bed and says: \"My sister says we should just talk to him. Is that enough?\"","options":[{"text":"\"Talk calmly, together, and then get the right help.\"","then":"Meenakshi hesitates. \"What help, though?\"","best":true},{"text":"\"Yes. Talking is enough. No need for anyone else.\"","then":"Meenakshi shrugs. \"If you say so.\""},{"text":"\"Let's take his phone quietly and read his chats.\"","then":"Meenakshi considers it. \"At least then we'd know.\""},{"text":"\"Let's scare him with stories of boys who ended up in jail.\"","then":"Meenakshi winces. \"Would that even work?\""}],"why":"A calm talk opens the door, and professional help gives him the best chance."},{"prompt":"Meenakshi says: \"What if he denies everything?\"","options":[{"text":"\"Then we stay calm and call Tele-MANAS 14416 anyway.\"","then":"Meenakshi nods slowly. \"Okay. I'll save the number.\"","best":true},{"text":"\"Then we keep searching until we find proof.\"","then":"Meenakshi nods. \"That's what I've been saying.\""},{"text":"\"Then we give him an ultimatum: tell us, or leave.\"","then":"Meenakshi hesitates. \"Leave? He's sixteen.\""},{"text":"\"Then we believe him and drop the whole thing.\"","then":"Meenakshi frowns. \"Even with everything we've seen?\""}],"why":"You can get advice even before he's ready to talk, and calm keeps him reachable."}],"relearn":"Crackdowns drive dependence underground; stay calm, keep the child close and get the right help."},
  {"id":"na-1400","cat":"tools-and-safety","type":"role-play","persona":"any","source":"agree the plan","hook":"At a family meeting, you're setting out what everyone should do if a child is ever in danger.","setup":"Your mother-in-law, partner and elder daughter are listening.","steps":[{"prompt":"Your mother-in-law asks: \"Why plan for trouble? It's bad luck to talk about it.\"","options":[{"text":"\"Planning keeps us calm if it happens. It's care.\"","then":"She purses her lips. \"Well, if it keeps the children safe.\"","best":true},{"text":"\"Okay. We'll work it out if it ever comes up.\"","then":"She nods, satisfied. The meeting drifts to wedding plans."},{"text":"\"With respect, that's superstition, and it's dangerous.\"","then":"She bristles. \"So now I'm the problem?\""},{"text":"\"Fine. Let's keep it between my partner and me, then.\"","then":"She nods. Your daughter looks curious, then left out."}],"why":"A plan made while calm means no hesitation later, and that is care, not bad luck."},{"prompt":"Your daughter asks: \"What if someone just won't wake up?\"","options":[{"text":"\"That's acute danger. We call 112 or go to hospital.\"","then":"Your daughter nods. \"112. No waiting.\"","best":true},{"text":"\"Call me at work first, and I'll decide what we should do.\"","then":"Your daughter frowns. \"And if you don't pick up?\""},{"text":"\"Let them sleep it off. They'll be fine by morning.\"","then":"Your daughter looks unsure. \"Are you sure?\""},{"text":"\"Call the family doctor, and do whatever he says.\"","then":"Your daughter frowns. \"What if his clinic is closed?\""}],"why":"Someone who can't be woken is in acute danger, so it's 112 or a hospital at once."},{"prompt":"Your partner asks: \"And if it's not an emergency, but we're worried?\"","options":[{"text":"\"We call Tele-MANAS 14416 and talk it through.\"","then":"Your partner writes 14416 on a note and sticks it on the fridge.","best":true},{"text":"\"We keep it among ourselves. No outsiders.\"","then":"Your mother-in-law nods firmly. \"Family matters stay in the family.\""},{"text":"\"We wait until it turns into an emergency.\"","then":"Your partner frowns. \"That seems very late.\""},{"text":"\"We ask the neighbours what they would do.\"","then":"Your partner laughs. \"And tell the whole building?\""}],"why":"Knowing which number fits which worry keeps everyone calm and quick."}],"relearn":"Agree the emergency plan in advance: in acute danger, call 112 or go to a hospital with no hesitation."},
  {"id":"na-1401","cat":"tools-and-safety","type":"role-play","persona":"Divya","source":"next step","hook":"You've noticed worrying signs in your son Arjun, 14, but you're running on empty.","setup":"Your sister Anu calls to check in.","steps":[{"prompt":"Anu asks: \"You sound done in. What's going on?\"","options":[{"text":"\"I'm worried about Arjun's gaming, and I'm exhausted.\"","then":"Anu's voice softens. \"Tell me. What have you noticed?\"","best":true},{"text":"\"Nothing. Just a long week. How are you?\"","then":"Anu chats about her week, then pauses. \"You still sound tired, though.\""},{"text":"\"Arjun's impossible. I've given up on him.\"","then":"Anu pauses. \"Given up? That doesn't sound like you.\""},{"text":"\"I'm fine. I'll deal with it when things calm down.\"","then":"Anu says, \"Okay, if you're sure.\" The call moves on."}],"why":"Naming your worry to someone you trust is the first step to getting support."},{"prompt":"Anu says: \"You always look after everyone. Who looks after you?\"","options":[{"text":"\"Not many. Maybe I need to ask for help too.\"","then":"Anu laughs. \"Start with me. Then maybe a helpline?\"","best":true},{"text":"\"No one. That's just how it is in this house.\"","then":"Anu sighs. \"It doesn't have to be.\""},{"text":"\"I don't need looking after. I'll manage somehow.\"","then":"Anu pauses. \"You don't have to do it all alone.\""},{"text":"\"Once Arjun is sorted, I'll think about me.\"","then":"Anu laughs softly. \"That day never comes, you know.\""}],"why":"Looking after yourself is part of helping your child, not something to put off."},{"prompt":"Anu asks: \"So what's one thing you'll actually do this week?\"","options":[{"text":"\"I'll call Tele-MANAS 14416 and talk it through.\"","then":"Anu says, \"Text me after you call. I mean it.\"","best":true},{"text":"\"I'll just hope it sorts itself out.\"","then":"Anu pauses. \"And if it doesn't?\""},{"text":"\"I'll take his console away and be done with it.\"","then":"Anu hesitates. \"And then what happens?\""},{"text":"\"I'll read up online after he's asleep.\"","then":"Anu sighs. \"You'll be up till two again.\""}],"why":"Even when you're depleted, one small call gets you real support, any time."},{"prompt":"Anu asks: \"Want me to come over this weekend?\"","options":[{"text":"\"Yes, please. I could use the help.\"","then":"\"Saturday, then,\" Anu says. \"I'll bring lunch.\"","best":true},{"text":"\"No, no. I don't want to be a bother.\"","then":"Anu sighs. \"You're never a bother.\""},{"text":"\"Only if you'll talk some sense into Arjun.\"","then":"Anu hesitates. \"I'd rather help you than lecture him.\""},{"text":"\"Maybe later, once things are under control.\"","then":"Anu says, \"Okay. The offer stands.\""}],"why":"Accepting support keeps you steady enough to support your child."}],"relearn":"Even when depleted, reach out: Tele-MANAS 14416 is there any time to talk a worry through."},
  {"id":"na-1402","cat":"tools-and-safety","type":"role-play","persona":"Kamla","source":"reassure","hook":"Your daughter Seema, 16, has admitted she's been drinking to get through the nights.","setup":"She sits close to you on the mat, knees pulled up.","steps":[{"prompt":"Seema says: \"I don't want help. They'll call the police, and I'll be in trouble.\"","options":[{"text":"\"You're not in trouble. Getting you well comes first.\"","then":"Seema looks up. \"Really? You're not angry?\"","best":true},{"text":"\"There'll be consequences, but fine, we'll see about help.\"","then":"Seema shrinks. \"Then I'd rather not.\""},{"text":"\"Nobody will call the police if you just stop on your own.\"","then":"Seema nods quickly. \"Okay. I'll stop. No help.\""},{"text":"\"You should have thought of trouble before you started.\"","then":"Seema turns away. \"I knew I shouldn't have told you.\""}],"why":"Leading with safety and care, not trouble, makes it possible for her to accept help."},{"prompt":"Seema asks: \"What if people at school find out?\"","options":[{"text":"\"Tele-MANAS 14416 is private. We choose who knows.\"","then":"Seema breathes out. \"So nobody has to know?\"","best":true},{"text":"\"They won't, as long as you stop and keep it quiet.\"","then":"Seema nods. \"Then I'll just hide it better.\""},{"text":"\"If they do, that's the price of what you did.\"","then":"Seema goes silent and stares at the floor."},{"text":"\"Who cares what they think? Stop worrying about it.\"","then":"Seema frowns. \"I care. That's the whole point.\""}],"why":"Knowing help can be private eases a real fear, so she can say yes to it."},{"prompt":"Seema says: \"I only drink because I can't sleep. Home is so loud at night.\"","options":[{"text":"\"What makes it loud? Do you feel safe at home?\"","then":"Seema nods. \"I'm safe. It's just crowded, and I never get any quiet.\"","best":true},{"text":"\"Don't blame home. Other girls your age manage just fine.\"","then":"Seema goes quiet. \"Forget it.\""},{"text":"\"Then just put earphones in and try to ignore it.\"","then":"Seema shrugs. \"I've tried. It doesn't help.\""},{"text":"\"Home is fine. Don't make things up to excuse it.\"","then":"Seema's face closes. \"Okay.\""}],"why":"Asking gently what's behind it, and whether she's safe, shows her the whole picture matters."},{"prompt":"Next morning, Seema asks: \"Are you sure you're not ashamed of me?\"","options":[{"text":"\"I'm proud you told me. We'll face this together.\"","then":"Seema leans against your shoulder. \"Okay. Let's get help, then.\"","best":true},{"text":"\"I'll be proud once you've stopped completely.\"","then":"Seema's face falls. \"So not now.\""},{"text":"\"Let's not talk about shame. Just don't do it again.\"","then":"Seema nods, and says nothing more."},{"text":"\"A little. But I'll get over it in time.\"","then":"Seema looks away, blinking hard."}],"why":"Unconditional support, alongside help, keeps a child honest and hopeful."}],"relearn":"Lead with safety and connection: help and well-being come first, not trouble or punishment."},
  {"id":"na-1403","cat":"tools-and-safety","type":"role-play","persona":"Vikram","source":"not willpower","hook":"Your son Kunal, 18, has started counselling for his drinking, and the wider family has heard.","setup":"At Sunday lunch, Mohan chacha puts down his spoon.","steps":[{"prompt":"Mohan chacha says: \"Counselling is a waste. In our day, willpower was enough.\"","options":[{"text":"\"It's not about willpower. It's a health issue.\"","then":"Chacha raises an eyebrow. \"Health? He just drinks too much.\"","best":true},{"text":"\"Maybe you're right. Let's just tell him to try harder.\"","then":"Chacha nods, satisfied. \"See? Simple.\""},{"text":"\"Please, not at lunch. Let's talk about something else.\"","then":"Chacha shrugs and moves on. Kunal stares at his plate."},{"text":"\"You drank plenty yourself, so don't lecture us.\"","then":"Chacha's face darkens. The table goes silent."}],"why":"Dependence changes the brain, so willpower isn't enough. Counsellors know what works, and recovery is real."},{"prompt":"After lunch, chacha says: \"Kunal is weak. That's the real problem.\"","options":[{"text":"\"He's not weak. Any of us could struggle with this.\"","then":"Chacha pauses. \"Hmm. Maybe.\" Kunal glances up.","best":true},{"text":"\"You're right. He's always been the soft one.\"","then":"Kunal leaves the room without a word."},{"text":"\"Let's not discuss Kunal while he's sitting right here.\"","then":"Chacha nods. Kunal has still heard every word."},{"text":"\"Say that again and you're not welcome in this house.\"","then":"Chacha pushes back his chair, offended. \"Fine. But answer me this.\""}],"why":"Pushing back on \"weak\" removes the stigma that stops people getting help."},{"prompt":"Chacha takes you aside and asks: \"So what, the family just sits back while doctors fix him?\"","options":[{"text":"\"No. We stay involved. Family support really matters.\"","then":"Chacha thinks. \"What could I even do?\"","best":true},{"text":"\"Yes. It's the counsellor's job now, not ours.\"","then":"Chacha shrugs. \"Then why make such a fuss?\""},{"text":"\"No. We watch him closely and report every slip.\"","then":"Chacha nods approvingly, already planning to check up on Kunal himself."},{"text":"\"Honestly, I don't know. Let's just leave it.\"","then":"Chacha shrugs. The question hangs in the air."}],"why":"Family involvement strongly improves outcomes, so everyone has a part to play."}],"relearn":"Dependence is a treatable health issue, not a willpower test; a counsellor knows what works."},
  {"id":"na-1404","cat":"tools-and-safety","type":"role-play","persona":"any","source":"begin the call","hook":"You're calling a de-addiction counsellor for the first time about your son Yash, and your voice shakes.","setup":"The phone is answered on the second ring.","steps":[{"prompt":"The counsellor says: \"Hello. How can I help you today?\"","options":[{"text":"\"I'm worried about my son, and I'd like some guidance.\"","then":"\"Of course. Take your time. Tell me what's been happening.\"","best":true},{"text":"\"Sorry to bother you. It's probably nothing.\"","then":"\"It's no bother. Would you tell me a little anyway?\""},{"text":"\"My son is an addict, and I don't know what to do with him.\"","then":"The counsellor pauses. \"Let's start with what you've noticed.\""},{"text":"\"I just need a place to send him away for a few months.\"","then":"\"Let's first understand what's going on. Tell me more.\""}],"why":"Saying plainly that you're worried and want guidance is how help begins."},{"prompt":"The counsellor asks: \"What have you noticed that worries you?\"","options":[{"text":"\"He barely sleeps or eats, and he's always out.\"","then":"\"Thank you. How long has that been going on?\"","best":true},{"text":"\"Everything. He's completely out of control.\"","then":"\"That sounds frightening. Can you tell me one specific thing?\""},{"text":"\"I'd rather not say too much on the phone.\"","then":"\"That's alright. Even a little helps me understand.\""},{"text":"\"His friends are the problem. Can you talk to them?\"","then":"\"I can't reach them, but I can help you. What have you seen in him?\""}],"why":"Specific changes over time help a counsellor understand the whole picture."},{"prompt":"The counsellor asks: \"How have you been responding so far?\"","options":[{"text":"\"Honestly, not very well. Can you guide me?\"","then":"\"Of course. Let's plan a calm first talk together.\"","best":true},{"text":"\"I've taken everything away from him. He'll learn.\"","then":"\"I see. Has that made him more open with you?\""},{"text":"\"I haven't said anything. I don't want a fight.\"","then":"\"I understand. What worries you about a fight?\""},{"text":"\"I've been checking his phone every night.\"","then":"\"That's understandable. How would he feel if he knew?\""}],"why":"Being honest about how it's going, and asking for guidance, lets the counsellor help you respond well."},{"prompt":"The counsellor says: \"It would help if the family came in together.\"","options":[{"text":"\"Yes. We'll come. What should we tell Yash?\"","then":"\"Tell him it's to help the family, not to punish him.\"","best":true},{"text":"\"Can't you just see him on his own?\"","then":"\"I can, but family involvement makes a big difference.\""},{"text":"\"Do we have to? Our family doesn't talk about these things.\"","then":"\"Many families feel that. Coming in together is often where it starts to change.\""},{"text":"\"We're very busy. Maybe after his exams are over.\"","then":"\"I understand. Earlier usually helps more, though.\""}],"why":"Family-inclusive help works far better than leaving the child to do it alone."},{"prompt":"Before hanging up, the counsellor asks: \"Is anything else worrying you?\"","options":[{"text":"\"Yes. I feel like I've failed him.\"","then":"\"You haven't. Reaching out is a strength. Let's talk about support for you too.\"","best":true},{"text":"\"No, nothing. I'm fine, really.\"","then":"\"Alright. You can call back any time you need.\""},{"text":"\"Only whether you can promise he'll be fine.\"","then":"\"I can't promise, but recovery is real and common with support.\""},{"text":"\"Just tell me what I did wrong as a parent.\"","then":"\"This isn't about blame. Let's focus on what helps now.\""}],"why":"Your wellbeing matters too, and naming how you feel lets the counsellor support you."}],"relearn":"Reaching out for guidance is a strength; a counsellor is there to help you and your child."},
  {"id":"na-1405","cat":"tools-and-safety","type":"role-play","persona":"Divya","source":"better way","hook":"You and your partner Sameer have just learned that your daughter Aisha has been vaping.","setup":"He sits on the edge of the bed, keeping his voice low.","steps":[{"prompt":"Sameer says: \"We'll handle this ourselves. No counsellors, no outsiders.\"","options":[{"text":"\"Doing it alone rarely works. Let's get a counsellor.\"","then":"Sameer frowns. \"A stranger, in our business?\"","best":true},{"text":"\"Okay. We'll keep it between the two of us and tell no one.\"","then":"Sameer nods, relieved. \"Good. It stays in this room.\""},{"text":"\"Fine, but only until it gets really bad.\"","then":"Sameer nods. \"Agreed. We'll know when.\""},{"text":"\"You're only worried about what people will say.\"","then":"Sameer stiffens. \"That's not fair.\""}],"why":"Dependence usually needs professional help, and secrecy delays what works."},{"prompt":"Sameer says: \"If word gets out, people will talk about her for years.\"","options":[{"text":"\"Counselling is confidential. Her health matters more.\"","then":"Sameer rubs his forehead. \"Confidential? You're sure?\"","best":true},{"text":"\"You're right. Her reputation has to come first.\"","then":"Sameer nods. \"Exactly. We protect her name.\""},{"text":"\"Let them talk. Who cares what people say?\"","then":"Sameer shakes his head. \"I care. So will she.\""},{"text":"\"Then let's find someone in another city, to be safe.\"","then":"Sameer considers it. \"That might take months.\""}],"why":"Confidential help protects both her health and her privacy."},{"prompt":"Sameer asks: \"And what do we tell Aisha?\"","options":[{"text":"\"That we love her, and we'll get help together.\"","then":"Sameer nods slowly. \"Together. Okay.\"","best":true},{"text":"\"That she's embarrassed us, and it has to stop.\"","then":"Sameer hesitates. \"That might make her hide it.\""},{"text":"\"Nothing yet. Let's watch her quietly for a few weeks first.\"","then":"Sameer shrugs. \"For how long, though?\""},{"text":"\"That we're taking her phone until she quits.\"","then":"Sameer nods. \"At least that's clear.\""}],"why":"Telling her you love her and will help together keeps her willing to accept it."},{"prompt":"Later, Sameer admits: \"If we did see someone, I'd be scared they'd blame us.\"","options":[{"text":"\"No. They'll help us help her.\"","then":"Sameer exhales. \"Okay. Book it. I'll come too.\"","best":true},{"text":"\"Probably. We must have done something wrong.\"","then":"Sameer's face falls. \"Then maybe we shouldn't go.\""},{"text":"\"Who cares? We don't have to listen to them.\"","then":"Sameer frowns. \"Then why go at all?\""},{"text":"\"You go. I can't face it.\"","then":"Sameer looks at you. \"Then neither can I.\""}],"why":"Counsellors work with families, not against them, and family involvement makes a real difference."}],"relearn":"Handling dependence secretly alone usually isn't enough; bring in professional, family-inclusive help."},
  {"id":"na-1406","cat":"tools-and-safety","type":"role-play","persona":"Vikram","source":"commit to them","hook":"Your son Zubin, 14, starts counselling for his gaming next week.","setup":"At bedtime, he lingers at your door.","steps":[{"prompt":"Zubin asks: \"Once I'm fixed, will you stop caring about all this?\"","options":[{"text":"\"I'm in this for the long haul. Good days and hard ones.\"","then":"Zubin leans on the door frame. \"Even if it takes ages?\"","best":true},{"text":"\"Once the counsellor takes over, you're on your own with it.\"","then":"Zubin nods slowly. \"Right. Got it.\""},{"text":"\"Of course. That's the whole point of the counselling.\"","then":"Zubin looks away. \"Okay.\""},{"text":"\"There's nothing to fix if you'd just play less.\"","then":"Zubin frowns. \"It's not that simple.\""}],"why":"Promising to stay through the long haul gives him the steady support that helps recovery last."},{"prompt":"Zubin asks: \"What if I mess up and play all night again?\"","options":[{"text":"\"Then we talk and keep going. I won't give up.\"","then":"Zubin exhales. \"Okay. That helps.\"","best":true},{"text":"\"Then the console goes, for good this time.\"","then":"Zubin's face tightens. \"So one mistake and it's over.\""},{"text":"\"You won't. You're stronger than that.\"","then":"Zubin shrugs. \"What if I'm not?\""},{"text":"\"Then it means the counselling isn't working.\"","then":"Zubin looks worried. \"So it'd all be for nothing?\""}],"why":"Slips happen, and knowing you'll stay calm makes it safe for him to tell you."},{"prompt":"Zubin asks: \"Will you come to the sessions too?\"","options":[{"text":"\"Whenever they want me, I'll be there.\"","then":"Zubin nods. \"Okay. I'd like that.\"","best":true},{"text":"\"No. That's your time with the counsellor.\"","then":"Zubin shrugs. \"Oh. Okay.\""},{"text":"\"Only if you keep messing up.\"","then":"Zubin's face falls. \"So it's a punishment?\""},{"text":"\"I'm too busy, but your mother can go with you.\"","then":"Zubin shrugs. \"Sure. Whatever.\""}],"why":"Being ready to join in shows him it's a family effort, which strongly improves outcomes."}],"relearn":"Stay involved through recovery; family support over the long haul strongly improves outcomes."},
  {"id":"na-1407","cat":"tools-and-safety","type":"role-play","persona":"Kamla","source":"give the route","hook":"Your friend Parvati's son Mani, 13, has been drinking with older boys and is in a bad way.","setup":"She calls you, close to tears.","steps":[{"prompt":"Parvati says: \"I don't know who to call. Please tell me.\"","options":[{"text":"\"Childline 1098. Or 112 if it's acute danger.\"","then":"Parvati repeats it. \"Childline 1098, or 112 if it's acute. Okay.\"","best":true},{"text":"\"Honestly, just search online when it happens.\"","then":"Parvati's voice rises. \"It's happening now!\""},{"text":"\"Ask the neighbours to go and drag him back home.\"","then":"Parvati hesitates. \"They'll only shout at him.\""},{"text":"\"Don't call anyone yet. Wait till he comes home.\"","then":"Parvati sobs. \"What if he doesn't?\""}],"why":"Childline 1098 is for a child in distress or danger, and 112 is for acute danger."},{"prompt":"Parvati asks: \"What if he comes home in a bad way? When is it an emergency?\"","options":[{"text":"\"If he won't wake, or you fear for him, it's 112.\"","then":"Parvati takes a breath. \"Okay. 112 if it's like that.\"","best":true},{"text":"\"If he's still talking, he's fine. Don't worry so much.\"","then":"Parvati hesitates. \"Are you sure?\""},{"text":"\"Wait an hour and see how he is then.\"","then":"Parvati sounds unsure. \"A whole hour?\""},{"text":"\"Ask his friends. They'll know if it's serious.\"","then":"Parvati sighs. \"They've been drinking too.\""}],"why":"Any fear for a child's life is an emergency, so 112 comes first. Never wait and see."},{"prompt":"Later, Parvati says: \"He's home and safe. But I can't go through this again.\"","options":[{"text":"\"Save Childline 1098 and 112. Ring Tele-MANAS 14416 this week.\"","then":"Parvati writes all three down. \"Okay. This week.\"","best":true},{"text":"\"Lock him in until he learns his lesson.\"","then":"Parvati hesitates. \"He'll just climb out.\""},{"text":"\"Try to forget it. He's home now.\"","then":"Parvati sighs. \"Until next time.\""},{"text":"\"Keep it quiet, so the whole building doesn't find out about Mani.\"","then":"Parvati nods. \"Yes. No one must know.\""}],"why":"Saving the routes now, and getting support early, means she won't scramble next time."}],"relearn":"Childline 1098 for a child in distress or danger; 112 for acute danger or a medical emergency."},
  {"id":"na-1408","cat":"tools-and-safety","type":"role-play","persona":"any","source":"be honest","hook":"Worried about your son Varun's drinking, you're looking up helplines on the laptop.","setup":"Varun, 15, walks in and reads the screen.","steps":[{"prompt":"Varun asks: \"Why are you looking at addiction helplines? Am I in trouble?\"","options":[{"text":"\"No. I'm finding out how to help you, not punish you.\"","then":"Varun hesitates. \"Help me how?\"","best":true},{"text":"\"None of your business. Just stay out of my way.\"","then":"Varun backs out of the room, then stops at the door."},{"text":"\"It's for a colleague at work, not you. Don't worry.\"","then":"Varun frowns at the screen. \"A colleague? You're sure it's not me?\""},{"text":"\"You tell me. Should you be in trouble?\"","then":"Varun's face closes. \"I knew it. You think I'm a drunk.\""}],"why":"Being honest that help is support, not punishment, keeps him reachable."},{"prompt":"Varun says: \"I'm not an addict. I just drink at parties sometimes.\"","options":[{"text":"\"I'm not calling you anything. Tell me more?\"","then":"Varun sits on the arm of the sofa. \"It's just been more lately.\"","best":true},{"text":"\"Sometimes? You came home sick twice this month.\"","then":"Varun's jaw sets. \"So you've been counting.\""},{"text":"\"Okay, then. As long as it's only at parties.\"","then":"Varun nods, relieved, and turns to leave."},{"text":"\"That's exactly what every addict says.\"","then":"Varun turns away. \"Great. So that's what I am to you.\""}],"why":"Avoiding labels and staying curious helps him tell you more."},{"prompt":"Varun asks: \"So who were you going to call?\"","options":[{"text":"\"Tele-MANAS 14416, to learn how to help. Want to listen?\"","then":"Varun shrugs. \"Maybe. Not today.\"","best":true},{"text":"\"A rehab centre, so they can take you away.\"","then":"Varun goes pale. \"You'd send me away?\""},{"text":"\"No one. I was only reading, out of curiosity.\"","then":"Varun narrows his eyes. \"You're lying.\""},{"text":"\"Your school counsellor, so she can keep an eye on you.\"","then":"Varun groans. \"Great. Now the school will know.\""}],"why":"Being open about who you're calling, and inviting him in, makes help less frightening."},{"prompt":"Varun says: \"Just don't tell the relatives, okay?\"","options":[{"text":"\"I won't spread it. But I will get us proper help.\"","then":"Varun nods slowly. \"Okay. Deal.\"","best":true},{"text":"\"I promise I won't tell anyone at all, ever.\"","then":"Varun relaxes. You've promised more than you can keep."},{"text":"\"If you stop drinking, nobody ever needs to know.\"","then":"Varun nods. You can see him deciding to hide it better."},{"text":"\"I'll tell whoever I need to. You don't get a say.\"","then":"Varun's face shuts. \"Then I'm not telling you anything.\""}],"why":"Protecting his privacy while being honest about getting help keeps trust on both sides."}],"relearn":"Frame help-finding as support, not punishment; honesty keeps your child reachable and willing."},
  {"id":"na-1409","cat":"tools-and-safety","type":"role-play","persona":"Vikram","source":"ask spouse in","hook":"You've made a calm-response plan for your daughter Nisha, 16, but only you know it.","setup":"Your partner Sunita is folding laundry beside you.","steps":[{"prompt":"Sunita says: \"You deal with Nisha's stuff. You're better at it.\"","options":[{"text":"\"Learn the plan with me, so whoever's home can act.\"","then":"Sunita pauses. \"What would I even do?\"","best":true},{"text":"\"Don't worry about it. I'll deal with everything myself.\"","then":"Sunita smiles, relieved, then pauses. \"But what if you're not home?\""},{"text":"\"Fine, but if something happens, it's on you.\"","then":"Sunita's hands go still. \"That's not fair.\""},{"text":"\"I'll write it down, and you can read it sometime.\"","then":"Sunita nods. \"Sure, sometime.\""}],"why":"A plan only works if every carer knows it, so anyone at home can stay steady."},{"prompt":"Sunita asks: \"What would I say if I found her drunk?\"","options":[{"text":"\"Make sure she's safe, then talk calmly the next day.\"","then":"Sunita nods. \"Safe first. Talk later.\"","best":true},{"text":"\"Tell her exactly how disappointed you are in her.\"","then":"Sunita hesitates. \"Wouldn't that make her hide it?\""},{"text":"\"Take her phone and ground her on the spot.\"","then":"Sunita frowns. \"At midnight? She'd just scream.\""},{"text":"\"Nothing. Just wait for me to get home.\"","then":"Sunita frowns. \"What if you're away for days?\""}],"why":"Keeping her safe first and talking when everyone is calm keeps her reachable."},{"prompt":"Sunita asks: \"And if she can't wake up properly?\"","options":[{"text":"\"That's an emergency. 112, or straight to hospital.\"","then":"Sunita writes 112 on the back of her hand. \"Got it.\"","best":true},{"text":"\"Call me first, and I'll decide what we should do.\"","then":"Sunita frowns. \"What if you don't answer?\""},{"text":"\"Let her sleep. She'll be fine by morning.\"","then":"Sunita looks unsure. \"Are you sure about that?\""},{"text":"\"Call your brother. He'll know what to do.\"","then":"Sunita hesitates. \"He's an hour away.\""}],"why":"Anyone at home must know that acute danger means 112 or a hospital at once."},{"prompt":"Sunita says: \"Okay. Where do we keep all this?\"","options":[{"text":"\"In both our phones, and on the fridge.\"","then":"Sunita nods. \"And we go over it together each month?\"","best":true},{"text":"\"In my head. I'll remind you when it's needed.\"","then":"Sunita laughs. \"That's the problem we started with.\""},{"text":"\"In my drawer, so Nisha doesn't see it.\"","then":"Sunita shrugs. \"Then I'll never find it in a hurry.\""},{"text":"\"Somewhere safe. We'll find it if we need it.\"","then":"Sunita raises an eyebrow. \"Will we, though?\""}],"why":"A shared plan kept where both of you can reach it is one either of you can use."}],"relearn":"Share the calm-response plan with every carer, so whoever is home can stay steady and act."},
  {"id":"na-1410","cat":"tools-and-safety","type":"role-play","persona":"Divya","source":"decide now","hook":"You and your partner Harish keep meaning to make a help plan for your son Tejas, 15.","setup":"Tonight the house is finally quiet.","steps":[{"prompt":"Harish yawns and says: \"Let's do the plan when things calm down.\"","options":[{"text":"\"This is calm. Let's do it tonight.\"","then":"Harish stretches. \"Fine. Twenty minutes, then.\"","best":true},{"text":"\"Okay. Let's put it off until things settle.\"","then":"Harish nods, relieved, and reaches for the remote."},{"text":"\"You never want to deal with anything, do you?\"","then":"Harish sighs. \"Here we go again.\""},{"text":"\"I'll do it alone some other night. Go to bed.\"","then":"Harish shrugs. \"If you're sure.\""}],"why":"The calm moment before a crisis is the best time to prepare."},{"prompt":"Harish asks: \"Whenever we make it, what if Tejas finds the plan and thinks we don't trust him?\"","options":[{"text":"\"We'll tell him. It's about help, not suspicion.\"","then":"Harish nods. \"Maybe he should know the numbers too.\"","best":true},{"text":"\"We'll hide it where he can never see it.\"","then":"Harish nods. \"Top shelf, behind the files.\""},{"text":"\"Then let's not make one, just to be safe.\"","then":"Harish looks relieved, then hesitates. \"We should still keep the numbers.\""},{"text":"\"He shouldn't mind if he has nothing to hide.\"","then":"Harish winces. \"That sounds like we're spying.\""}],"why":"Being open about the plan shows him it's about help, which keeps his trust."},{"prompt":"Harish asks: \"So which numbers should we keep?\"","options":[{"text":"\"Tele-MANAS 14416, Childline 1098, and 112 for emergencies.\"","then":"Harish types them into his phone. \"Done. Now the fridge.\"","best":true},{"text":"\"Just the family doctor's number. He knows us all.\"","then":"Harish nods. \"What if it's midnight, though?\""},{"text":"\"We'll look them up online when something happens.\"","then":"Harish frowns. \"In a panic? We'd never find the right one.\""},{"text":"\"Only 112. Anything less than that, we handle ourselves at home.\"","then":"Harish hesitates. \"Even when we're just worried?\""}],"why":"Saving the right routes now means you won't be searching in a panic later."}],"relearn":"Make the plan and save the numbers now; the calm moment before a crisis is the time to prepare."},
];

